UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Мұхит самалы бейглі - Албырт қосылған тост'), description_kk = COALESCE(description_kk, 'Ойды тұмандандыратын күйді сейілтіп, теріге жарқыл беретін Омега-3 көзі.

