UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Super Grain Bowl – киноа салаты'), description_kk = COALESCE(description_kk, 'Ақуызға бай тағам. Құрамында барлық алмастырылмайтын аминқышқылдары бар, ана сүтінің сапасын жақсартады.'), category_kk = COALESCE(category_kk, 'nahar_yemeyi'), tags_kk = COALESCE(tags_kk, ARRAY['postpartum']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Киноа: жарты стақан (піскен)","Қара үрме бұршақ немесе ноқат: жарты стақан","Авокадо: жарты дана","Ақжелкен: 1 бума","Лимон шырыны, зәйтүн майы"]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Киноаны жуып, 15 минут пісіріңіз де, суын төгіңіз","Піскен үрме бұршақты/ноқатты қосыңыз","Авокадоны текшелеп тураңыз","Ақжелкен, лимон шырыны және зәйтүн майымен араластырыңыз","Салқын немесе бөлме температурасында ұсыныңыз"]'::jsonb) WHERE id = '971c317e-b7ac-4733-b72a-ef93a65eb1b6';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Алғашқы жасыл дәм – кәді пюресі'), description_kk = COALESCE(description_kk, 'Бөпенің ас қорыту жүйесіне арналған ең жеңіл қосымша тағам (6 ай+)'), category_kk = COALESCE(category_kk, 'baby_food'), tags_kk = COALESCE(tags_kk, ARRAY['baby_food']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Кәді - 1 кішкентай дана","Зәйтүн майы - 1 шай қасық","Ана сүті/қоспа"]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Кәдіні буға пісіріңіз","Блендермен езіңіз","Ана сүті мен зәйтүн майын қосыңыз"]'::jsonb) WHERE id = '12f0782c-f0f2-4ba6-a173-dbb482071e15';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Шакшука'), description_kk = COALESCE(description_kk, 'Қызанақ пен дәмдеуіш мол қосылған, ыстық күйінде ұсынылатын демалыс күндерінің классикалық тағамы.

Пайдасы: Піскен қызанақтың құрамындағы ликопен — әйел ағзасын қатерлі ісіктен қорғауға көмектесетін күшті антиоксиданттардың бірі.'), category_kk = COALESCE(category_kk, 'таңғы ас'), tags_kk = COALESCE(tags_kk, ARRAY['жалпы']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Жұмыртқа: 2 дана","Қызанақ: 2 дана (туралған)","Түрлі түсті бұрыш: жарты дана (туралған)","Пияз: жарты дана","Зәйтүн майы, ұнтақталған зире (кумин), тұз, бұрыш."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Табаға зәйтүн майын құйып, пияз бен бұрышты қуырыңыз. Қызанақ пен дәмдеуіштерді қосып, тұздық тәрізді болғанша пісіріңіз. Тұздықтың арасынан ойықтар жасап, жұмыртқаларды жарып салыңыз да, қақпағын жауып, қалаған қоюлыққа дейін пісіріңіз."]'::jsonb) WHERE id = '29bb0ce4-9bdc-4fac-b1c7-e5b836d8f1d0';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Мұхит сыйы — албырт'), description_kk = COALESCE(description_kk, 'Емшек сүтін омега-3 май қышқылдарымен байытуға арналған тамаша тағам. Бөпенің миының дамуын қолдайды.'), category_kk = COALESCE(category_kk, 'түскі ас'), tags_kk = COALESCE(tags_kk, ARRAY['босанғаннан кейінгі кезең']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Албырт (сомон): 150 qr","Қояншөп немесе жасыл үрмебұршақ: 100 qr","Лимон: жарты дана","Аскөк: 1 бума","Зәйтүн майы: 1 ас қасық"]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Балыққа тұз сеуіп, лимон шырынына маринадтаңыз (10 dəq)","Көкөністерді балықтың жанына орналастырыңыз","Үстіне зәйтүн майын жағып, фольгаға ораңыз","Пеште 180°C температурада 20 минут пісіріңіз","Үстіне балғын аскөкті молынан себіңіз"]'::jsonb) WHERE id = 'fe3cad51-3e25-4969-b2ba-dbb221d883b9';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Изумруд барқыт — саумалдық сорпасы'), description_kk = COALESCE(description_kk, 'Темірге деген қажеттілікті өтеуге және шаршауды азайтуға көмектесетін жасыл қуат көзі. Фолий қышқылына бай.'), category_kk = COALESCE(category_kk, 'түскі ас'), ingredients_kk = COALESCE(ingredients_kk, '["Саумалдық: 1 үлкен бума","Картоп: 1 дана","Пияз: 1 дана","Кілегей (немесе сүт): жарты стақан","Тұз, бұрыш"]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Көкөністерді турап, суға қайнатыңыз","Жұмсарғаннан кейін блендермен езіп, пюре күйіне келтіріңіз","Соңында кілегейді қосып, бір қайнатып алыңыз","Тұз бен бұрыш қосыңыз","Ыстық күйінде ұсыныңыз — темірге деген қажеттілікті өтеуге көмектеседі"]'::jsonb) WHERE id = '7b50a305-3e3e-47ca-8cb4-e9cc2bf8695d';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Жақұт бұқтырмасы — қызылша мен ет'), description_kk = COALESCE(description_kk, 'Қан түзілуін және емшек сүтінің бөлінуін қолдайтын тамаша үйлесім. Темір мен ақуыздың көзі.'), category_kk = COALESCE(category_kk, 'түскі_ас'), tags_kk = COALESCE(tags_kk, ARRAY['босанғаннан_кейін']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Сиыр еті: 200 qr (текшелеп туралған)","Қызылша: 1 дана (үлкен)","Сәбіз: 1 дана","Сорпа: 2 стақан","Тұз, бұрыш"]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Етті кішкентай текшелерге турап, жұмсарғанша қайнатыңыз","Қызылша мен сәбізді аршып, тураңыз","Етке қосып, баяу отта 30-40 минут пісіріңіз","Тұз бен бұрыш қосыңыз","Ыстық күйінде ұсыныңыз — қан түзілуі мен емшек сүтінің көбеюін қолдайды"]'::jsonb) WHERE id = '7bcfa70e-7c6a-42b0-84fa-c8b8642dc2e8';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Ваниль дәндері қосылған макиато'), description_kk = COALESCE(description_kk, 'Жасанды шәрбаттың орнына табиғи ваниль дәндері қолданылатын нағыз италиялық дәм.'), category_kk = COALESCE(category_kk, 'жалпы'), tags_kk = COALESCE(tags_kk, ARRAY['жалпы']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["1 шыныаяқ эспрессо, төрттен бір стақан ыстық әрі көпіршітілген сүт, табиғи ваниль таяқшасының дәндері (немесе органикалық ваниль сығындысы)."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Сүтті ванильмен бірге жылытып, жақсылап көпіршітіңіз. Ыстық эспрессоның үстіне тек ваниль қосылған көбікті қасықпен салыңыз."]'::jsonb) WHERE id = 'fa71b0aa-2b84-4b46-9f5a-66cd2a1a924c';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Алтын түсті киноа ботқасы'), description_kk = COALESCE(description_kk, 'Дәлелденген қуат және өсімдік тектес темір көзі.

Пайдасы: Киноа — құрамында глютен жоқ әрі барлық алмастырылмайтын аминқышқылдары бар құнды дақыл, ол қандағы қант деңгейін реттеуге көмектеседі.'), category_kk = COALESCE(category_kk, 'таңғы_ас'), ingredients_kk = COALESCE(ingredients_kk, '["Киноа: Жарты стақан (жақсылап жуылған)","Бадам сүті: 1 стақан","Ұнтақталған куркума: Жарты шай қасық (қабынуға қарсы)","Бадам дәні, мейіз немесе кептірілген қара өрік."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Киноаны сүтпен бірге кәстрөлге салып, куркума қосыңыз да, сұйықтығын сіңіргенше баяу отта пісіріңіз. Оттан алып, үстіне бадам мен мейіз себіңіз."]'::jsonb) WHERE id = 'a8e7b2fb-a93b-4062-b10e-3ec92ab8f15b';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Қызғылт сары шұғыла — Сәбіз салаты'), description_kk = COALESCE(description_kk, 'Сәбіз бен тахинидің кальцийге бай үйлесімі. Бета-каротин мен кальций ана сүтінің сапасын арттырады.'), category_kk = COALESCE(category_kk, 'sam_yemeyi'), ingredients_kk = COALESCE(ingredients_kk, '["Сәбіз: 2 дана (үккіштен өткізілген)","Жаңғақ: 1 уыс (ұсақталған)","Тахини (күнжіт пастасы): 1 ас қасық","Лимон шырыны, зәйтүн майы","Аскөк: бірнеше бұтақ"]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Сәбізді үккіштен өткізіңіз","Жаңғақты ұсақтап, қосыңыз","Аскөкті майдалап тураңыз","Тахини, лимон шырыны және зәйтүн майынан тұздық дайындаңыз","Барлығын араластырып, ұсыныңыз — дәруменге толы"]'::jsonb) WHERE id = 'ee7e5b2c-3005-40bc-948c-9e7d5600cfdc';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Өмір нәрі компоты'), description_kk = COALESCE(description_kk, 'Кептірілген жемістерден қантсыз дайындалған табиғи сусын. Ана сүтінің 80%-ы судан тұрады — бұл компот шөлді жақсы басады.'), category_kk = COALESCE(category_kk, 'saglam_ickiler'), ingredients_kk = COALESCE(ingredients_kk, '["Кептірілген өрік: 5-6 дана","Кептірілген қара өрік: 3-4 дана","Алма (кептірілген немесе балғын): тілімделген","Су: 1.5 литр"]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Кептірілген жемістерді жуыңыз","1.5 литр суға салып, қайнатыңыз","Қайнағаннан кейін баяу отта 20 минут пісіріңіз","Қант қоспаңыз — жемістердің табиғи тәттілігі жеткілікті","Салқын күйінде ішіңіз — күні бойы молынан"]'::jsonb) WHERE id = '50c1c324-2182-4a8b-9fa1-e6567601c2d3';
