UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Кремді ми — Авокадо мен банан'), description_kk = COALESCE(description_kk, 'Мидың дамуына арналған Омега-3 көзі, пісіруді қажет етпейді (7 ай+)'), category_kk = COALESCE(category_kk, 'baby_food'), tags_kk = COALESCE(tags_kk, ARRAY['baby_food', 'vitamin_rich']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Авокадо — жарты дана","Банан — жарты дана"]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Екеуін де шанышқымен езіңіз","Аздап түйіршікті күйде қалдырыңыз"]'::jsonb) WHERE id = '2b374b35-8810-48b4-a990-d7b6c19bcd99';
