UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Orange Power - Асқабақ пен сәбіз езбесі'), description_kk = COALESCE(description_kk, 'Бета-каротинге бай, тәтті дәмі бөпелерге ұнайды (6-7 ай)'), category_kk = COALESCE(category_kk, 'бөпе тағамы'), tags_kk = COALESCE(tags_kk, ARRAY['бөпе тағамы']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Асқабақ - 1 тілім","Сәбіз - 1 дана"]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Көкөністерді буға пісіріңіз","Блендермен біркелкі езбе дайындаңыз"]'::jsonb) WHERE id = '8c40752c-6db4-4615-b2ca-638a97aa09f6';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Мұхит маржаны — албырт пен қояншөп'), description_kk = COALESCE(description_kk, 'Теріні іштен ылғалдандырып, ісінуді басуға көмектесетін классикалық үйлесім.

Пайдасы: Албырттағы Омега-3 шаш пен теріге жылтыр береді, ал қояншөп — табиғи диуретик (ағзадағы артық су мен ісінуді азайтуға көмектеседі).'), category_kk = COALESCE(category_kk, 'түскі ас'), tags_kk = COALESCE(tags_kk, ARRAY['жалпы']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Албырт (сомон) сүбесі: 150 qr","Қояншөп (аспарагус): 6-8 дана","Лимон: Жарты дана","Зәйтүн майы, теңіз тұзы, қара бұрыш."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Қояншөптің қатты ұштарын кесіңіз. Балық пен қояншөпті пеш табасына орналастырыңыз. Үстіне зәйтүн майын, тұз, бұрыш және лимон шырынын қосып, 180 градуста 15-20 минут пісіріңіз."]'::jsonb) WHERE id = '07319d7d-c920-4693-bc34-502061f38b1b';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Пеште пісірілген фалафель'), description_kk = COALESCE(description_kk, 'Қуырылған тағамнан бас тартатындарға арналған, пеште пісірілген, жасұныққа бай әрі қытырлақ шығыс дәмі.

Пайдасы: Ноқат әйел ағзасындағы эстроген деңгейін табиғи жолмен қолдайды, ал құрамындағы жасұнық іш қатудың алдын алуға көмектеседі.'), category_kk = COALESCE(category_kk, 'түскі ас'), tags_kk = COALESCE(tags_kk, ARRAY['жалпы']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Ноқат: 1 стақан (кештен бері жібітілген, шикі)","Балғын ақжелкен мен күнзе: Жарты бума","Пияз, сарымсақ, зире (ұнтақталған)."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Барлық өнімді блендерде қатты езбей, ұсақтаңыз. Қолыңызбен шағын домалақтар жасап, майлы қағаздың үстіне қойып, 180 градуста 25 минут пісіріңіз. Қасына йогурт немесе тахини тұздығын қосып жеңіз."]'::jsonb) WHERE id = 'fff5b4d4-5ba2-4e96-98ea-a65ef476ad64';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Брокколи (гүлді қырыққабат) гратені'), description_kk = COALESCE(description_kk, 'Кальций мен C дәруменінің көзі, ет жегіңіз келмейтін күндерге арналған балама'), category_kk = COALESCE(category_kk, 'кешкі_ас'), tags_kk = COALESCE(tags_kk, ARRAY['жүктілік']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Гүлді қырыққабат немесе брокколи - 300 гр","Жұмыртқа - 2 дана","Йогурт - 2 ас қасық","Ұн - 1 ас қасық","Ірімшік - 30 гр"]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Гүлді қырыққабатты немесе брокколиді пісіріңіз","Жұмыртқа, йогурт пен ұнды араластырып, жақсылап шайқаңыз","Қоспаны көкөністің үстіне құйыңыз","Үстіне ірімшік сеуіп, пеште пісіріңіз"]'::jsonb) WHERE id = '0af2c4bf-6712-4fe8-994f-bb2c520b2caf';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Авокадо қосылған шоколадты мусс'), description_kk = COALESCE(description_kk, 'Авокадо фолий қышқылы мен магнийге бай, ал какао бақыт гормонының бөлінуіне ықпал етеді'), category_kk = COALESCE(category_kk, 'пайдалы_сусындар'), ingredients_kk = COALESCE(ingredients_kk, '["Авокадо - 1 дана","Какао - 2 ас қасық","Бал - 3 ас қасық","Ваниль","Бадам сүті - 3 қасық"]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Барлық ингредиентті блендерге салыңыз","Крем тәрізді болғанша араластырыңыз","Тоңазытқышта 30 минут ұстаңыз","Құлпынаймен бірге ұсыныңыз"]'::jsonb) WHERE id = 'c7535dc2-4407-4715-bc23-3a8242531319';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Жасыл ғажайып — аскөк қосылған тефтели'), description_kk = COALESCE(description_kk, 'Әзербайжан асханасындағы сүттің көбеюіне көмектесетін ең танымал құпия: мол аскөк! Сүттің бөлінуін жақсартады.'), category_kk = COALESCE(category_kk, 'түскі_ас'), ingredients_kk = COALESCE(ingredients_kk, '["Тартылған ет (сиыр немесе тауық еті): 300 гр","Күріш: жарты стақан","Аскөк: 2 үлкен бума","Картоп: 2 дана","Пияз: 1 дана","Тұз, бұрыш"]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Тартылған етті, жуылған күрішті және ұсақтап туралған аскөктің жартысын араластырыңыз","Тұз бен бұрыш қосып, тефтели жасаңыз","Қайнап тұрған суға туралған картоп пен пиязды салыңыз","5 минуттан кейін тефтелиді қосып, баяу отта 25-30 минут пісіріңіз","Пісуге жақындағанда қалған аскөкті молынан турап, сорпаға қосыңыз"]'::jsonb) WHERE id = 'b8788575-43f0-4748-a08b-a02e6044caa7';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Кәріптас ағыны — пажитник шайы'), description_kk = COALESCE(description_kk, 'Ана сүтін арттыруға көмектесетін ең күшті өсімдіктердің бірі — пажитник (Fenugreek). Ол пролактин гормонының бөлінуін ынталандырады.'), category_kk = COALESCE(category_kk, 'пайдалы_сусындар'), ingredients_kk = COALESCE(ingredients_kk, '["Пажитник тұқымы (Fenugreek): 1 шай қасық","Су: 2 стақан","Бал: 1 шай қасық (қалауыңызша)","Лимон: бірнеше тамшы"]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Пажитник тұқымдарын құрғақ табада 1-2 минут жеңіл қуырыңыз (күйіп кетпесін)","Қайнаған суға қосыңыз","10 минут демдеп, сүзіңіз","Қалауыңызша бал мен лимон қосыңыз","Күніне 2-3 кесе ішіңіз — сүттің артқаны 24-48 сағаттан кейін байқалуы мүмкін"]'::jsonb) WHERE id = '52d3741b-ea80-45a2-99fd-beda7e7b6c4a';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Матчалы таңғы боул'), description_kk = COALESCE(description_kk, 'Кофесіз сергігісі келетіндерге арналған антиоксиданттарға бай, зат алмасуды қолдайтын таңғы ас.

Пайдасы: Матча шайы зат алмасуды қолдап, терінің тазаруына көмектеседі. Кофе секілді энергияны бірден көтеріп, кейін шаршатпайды, күні бойы бірқалыпты сергектік береді'), category_kk = COALESCE(category_kk, 'таңғы ас'), tags_kk = COALESCE(tags_kk, ARRAY['жалпы']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Мұздатылған банан: 1 дана","Матча ұнтағы: 1 шай қасық","Саумалдық: 1 кішкентай уыс","Бадам сүті: Жарты стақан","Бетін безендіруге: Кокос жаңқасы, бадам дәні, киви тілімдері."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Банан, матча, саумалдық пен сүтті қою смузи болғанша блендермен араластырыңыз. Ыдысқа құйып, бетін жаңғақтармен және кивимен безендіріңіз."]'::jsonb) WHERE id = '8c4792f6-0abc-4597-99d1-ff981dc2a340';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Тәтті ұйқы шоты'), description_kk = COALESCE(description_kk, 'Бұлшықет құрысуы мен кернеуін азайтуға арналған'), category_kk = COALESCE(category_kk, 'пайдалы_сусындар'), ingredients_kk = COALESCE(ingredients_kk, '["Бадам - 5 дана (суға жібітілген)","Банан - төрттен бір бөлігі","Какао - жарты шай қасық","Су - 2 ас қасық"]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Бадамдардың қабығын аршыңыз","Барлығын блендермен сұйық күйге дейін араластырыңыз"]'::jsonb) WHERE id = '13b7591b-479c-457d-ab27-09785681c532';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Жақұт түсті гибискус мохитосы'), description_kk = COALESCE(description_kk, 'Жастық эликсирі әрі қан қысымын реттеуге көмектесетін қызыл сусын.

Пайдасы: Гибискус (судан раушаны) — C дәрумені мен антиоксиданттардың мол көзі, зат алмасуды жылдамдатып, жүрек-қан тамырлары жүйесін қорғайды.'), category_kk = COALESCE(category_kk, 'Пайдалы сусындар'), ingredients_kk = COALESCE(ingredients_kk, '["Гибискус шайы (қою демделіп, салқындатылған): Жарты стақан","Жалбыз жапырақтары: 5-6 дана","Лайм: Жарты дана (тілімделген)","Газдалған су (минералды су) және мұз."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Стақанның түбінде жалбыз бен лайм тілімдерін ағаш келсаппен езіңіз. Үстіне молынан мұз салыңыз. Салқын гибискус шайы мен минералды суды қосып, араластырыңыз."]'::jsonb) WHERE id = 'd9f4e457-b6da-4ebb-92a8-543b9465b164';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Цитрусты серпін'), description_kk = COALESCE(description_kk, 'Зат алмасуды белсендіріп, май жағуға көмектесетін таңғы коктейль.

Пайдасы: Грейпфрут инсулин деңгейін теңестіруге көмектеседі, ал гүлшетен есте сақтау қабілеті мен зейінді арттырады.'), category_kk = COALESCE(category_kk, 'Пайдалы сусындар'), tags_kk = COALESCE(tags_kk, ARRAY['жалпы']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Грейпфрут шырыны (жаңа сығылған): Жарты стақан","Балғын гүлшетен: 1 бұтақ","Газдалған су: Жарты стақан","Мұз."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Гүлшетен бұтағын хош иісі шығуы үшін қолыңызбен аздап езіп, стақанға салыңыз. Үстіне мұз, грейпфрут шырыны мен минералды су құйыңыз."]'::jsonb) WHERE id = 'd407408a-9e13-47c0-b565-ec699f31591e';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Мұзды какао-протеин шейкі'), description_kk = COALESCE(description_kk, 'Жаттығудан кейін бұлшықеттерді қалпына келтіруге және ұзақ уақыт тоқ жүруге өте қолайлы.'), category_kk = COALESCE(category_kk, 'Пайдалы сусындар'), ingredients_kk = COALESCE(ingredients_kk, '["1 ас қасық какао, 1 мұздатылған банан, 1 ас қасық жержаңғақ пастасы, 1 стақан салқын сүт, мұз."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Барлық ингредиентті блендерде қою шейк болғанша араластырыңыз."]'::jsonb) WHERE id = 'fff46867-aa41-4bc9-8647-1346ba044359';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Киноа мен шоколадтан жасалған қытырлақ тәттілер'), description_kk = COALESCE(description_kk, 'ПМС (етеккір алдындағы) кезеңінде шоколадқа деген құштарлықты басатын ең қытырлақ әрі пайдалы тәтті.

Пайдасы: Қара шоколад магнийге бай (түйілу мен ширығуды азайтады), ал қопсытылған киноа ақуызбен қамтамасыз етіп, қандағы қант деңгейін тұрақты ұстайды.'), category_kk = COALESCE(category_kk, 'Пайдалы тәттілер'), tags_kk = COALESCE(tags_kk, ARRAY['general']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Қара шоколад (кемінде 70% какао): 100 г","Қопсытылған киноа (немесе сұлы): 1 стақан","Теңіз тұзы: Өте аз мөлшерде (бетіне себу үшін)"]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Шоколадты бу моншасында (bain-marie әдісімен) ерітіңіз. Оған киноаны қосып, жақсылап араластырыңыз. Қасықпен пергамент қағаздың үстіне шағын үйінділер түрінде салыңыз. Бетіне теңіз тұзын сеуіп, тоңазытқышта 20 минут салқындатыңыз."]'::jsonb) WHERE id = 'b3153614-fcee-47f5-887f-a9f21df0723d';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Какао мен авокадо қосылған тарт'), description_kk = COALESCE(description_kk, 'Шоколадты тарттың ешкім пайдалы деп ойламайтындай, пісіруді қажет етпейтін нұсқасы.

Пайдасы: Авокадодағы пайдалы майлар әйел гормондарының синтезі үшін өте маңызды. Ал какао эндорфиннің (бақыт гормонының) бөлінуін арттырады.'), category_kk = COALESCE(category_kk, 'Пайдалы тәттілер'), ingredients_kk = COALESCE(ingredients_kk, '["Негізі үшін: 1 стақан грек жаңғағы, 10 құрма.","Кремі үшін: 2 піскен авокадо, жарты стақан қантсыз какао, 4 ас қасық бал немесе пекмез."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Грек жаңғағы мен құрманы блендерде ұсақтап, тарт пішінінің түбіне тегістеп жайыңыз. Крем үшін авокадо, какао мен балды жібектей біркелкі болғанша блендермен араластырыңыз. Негіздің үстіне жайып, тоңазытқышта 2 сағат ұстаңыз."]'::jsonb) WHERE id = '1b665124-a619-4ee4-9dce-a48ced0f8106';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Жержаңғақ пастасы қосылған құрма'), description_kk = COALESCE(description_kk, 'Нағыз карамельді шоколад жеп отырғандай әсер сыйлайтын әрі бірден қуат беретін тіскебасар.

Пайдасы: Тазартылған қантқа деген құштарлықты толығымен басады. Жержаңғақ пастасындағы ақуыз бен пайдалы майлар тоқтық сезімін ұзартады.'), category_kk = COALESCE(category_kk, 'Пайдалы тәттілер'), tags_kk = COALESCE(tags_kk, ARRAY['general']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Medjool құрмасы (ірі, жұмсақ): 5-6 дана","Қантсыз жержаңғақ пастасы: 2 ас қасық","Қара шоколад (ерітілген)."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Құрмаларды ұзынынан кесіп, сүйегін алып тастаңыз. Ішін жержаңғақ пастасымен толтырыңыз. Құрмаларды жартысына дейін ерітілген қара шоколадқа батырып, қатуы үшін тоңазытқышқа қойыңыз."]'::jsonb) WHERE id = '23124658-0378-42aa-b696-d264cdef885d';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Гүлді қырыққабат пиццасы'), description_kk = COALESCE(description_kk, 'Пиццаның дәмін артық кінә сезімінсіз, глютенсіз және қамырсыз тамашалау үшін.

Пайдасы: Гүлді қырыққабат фитонутриенттерге бай әрі бауырды тазартады. Бұл пицца іштің кебуі мен қыжылды мүлде тудырмайды.'), category_kk = COALESCE(category_kk, 'кешкі ас'), ingredients_kk = COALESCE(ingredients_kk, '["Гүлді қырыққабат: Жарты бас (үккіштен өткізіліп, суы толық сығылған)","Жұмыртқа: 1 дана","Ірімшік (үккіштен өткізілген): 3 ас қасық (қамырына)","Бетіне: Томат пастасы, қызанақ тілімдері, ірімшік, насыбайгүл."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Үккіштен өткізілген гүлді қырыққабатты жұмыртқа және ірімшікпен араластырып, пеш табасына пицца қамыры тәрізді етіп жайыңыз. 200 градуста 15 минут (қызарғанша) пісіріңіз. Содан кейін пештен шығарып, үстіне тұздық пен басқа ингредиенттерді салыңыз да, ірімшік ерігенше тағы 5 минут пісіріңіз."]'::jsonb) WHERE id = 'e3dad099-6f8a-4e3c-8dfa-2922158c70b6';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Жылы саңырауқұлақ пен шпинат салаты'), description_kk = COALESCE(description_kk, 'Ет жегіңіз келмейтін кештерге арналған хош иісті, жылы әрі тойымды салат.

Пайдасы: Шпинаттағы магний бұлшықеттерді босаңсытады, ал саңырауқұлақ иммунитетті нығайтатын D дәрумені мен B тобының дәрумендеріне бай.'), category_kk = COALESCE(category_kk, 'кешкі ас'), tags_kk = COALESCE(tags_kk, ARRAY['жалпы']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Шампиньон немесе вешенка саңырауқұлағы: 150 qr (туралған)","Жас шпинат: 2-3 уыс (шикі)","Грек жаңғағы: 1 уыс","Бальзам сірке суы, зәйтүн майы, сарымсақ (аздап)."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Саңырауқұлақтарды бір түйір сарымсақпен бірге аз мөлшердегі майға салып, қызарғанша қуырыңыз. Шпинатты ыдысқа салыңыз. Ыстық саңырауқұлақтарды шпинаттың үстіне құйыңыз (жылу шпинатты аздап жұмсартады). Үстіне грек жаңғағын сеуіп, бальзам сірке суын құйыңыз."]'::jsonb) WHERE id = 'cc18259a-201a-4dd4-83bd-d60fc14dccba';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Жасымық қосылған кәді спагеттиі'), description_kk = COALESCE(description_kk, 'Спагеттиге деген сағынышты басатын, өсімдік тектес ақуызға бай паста баламасы.

Пайдасы: Кәдінің арқасында көмірсуды мүлде тұтынбайсыз, ал жасымық өсімдік тектес темір мен талшық беріп, ас қорытуды жеңілдетеді.'), category_kk = COALESCE(category_kk, 'кешкі ас'), tags_kk = COALESCE(tags_kk, ARRAY['жалпы']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Кәді: 2 дана (спагетти тәрізді кесілген)","Қызыл жасымық: Жарты стақан (пісірілген)","Қызанақ, пияз, сарымсақ (тұздыққа)."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Пияз бен қызанақтан \"Болоньезе\" тәрізді тұздық дайындап, оған піскен жасымықты қосыңыз. Кәдіні табада 2 минут қуырып, тәрелкеге салыңыз да, үстіне жасымықты тұздықты молынан құйыңыз."]'::jsonb) WHERE id = 'a5b41661-394b-4403-8c11-ef8c670867ac';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Кемпірқосақ түсті жеміс ш串лары (3 жас+)'), description_kk = COALESCE(description_kk, 'Жеміс жеуді қызықты ойынға айналдыратын түрлі түсті әрі қауіпсіз ш串лар.

Пайдасы: Түрлі түсті жемістердің құрамында әртүрлі дәрумендер (C, K, антиоксиданттар) бар.'), category_kk = COALESCE(category_kk, 'Қосымша тағам'), tags_kk = COALESCE(tags_kk, ARRAY['general']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Құлпынай (қызыл), мандарин (қызғылт сары), банан (сары), киви (жасыл), көкжидек (көк/күлгін).","Балаларға арналған қауіпсіз, ұшы доғал пластик немесе ағаш ш串лар (таяқшалар)."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Жемістерді бала жей алатындай кішкентай текшелерге тураңыз. Оларды кемпірқосақ түстерінің ретімен ш串ларға тізіңіз."]'::jsonb) WHERE id = '0b4a6a47-3a40-4940-a2d5-e0a7260449ef';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Сарымсақ қосылған асшаян мен кәді'), description_kk = COALESCE(description_kk, 'Кафе немесе мейрамханадағыдай дәмді, бірақ калориясы өте аз теңіз өнімдерінен жасалған тағам.

Пайдасы: Асшаян мырыш пен йодқа бай (шаш пен тырнақты нығайтады). Өте жеңіл болғандықтан, кешкі асқа өте қолайлы.'), category_kk = COALESCE(category_kk, 'кешкі ас'), tags_kk = COALESCE(tags_kk, ARRAY['general']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Асшаян (тазартылған): 150 г","Кәді: 2 дана (спагетти тәрізді туралған)","Сары май (аздап) мен зәйтүн майының қоспасы.","Сарымсақ: 2 түйір (езілген), қызыл бұрыш үлпектері."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Табада май мен сарымсақты қыздырып, асшаяндарды салыңыз да, қызғылт түске енгенше (бар болғаны 3-4 минут) қуырыңыз. Кәдіні қосып, тағы 2 минут қуырыңыз. Үстіне лимон шырынын сығып, бірден дастарқанға ұсыныңыз."]'::jsonb) WHERE id = '71d8c222-1035-4fd0-929b-23c2b485af16';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Лаванда сүті'), description_kk = COALESCE(description_kk, 'Қарбалас күннен кейінгі күйзелісті басып, бөпедей тәтті ұйықтауға көмектесетін сиқырлы сусын.

Пайдасы: Лаванданың хош иісі мен дәмі жүйке жүйесін жылдам тыныштандырып, ұйқы сапасын жақсартады.'), category_kk = COALESCE(category_kk, 'Пайдалы сусындар'), tags_kk = COALESCE(tags_kk, ARRAY['general']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Бадам немесе сұлы сүті: 1 стақан","Кептірілген лаванда (аспаздық мақсатқа арналған): 1 шай қасық","Бал немесе агава шәрбаты: 1 шай қасық","Ваниль сығындысы: Бірнеше тамшы."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Сүтті кәстрөлде қыздырыңыз (қайнатпаңыз). Оған лаванда қосып, 5-10 минут демделуін күтіңіз. Сүзгіден өткізіп, стақанға құйыңыз. Бал мен ваниль қосып, жылы күйінде ішіңіз."]'::jsonb) WHERE id = '866a9373-a971-4ae1-bcb7-5c987dbcae3a';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Саумалдық пен жасыл бұршақ езбесі 
(8 ай+)'), description_kk = COALESCE(description_kk, 'Болашақтың мықты батырларына арналған темір мен ақуызға бай, түсімен назар аударатын тағам.

Пайдасы: Саумалдықтағы фолий қышқылы мен жасыл бұршақтағы ақуыз қарқынды өсуді қолдайды.'), category_kk = COALESCE(category_kk, 'Қосымша тағам'), ingredients_kk = COALESCE(ingredients_kk, '["Саумалдық: 1 уыс (тазартылған)","Балғын жасыл бұршақ: 1 ас қасық","Картоп: Жарты кішкентай дана","Сары май: Өте кішкентай бөлік (тұзсыз)."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Картоп пен жасыл бұршақты суға пісіріңіз. Пісуге аз қалғанда саумалдықты қосыңыз. Суын төгіп, сары май қосып, езбе күйіне келтіріңіз."]'::jsonb) WHERE id = 'fb03ef40-89b2-4c37-a867-f84dac70544e';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Көкжидек панкейкі
(9 ай+)'), description_kk = COALESCE(description_kk, 'Бөпе өз қолымен жей алатын (BLW), қимыл-қозғалыс дағдыларын дамытатын дәмді тағам.

Пайдасы: Көкжидек — ми қызметін ынталандыратын күшті антиоксидант. Қантсыз, ұнсыз, жұмсақ панкейк.'), category_kk = COALESCE(category_kk, 'Қосымша тағам'), tags_kk = COALESCE(tags_kk, ARRAY['baby_food']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Банан: 1 дана (піскен, езілген)","Жұмыртқаның сарысы: 1 дана (ағын 1 жасқа дейін беруге болмайды)","Көкжидек: 6-7 дана (ортасынан бөлінген)","Сұлы ұны: 1 ас қасық."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Бананды езіп, жұмыртқаның сарысы және ұнмен араластырыңыз. Туралған көкжидекті қосыңыз. Майсыз табаға қасықпен шағын дөңгелектер жасап құйып, екі жағын да пісіріңіз."]'::jsonb) WHERE id = 'e4dcec61-d668-42ad-9158-cfc7b2b1485d';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Даршын қосылған сұлы флет-уайты'), description_kk = COALESCE(description_kk, 'Қандағы қант (инсулин) деңгейін күрт көтермейтін, жеңіл әрі хош иісті кофе.'), category_kk = COALESCE(category_kk, 'Пайдалы сусындар'), tags_kk = COALESCE(tags_kk, ARRAY['general', 'milk_boost']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["1 кесе (шот) эспрессо, жарты стақан көпіршітілген сұлы сүті, 1 шай қасық даршын ұнтағы."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Эспрессоға ыстық, қою көбікті сұлы сүтін қосып, үстіне молынан даршын себіңіз."]'::jsonb) WHERE id = 'a3480015-30ca-4f9a-b8de-a642fd9a639c';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Құлпынай мен кешьюден жасалған чизкейк'), description_kk = COALESCE(description_kk, 'Сүт өнімдерін, ұн мен қантты қоспай дайындалатын керемет «Raw Vegan» чизкейк.

Пайдасы: Кешью қан қысымын реттеуге көмектеседі, ал құлпынай қартаюға қарсы әсері бар C дәруменіне бай.'), category_kk = COALESCE(category_kk, 'Пайдалы тәттілер'), tags_kk = COALESCE(tags_kk, ARRAY['general']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Негізі үшін: бадам, құрма (блендерде ұсақталған).","Крем үшін: 1.5 стақан кешью (түнге суға жібітілген), 1 стақан құлпынай, 3 ас қасық ерітілген кокос майы, агава шәрбаты."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Негізге арналған қоспаны қалыптың түбіне нығыздап салыңыз. Суы сорғытылған кешьюді құлпынай, май және шәрбатпен бірге блендерде біркелкі тегіс крем болғанша араластырыңыз. Негіздің үстіне құйып, мұздатқышта 4 сағат ұстаңыз."]'::jsonb) WHERE id = '64191934-b404-495f-b229-388b63914389';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Тәтті картоп пен алма езбесі (6 ай+)'), description_kk = COALESCE(description_kk, 'Бөпелердің тәтті дәмдерді жақсы көретінін ескерсек, бұл олардың ең сүйікті алғашқы тағамдарының біріне айналады.

Пайдасы: Тәтті картоп (батат) A дәрумені мен жасұныққа бай, ал алма ас қорытуды жеңілдетеді.'), category_kk = COALESCE(category_kk, 'Қосымша тағам'), tags_kk = COALESCE(tags_kk, ARRAY['baby_food']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Тәтті картоп: 1 кішкентай дана (қабығы аршылып, текшелеп туралған)","Тәтті алма: Жарты дана (қабығы аршылған)","Ана сүті немесе сүт қоспасы (сұйылту үшін)."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Тәтті картоп пен алманы буға немесе өте аз суға әбден жұмсарғанша пісіріңіз. Шанышқымен езіңіз немесе пюре жасаңыз. Жылы кезінде аздап ана сүтін қосып, қоюлығын реттеңіз."]'::jsonb) WHERE id = '27feef17-d812-4444-aa98-c2116d7d5049';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Сәбіз бен жасымық сорпасы
(8 ай+)'), description_kk = COALESCE(description_kk, 'Бөпені темірге бай тағаммен таныстыруға арналған дәмді, қызғылт сары түсті әрі іш кебуін тудырмайтын сорпа.

Пайдасы: Қызыл жасымық — өсімдік тектес ақуыз бен темірдің көзі. Ал сәбіз көздің дамуына қажетті бета-каротинге бай.'), category_kk = COALESCE(category_kk, 'Қосымша тағам'), tags_kk = COALESCE(tags_kk, ARRAY['baby_food']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Қызыл жасымық: 2 ас қасық (жақсылап жуылған)","Сәбіз: 1 кішкентай дана (үккіштен өткізілген)","Зәйтүн майы: 1 шай қасық."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Сәбіз бен жасымықты кішкентай кәстрөлге салып, бетін жабатындай су құйып, әбден жұмсарғанша қайнатыңыз. Блендерден өткізіп, үстіне 1 шай қасық тазартылмаған зәйтүн майын құйыңыз."]'::jsonb) WHERE id = '10778f55-a6f7-4dea-b6b5-e285d45babb5';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Кемпірқосақ ризоттосы (1 жас+)'), description_kk = COALESCE(description_kk, 'Шайнау дағдысын дамытатын, түрлі түсті дәндерге толы тойымды түскі ас.

Пайдасы: Көмірсулар, ақуыздар мен дәрумендер бір ыдыста үйлескен өте теңгерімді тағам.'), category_kk = COALESCE(category_kk, 'Қосымша тағам'), tags_kk = COALESCE(tags_kk, ARRAY['baby_food']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Домалақ дәнді күріш: 2 ас қасық (жақсылап жуылған)","Сәбіз, жасыл бұршақ, жүгері: әрқайсысынан 1 ас қасық (өте ұсақ туралған)","Сүйек немесе тауық сорпасы: 1 стақан","Сары май: өте аз мөлшерде."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Көкөністер мен күрішті сорпаға салып, толық жұмсарып, суын сіңіріп, ботқа (ризотто) тәрізді болғанша баяу отта пісіріңіз. Соңында сары май қосып, араластырыңыз."]'::jsonb) WHERE id = 'ec6cb7d9-6570-4500-be81-64329c0e4a07';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Салқын коко-эспрессо'), description_kk = COALESCE(description_kk, 'Тропикалық дәмдерді ұнататындарға арналған сергітетін, қантсыз жауһар сусын.'), category_kk = COALESCE(category_kk, 'Пайдалы сусындар'), tags_kk = COALESCE(tags_kk, ARRAY['general']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["1 кесе (shot) эспрессо, 1 стақан табиғи кокос суы (coconut water), мол мұз."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Стақанға мұзды салып, үстіне кокос суын құйыңыз. Екі түрлі түсті қабат пайда болуы үшін ең соңында эспрессоны баяу құйыңыз. Араластырып ішіңіз."]'::jsonb) WHERE id = '269778e2-5f1d-4cd3-b820-0a1898c7e6ea';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Кәдіден жасалған котлеттер (2 жас+)'), description_kk = COALESCE(description_kk, 'Көкөністерді панкейк/котлет түрінде ұсынып, баланың назарын аударатын дәмді тағам.

Пайдасы: Кәді мен көк шөптер талшыққа бай, ішектің жұмысын реттейді. Өте жұмсақ болғандықтан, шайнауға оңай.'), category_kk = COALESCE(category_kk, 'Қосымша тағам'), tags_kk = COALESCE(tags_kk, ARRAY['baby_food']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Кәді: 1 дана (үккіштен өткізіліп, суы толық сығылған)","Жұмыртқа: 1 дана","Ақ ірімшік немесе сүзбе: 1 ас қасық","Тұтас бидай ұны: 1-2 ас қасық."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Суы сығылған кәдіні жұмыртқа, ірімшік және ұнмен араластырып, қою қамыр дайындаңыз.","Май жағылған ыстық табаға қасықпен шағын дөңгелектер етіп салыңыз.","Екі жағын да алтын түсті реңкке енгенше пісіріңіз."]'::jsonb) WHERE id = 'b53735ed-6abe-4b68-b652-4d5d294d5553';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Авокадо мен жұмыртқа езбесі
(8 ай+)'), description_kk = COALESCE(description_kk, 'Пісіруді қажет етпейтін (жұмыртқадан басқа), таңертең аналардың уақытын үнемдейтін табиғи әрі нәрлі үйлесім.

Пайдасы: Екі керемет «суперфуд» бір тағамда. Авокадодағы Омега майлары мен жұмыртқаның сарыуызындағы холин ақыл-ой мен есте сақтау қабілетінің дамуына тікелей ықпал етеді.'), category_kk = COALESCE(category_kk, 'Қосымша тағам'), tags_kk = COALESCE(tags_kk, ARRAY['baby_food']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Қатты піскен жұмыртқаның сарыуызы: 1 дана","Авокадо: төрттен бір бөлігі (әбден піскен, өте жұмсақ)","Емшек сүті немесе сүт қоспасы."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Авокадо мен піскен жұмыртқаның сарыуызын ыдысқа салып, шанышқымен жақсылап езіңіз. Қоспа тым қою болса, бірнеше тамшы емшек сүтін немесе жылы су қосып, жұмсартыңыз."]'::jsonb) WHERE id = 'e39c8f3d-f865-4de6-8f5d-d3f60a5624c8';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Қызғылт пантера пастасы(1 жас+)'), description_kk = COALESCE(description_kk, 'Ашық түсімен балаларды қызықтыратын, ірімшік пен қызылшадан жасалған көңілді паста.

Пайдасы: Қызылша қан айналымын қолдайды, ал ірімшік — сүйектің дамуына қажетті кальцийдің мол көзі.'), category_kk = COALESCE(category_kk, 'Қосымша тағам'), tags_kk = COALESCE(tags_kk, ARRAY['baby_food']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Бөпелерге арналған макарон (ұсақ пішінді): 3-4 ас қасық","Қызылша езбесі (пісіріліп, езілген): 1 ас қасық","Сүзбе ірімшігі немесе кілегейлі ірімшік: 1 ас қасық"]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Макаронды әбден жұмсарғанша суға пісіріп, сүзіңіз. Ыстық макаронға қызылша езбесі мен ірімшікті қосып, жақсылап араластырыңыз. Макарон бірден ашық қызғылт түске боялады."]'::jsonb) WHERE id = 'dc9362af-ecb7-4bac-9ddf-d84bf1aa2f2d';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Пайдалы наггетстер(1 жас+)'), description_kk = COALESCE(description_kk, 'Дүкендегі наггетстерге пайдалы, пеште пісірілетін әрі қоспасыз балама.

Пайдасы: Таза тауық ақуызы мен сұлыдан жасалған талшықты қаптамасының арқасында бұл — нағыз қуат көзі.'), category_kk = COALESCE(category_kk, 'Қосымша тағам'), tags_kk = COALESCE(tags_kk, ARRAY['baby_food']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Тауықтың төс еті: 100 qr (блендермен тартылған немесе өте ұсақ туралған)","Сұлы ұны (немесе ұсақталған сұлы үлпегі): Аунату үшін","Жұмыртқа: 1 дана (шайқалған)","Тәтті қызыл ұнтақ бұрыш (паприка — ащы емес)."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Тауық етіне аздап паприка қосып, жақсылап илеңіз. Кішкентай бөліктерге бөліп, алдымен жұмыртқаға, содан кейін сұлы ұнына батырыңыз. Пісіру қағазы төселген табада, пеште 180 градуста 20 минут пісіріңіз."]'::jsonb) WHERE id = '732a8d20-182d-45bb-9171-f30bbd4cd142';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Қоян пішінді печенье (2 жастан бастап)'), description_kk = COALESCE(description_kk, 'Қантсыз, кәдімгі печеньенің орнына ұсынуға болатын қытырлақ әрі өте пайдалы үй печеньесі.

Пайдасы: Талшыққа бай сұлы мен дәруменді сәбіз баланың ас қорытуын жақсартады. Дүкен печеньелеріне ең пайдалы балама.'), category_kk = COALESCE(category_kk, 'Қосымша тағам'), tags_kk = COALESCE(tags_kk, ARRAY['baby_food']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Сұлы үлпегі: 1 стақан","Сәбіз: 1 дана (үккіштен өткізілген)","Алма езбесі: Жарты стақан (алманы пісіріп, езіңіз, ол тәтті дәм береді)","Мейіз (өте ұсақ туралған): 1 ас қасық","Сары май: 1 ас қасық (ерітілген)."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Барлық қоспаны терең ыдысқа салып, жақсылап илеңіз.","Қолыңызбен кішкентай жалпақ печенье пішінін жасаңыз (немесе жануар пішінді қалыптарды қолданыңыз).","170 градустық пеште 15-20 минут, сәл қызарғанша пісіріңіз."]'::jsonb) WHERE id = '7cc7ac25-0798-468f-82c0-6764afc0cd4f';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Шағын бургерлер (3 жастан бастап)'), description_kk = COALESCE(description_kk, 'Фастфудқа деген әуестікті басатын, 100% үйде дайындалған пайдалы шағын бургерлер.

Пайдасы: Үйде тартылған таза ет ақуыз бен темірге, ал тұтас бидайдан жасалған нан В дәруменіне бай.'), category_kk = COALESCE(category_kk, 'Қосымша тағам'), tags_kk = COALESCE(tags_kk, ARRAY['baby_food']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Тұтас бидай ұнынан жасалған шағын бургер тоқаштары: 2 дана","Майсыз тартылған сиыр еті: 100 гр","Голланд ірімшігі: 1-2 жұқа тілім","Қызанақ пен салат жапырағы","Зәйтүн майы."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Тартылған еттен тоқаштың көлеміндей жұқа әрі жалпақ котлеттер жасап, табада аз мөлшердегі майға қуырыңыз. Тоқаштардың арасына котлет, ірімшік, қызанақ пен салат жапырағын салып, шағын бургерлерді құрастырыңыз."]'::jsonb) WHERE id = 'e6d245f4-3ec1-4650-92fc-b0b877ba16f0';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Пеште пісірілген көкөніс таяқшалары (3 жастан бастап)'), description_kk = COALESCE(description_kk, 'Классикалық фри картобының орнына ұсынуға болатын түрлі түсті, қытырлақ көкөніс таяқшалары.

Пайдасы: Тәтті картоп пен сәбіз — А дәруменінің мол көзі. Майға қуырылмайтындықтан, құрамында трансмайлар жоқ.'), category_kk = COALESCE(category_kk, 'Қосымша тағам'), tags_kk = COALESCE(tags_kk, ARRAY['baby_food']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Тәтті картоп (батат): 1 дана","Сәбіз: 1 үлкен дана","Зәйтүн майы: 1 ас қасық","Өте аз мөлшерде тұз және тәтті қызыл бұрыш ұнтағы (паприка)."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Көкөністерді бірдей көлемдегі ұзынша таяқшалар (фри) түрінде тураңыз. Зәйтүн майы және дәмдеуіштермен араластырып, пісіруге арналған қағаздың үстіне тізіңіз. 200 градуста 20-25 минут, шеттері қытырлақ болғанша пісіріңіз."]'::jsonb) WHERE id = '705fa4d6-de4b-4c10-bc6c-46c0cc463f11';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Таңқурайлы аю тостағаны (2 жас+)'), description_kk = COALESCE(description_kk, 'Тіскебасарға немесе таңғы асқа арналған, балмұздақ әсерін беретін көңілді смузи тостағаны.

Пайдасы: Қою йогурт пробиотиктерге бай (иммунитетті нығайтады), ал жидектер — антиоксиданттардың мол көзі.'), category_kk = COALESCE(category_kk, 'Қосымша тағам'), tags_kk = COALESCE(tags_kk, ARRAY['baby_food']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Қою йогурт: 3 ас қасық","Мұздатылған таңқурай немесе құлпынай: 1 уыс","Банан: Жарты дана (йогуртпен араластыру үшін)","Безендіру үшін: Банан тілімдері, көкжидек (аюдың бетін жасау үшін)."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Йогуртты, жарты бананды және мұздатылған жидектерді блендерде біркелкі әрі қою крем болғанша араластырыңыз.","Тостағанға құйыңыз.","Екі банан тілімінен аюдың құлақтарын, ал көкжидектен көзі мен мұрнын жасаңыз."]'::jsonb) WHERE id = 'b83ce14e-ac83-4541-a4e8-d4b8fa3d176e';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Пайдалы қара мокка'), description_kk = COALESCE(description_kk, 'Кофе мен шоколадтың дәмін бір уақытта сезінгісі келетіндерге арналған шәрбатсыз балама.'), category_kk = COALESCE(category_kk, 'Пайдалы сусындар'), tags_kk = COALESCE(tags_kk, ARRAY['general']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["1 кесе эспрессо, 1 шай қасық таза какао, 1 шай қасық бал, 1 стақан жылы бадам сүті."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Ыстық эспрессоға какао мен балды ерітіңіз. Үстіне жылы, көбіктелген бадам сүтін қосыңыз."]'::jsonb) WHERE id = 'fdd5be2e-2d65-464b-84d3-084f637ea16e';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Күлімдеген пиццалар (2 жас+)'), description_kk = COALESCE(description_kk, '2 жастағы балаңыз Сізге дайындауға көмектесе алатын көңілді әрі пайдалы пицца.

Пайдасы: Үйде дайындалатындықтан, құрамында қоспалар жоқ. Күлімдеген бет пішіні баланың тағаммен жағымды эмоциялық байланыс орнатуына көмектеседі.'), category_kk = COALESCE(category_kk, 'Қосымша тағам'), tags_kk = COALESCE(tags_kk, ARRAY['baby_food']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Тұтас бидай ұнынан жасалған шағын пита наны (немесе кішкентай жұқа нан): 1 дана","Қызанақ езбесі (үйде дайындалған, қантсыз): 1 ас қасық","Моцарелла ірімшігі: 2 ас қасық үгітілген","Қара зәйтүн сақиналары (көздері үшін) және қызыл бұрыш жолағы (аузы үшін)."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Пита нанының үстіне қызанақ езбесін жағыңыз.","Үстіне ірімшікті молынан себіңіз.","Зәйтүн мен бұрыштан \"күлімдеген бет\" жасаңыз. Ірімшік ерігенше пеште (шамамен 5-7 минут) пісіріңіз."]'::jsonb) WHERE id = 'b7520537-fae1-481b-9bea-7a9cf32f15f7';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Қонжық пішінді тост (3 жас+)'), description_kk = COALESCE(description_kk, 'Таңғы ас кезінде көңіл-күйіңізді көтеретін, небәрі 2 минутта дайын болатын дәмді тағам.

Пайдасы: Жержаңғақ пастасының құрамында миға пайдалы майлар мен ақуыз бар. Ал банан қуат береді.'), category_kk = COALESCE(category_kk, 'Қосымша тағам'), tags_kk = COALESCE(tags_kk, ARRAY['baby_food']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Шаршы пішінді тұтас дәнді нан: 1 тілім (қуырылған)","Жержаңғақ пастасы: 1 ас қасық","Банан: 3 дөңгелек тілім","Көкжидек: 3 дана."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Қуырылған нанның бетіне жержаңғақ пастасын жағыңыз. Бананның екі тілімін құлақ етіп жоғарғы шеттеріне, ал біреуін мұрын тұсына қойыңыз. Көкжидектерден көздері мен мұрнының ұшын жасаңыз."]'::jsonb) WHERE id = '36867e84-3459-4059-a668-70f297e35576';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Құпия бақ маффиндері (3 жас+)'), description_kk = COALESCE(description_kk, 'Құрамында ірімшік пен көкөністер бар, саябаққа немесе сапарға алып шығуға өте ыңғайлы тұзды кекстер.

Пайдасы: Қантсыз. Бала қолына ұстап, шашпай жей алатындай ыңғайлы, ал құрамы минералдар мен кальцийге бай.'), category_kk = COALESCE(category_kk, 'Қосымша тағам'), tags_kk = COALESCE(tags_kk, ARRAY['baby_food']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Жұмыртқа: 2 дана","Йогурт: 2 ас қасық","Сәбіз (үгітілген) және брокколи (өте ұсақ туралған): Жарты стақан","Ақ ірімшік: 2 ас қасық (ұсақталған)","Тұтас бидай ұны және қамыр қопсытқыш."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Сұйық ингредиенттерді шайқаңыз. Көкөністер мен ірімшікті қосыңыз. Ұн мен қамыр қопсытқышты араластырып, қою кекс қамырын дайындаңыз. Маффин қалыптарына құйып, 180 градуста 20-25 минут бойы көтеріліп, қызарғанша пісіріңіз."]'::jsonb) WHERE id = 'ecfe7439-ff4e-4167-ab7a-c45d91fa903c';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Ұшатын табақша пиццалары (4 жас+)'), description_kk = COALESCE(description_kk, 'Қамырдың орнына саңырауқұлақ қалпақшаларынан дайындалатын, глютенсіз әрі көңілді шағын пиццалар.

Пайдасы: Портобелло немесе ірі шампиньон саңырауқұлақтары D дәруменіне бай. Баланы саңырауқұлақ жеуге үйретудің тамаша тәсілі.'), category_kk = COALESCE(category_kk, 'Қосымша тағам'), tags_kk = COALESCE(tags_kk, ARRAY['baby_food']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Ірі шампиньон саңырауқұлақтары: 4-5 дана (сабақтары алынып тасталған)","Томат пастасы: 2 ас қасық","Моцарелла ірімшігі: 3 ас қасық (үгітілген)","Жүгері немесе зәйтүн."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Саңырауқұлақтардың ішіне томат пастасын жағыңыз. Үстіне ірімшік пен жүгері дәндерін салыңыз. 180 градустық пеште ірімшік еріп, саңырауқұлақтар жұмсарғанша (шамамен 15 минут) пісіріңіз."]'::jsonb) WHERE id = '0a108d2a-2483-496b-8459-a35dba184122';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Таңғы кемпірқосақ (4 жас+)'), description_kk = COALESCE(description_kk, 'Шағын құймақтар мен жемістерден жасалған, қолмен жеуге ыңғайлы таңғы ас.

Пайдасы: Әртүрлі жемістер — әртүрлі дәрумендердің көзі. Шағын кәуаптар балалардың ұсақ моторикасын дамытып, тағамға қызығушылығын арттырады.'), category_kk = COALESCE(category_kk, 'Қосымша тағам'), tags_kk = COALESCE(tags_kk, ARRAY['baby_food']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Шағын құймақтар: Тиын көлеміндей етіп пісірілген","Құлпынай, дөңгелектеп туралған банан, тілімделген киви.","Ұшы доғал ағаш таяқшалар."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Таяқшаларға кезекпен шағын құймақ, құлпынай, банан, қайтадан құймақ пен киви өткізіңіз. Жанына балға немесе пекмезге батырып жеуге арналған шағын ыдыс қойыңыз."]'::jsonb) WHERE id = 'bb88a8d3-5c23-4d20-8927-32de71e35006';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Балық котлеттері (4 жас+)'), description_kk = COALESCE(description_kk, 'Балықты ұнатпайтын балалар да қызықты пішініне елітіп, сүйсініп жейтін Омега-3 көзі.

Пайдасы: Албырт мидың жұмысын және есте сақтау қабілетін жақсартады.'), category_kk = COALESCE(category_kk, 'Қосымша тағам'), ingredients_kk = COALESCE(ingredients_kk, '["Албырт (сомга) сүбесі: 100 qr (пісірілген, талшықтарға бөлінген)","Картоп: 1 дана (пісіріліп, езілген)","Аскөк: Өте аз (ұсақтап туралған)"]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Езілген картопты, балық пен аскөкті араластырып, жақсылап илеңіз. Қоспаны пісіруге арналған қағаздың үстіне жайып, жұлдыз пішінді қалыппен кесіңіз. Табада немесе пеште сәл қызарғанша пісіріңіз."]'::jsonb) WHERE id = '94068d6c-ec4c-4f36-a84e-fdd44212d93d';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Ғарыш пастасы (5 жас+)'), description_kk = COALESCE(description_kk, 'Жұлдыздар мен көбелектерді елестететін пішінді макароннан жасалған, кілегейлі ірімшік қосылған ғарыш тағамы.

Пайдасы: Түрлі түсті көкөністер (асбұршақ, жүгері) тағамның дәрумендік құндылығын арттырады, ал қантсыз йогурт пен ірімшік соусы асқазанға ауырлық түсірмейді.'), category_kk = COALESCE(category_kk, 'Қосымша тағам'), tags_kk = COALESCE(tags_kk, ARRAY['baby_food']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Глютенсіз көбелек пішінді макарон (Farfalle) немесе түрлі түсті макарон: 1 стақан","Жасыл асбұршақ пен жүгері: Әрқайсысы 1 ас қасық","Черри қызанағы: 3-4 дана (екіге бөлінген)","Кілегейлі ірімшік (немесе сүзілген йогурт): 1 ас қасық."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Макаронды әбден жұмсарғанша қайнатып, суын сүзіңіз (суынан аздап қалдырыңыз). Ыстық макаронға кілегейлі ірімшікті, асбұршақты, жүгері мен қызанақты қосып араластырыңыз. Ірімшік еріп, қою әрі жұмсақ соусқа айналады."]'::jsonb) WHERE id = 'f234c77f-4a04-4526-9394-c82a1bc713cf';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Сиқырлы балабақша кекстері (4 жастан бастап)'), description_kk = COALESCE(description_kk, 'Саябаққа, балабақшаға немесе жолға алып жүруге ыңғайлы, құрамында мол ірімшік пен көкөніс жасырылған тұзды кекстер.

Пайдасы: Қантсыз. Кальций (ірімшік) мен дәрумендер (көкөністер) бір тағамда үйлескен, қолға ұстап жеуге ыңғайлы.'), category_kk = COALESCE(category_kk, 'Қосымша тағам'), tags_kk = COALESCE(tags_kk, ARRAY['baby_food']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Жұмыртқа: 2 дана","Айран: 2 ас қасық","Сәбіз (үгітілген) және кәді (суы сығылған): Жарты стақан","Ақ ірімшік: 2 ас қасық","Ұн және қопсытқыш."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Сұйық ингредиенттер мен ірімшікті араластырып, жақсылап шайқаңыз. Көкөністерді қосыңыз. Соңында ұн мен қопсытқышты араластырып, маффин қалыптарына құйып, 180 градуста 20-25 минут пісіріңіз."]'::jsonb) WHERE id = '4232cb2b-2881-4a46-bce4-1d4070cda869';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Сиқырлы сусын (5 жастан бастап)'), description_kk = COALESCE(description_kk, 'Таңғы асқа немесе десертке арналған, мөлдір стақанға қабаттап дайындалатын көз тартарлық дәмді тағам.

