UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Дзен лимонады'), description_kk = COALESCE(description_kk, 'Жаз күндері зат алмасуды жылдамдатып, іштің кебуін азайтатын газдалған матча.'), category_kk = COALESCE(category_kk, 'Пайдалы сусындар'), tags_kk = COALESCE(tags_kk, ARRAY['general']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["1 шай қасық матча ұнтағы, жарты лимонның шырыны, 1 шай қасық агава шәрбаты немесе бал, 1 стақан минералды (газдалған) су, жалбыз жапырақтары, мұз."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Матчаны аз мөлшердегі суға бал және лимон шырынымен қосып, жақсылап араластырып ерітіңіз. Стақанға мұз бен жалбыз салып, үстіне матча қоспасы мен минералды су құйыңыз."]'::jsonb) WHERE id = '2e2ead49-bcaf-4338-94ee-467ad791737c';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Кокос пен матча ләззаты'), description_kk = COALESCE(description_kk, 'Теріні іштен ылғалдандыратын, жұмсақ дәмді әрі тропикалық жылы сусын.'), category_kk = COALESCE(category_kk, 'Пайдалы сусындар'), tags_kk = COALESCE(tags_kk, ARRAY['жалпы']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["1 шай қасық матча ұнтағы, 1 стақан кокос сүті, 1 шымшым ваниль сығындысы."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Кокос сүтін кәстрөлде бу шыққанша қыздырыңыз (қайнатпаңыз). Ваниль мен матчаны қосып, арнайы шайқағышпен (немесе капучинатормен) көбіктендіріңіз."]'::jsonb) WHERE id = 'f005b3c3-1f74-4e4e-bab7-c8bc5e03c14a';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Жалбызды матча-фраппе'), description_kk = COALESCE(description_kk, 'Қантты «фраппучиноларға» 100% табиғи, кофеинсіз әрі сергітетін балама.'), category_kk = COALESCE(category_kk, 'Пайдалы сусындар'), tags_kk = COALESCE(tags_kk, ARRAY['жалпы']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["1 шай қасық матча, 1 мұздатылған банан, 3-4 балғын жалбыз жапырағы, жарты стақан сұлы сүті."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Барлық ингредиентті блендерде балмұздақ тәрізді қою консистенцияға (фраппе) жеткенше жоғары жылдамдықпен араластырыңыз."]'::jsonb) WHERE id = 'e8f085b1-b955-46e7-bd90-9c504005461c';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Дәмдеуіш қосылған какао'), description_kk = COALESCE(description_kk, 'Зат алмасуды «жандандырып», қан айналымын жақсартатын көне рецепт.'), category_kk = COALESCE(category_kk, 'Пайдалы сусындар'), tags_kk = COALESCE(tags_kk, ARRAY['жалпы']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["1 ас қасық таза какао, 1 шымшым даршын, өте аз (пышақтың ұшымен) ащы қызыл бұрыш ұнтағы (кайен бұрышы), 1 стақан ыстық орман жаңғағы сүті, бал."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Ыстық сүтке какао мен дәмдеуіштерді қосып, толық ерігенше араластырыңыз. Ащы және тәтті дәмнің үйлесімі бойыңызды жылытады."]'::jsonb) WHERE id = '692f8fd9-2a1f-4e6e-90a2-3450b555119d';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Қытырлақ балық түйіршіктері (5 жас+)'), description_kk = COALESCE(description_kk, 'Тіпті балық жегісі келмейтін 5 жастағы балаларды да қызықтыратын, қызғылт-сары түсті қытырлақ балық текшелері.

Пайдасы: Ақ балық — фосфордың, йодтың және оңай сіңетін ақуыздың көзі. Зияткерлік дамуға өте пайдалы.'), category_kk = COALESCE(category_kk, 'Қосымша тағам'), tags_kk = COALESCE(tags_kk, ARRAY['бөпе_тамағы']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Ақ балықтың сүбесі (мысалы, нәлім, сибас): 150 qr (текшелеп туралған және сүйексіз)","Жұмыртқа: 1 дана","Қантсыз жүгері үлпектері (корнфлекс) немесе кепкен нан ұнтағы: Аунатып алу үшін"]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Жүгері үлпектерін қолыңызбен ұсақтаңыз. Балық текшелерін алдымен шайқалған жұмыртқаға, содан кейін жүгері үгінділеріне батырыңыз. Майлы қағаз төселген табада 180 градуста 15-20 минут пісіріңіз."]'::jsonb) WHERE id = 'fe1e3f3e-8c82-4bdd-8cb3-2212d66df10f';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Қытырлақ алма сэндвичтері (5 жас+)'), description_kk = COALESCE(description_kk, 'Нанның орнына алма тілімдері қолданылатын, мектептен немесе балабақшадан кейін жеуге арналған қуат беретін тіскебасар.

Пайдасы: Алмадағы пектин талшықтары мен жержаңғақ пастасындағы ақуыз ұзақ уақыт тоқтық сезімін сақтап, тәттіге деген қажеттілікті табиғи түрде қанағаттандырады.'), category_kk = COALESCE(category_kk, 'Қосымша тағам'), tags_kk = COALESCE(tags_kk, ARRAY['бөпе_тамағы']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Үлкен алма: 1 дана (өзегі алынған, сақина түрінде кесілген)","Жержаңғақ немесе бадам пастасы (қантсыз): 2 ас қасық","Мейіз немесе шоколад тамшылары (арасына салу үшін)."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Екі алма сақинасының біріне жержаңғақ пастасын жағып, үстіне мейіздерді орналастырыңыз да, екінші сақинаны сэндвич сияқты жабыңыз. Балаға ұстауға ыңғайлы болуы үшін ортасынан кесуге болады."]'::jsonb) WHERE id = '2f4202ed-6015-4318-b0d0-ac257ccd10af';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Кардамон қосылған Cold Brew'), description_kk = COALESCE(description_kk, 'Қыжыл тудырмайтын, қышқылдығы өте төмен және ас қорытуды жеңілдететін салқын кофе.'), category_kk = COALESCE(category_kk, 'Пайдалы сусындар'), tags_kk = COALESCE(tags_kk, ARRAY['жалпы']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["1 стақан Cold Brew (суық тәсілмен демделген кофе), 1-2 дана кардамон (ұсақталған), мұз, қалауыңызға қарай аздап өсімдік сүті."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Кофені демдеу (немесе сүзу) кезінде оған ұсақталған кардамон дәндерін қосыңыз. Мол мұзбен ұсыныңыз. Кардамон кофеге өте \"керемет\" әрі ерекше хош иіс береді."]'::jsonb) WHERE id = '75bdd91d-7aed-40d8-9434-8c6ca0198e19';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Мака мен какаодан қуат беретін сусын'), description_kk = COALESCE(description_kk, 'Гормондық тепе-теңдікті қолдап, физикалық төзімділікті арттыратын әйелдерге пайдалы сусын.'), category_kk = COALESCE(category_kk, 'Пайдалы сусындар'), tags_kk = COALESCE(tags_kk, ARRAY['жалпы']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["1 ас қасық какао, 1 шай қасық мака (maca) ұнтағы, 1 стақан сұлы сүті, 1 дана құрма (езбе түрінде)."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Барлық ингредиентті блендерде (ыстық немесе салқын сүтпен) біркелкі болғанша араластырыңыз."]'::jsonb) WHERE id = 'da26b0d3-2e6e-4084-9b19-693dd01e5caa';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Пайдалы Nutella сусыны'), description_kk = COALESCE(description_kk, 'Тәттіге деген құмарлықты басатын, бірақ құрамында мүлде қант жоқ ыстық әрі дәмді сусын.'), category_kk = COALESCE(category_kk, 'Пайдалы сусындар'), tags_kk = COALESCE(tags_kk, ARRAY['жалпы']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["1 ас қасық какао, 1 ас қасық табиғи орман жаңғағы езбесі (қантсыз), 1 стақан ыстық сүт."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Орман жаңғағы езбесі мен какаоны ыстық сүтке қосып, блендермен немесе көпірткішпен әбден біркелкі болғанша араластырыңыз."]'::jsonb) WHERE id = '1c2d3ae5-c16d-47ab-acbd-eff8a82af792';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Ноқатпен толтырылған батат'), description_kk = COALESCE(description_kk, 'Спортшылар мен дұрыс тамақтанатын жандарға арналған, ұзақ уақыт тоқтық сезімін сақтайтын күрделі көмірсуларға бай классикалық түскі ас.

Пайдасы: Батат калийге, ал ноқат өсімдік ақуызына бай. Бұл — нағыз қуат көзі.'), category_kk = COALESCE(category_kk, 'жалпы'), tags_kk = COALESCE(tags_kk, ARRAY['жалпы']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Тәтті картоп (батат): 2 дана (орташа)","Піскен ноқат (консервіленгені де болады): 1 стақан","Тахини (күнжіт езбесі): 2 ас қасық","Лимон шырыны, зәйтүн майы, зире."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Бататтарды шанышқымен бірнеше жерден тесіп, пеште (200 градус) әбден жұмсарғанша пісіріңіз (шамамен 40 минут). Пештен шығарып, ортасынан кесіңіз де, ішін аздап езіңіз. Үстіне дәмдеуіштер қосылған ноқатты салып, тахини мен лимоннан жасалған тұздықты құйыңыз."]'::jsonb) WHERE id = '1eca4e78-4116-42f3-b2fa-fb5f13684582';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Гүлді қырыққабат палауы'), description_kk = COALESCE(description_kk, 'Кето және көмірсуы аз диеталардың басты тағамы. Күрішті 100% алмастыратын әрі мүлде артық салмақ қоспайтын рецепт.

Пайдасы: Бір порциясында небәрі 40-50 калория бар. Кәдімгі күріш палауы сияқты ауырлық пен ұйқышылдық сезімін тудырмайды.'), category_kk = COALESCE(category_kk, 'жалпы'), tags_kk = COALESCE(tags_kk, ARRAY['жалпы']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Гүлді қырыққабат: Жарты бас","Сәбіз және жасыл бұршақ: Әрқайсысы 2 ас қасықтан","Пияз: 1 кішкентай бас","Зәйтүн майы және сары май."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Гүлді қырыққабатты үккіштен өткізіп немесе блендермен күріш түйіршіктеріндей етіп ұсақтаңыз. Табада пиязды, сәбізді және бұршақты аз мөлшердегі майға қуырыңыз. Үстіне қырыққабат «күрішін» қосып, араластыра отырып 5-6 минут (тым жұмсарып кетуіне жол бермей) қуырыңыз."]'::jsonb) WHERE id = '836bc22f-3cef-4e15-bfd2-c877bc04f782';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Кілегейлі брокколи және чеддер сорпасы'), description_kk = COALESCE(description_kk, 'Американың "Panera Bread" мейрамханалар желісі арқылы танымал болған, әлемдегі ең дәмді қысқы сорпалардың бірі.

Пайдасы: Үй жағдайында дайындалғанда кальций мен тағамдық талшыққа бай, сүйекті нығайтатын нағыз пайдалы сорпаға айналады.'), category_kk = COALESCE(category_kk, 'жалпы'), tags_kk = COALESCE(tags_kk, ARRAY['жалпы']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Брокколи: 300 qr (өте ұсақ туралған)","Сәбіз: 1 дана (үккіштен өткізілген)","Чеддер (Cheddar) ірімшігі: 1 кесе (үккіштен өткізілген)","Тауық немесе көкөніс сорпасы: 3 кесе","Кілегей немесе сүт: Жарты кесе."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Сәбіз бен брокколиді сорпада жұмсарғанша пісіріңіз (блендермен жартылай ұсақтап, ішінде түйіршіктер қалдырыңыз). Сүтті/кілегейді қосыңыз. Оттан алып, ыстық сорпаға үккіштен өткізілген чеддер ірімшігін қосып, ерігенше араластырыңыз."]'::jsonb) WHERE id = 'c8f59b0c-497f-493b-9f85-c45a2583194f';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Мексика үлгісіндегі киноа салаты'), description_kk = COALESCE(description_kk, 'Батыс әлеміндегі "Meal Prep" (тағамды алдын ала дайындау) мәдениетінің ең танымал өкілдерінің бірі.

Пайдасы: Түрлі-түсті, тойымды және өсімдік ақуызына өте бай. Тоңазытқышта 3 күн бойы балғын күйінде сақталады.'), category_kk = COALESCE(category_kk, 'жалпы'), tags_kk = COALESCE(tags_kk, ARRAY['жалпы']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Киноа (піскен): 1 кесе","Қара үрмебұршақ (консервіленген): Жарты кесе","Жүгері: Жарты кесе","Черри қызанағы және қызыл пияз (туралған)","Балғын күнзе, лайм шырыны, зәйтүн майы, халапеньо бұрышы (қалауыңызша)."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Барлық азық-түлікті үлкен ыдыста араластырыңыз. Зәйтүн майы, лайм шырыны және күнзеден дайындалған тұздықты үстіне құйып, жақсылап араластырыңыз."]'::jsonb) WHERE id = 'a5af4229-e447-48cc-a6f1-6146ae4643a0';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Авокадо қосылған брауни'), description_kk = COALESCE(description_kk, 'Сары майдың орнына авокадо, бидай ұнының орнына бадам ұны қолданылатын керемет «қантсыз брауни».

Пайдасы: Құрамында ұн мен тазартылған қант жоқ. Авокадо тәттіге ерекше ылғалдылық пен барқыттай жұмсақ құрылым береді, ал дәмі мүлде сезілмейді.'), category_kk = COALESCE(category_kk, 'жалпы'), tags_kk = COALESCE(tags_kk, ARRAY['жалпы']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Авокадо: 1 үлкен дана (толық піскен, езбе түрінде)","Бадам ұны: Жарты стақан","Табиғи какао (қантсыз): Жарты стақан","Жұмыртқа: 2 дана","Бал немесе үйеңкі шәрбаты: Стақанның үштен бірі."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Барлық ингредиентті блендерде біркелкі шоколадты крем болғанша араластырыңыз. Қоспаны пергамент қағазы төселген төртбұрышты кекс пішініне құйып, 175 градуста 25-30 минут пісіріңіз. Жылы күйінде тілімдерге бөліңіз."]'::jsonb) WHERE id = '64fd534a-ee42-4741-ad1d-2c83048a4d5e';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Авокадо қосылған жұмыртқа қайықшалары'), description_kk = COALESCE(description_kk, 'Майонезсіз дайындалатын, кетогендік әрі ақуызға бай дәмді тағам.

Пайдасы: Жұмыртқа ақуызындағы протеин мен авокадодағы Омега май қышқылдары ойдың тұмандануын азайтып, қуатты қалпына келтіреді.'), category_kk = COALESCE(category_kk, 'жалпы'), tags_kk = COALESCE(tags_kk, ARRAY['жалпы']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Қатты піскен жұмыртқа: 3 дана","Авокадо: Жарты дана (піскен)","Зығыр тұқымы немесе чиа: Өте аз мөлшерде (үстіне себу үшін)","Лимон шырыны, тұз, қара бұрыш."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Жұмыртқаларды ұзынынан екіге бөліңіз. Сарысын алып, авокадо, лимон шырыны және дәмдеуіштермен бірге біркелкі крем болғанша езіңіз. Жасыл кремді жұмыртқа ақтарының ішіне қайта толтырыңыз. Үстіне зығыр тұқымын себіңіз."]'::jsonb) WHERE id = 'c93f159c-1f03-4766-a5e7-3350ed9505bf';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Бадам, зығыр және чиа қосылған түйіршіктер'), description_kk = COALESCE(description_kk, 'Пісірмей дайындалатын, жаттығу алдында немесе кофемен бірге жеуге арналған қытырлақ қуат түйіршіктері.

Пайдасы: Үш супертағамның (бадам, зығыр, чиа) күшін біріктіреді. Жылдам қуат береді әрі жасұнық пен минералдарға бай.'), category_kk = COALESCE(category_kk, 'жалпы'), tags_kk = COALESCE(tags_kk, ARRAY['жалпы']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Бадам пастасы (қантсыз): Жарты стақан","Зығыр тұқымы (ұнтақталған): 2 ас қасық","Чиа тұқымы: 1 ас қасық","Сұлы: Жарты стақан","Бал немесе агава шәрбаты: 2 ас қасық."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Барлық ингредиентті ыдысқа салып, жабысқақ масса болғанша илеңіз. Қолыңызбен жаңғақ көлеміндей түйіршіктер жасап, тоңазытқышқа қойып қатырыңыз. Қалтада немесе сөмкеде алып жүруге өте ыңғайлы."]'::jsonb) WHERE id = '0160a14d-2320-433d-b86d-228b4fe1defc';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Бадамды кето-кекс'), description_kk = COALESCE(description_kk, 'Өзін жеңіл, бұлт үстінде жүргендей сезінгісі келетіндерге арналған көмірсусыз кекс.

Пайдасы: Құрамында глютен, бидай ұны және қант жоқ. Әсіресе диета кезінде тәттіге деген құмарлықты қауіпсіз түрде басады.'), category_kk = COALESCE(category_kk, 'жалпы'), tags_kk = COALESCE(tags_kk, ARRAY['жалпы']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Бадам ұны: 1.5 стақан","Жұмыртқа: 3 дана","Бадам сүті: Стақанның төрттен бірі","Үгітілген лимон қабығы немесе ваниль.","Стевия немесе өте аз мөлшерде бал (тәтті дәм беру үшін)."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Сұйық ингредиенттерді шайқап, үстіне бадам ұнын қосып араластырыңыз. Кекс (маффин) қалыптарына құйып, 175 градуста 20 минут қызарғанша пісіріңіз."]'::jsonb) WHERE id = '9ef68860-bc8e-4727-a11e-6e5469f057ef';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Грек сувлакиі және цацики'), description_kk = COALESCE(description_kk, 'Жерорта теңізі диетасының жауһары: таза ақуыз, пробиотиктер және пайдалы майлар.

Пайдасы: Цацики (йогурт пен қиярдан жасалған тұздық) ішек микрофлорасын сақтауға көмектеседі. Ал тауық еті ағзаны ақуызбен қамтамасыз етіп, зат алмасуды жылдамдатады.'), category_kk = COALESCE(category_kk, 'жалпы'), tags_kk = COALESCE(tags_kk, ARRAY['жалпы']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Тауықтың төс еті: 200 qr (текшелеп туралған, лимон және тасшөппен маринадталған)","Сүзбе йогурт (грек йогурты): 4 ас қасық","Қияр: 1 дана (үккіштен өткізіліп, суы толық сығылған)","Балғын жалбыз, сарымсақ, зәйтүн майы."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Тауық етін ағаш істіктерге тізіп, табада немесе грильде қуырыңыз. Цацики тұздығы үшін йогуртты, суы сығылған қиярды, сарымсақты, жалбызды және зәйтүн майын араластырыңыз. Тауық кәуабын осы салқын тұздыққа батырып жеңіз."]'::jsonb) WHERE id = 'e067e84f-8a22-4eb0-b5fa-1ae3ae37b95f';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Француз рататуйі'), description_kk = COALESCE(description_kk, 'Оңтүстік Францияның түрлі-түсті, толығымен веган әрі көрікті көкөніс тағамы.

Пайдасы: Калориясы аз, ал жасұнық пен дәрумендерге бай. Барлық көкөністің өз шырынында баяу пісуі олардың тағамдық құндылығын сақтайды.'), category_kk = COALESCE(category_kk, 'жалпы'), tags_kk = COALESCE(tags_kk, ARRAY['жалпы']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Кәді, баялды, қызанақ: Әрқайсысы 2 дана (бірдей көлемде, өте жұқа дөңгелектеп туралған)","Томат пастасы және сарымсақ (астыңғы тұздық үшін).","Прованс шөптері (тасшөп, гүлшетен), зәйтүн майы."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Дөңгелек пеш қалыбының түбіне қызанақ тұздығын жағыңыз. Туралған көкөністерді түс ретімен (баялды, қызанақ, кәді) қалыптың шетінен ортасына қарай шиыршық түрінде орналастырыңыз. Үстіне шөптерді сеуіп, май құйыңыз да, бетін жауып, 190 градуста 45 минут пісіріңіз."]'::jsonb) WHERE id = '3a7875bd-9bf1-4570-9e1d-e51c83452192';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Жапон мисо сорпасы'), description_kk = COALESCE(description_kk, 'Жапондардың ұзақ өмір сүру құпиясы саналатын, таңертең немесе кешке ішетін жеңіл ферменттелген сорпа.

Пайдасы: Мисо пастасы (ферменттелген соя) — ішек саулығына пайдалы ең күшті пробиотиктердің бірі. Ас қорытуды қалыпқа келтіреді.'), category_kk = COALESCE(category_kk, 'жалпы'), tags_kk = COALESCE(tags_kk, ARRAY['жалпы']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Мисо пастасы: 2 ас қасық (Азия өнімдері сатылатын дүкендерден табуға болады)","Тофу ірімшігі: 100 qr (кішкентай текшелерге туралған)","Көк пияз: 2 сабақ (туралған)","Жылы су немесе көкөніс сорпасы: 2 стақан."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Суды қайнауға жеткізіп, оттан алыңыз (мисоны қайнатуға болмайды, әйтпесе пробиотиктер жойылады). Мисо пастасын суда ерітіңіз. Тофу текшелері мен көк пиязды қосып, бірден ыстық күйінде ішіңіз."]'::jsonb) WHERE id = '35ab7142-651b-45ae-b7e5-7c6acf7f3691';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Албырт пен картоп (1 жас+)'), description_kk = COALESCE(description_kk, 'Тіпті балықты ұнатпайтын балалар да сүйсініп жейтін жұмсақ балық котлеттері.

Пайдасы: Албырт мидың және көздің дамуына қажетті Омега-3 май қышқылдарымен қамтамасыз етеді.'), category_kk = COALESCE(category_kk, 'Қосымша тағам'), tags_kk = COALESCE(tags_kk, ARRAY['жалпы', 'бөпе_тамағы']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Албырт (Сомон) филесі: 50 qr (буға пісіріліп, ұсақталған)","Картоп: 1 дана (пісіріліп, езілген)","Балғын аскөк: Өте аз (туралған)","Зәйтүн майы."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Езілген картопты, сүйексіз ұсақталған балықты және аскөкті араластырыңыз. Кішкентай котлеттер жасап, табада өте аз зәйтүн майына екі жағын да сәл қызартып қуырыңыз."]'::jsonb) WHERE id = '34a3ec68-3237-4337-99bf-0423a1d5cd88';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Сүзбе йогурт пен чиа боулы (1 жас+)'), description_kk = COALESCE(description_kk, 'Тіскебасарға немесе жеңіл кешкі асқа арналған пробиотиктер мен кальцийдің мол көзі.

Пайдасы: Йогурт ішек микрофлорасын байытады, ал чиа тұқымы Омега-3-пен қамтамасыз етеді.'), category_kk = COALESCE(category_kk, 'Қосымша тағам'), tags_kk = COALESCE(tags_kk, ARRAY['бөпе_тамағы']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Сүзбе йогурт немесе грек йогурты: 2-3 ас қасық","Чиа тұқымы: Жарты шай қасық (алдын ала 1 қасық суға жібітілген)","Таңқурай немесе құлпынай: 2-3 дана (езіліп, пюре жасалған)","Бал: Шай қасықтың ұшымен (1 жастан асқан балалар үшін қауіпсіз)."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Йогуртты, жібітілген чиа тұқымын, езілген жеміс пюресін және өте аз балды бір ыдыста араластырыңыз. Түсі балаңыздың қызығушылығын тудыратын дәмді десерт дайын болады."]'::jsonb) WHERE id = '90e2d20f-198b-4417-92bb-ccab337989e6';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Алма донаттары (4 жас+)'), description_kk = COALESCE(description_kk, 'Қамырсыз және қантсыз дайындалатын, әзірлеу үдерісі балалар үшін ойынға айналатын донаттар.

Пайдасы: Алмадағы жасұнық ас қорытуды реттейді, ал жержаңғақ пастасы тойымды ақуызбен қамтамасыз етеді.'), category_kk = COALESCE(category_kk, 'Қосымша тағам'), tags_kk = COALESCE(tags_kk, ARRAY['baby_food']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Үлкен алма: 1-2 дана (қызыл немесе жасыл)","Жержаңғақ пастасы немесе шоколадты орман жаңғағы пастасы (қантсыз): 2 ас қасық","Шоколад тамшылары, кокос жаңқасы, ұсақталған жаңғақ."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Алманы дөңгелектеп турап, ортасындағы дәні бар бөлігін шеңбер түрінде кесіп алыңыз (донат пішіні шығуы керек). Үстіне жержаңғақ пастасын жағыңыз. Балаңызға өз «дөңгелектерін» шоколад тамшылары және кокос жаңқасымен безендіруге мүмкіндік беріңіз."]'::jsonb) WHERE id = 'a8a21b7d-5abe-40d9-9276-a772ffab8e70';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Саумалдықты вафлилер (5 жас+)'), description_kk = COALESCE(description_kk, 'Жасыл түсімен балалардың назарын аударатын, таңертең оларға «айдаһар күшін» сыйлайтын вафлилер.

Пайдасы: Саумалдық темірге, ал сұлы жасұныққа бай. Баланы ұзақ уақыт тоқ ұстап, қан аздығының алдын алуға көмектеседі.'), category_kk = COALESCE(category_kk, 'Қосымша тағам'), tags_kk = COALESCE(tags_kk, ARRAY['baby_food']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Жас саумалдық: 1 үлкен уыс","Жұмыртқа: 1 дана","Сұлы ұны (немесе тұтас бидай ұны): 3-4 ас қасық","Сүт: Жарты стақан","Зәйтүн майы: 1 шай қасық."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Барлық азық-түлікті блендерге салып, біркелкі әрі ашық жасыл қамыр болғанша араластырыңыз. Вафли пісіргішті (немесе табаны) майлап, қамырды құйыңыз да, қытырлақ болғанша пісіріңіз. Үстіне аздап бал құюға болады."]'::jsonb) WHERE id = 'cb924e7b-c487-4059-bef0-ff92f0b6b771';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Алтын қазына кекстері (5 жас+)'), description_kk = COALESCE(description_kk, 'Жұмыртқаны ұнатпайтын балаларға да ұнайтын, ішінде түрлі түсті «қазыналары» бар жұмыртқалы кекстер.

Пайдасы: Жұмыртқаның сарыуызындағы холин есте сақтау қабілетін жақсартады. Ұнсыз әрі глютенсіз болғандықтан, өте жеңіл.'), category_kk = COALESCE(category_kk, 'Қосымша тағам'), tags_kk = COALESCE(tags_kk, ARRAY['baby_food']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Жұмыртқа: 3 дана","Түрлі түсті болгар бұрышы (қызыл және жасыл): 2 ас қасық (өте ұсақ туралған)","Ірімшік (үгітілген): 2 ас қасық","Тұз және аздап сүт."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Жұмыртқаларды сүт және тұзбен араластырып шайқаңыз. Үстіне туралған бұрыш пен ірімшікті қосыңыз. Кекс (маффин) қалыптарын аздап майлап, қоспаны оларға бөліп құйыңыз. 180 градустық пеште көтеріліп, қызарғанша (15-20 минут) пісіріңіз."]'::jsonb) WHERE id = '37d5dece-84c4-4e64-b999-a935190306a7';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Макарон салаты (2 жас+)'), description_kk = COALESCE(description_kk, 'Түрлі түстер мен текстуралар 2 жастағы баланың ұсақ моторикасы мен қызығушылығын дамытады.

Пайдасы: Тойымды көмірсулар мен көкөніс талшықтары үйлескен. Жаздың ыстық күндеріне арналған тамаша сергітетін түскі ас.'), category_kk = COALESCE(category_kk, 'Қосымша тағам'), tags_kk = COALESCE(tags_kk, ARRAY['baby_food']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Түрлі түсті фузилли макароны (көкөністі): 1 стақан (қайнатылған)","Жасыл бұршақ пен жүгері: Әрқайсысы 1 ас қасықтан (қайнатылған)","Сәбіз: Жарты дана (өте ұсақ текшелерге туралған және пісірілген)","Йогурт (тұздық үшін): 1 ас қасық."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Жылы макаронды, бұршақты, жүгеріні және сәбізді бір ыдысқа салып араластырыңыз.","Үстіне йогурт қосып, бәрін жақсылап араластырыңыз.","Өз қолымен жеуі үшін алдына қойыңыз."]'::jsonb) WHERE id = '78095524-c00e-403c-92d3-bbc3e2809be1';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Тәтті картоптан жасалған вафли (2 жас+)'), description_kk = COALESCE(description_kk, 'Панкейктен жалыққан балаларға арналған қытырлақ әрі қолға ұстауға ыңғайлы вафли.

Пайдасы: Тәтті картоп қандағы қант деңгейін реттеуге көмектесіп, балаға ұзақ уақытқа жететін қуат береді.'), category_kk = COALESCE(category_kk, 'Қосымша тағам'), tags_kk = COALESCE(tags_kk, ARRAY['baby_food']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Тәтті картоп езбесі: Жарты стақан","Жұмыртқа: 1 дана","Ұн (тұтас бидай немесе сұлы): 2 ас қасық","Даршын: Өте аз."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Барлық азықты бір ыдысқа салып араластырып, қамыр дайындаңыз.","Вафли пісіргішті аздап майлап, қамырды құйыңыз.","Алтын түске еніп, жиектері қытырлақ болғанша пісіріңіз. (Вафли пісіргіш болмаса, табада панкейк сияқты пісіруге де болады)."]'::jsonb) WHERE id = '945b98d6-f61a-4b5b-a323-8398d17756d0';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Үйде дайындалған наггетстер (4 жас+)'), description_kk = COALESCE(description_kk, 'Фастфудқа деген әуестікті басатын, пеште пісірілген және 100% үй жағдайында дайындалған қытырлақ наггетстер.

Пайдасы: Таза тауық ақуызы бұлшықеттерді нығайтады, ал сұлы қабығы ас қорытуды жеңілдетіп, тоқтықты ұзақ сақтайды.'), category_kk = COALESCE(category_kk, 'Қосымша тағам'), tags_kk = COALESCE(tags_kk, ARRAY['baby_food']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Тауықтың төс еті: 150 qr (текшелеп туралған)","Сұлы ұны немесе ұсақталған сұлы: Аунату үшін","Жұмыртқа: 1 дана","Тәтті қызыл ұнтақ бұрыш (паприка) және аздап тұз."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Тауық текшелерін алдымен шайқалған жұмыртқаға, содан кейін дәмдеуіштер қосылған сұлы ұнына аунатыңыз. Пісіру қағазы төселген пеш табасына тізіп, 190 градуста 20 минут қызарғанша пісіріңіз."]'::jsonb) WHERE id = '4660742b-6a15-4753-92bd-b4b19340e368';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Киноа салынған түрлі-түсті бұрыш'), description_kk = COALESCE(description_kk, 'Жерорта теңізі асханасындағы танымал тағамның күріш орнына киноа қолданылатын, ақуызға бай нұсқасы.

Пайдасы: Түрлі-түсті бұрыштар С дәруменіне бай. Пеште піскен кезде бұрыш киноаның құрылымымен керемет үйлеседі.'), category_kk = COALESCE(category_kk, 'жалпы'), tags_kk = COALESCE(tags_kk, ARRAY['жалпы']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Болгар бұрышы (қызыл, сары): 3-4 дана (ортасынан бөлініп, дәндері тазартылған)","Киноа (піскен): 1.5 стақан","Тартылған ет немесе саңырауқұлақ: 150 qr (қуырылған)","Томат пастасы, ірімшік (бетіне себу үшін)."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Піскен киноаны қуырылған тартылған етпен/саңырауқұлақпен және томат пастасымен араластырыңыз. Қоспаны бұрыштардың ішіне салыңыз. Пешке арналған ыдысқа орналастырып, бұрыштар жұмсарғанша 180 градуста пісіріңіз. Пештен алуға 5 минут қалғанда үстіне ірімшік себіңіз."]'::jsonb) WHERE id = 'b1385dc4-14fe-4718-ab79-5558f3683c72';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Авокадо мен бадам смузиі'), description_kk = COALESCE(description_kk, 'Жеңіл тіскебасар ретінде де, дәмді десерттің орнына да ішуге болатын ерекше кремді смузи.

Пайдасы: Авокадодағы пайдалы майлар мен бадамдағы Е дәрумені жасуша деңгейінде жасартатын әсерге ие.'), category_kk = COALESCE(category_kk, 'жалпы'), tags_kk = COALESCE(tags_kk, ARRAY['жалпы']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Авокадо: Жарты дана (толық піскен, жұмсақ)","Бадам сүті: 1 стақан","Чиа тұқымы: 1 шай қасық (бетіне себу үшін)","Бал: 1 шай қасық","Мұз текшелері."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Авокадо, бадам сүті, мұз бен балды блендерде толық біркелкі, \"жібектей\" массаға айналғанша араластырыңыз. Стақанға құйып, үстіне чиа тұқымын себіңіз."]'::jsonb) WHERE id = '14732b3b-b0ea-4f4d-834e-0f74c755ed69';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Protein Cloud — Сүзбелі панкейк'), description_kk = COALESCE(description_kk, 'Тәттіге деген құмарлықты пайдалы жолмен басатын, ұнсыз әрі ақуызға бай панкейк.

Пайдасы: Ақуыздың жоғары мөлшері ұзақ уақыт тоқтық сезімін беріп, бұлшықет массасын сақтауға көмектеседі. Құрамында ұн болмағандықтан, қандағы қант деңгейін күрт көтермейді.'), category_kk = COALESCE(category_kk, 'таңғы ас'), tags_kk = COALESCE(tags_kk, ARRAY['жалпы']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Сүзбе (майы аз): 100 qr","Жұмыртқа: 1 дана","Сұлы ұны: 2 ас қасық","Ваниль мен даршын.","Ұсыну үшін: Йогурт немесе бал."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Сүзбені жұмыртқамен жақсылап езіп араластырыңыз. Үстіне сұлы ұны мен дәмдеуіштерді қосып, қамыр дайындаңыз. Майсыз табада кішкентай дөңгелек пішін жасап, екі жағын да қызартып пісіріңіз."]'::jsonb) WHERE id = '29f853dc-e269-415a-b733-458329d3f202';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Батат сотесі'), description_kk = COALESCE(description_kk, 'Тағамдық талшықтар мен күрделі көмірсуларға бай, ұзақ уақыт тоқтық сыйлайтын ерекше дәм.

Пайдасы: Бататтың құрамындағы тағамдық талшықтар мен дәрумендер инсулинге төзімділікті реттеуге көмектесіп, тәттіге деген құмарлықты азайтады.'), category_kk = COALESCE(category_kk, 'таңғы ас'), tags_kk = COALESCE(tags_kk, ARRAY['жалпы']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Батат: 1 орташа (ұсақ текшелерге туралған)","Қызыл пияз: Жарты дана","Саумалдық: 1 уыс","Зәйтүн майы, тұз, қара бұрыш."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Табада майды қыздырып, батат пен пиязды жұмсарғанша қуырыңыз. Толық піскеннен кейін саумалдықты қосып, 1 минут араластырыңыз. Жанына 1 тілім ірімшік қосып ұсынсаңыз, өте дәмді болады."]'::jsonb) WHERE id = '62b8e0b6-2240-42de-af0b-ccfb0617485b';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Брокколи мен саумалдық сорпасы'), description_kk = COALESCE(description_kk, 'Таңертең ішіңіз жеңіл әрі жайлы болып оянуыңызға арналған ең жақсы «сұйық» кешкі ас.

Пайдасы: Ағзадан токсиндердің шығарылуына көмектесіп, бауыр мен ішекті біртіндеп тазартатын жасыл детокс сорпасы.'), category_kk = COALESCE(category_kk, 'кешкі ас'), tags_kk = COALESCE(tags_kk, ARRAY['жалпы']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Брокколи: 200 qr","Саумалдық: 1 уыс","Пияз, сарымсақ (аздап).","Бадам сүті немесе кілегей: 2 ас қасық"]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Брокколи мен пиязды суда жұмсарғанша пісіріңіз. Дайын болуына 1 минут қалғанда саумалдықты қосыңыз. Барлығын блендерден өткізіп, үстіне сүт/кілегей қосыңыз да, крем тәрізді болғанша араластырыңыз. Қуырылған асқабақ дәнімен ұсыныңыз."]'::jsonb) WHERE id = '94c6eeab-3fdb-44c0-af09-f90065cd1128';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Лимон қосылған тауық еті мен қояншөп'), description_kk = COALESCE(description_kk, 'Бір табада дайындалатын, қарапайым естілгенімен, өте «бай» көрінетін диеталық тағам.

Пайдасы: Тауықтың төс еті ақуызға бай, ал қояншөп бүйрек жұмысын белсендіріп, ағзадағы артық сұйықтықты (ісінуді) шығаруға көмектесетін супертағам.'), category_kk = COALESCE(category_kk, 'кешкі ас'), ingredients_kk = COALESCE(ingredients_kk, '["Тауықтың төс еті: 150 qr (жұқалап жаншылған немесе туралған)","Қояншөп (аспарагус): 1 бума","Лимон: 1 дана (жартысы шырынына, жартысы тілімдеуге)","Зәйтүн майы, сарымсақ ұнтағы."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Кең табада тауық етінің екі жағын майға қызартып қуырыңыз. Тауық еті пісуге жақындағанда, табаға қояншөп пен лимон тілімдерін қосып, барлығын бірге 5-7 минут қуырыңыз. Үстіне лимон шырынын сығып, дастарқанға ұсыныңыз."]'::jsonb) WHERE id = '51c68a19-8648-4032-8605-7b8cccf441b0';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Күркетауық еті мен киноа салынған бұрыш'), description_kk = COALESCE(description_kk, 'Кәдімгі долманың көмірсуы аз, дәрумендерге бай әрі түрлі-түсті нұсқасы.

Пайдасы: С дәрумені (түрлі-түсті бұрыштар) мен ақуыздың (күркетауық еті) үйлесімі терідегі коллаген түзілуін қолдайды.'), category_kk = COALESCE(category_kk, 'түскі ас'), tags_kk = COALESCE(tags_kk, ARRAY['general']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Түрлі-түсті болгар бұрышы: 2 дана (ортасынан екіге бөлінген, қайықша пішінінде)","Күркетауықтың тартылған еті (немесе майсыз сиыр еті): 150 qr","Киноа (піскен): 2 ас қасық","Қызанақ соусы."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Тартылған етті киноа және қызанақ соусымен табада шала пісіріңіз. Қоспаны бұрыш қайықшаларының ішіне салып, бұрыш жұмсарғанша пеште пісіріңіз."]'::jsonb) WHERE id = 'b2be2ad1-ce46-48a9-9075-79f7864e5758';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Матча лимонады'), description_kk = COALESCE(description_kk, 'Антиоксиданттарға бай, сергітетін екі түсті сусын.

Пайдасы: Матчада кофеин бар, алайда оның сергітетін әсері кофеге қарағанда бірқалыптырақ сезіліп, күні бойы сергектікті сақтауға көмектесуі мүмкін.'), category_kk = COALESCE(category_kk, 'Пайдалы сусындар'), tags_kk = COALESCE(tags_kk, ARRAY['general']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Матча ұнтағы: 1 шай қасық (жылы суда көпіртілген)","Жаңа сығылған лимон шырыны: Стақанның үштен бірі","Агава шәрбаты немесе бал: 1 ас қасық","Су және көп мөлшерде мұз."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Стақанға мұз салыңыз. Лимон шырынын, бал мен суды араластырып, мұздың үстіне құйыңыз. Соңында көпіртілген жасыл матчаны баяу қосыңыз (осылайша стақанда екі түс – астында сары, үстінде жасыл болады)."]'::jsonb) WHERE id = 'cb10f111-6a9d-4baa-9dd6-af7ef8393f1e';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Жаңғақ пен банан қосылған түнге жібітілген сұлы'), description_kk = COALESCE(description_kk, 'Таңертең жүрегі айнитындар үшін таптырмас салқын әрі жеңіл таңдау'), category_kk = COALESCE(category_kk, 'таңғы ас'), ingredients_kk = COALESCE(ingredients_kk, '["Сұлы үлпегі - 4 ас қасық","Сүт - 1 стақан","Банан - жарты дана","Грек жаңғағы - 2 дана","Бал - 1 шай қасық"]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Кешке сұлы үлпегін, сүт пен балды араластырыңыз","Тоңазытқышта сақтаңыз","Таңертең банан мен жаңғақ қосыңыз"]'::jsonb) WHERE id = 'ae635663-e33c-479a-970a-94bd85e39010';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Баклажан мен ірімшік қаттамасы'), description_kk = COALESCE(description_kk, 'Көмірсуы аз әрі жеңіл балама — жалған лазанья'), category_kk = COALESCE(category_kk, 'кешкі ас'), ingredients_kk = COALESCE(ingredients_kk, '["Баклажан - 2 дана","Қызанақ - 2 дана","Ақ ірімшік - 60 qr","Насыбайгүл"]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Баклажандарды жұқалап турап, пеште жұмсарғанша пісіріңіз","Үстіне ірімшік, қызанақ пен насыбайгүл салыңыз","Пеште ірімшік ерігенше пісіріңіз"]'::jsonb) WHERE id = 'c940ec18-0208-46aa-8361-f2f2f659b141';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Пеште даршынмен пісірілген шабдалы'), description_kk = COALESCE(description_kk, 'Өте жеңіл, балмұздақ әсерін беретін, бірақ калориясы жоқтың қасы десерт.

Пайдасы: Шабдалы талшыққа бай (ас қорытуды жылдамдатады), ал даршын қандағы қант деңгейін тұрақтандыруға көмектеседі.'), category_kk = COALESCE(category_kk, 'Пайдалы тәттілер'), ingredients_kk = COALESCE(ingredients_kk, '["Шабдалы: 2 дана (ортасынан бөлінген, сүйегі алынған)","Даршын: 1 шай қасық","Грек жаңғағы немесе пекан жаңғағы: ұсақталған","Сүзілген йогурт (ұсыну үшін)."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Шабдалының жарты бөліктерін пешке арналған қалыпқа орналастырып, орталарына даршын мен жаңғақ себіңіз. 180 градуста 15-20 минут жұмсарғанша пісіріңіз. Жылы күйінде ортасына бір қасық сүзілген йогурт салып жеңіз."]'::jsonb) WHERE id = 'e7b8a04c-a4fa-4769-bbd9-6735976b643a';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Асқабақ пен кокос сүті
(8 ай+)'), description_kk = COALESCE(description_kk, 'Бөпенің ерекше тропикалық дәмдермен алғашқы таныстығы. Құрылымы жібектей жұмсақ.

Пайдасы: Асқабақ құрамындағы А дәрумені көз саулығын қолдайды. Ал кокос сүті — сиыр сүтіне тамаша балама әрі құрамында ана сүтіндегідей пайдалы майлар бар.'), category_kk = COALESCE(category_kk, 'Қосымша тағам'), tags_kk = COALESCE(tags_kk, ARRAY['baby_food']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Асқабақ: 1 тілім (қабығы аршылып, текшелеп туралған)","Кокос сүті (қораптағы ішуге арналған түрі емес, қою аспаздық түрі): 2 ас қасық."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Асқабақты буға жұмсарғанша пісіріңіз. Үстіне кокос сүтін қосып, блендермен езіңіз. Өте тойымды әрі дәмді сорпа шығады."]'::jsonb) WHERE id = 'a8859019-9d72-40f8-8956-b03d1cfb1e34';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Брокколи мен ірімшік түйіршіктері (1 жастан бастап)'), description_kk = COALESCE(description_kk, 'Брокколиді жақсы көрудің ең қытырлақ әрі қызықты жолы.

Пайдасы: Брокколи иммунитетті нығайтатын C дәруменіне бай, ал ірімшік пен жұмыртқа сапалы ақуызбен қамтамасыз етеді.'), category_kk = COALESCE(category_kk, 'Қосымша тағам'), tags_kk = COALESCE(tags_kk, ARRAY['baby_food']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Брокколи: 4-5 гүлшоғыры (буға пісірілген және өте ұсақ туралған)","Жұмыртқа: 1 дана","Голланд ірімшігі немесе моцарелла: 2 ас қасық (үгітілген)","Тұтас бидай ұны немесе кепкен нан ұнтағы: 1 ас қасық"]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Туралған брокколиді жұмыртқа, ірімшік және ұнмен араластырыңыз. Қолыңызбен кішкентай цилиндр (немесе ағаш) пішінін жасаңыз. 180 градустағы пеште қызарғанша 15 минут пісіріңіз."]'::jsonb) WHERE id = 'a31f99ac-a31e-4008-9edc-552e80b3f2f2';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Күншуақ сарыуыз — жұмыртқа мен картоп'), description_kk = COALESCE(description_kk, 'Жұмыртқаның сарыуызы ми мен көздің дамуы үшін маңызды (8 айдан бастап)'), category_kk = COALESCE(category_kk, 'baby_food'), tags_kk = COALESCE(tags_kk, ARRAY['baby_food']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Жұмыртқаның сарыуызы - 1 дана","Картоп - 1 кішкентай дана","Ана сүті/қоспа"]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Картоп езбесін дайындаңыз","Піскен жұмыртқаның сарыуызын езіп қосыңыз","Сүт қосып, жұмсартыңыз"]'::jsonb) WHERE id = '0d1f8dc7-ed50-4792-a9b8-aaed4334e5c7';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Құс жолы печеньесі'), description_kk = COALESCE(description_kk, 'Әлемге танымал лактацияға арналған печеньенің пайдалы нұсқасы. Сұлы мен зығыр тұқымы пролактинді арттырады.'), category_kk = COALESCE(category_kk, 'пайдалы_тәттілер'), ingredients_kk = COALESCE(ingredients_kk, '["Сұлы: 1.5 стақан","Сары май: 50 qr","Бал: 3 ас қасық","Жұмыртқа: 1 дана","Зығыр тұқымы: 2 ас қасық","Шоколад түйіршіктері: қалауыңызша"]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Сары майды ерітіп, бал және жұмыртқамен бірге шайқаңыз","Сұлы мен зығыр тұқымын қосып, араластырыңыз","Қалауыңызша шоколад түйіршіктерін қосыңыз","Қасықпен қағаздың үстіне дөңгелек пішіндер жасаңыз","175°C-та 12-15 минут пісіріңіз — күніне 2-3 дана жеңіз"]'::jsonb) WHERE id = 'f09a3c1e-ec4c-4eb2-b2d1-b699bce46612';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Патшайым ботқасы — Патшайымның таңы'), description_kk = COALESCE(description_kk, 'Құрма мен жаңғақтың қуаты және сұлының сүтті көбейтетін қасиеті үйлескен тағам. Пролактиннің түзілуін ынталандырады.'), category_kk = COALESCE(category_kk, 'таңғы_ас'), ingredients_kk = COALESCE(ingredients_kk, '["Сұлы: 3 ас қасық","Сүт: 1 стақан","Құрма: 2-3 дана (сүйексіз)","Грек жаңғағы: 1 уыс","Даршын: бір шымшым"]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Сүт пен сұлыны кәстрөлге салып, орташа отта араластыра отырып пісіріңіз","Қоюланғанша (5-7 мин) араластыра беріңіз","Оттан алып, туралған құрманы қосыңыз","Үстіне грек жаңғағы мен даршын себіңіз","Жылы күйінде жеңіз — сүтті көбейтуге арналған ең пайдалы таңғы ас"]'::jsonb) WHERE id = 'e130e1c4-d49f-409f-844e-56265cb3eca7';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Жасыл детокс эликсирі'), description_kk = COALESCE(description_kk, 'Бауыр мен теріні тазартып, жасушалардың жаңаруына көмектесетін ерекше «жасыл шырын».

