UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Алмұрт пен қара өрік езбесі
(6 ай+)'), description_kk = COALESCE(description_kk, 'Қосымша тағамға көшкенде жиі кездесетін іш қату мәселесінің табиғи әрі дәмді шешімі.

