UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Зығыр лавашындағы авокадо'), description_kk = COALESCE(description_kk, 'Бар болғаны 2 өнімнен дайындалатын, ұнсыз әрі глютенсіз «веган лаваш».

