UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Пеште пісірілген ақ балық'), description_kk = COALESCE(description_kk, 'Ақ балықтың майы аз, сондықтан асқазанға ауырлық түсірмейді. Ақуыз көзі'), category_kk = COALESCE(category_kk, 'кешкі_ас'), ingredients_kk = COALESCE(ingredients_kk, '["Ақ балық - 1 филе","Лимон - 2 тілім","Лавр жапырағы - 1","Зәйтүн майы","Қара бұрыш"]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Балыққа май жағыңыз","Үстіне лимон мен лавр жапырағын қойыңыз","Қағазға орап, 180°C-де 25 минут пісіріңіз"]'::jsonb) WHERE id = '67463cf4-ba39-4257-b387-541018594397';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Пеште пісірілген даршын қосылған алма чипсысы'), description_kk = COALESCE(description_kk, 'Кәмпиттің орнына пайдалы тіскебасар'), category_kk = COALESCE(category_kk, 'пайдалы_тәттілер'), ingredients_kk = COALESCE(ingredients_kk, '["Алма - 2 дана","Даршын - 1 шай қасық"]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Алманы жұқалап тураңыз","Үстіне даршын себіңіз","Пеште төмен температурада кептіріңіз"]'::jsonb) WHERE id = '396d0e08-df24-45b2-bbc5-d0eb5bb97a61';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Сәбіз бен жаңғақ қосылған жұмсақ кекс'), description_kk = COALESCE(description_kk, 'Сәбіздегі А дәрумені мен жаңғақтағы Омега-3 көз бен мидың дамуына пайдалы'), category_kk = COALESCE(category_kk, 'пайдалы_тәттілер'), ingredients_kk = COALESCE(ingredients_kk, '["Сұлы ұны - 1 стақан","Сәбіз - 2 дана","Жұмыртқа - 2 дана","Грек жаңғағы - жарты стақан","Бал - 3 ас қасық","Даршын, қопсытқыш"]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Жұмыртқаны балмен шайқаңыз","Сәбіз, жаңғақ пен даршын қосыңыз","Сұлы ұны мен қопсытқышты араластырыңыз","170°C температурада 25 минут пісіріңіз"]'::jsonb) WHERE id = 'e1dfdbd8-e8bb-4c32-930c-c832c8f118d3';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Green Goddess смузиі'), description_kk = COALESCE(description_kk, 'Саумалдықтағы темір мен С дәрумені қаназдыққа қарсы нағыз супер күш'), category_kk = COALESCE(category_kk, 'пайдалы_сусындар'), ingredients_kk = COALESCE(ingredients_kk, '["Саумалдық - 1 уыс","Киви - 1 дана","Жасыл алма - жарты алма","Кокос суы - жарты стақан","Лимон шырыны"]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Барлық ингредиентті блендермен араластырыңыз","Дайындағаннан кейін бірден ішіңіз"]'::jsonb) WHERE id = '6f156a10-e92e-4a17-a7af-3e68646cf53d';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Жарқырау салаты'), description_kk = COALESCE(description_kk, 'Көкөніс жеуді таңертеңнен бастағысы келетіндерге арналған детокс әсері бар таңғы ас.

Пайдасы: Саумалдық пен зәйтүн майы ішектің жұмысын белсендіреді, ағзадағы токсиндердің шығарылуын жылдамдатады.'), category_kk = COALESCE(category_kk, 'таңғы ас'), tags_kk = COALESCE(tags_kk, ARRAY['жалпы']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Жас саумалдық немесе салат жапырағы: 1-2 уыс","Қатты пісірілген жұмыртқа: 1 дана","Грек жаңғағы: 2-3 дана","Зәйтүн майы және лимон шырыны.","Сүзбе: 2 ас қасық."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Саумалдықты ыдысқа салыңыз. Үстіне туралған жұмыртқа, сүзбе және грек жаңғағын қосыңыз. Зәйтүн майы мен лимон шырынынан жасалған тұздықты құйып, жеңіз."]'::jsonb) WHERE id = 'b7b9eff5-fed2-499e-b5d9-5c57fb32426f';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Алтын дәндер — булгур палауы'), description_kk = COALESCE(description_kk, 'Булгур мен жасымықтың үйлесімі. В дәрумендеріне бай, сүт безі тіндерінің қоректенуіне ықпал етеді.'), category_kk = COALESCE(category_kk, 'түскі ас'), ingredients_kk = COALESCE(ingredients_kk, '["Булгур: 1 стақан","Жасыл жасымық: жарты стақан (пісірілген)","Пияз: 1 дана","Сары май: 1 ас қасық","Су: 2 стақан"]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Пиязды сары майға салып, қызарғанша қуырыңыз","Жуылған булгурды қосып, 1-2 минут қуырыңыз","Алдын ала пісірілген жасымықты қосыңыз","Үстіне 2 стақан су құйып, қайнатыңыз","Суы толық сіңгенше баяу отта бұқтырыңыз (15-20 мин)"]'::jsonb) WHERE id = 'dcd85da7-ccb3-4272-a895-942bd99de63b';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Zen баланс смузиі'), description_kk = COALESCE(description_kk, 'Қыжылы бар адамдарға арналған тыныштандыратын сусын'), category_kk = COALESCE(category_kk, 'пайдалы сусындар'), ingredients_kk = COALESCE(ingredients_kk, '["Сұлы үлпегі - 2 ас қасық","Банан - 1 дана","Сүт - 1 стақан","Бал - 1 шай қасық"]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Сұлы үлпегін сүтке салып, жұмсартыңыз","Банан және балмен бірге блендерде араластырыңыз"]'::jsonb) WHERE id = 'db9dd331-557e-46cd-9d2b-a47d4771ad41';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Жүрек айнуға қарсы шот'), description_kk = COALESCE(description_kk, 'Таңертеңгі жүрек айнуды басуға арналған ең тиімді сусын'), category_kk = COALESCE(category_kk, 'пайдалы сусындар'), ingredients_kk = COALESCE(ingredients_kk, '["Зімбір шырыны - 1 шай қасық","Лимон шырыны - 1 ас қасық","Алма шырыны - 2 ас қасық"]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Кішкентай стақанда араластырыңыз","Таңертең ашқарынға ішіңіз"]'::jsonb) WHERE id = '880d9940-72c5-4091-be98-b624aa0ce63b';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Киноа мен көкөніс боулы'), description_kk = COALESCE(description_kk, 'Түрлі түсті, тойымды әрі толығымен өсімдік тектес қуат көзі.

Пайдасы: Киноа — қандағы қант деңгейін күрт көтермейтін күрделі көмірсу, ал ноқат өсімдік тектес ақуыз бен фитоэстрогендерге (әйел гормондарын реттейді) бай.'), category_kk = COALESCE(category_kk, 'түскі ас'), tags_kk = COALESCE(tags_kk, ARRAY['жалпы']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Киноа: Жарты стақан (піскен)","Тәтті картоп (батат): 1 дана (текшелеп туралған және пеште пісірілген)","Қызыл қырыққабат: 1 уыс (жұқалап туралған)","Ноқат: 3 ас қасық (қайнатылған)","Тұздық үшін: 1 ас қасық тахини, лимон шырыны, зәйтүн майы."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Барлық ингредиентті шұңғыл ыдысқа түрлі түсті етіп қатар-қатар орналастырыңыз. Үстіне тахини тұздығын құйып, дастарқанға ұсыныңыз."]'::jsonb) WHERE id = 'aef368fe-083d-4b68-9edb-d6de124b4d49';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Баялды гратені'), description_kk = COALESCE(description_kk, 'Италиялықтардың әйгілі "Parmigiana" тағамының қуырылмай дайындалатын диеталық нұсқасы.

Пайдасы: Баялды қабығындағы "насунин" деп аталатын антиоксидант ми жасушаларын қорғайды. Тойымды, бірақ калориясы төмен.'), category_kk = COALESCE(category_kk, 'кешкі ас'), tags_kk = COALESCE(tags_kk, ARRAY['жалпы']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Баялды: 2 дана (ұзынынан жұқалап туралған)","Қызанақ тұздығы: 1 стақан","Моцарелла және лор (тұзды) ірімшігі: Тең мөлшерде араластырылған","Балғын райхан."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Баялды тілімдерін пеште майсыз жұмсартып пісіріңіз. Пешке арналған қалыпқа тұздық, баялды, ірімшік және райханды кезекпен қабаттап салыңыз (лазанья секілді). Үстіңгі ірімшік қызарғанша пеште пісіріңіз."]'::jsonb) WHERE id = 'c5e3e953-1def-4129-bf13-05450ac7ffc6';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Қытырлақ тако тостағаншалары (3 жас+)'), description_kk = COALESCE(description_kk, 'Лаваштан жасалған қытырлақ тостағаншалардағы ақуызға бай Мексика дәмі.

Пайдасы: Үрмебұршақтағы тағамдық талшықтар ас қорытуды жеңілдетеді, ал жүгері мен ет баланың өсуіне қажетті қуат береді.'), category_kk = COALESCE(category_kk, 'Қосымша тағам'), tags_kk = COALESCE(tags_kk, ARRAY['бөпе_тағамы']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Лаваш (немесе тортилья): 1 дана","Қызыл үрмебұршақ (піскен): 2 ас қасық","Жүгері: 1 ас қасық","Тартылған ет немесе талшықтап бөлінген тауық еті: 2 ас қасық","Үккіштен өткізілген ірімшік."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Лавашты стақанның жиегімен дөңгелектеп кесіңіз. Дөңгелектерді кекс (маффин) қалыптарының ішіне басып салып, \"тостағанша\" пішінін жасаңыз. Ішіне үрмебұршақ, жүгері, ет, ал ең үстіне ірімшік салыңыз. Ірімшік еріп, лаваш қытырлақ болғанша (10 минут) пеште пісіріңіз."]'::jsonb) WHERE id = 'feb3870e-5bf3-4d4e-8622-e75280b05802';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Жасымықтан жасалған құнарлы сорпа'), description_kk = COALESCE(description_kk, 'Фолий қышқылына бай, жүкті әйелдер үшін таптырмас тағам'), category_kk = COALESCE(category_kk, 'түскі_ас'), ingredients_kk = COALESCE(ingredients_kk, '["Қызыл жасымық - 1 стақан","Сәбіз - 1 дана","Картоп - 1 дана","Пияз - 1 дана","Сорпа - 4 стақан","Жалбыз, лимон"]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Пиязды қуырып, сәбізді қосыңыз","Жасымық пен картопты қосыңыз","Сорпаны құйып, пісіріңіз","Блендермен езіңіз","Жалбыз бен лимон қосыңыз"]'::jsonb) WHERE id = '290acd87-550a-458c-a7f4-69cb997009e4';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Пеште пісірілген лимонды албырт'), description_kk = COALESCE(description_kk, 'Бөпенің миының дамуына қажетті Омега-3 көзі'), category_kk = COALESCE(category_kk, 'кешкі_ас'), ingredients_kk = COALESCE(ingredients_kk, '["Балықтың сүбесі - 200 гр","Лимон - 2 тілім","Брокколи - 100 гр","Зәйтүн майы, тасшөп"]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Балықты дәмдеуіштермен ысқылаңыз","Фольгаға балық пен көкөністерді салыңыз","Лимон тілімдерін орналастырыңыз","180°C-та 25 минут пісіріңіз"]'::jsonb) WHERE id = '497f352b-6f6a-4450-a0eb-ddccc2332776';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Зире жайлылығы - Жасымық сорпасы'), description_kk = COALESCE(description_kk, 'Ана мен бөпедегі іш кебу мәселесін жеңілдететін сорпа. Зире емшек сүтін көбейтіп, шаншуды азайтады.'), category_kk = COALESCE(category_kk, 'емізу'), tags_kk = COALESCE(tags_kk, ARRAY['босанғаннан_кейін', 'сүтті_көбейту']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Қызыл жасымық: 1 стақан","Пияз: 1 дана","Картоп: 1 дана","Зире (кумин): 1 шай қасық (молынан)","Сары май: 1 ас қасық"]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Жасымықты, пияз бен картопты турап, суға қайнатыңыз","Жұмсарғаннан кейін блендермен езіңіз","Бөлек табада зирені (куминді) сары майға хош иісі шыққанша қыздырыңыз","Қыздырылған зирелі майды сорпаның үстіне құйыңыз","Ыстық күйінде ішіңіз — емшек сүтін көбейтіп, шаншуды азайтуға көмектеседі"]'::jsonb) WHERE id = '56b6eb44-1b68-4703-8191-5abf175ce6b4';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Пробиотикалық парфе'), description_kk = COALESCE(description_kk, 'Ішек саулығына (екінші миға) пайдалы кальций мен пробиотиктердің мол көзі.

Пайдасы: Сау ішек микрофлорасы әйелдердің иммунитеті мен психологиялық саулығына тікелей әсер етеді.'), category_kk = COALESCE(category_kk, 'таңғы_ас'), tags_kk = COALESCE(tags_kk, ARRAY['жалпы']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Сүзбе йогурт (немесе грек йогурты): 1 стақан","Қантсыз гранола (немесе қуырылған сұлы/жаңғақ қоспасы): 3 ас қасық","Жаңа піскен жеміс (киви, шабдалы немесе құлпынай): Туралған"]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Биік стақанға алдымен йогурттың жартысын, содан кейін жемісті, одан соң граноланы қабаттап салыңыз. Үстіне қайтадан йогурт салып, ең бетіне аздап гранола себіңіз."]'::jsonb) WHERE id = '06ed0fa8-cbd9-44a6-9ddc-7e7b1fe1e84d';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Алтын крем - Хумус'), description_kk = COALESCE(description_kk, 'Ноқат пен тахинидің емшек сүтін көбейтетін қасиеттері үйлескен ең дәмді тағам. Өсімдік ақуызы мен кальцийге бай.'), category_kk = COALESCE(category_kk, 'түскі_ас'), ingredients_kk = COALESCE(ingredients_kk, '["Ноқат: 1 стақан (қайнатылған)","Тахини (күнжіт пастасы): 2 ас қасық","Лимон шырыны: 1 ас қасық","Сарымсақ: 1 түйір","Зәйтүн майы: 2 ас қасық"]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Ноқатты алдын ала жібітіп, жұмсарғанша қайнатыңыз","Блендерге ноқат, тахини, лимон шырыны мен сарымсақты салыңыз","Біркелкі крем тәрізді болғанша блендермен араластырыңыз","Қажет болса, ноқаттың қайнаған суынан қосыңыз","Үстіне зәйтүн майын құйып, нанмен бірге ұсыныңыз"]'::jsonb) WHERE id = '9448c07e-1f48-40e0-a861-ab4dcd62db5b';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Цитрус хош иісті ақ балық'), description_kk = COALESCE(description_kk, 'Асқазанға мүлде ауырлық түсірмейтін, хош иісті әрі нәзік теңіз тағамы.

Пайдасы: Ақ балықтар (сибас, көксерке) — оңай қорытылатын таза ақуыз бен қалқанша безді қорғайтын йодтың көзі. Ал лимон темірдің сіңуіне көмектеседі.'), category_kk = COALESCE(category_kk, 'кешкі ас'), tags_kk = COALESCE(tags_kk, ARRAY['жалпы']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Ақ балықтың сүбесі: 150-200 гр","Лимон және апельсин: Әрқайсысынан 2 тілім","Балғын жебіршөп (тимьян) немесе гүлшетен: 1-2 бұтақ","Зәйтүн майы, тұз, қара бұрыш."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Тазартылған балықты пергамент қағаздың үстіне қойыңыз. Тұз, бұрыш сеуіп, май құйыңыз. Үстіне цитрус тілімдері мен хош иісті шөптерді салыңыз. Қағазды пакет тәрізді орап, 180 градуста 20 минут пісіріңіз. Мол жасыл салатпен бірге жеңіз."]'::jsonb) WHERE id = '69335e75-4e74-4b38-bb31-495c4674ceb3';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Тропикалық оазис'), description_kk = COALESCE(description_kk, 'Ағзаның су балансын қалпына келтіретін (электролиттермен толықтыратын) және ісінуді басатын тап-таза сусын.

Пайдасы: Кокос суы — табиғи спорттық сусын (калийге бай). Ал қияр тері мен ағзаны іштен тазартады.'), category_kk = COALESCE(category_kk, 'Пайдалы сусындар'), ingredients_kk = COALESCE(ingredients_kk, '["Кокос суы (табиғи): 1 стақан","Қияр: Жұқа таспа түрінде кесілген тілімдер","Балғын жалбыз және лайм шырыны."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Барлық ингредиентті графинге немесе үлкен стақанға салып, дәмдері араласуы үшін тоңазытқышта 30 минут ұстаңыз. Салқын күйінде ішіңіз."]'::jsonb) WHERE id = '59177852-56ab-4ae0-9965-367e9142cf8e';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Авокадо мен тауық салаты'), description_kk = COALESCE(description_kk, 'Көмірсуы аз, ұзақ уақыт тоқ ұстайтын әрі бұлшықеттерді қоректендіретін дәмді тағам.

Пайдасы: Тойымды ақуыз (тауық еті) бен пайдалы майлардың (авокадо) үйлесімі тәттіге деген қатты құмарлықтың алдын алады.'), category_kk = COALESCE(category_kk, 'түскі ас'), tags_kk = COALESCE(tags_kk, ARRAY['жалпы']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Тауықтың төс еті: 150 гр (грильде немесе табада қуырылған)","Авокадо: Жарты дана (тілімделген)","Жас саумалдық немесе салат жапырағы: 2 уыс","Черри қызанағы: 5-6 дана","Лимон шырыны, зәйтүн майы."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Тауық етін ұзынша етіп тураңыз. Көк шөптерді, қызанақ пен авокадоны үлкен тәрелкеге салып, үстіне тауық тілімдерін орналастырыңыз. Лимон шырыны мен майдан жасалған тұздықпен дәмдеңіз."]'::jsonb) WHERE id = '0ad5770d-c00e-4aaf-a326-ab7ca620f797';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Жұмыртқалы авокадо тосты(1 жас+)'), description_kk = COALESCE(description_kk, 'Өз қолымен тамақтанғанды ұнататын 1 жастағы балалардың сүйікті асы.

Пайдасы: Авокадо пайдалы майларға бай, ал жұмыртқа ағзаны алмастырылмайтын аминқышқылдармен қамтамасыз етеді.'), category_kk = COALESCE(category_kk, 'Қосымша тағам'), tags_kk = COALESCE(tags_kk, ARRAY['baby_food']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Тұтас дәнді бидай наны: 1 тілім (шеттері кесілген, қуырылған)","Авокадо: Төрттен бір бөлігі (жақсылап езілген)","Жұмыртқа: 1 дана (қатты пісіріліп, үккіштен өткізілген)"]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Қуырылған нанның үстіне езілген авокадоны жағыңыз. Үстіне үккіштен өткізілген жұмыртқаны себіңіз. Бала қолына ұстай алатындай ұзынша жолақтарға кесіңіз."]'::jsonb) WHERE id = '3d1a500a-b203-4052-b1f2-91a4407a4e3c';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Саумалдық қосылған макарон(4 жас+)'), description_kk = COALESCE(description_kk, 'Жасыл түсімен балаларды қызықтыратын, ірімшік қосылған әрі темірге бай ғажайып тұздық.

Пайдасы: Саумалдық пен грек жаңғағы баланың миының дамуына ықпал етіп, қуат береді.'), category_kk = COALESCE(category_kk, 'Қосымша тағам'), tags_kk = COALESCE(tags_kk, ARRAY['baby_food']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Кебекті немесе түрлі түсті глютенсіз макарон: 1 стақан","Саумалдық: 1 үлкен уыс","Грек жаңғағының дәні: 2 дана","Кілегейлі ірімшік немесе зәйтүн майы: 1 ас қасық"]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Макаронды қайнатыңыз. Саумалдықты, грек жаңғағын және ірімшікті (немесе майды) блендермен біркелкі, ашық жасыл крем тәрізді болғанша араластырыңыз. Ыстық макаронды осы тұздықпен араластырып, дастарқанға ұсыныңыз."]'::jsonb) WHERE id = 'c842f7bd-4741-487b-b42c-981f40c245be';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Супер-күш беретін тефтельдер(2 жас+)'), description_kk = COALESCE(description_kk, 'Тіпті етті ұнатпайтын балалар да сүйсініп жейтін, ішінде тосынсыйы бар, пеште пісірілетін тефтельдер.

Пайдасы: Таза тауық ақуызы мен брокколидегі темір бір тағамда үйлескен. Майға қуырылмайтындықтан, асқазанға ауырлық түсірмейді.'), category_kk = COALESCE(category_kk, 'Қосымша тағам'), tags_kk = COALESCE(tags_kk, ARRAY['baby_food']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Тартылған тауық еті: 200 qr","Брокколи: 3-4 гүлшоғыры (блендерде ұнтақ тәрізді өте ұсақ етіп тартылған)","Пияз: Өте кішкентай бөлік (үккіштен өткізілген)","Кептірілген нан ұнтағы: 1 ас қасық","Зәйтүн майы және аздап тұз."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Барлық азық-түлікті бір ыдысқа салып, жақсылап илеңіз.","Бала қолына ұстап жей алатындай, грек жаңғағынан сәл кішірек тефтельдер жасаңыз.","Пергамент қағазы төселген пеште 180 градуста 20-25 минут пісіріңіз."]'::jsonb) WHERE id = 'ce232b23-613e-4e89-87ba-f0def071b9bc';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Жидекті чиа ғажайыбы'), description_kk = COALESCE(description_kk, 'Антиоксиданттарға бай, теріні іштен ылғалдандыратын салқын тіскебасар.'), category_kk = COALESCE(category_kk, 'таңғы ас'), tags_kk = COALESCE(tags_kk, ARRAY['жалпы']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Чиа тұқымы: 3 ас қасық","Бадам сүті (немесе кокос сүті): 1 стақан","Балғын таңқурай немесе көкжидек: 1 уыс","Бал немесе үйеңкі шәрбаты: 1 шай қасық"]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Кешке чиа тұқымын, сүт пен балды бір ыдысқа салып, жақсылап араластырыңыз (түйіршіктеніп қалмауы үшін 10 минуттан кейін қайта араластырыңыз). Тоңазытқышта таңға дейін сақтаңыз. Таңертең үстіне балғын жидектерді салып, ұсыныңыз."]'::jsonb) WHERE id = '76ceddd0-3762-4c0e-938c-757205264083';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Қызылша мен ірімшік салаты'), description_kk = COALESCE(description_kk, 'Қан айналымын жақсартатын, көз тартар түсі бар жеңіл түскі ас.

Пайдасы: Қызылша — бауырды тазартуға көмектесетін ең пайдалы көкөністердің бірі, ал ешкі ірімшігі немесе сүзбе — оңай қорытылатын кальций көзі.'), category_kk = COALESCE(category_kk, 'түскі ас'), tags_kk = COALESCE(tags_kk, ARRAY['жалпы']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Қызылша: 1 орташа (пеште пісірілген немесе қайнатылған, текшелеп туралған)","Ешкі ірімшігі (немесе тұзды ірімшік/сүзбе): 2 ас қасық","Аршылған жаңғақ: 1 уыс","Руккола (Arugula) жапырақтары.","Бальзам сірке суы және зәйтүн майы."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Руккола жапырақтарының үстіне туралған қызылшаны, ірімшік пен жаңғақты салыңыз. Үстіне бальзам сірке суы мен зәйтүн майының қоспасын құйыңыз."]'::jsonb) WHERE id = 'db6223cf-fd40-4b31-9334-3aa607532faa';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Авокадо қосылған тост'), description_kk = COALESCE(description_kk, 'Пайдалы майлар мен сапалы ақуыздың ең дәмді үйлесімі.

Пайдасы: Авокадо құрамында әйел гормондары үшін маңызды пайдалы майлар бар, ал жұмыртқа — бұлшықетті сақтауға көмектесетін таза ақуыз көзі.'), category_kk = COALESCE(category_kk, 'таңғы ас'), tags_kk = COALESCE(tags_kk, ARRAY['жалпы']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Тұтас бидай немесе қарабидай наны: 1-2 үлкен тілім","Авокадо: Жарты дана (піскен)","Жұмыртқа: 1-2 дана (пашот әдісімен немесе шала пісірілген)","Лимон шырыны, тұз, қызыл бұрыш үлпектері."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Нанды қызартып қуырыңыз. Авокадоны шанышқымен езіп, лимон шырыны және тұзбен араластырыңыз да, нанның үстіне жағыңыз. Үстіне піскен жұмыртқаны салып, қызыл бұрыш үлпектерін себіңіз."]'::jsonb) WHERE id = 'be15d84a-f891-40e8-bcea-25a7ea3f5e77';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Шпинат қосылған панкейк (1 жас+)'), description_kk = COALESCE(description_kk, 'Таңғы асқа арналған түсі ерекше, қантсыз, жұмсақ әрі дәмді бұлтшалар.

Пайдасы: Шпинат пен банан бір-бірімен тамаша үйлеседі. Темір мен калийге бай.'), category_kk = COALESCE(category_kk, 'Қосымша тағам'), tags_kk = COALESCE(tags_kk, ARRAY['baby_food']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Жас шпинат: 1 уыс","Банан: 1 дана (піскен)","Жұмыртқа: 1 дана","Ұн (тұтас бидай немесе сұлы ұны): 2 ас қасық"]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Шпинат, банан және жұмыртқаны блендерде біркелкі әрі жасыл масса болғанша араластырыңыз. Үстіне ұн қосып, араластырыңыз. Майсыз табаға қасықпен аз-аздан құйып, екі жағын да пісіріңіз."]'::jsonb) WHERE id = 'e3b32abb-4f90-4796-9370-d8e31b9a5d8e';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Тәтті картоптан жасалған қайықшалар (4 жас+)'), description_kk = COALESCE(description_kk, 'Кеме пішінінде ұсынылатын, түрлі түсті әрі дәруменге бай қайықшалар.

Пайдасы: Тәтті картоптың құрамындағы А дәрумені көз саулығын қорғайды. Ал жүгері мен жасыл бұршақ тағамға қызықты құрылым береді.'), category_kk = COALESCE(category_kk, 'Қосымша тағам'), tags_kk = COALESCE(tags_kk, ARRAY['baby_food']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Тәтті картоп (батат): 2 дана (ортасынан бөлініп, пеште пісірілген)","Жасыл бұршақ пен жүгері: әрқайсысы 1 ас қасықтан (пісірілген)","Талшықтап бөлінген тауық еті немесе тартылған ет: 2 ас қасық","Ірімшік (желкен үшін)."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Піскен картоптардың ішін аздап ойып алып, езбе жасаңыз. Оны жасыл бұршақ, жүгері және етпен араластырып, қайтадан картоптың ішіне салыңыз. Үстіне тіс шұқығышпен үшбұрыштап кесілген ірімшікті (желкенді) бекітіңіз."]'::jsonb) WHERE id = 'd55a1489-0c64-4fd1-9c95-61ccad0e27bf';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Апельсин қосылған какао'), description_kk = COALESCE(description_kk, 'Апельсин құрамындағы C дәрумені какаодағы темірдің сіңуіне көмектеседі. Теріге жарқыл береді.'), category_kk = COALESCE(category_kk, 'Пайдалы сусындар'), tags_kk = COALESCE(tags_kk, ARRAY['general']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["1 ас қасық какао, 1 стақан бадам сүті, 1 ас қасық жаңа сығылған апельсин шырыны (немесе үгітілген апельсин қабығы), 1 шай қасық пекмез."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Какаоны ыстық бадам сүтіне ерітіп, оттан алғаннан кейін апельсин шырыны мен пекмезді қосыңыз."]'::jsonb) WHERE id = 'c4928087-d44e-49b9-b047-6872459c8c34';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Күркетауық еті қосылған кәді'), description_kk = COALESCE(description_kk, 'Қамырсыз әрі нансыз дайындалатын, ақуызға бай, тәбет ашатын «қайықшалар».

Пайдасы: Көмірсу мөлшері өте төмен. Күркетауық етіндегі «триптофан» аминқышқылы мелатониннің (ұйқы гормонының) бөлінуін арттырып, терең әрі жайлы ұйықтауға көмектеседі.'), category_kk = COALESCE(category_kk, 'кешкі ас'), tags_kk = COALESCE(tags_kk, ARRAY['general']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Кәді: 2 орташа (ұзынынан екіге бөлініп, ортасы ойылған)","Күркетауық фаршы (немесе майсыз сиыр еті): 150 qr","Қызанақ: 1 дана (үккіштен өткізілген)","Моцарелла немесе голланд ірімшігі: 30 qr (үккіштен өткізілген)","Пияз, сарымсақ, жебіршөп."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Фаршты пияз, сарымсақ және қызанақпен табада шала пісіріңіз. Оны кәді қайықшаларының ішіне салып, 180 градустағы пеште кәді жұмсарғанша (шамамен 25 минут) пісіріңіз. Пештен алуға 5 минут қалғанда үстіне ірімшік себіңіз."]'::jsonb) WHERE id = 'f34874ad-c7fb-4bad-9d1d-814135cad038';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Албырт пен брокколи
(9 ай+)'), description_kk = COALESCE(description_kk, 'Ми жасушаларының қалыптасуына қажетті Омега-3 май қышқылдарына бай алғашқы теңіз тағамы.

Пайдасы: Албырт ми мен жүйке жүйесінің дамуы үшін өте маңызды. Ал брокколи ағзаны кальциймен және C дәруменімен қамтамасыз етеді.'), category_kk = COALESCE(category_kk, 'Қосымша тағам'), tags_kk = COALESCE(tags_kk, ARRAY['baby_food']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Албырт филесі: 30 qr (сүйегі толық алынған)","Брокколи: 2-3 гүлшоғыры","Зәйтүн майы: Бірнеше тамшы."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Балық пен брокколиді буға (немесе аз мөлшердегі суға) әбден пісіріңіз. Балықты шанышқымен ұсақтаған кезде сүйек қалмағанын қайта тексеріңіз. Брокколимен бірге езіп, үстіне зәйтүн майын тамызыңыз."]'::jsonb) WHERE id = 'd3ad67eb-6c19-4eee-9f9a-b784483c1a16';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Көкөністі күріш(4 жас+)'), description_kk = COALESCE(description_kk, 'Мерекелік көңіл күй сыйлайтын, түрлі түсті көкөністерге толы күріш.

Пайдасы: Көмірсулар, дәрумендер мен тағамдық талшықтар бір ыдыста үйлескен өте тойымды түскі ас.'), category_kk = COALESCE(category_kk, 'Қосымша тағам'), tags_kk = COALESCE(tags_kk, ARRAY['baby_food']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Басмати немесе ұзын дәнді күріш: 1 стақан","Сәбіз, жасыл бұршақ, тәтті қызыл бұрыш, жүгері: Әрқайсысынан 2 ас қасық (ұсақ текшелерге туралған)","Сары май және тауық сорпасы."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Көкөністерді аз мөлшердегі сары майға жеңіл қуырыңыз. Жуылған күріш пен сорпаны қосып, суы толық сіңіп, күріш дәндері бір-біріне жабыспай піскенше дайындаңыз."]'::jsonb) WHERE id = 'f04550c5-0fdb-4ab9-8b7b-831a4d2f5e5a';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Пеште пісірілген гүлді қырыққабат стейкі'), description_kk = COALESCE(description_kk, 'Вегандық және пайдалы тамақтану әлеміндегі ең танымал «ет алмастырғыштардың» бірі. Сыртқы көрінісі стейкке ұқсайды.

Пайдасы: Калориясы өте төмен, жасұныққа бай. Пеште піскен кезде қырыққабаттың табиғи қанты карамельденіп, керемет дәм береді.'), category_kk = COALESCE(category_kk, 'жалпы'), tags_kk = COALESCE(tags_kk, ARRAY['жалпы']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Гүлді қырыққабат: 1 бүтін бас (өте үлкен)","Зәйтүн майы: 2 ас қасық","Сарымсақ ұнтағы, тәтті қызыл бұрыш ұнтағы (паприка), теңіз тұзы, қара бұрыш."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Гүлді қырыққабатты бүтін күйінде жуып, ортасынан қалыңдығы 2 сантиметр болатын бүтін «стейк» тілімдерін кесіңіз. Пеш табасына салып, екі жағына да зәйтүн майы мен дәмдеуіштер қоспасын қылқаламмен жағыңыз. 200 градуста екі жағы қызарғанша (шамамен 25-30 минут) пісіріңіз."]'::jsonb) WHERE id = 'dbb5731f-3844-4a55-a0b0-63c083018f90';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Қайықша жұмыртқалар (3 жас+)'), description_kk = COALESCE(description_kk, 'Жұмыртқаның сарысын ұнатпайтын балаларға арналған «кеме» пішініндегі көңілді тіскебасар.

Пайдасы: Жұмыртқаның сарысындағы холин 3 жастағы баланың қарқынды дамып келе жатқан миы мен есте сақтау қабілеті үшін аса маңызды заттардың бірі.'), category_kk = COALESCE(category_kk, 'Қосымша тағам'), tags_kk = COALESCE(tags_kk, ARRAY['бөпе_тамағы']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Қатты пісірілген жұмыртқа: 2 дана","Йогурт: 1 шай қасық","Өте ұсақ туралған түрлі түсті бұрыш («қазына» үшін)","Ірімшік: Үшбұрыштап жұқа кесілген тілімдер (желкен үшін) және тіс шұқығыш."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Жұмыртқаларды тігінен екіге бөліңіз. Сарысын алып, йогуртпен езіңіз де, ішіне түрлі түсті бұрыштың ұсақ бөліктерін («қазынаны») қосып, қайтадан жұмыртқаның ағына салыңыз. Үшбұрышты ірімшік тілімін тіс шұқығышқа өткізіп, жұмыртқаға «желкен» тәрізді қадаңыз (жер алдында тіс шұқығышты алып тастауды ұмытпаңыз!)."]'::jsonb) WHERE id = '38175de9-042b-4fc9-8a58-cdff56307d6d';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Салма салынған портобелло саңырауқұлағы'), description_kk = COALESCE(description_kk, 'Қызыл ет жемей-ақ, еттің құрылымы мен дәмін беретін керемет «қалпақшалар».

Пайдасы: Портобелло саңырауқұлағы теріні ерте қартаюдан қорғайтын селен минералына бай. Өте оңай қорытылады және асқазанға салмақ түсірмейді.'), category_kk = COALESCE(category_kk, 'кешкі ас'), tags_kk = COALESCE(tags_kk, ARRAY['жалпы']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Портобелло саңырауқұлағы: 2 үлкен дана (сабақтары алынып, іші тазартылған)","Саумалдық: 1 уыс (туралған)","Киноа (немесе булгур): 2 ас қасық (піскен)","Фета (немесе ақ ірімшік): 1 ас қасық"]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Саңырауқұлақтардың ішіне киноа, саумалдық және ірімшік қоспасын салыңыз. Пешке арналған ыдысқа салып, үстіне аздап зәйтүн майын құйыңыз. 180 градуста саңырауқұлақтар жұмсарғанша пісіріңіз."]'::jsonb) WHERE id = 'fef93b73-64a7-48d4-94bf-fe08f3ed1adc';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Рубин печеньелері'), description_kk = COALESCE(description_kk, 'Шайға арналған ұнсыз, глютенсіз, тосап қосылған "thumbprint" печеньелері.

Пайдасы: Бадам ұны теріні Е дәруменімен нәрлендіреді, ал үйде дайындалған чиа "тосабы" Омега-3 қажеттілігін өтеуге көмектеседі.'), category_kk = COALESCE(category_kk, 'Пайдалы тәттілер'), tags_kk = COALESCE(tags_kk, ARRAY['general']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Бадам ұны: 1.5 стақан","Бал немесе агава шәрбаты: 3 ас қасық","Кокос майы: 2 ас қасық (ерітілген)","Балғын таңқурай және 1 ас қасық чиа тұқымы (тосап үшін)."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Таңқурайды шанышқымен езіп, чиа тұқымымен араластырыңыз (қоюлануы үшін 15 мин. қоя тұрыңыз). Бадам ұнын, май мен балды араластырып илеп, кішкентай домалақтар жасаңыз. Ортасын саусағыңызбен ойып, пеште 160 градуста 10 мин. пісіріңіз. Пештен шығарып, ойықтарына таңқурай мен чиадан жасалған тосапты салыңыз."]'::jsonb) WHERE id = '6b9ff319-0e3b-432c-ae21-5efca3c9d50d';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Қызылша мен алма езбесі
(7 ай+)'), description_kk = COALESCE(description_kk, 'Бөпеңіздің бетіне қан жүгіртіп, иммунитетін нығайтатын тәтті езбесі.

Пайдасы: Қызылша — қан аздығына қарсы ең тиімді табиғи өнімдердің бірі. Ал алма қызылшаның өзіне тән жер дәмін жұмсартады.'), category_kk = COALESCE(category_kk, 'Қосымша тағам'), tags_kk = COALESCE(tags_kk, ARRAY['baby_food']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Қызылша: 1 кішкентай дана","Алма: Жарты дана"]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Қызылшаны дәрумендері сақталуы үшін қабығымен қайнатыңыз немесе пеште пісіріңіз. Содан кейін қабығын аршып, алмамен бірге блендерде біркелкі езбеге айналдырыңыз. Киіміне төгіліп кетпеуін қадағалаңыз!"]'::jsonb) WHERE id = '55df2691-7b63-4f38-bfb6-d946010b6903';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Тұзды кемпірқосақ кексі(2 жас+)'), description_kk = COALESCE(description_kk, 'Тәттіге ұқсайтын, бірақ шын мәнінде көкөніс пен ірімшік қосылған тұзды кекс.

Пайдасы: Тамақ талғайтын балаға әртүрлі көкөністерді (түрлі түсті бұрыш, көк шөптер) ұнатудың оңай жолы. Саябаққа шыққанда өзіңізбен бірге алып жүруге де өте ыңғайлы.'), category_kk = COALESCE(category_kk, 'Қосымша тағам'), tags_kk = COALESCE(tags_kk, ARRAY['baby_food']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Жұмыртқа: 2 дана","Айран: 2 ас қасық","Зәйтүн майы: 1 ас қасық","Қызыл бұрыш пен саумалдық: Өте ұсақ туралған (1-2 ас қасық)","Ірімшік (үккіштен өткізілген): 2 ас қасық","Ұн мен қопсытқыш (қою кекс қамыры болғанша)."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Сұйық ингредиенттерді (жұмыртқа, айран, май) шайқаңыз. Көкөністер мен ірімшікті қосыңыз.","Соңында ұн мен қопсытқышты қосып араластырыңыз.","Маффин (кекс) қалыптарына құйып, 180 градуста 20 минут көтеріліп, қызарғанша пісіріңіз."]'::jsonb) WHERE id = '03922c9b-57cd-4e60-9084-3b45e0d48642';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Чиа қосылған авокадо тосты'), description_kk = COALESCE(description_kk, 'Классикалық авокадо тостының Омега-3-ке бай, қытырлақ әрі тойымды нұсқасы.

Пайдасы: Чиа тұқымы мен авокадоның үйлесімі — теріні іштен ылғалдандыруға көмектесетін пайдалы майлардың тамаша қоспасы.'), category_kk = COALESCE(category_kk, 'жалпы'), tags_kk = COALESCE(tags_kk, ARRAY['жалпы']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Қара немесе тұтас дәнді бидай наны: 1 тілім (қуырылған)","Авокадо: Жарты дана (піскен)","Чиа тұқымы: 1 шай қасық","Лимон шырыны, теңіз тұзы, қызыл бұрыш үлпектері."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Авокадоны шанышқымен езіп, лимон шырыны және тұзбен араластырыңыз. Қуырылған нанның үстіне молынан жағыңыз. Қытырлақ дәм мен қосымша пайда беру үшін бетіне чиа тұқымы мен қызыл бұрыш үлпектерін себіңіз."]'::jsonb) WHERE id = '87d23e0f-a0db-4aa1-b0fb-794cb2b35b28';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Раушан мен жидек спритці'), description_kk = COALESCE(description_kk, 'Теріңізге арналған сұйық коллаген мен антиоксиданттық қолдау. Өте нәзік әрі сергітетін сусын.

Пайдасы: Жидектер жасушалардың қартаюын баяулатады, ал раушан суы теріні іштен ылғалдандырып, табиғи "glow" (жарқырау) сыйлайды.'), category_kk = COALESCE(category_kk, 'Пайдалы сусындар'), tags_kk = COALESCE(tags_kk, ARRAY['жалпы']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Балғын таңқурай немесе құлпынай: 1 уыс","Раушан суы (ішуге жарамды, қоспасыз): 1 ас қасық","Газдалған су (минералды су): 1 стақан","Лайм: 1 тілім","Мұз текшелері."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Стақанның түбінде жидектерді шанышқымен езіңіз. Үстіне мұзды, раушан суын және лайм шырынын қосыңыз. Соңында газдалған суды құйып, араластырыңыз"]'::jsonb) WHERE id = 'f84c1bc3-0bf2-4206-b695-21d5ec9708da';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Куркума қосылған десерт'), description_kk = COALESCE(description_kk, 'Теріге жарқырау сыйлайтын, қабынуға қарсы италиялық классикалық десерт.

Пайдасы: Куркума мен кокос сүті безеулерді іштен азайтуға көмектеседі, ал желатин — тырнақ пен шашты нығайтатын табиғи коллаген көзі.'), category_kk = COALESCE(category_kk, 'Пайдалы тәттілер'), tags_kk = COALESCE(tags_kk, ARRAY['жалпы']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Кокос сүті (құтыдағы, қою): 1 стақан","Куркума ұнтағы: 1 шай қасық","Бал: 2 ас қасық","Жапырақ желатин: 2 дана (немесе 1 шай қасық агар-агар)"]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Желатинді суық суға жібітіңіз. Сүтті кәстрөлде қыздырыңыз (қайнатпаңыз), оған куркума, бал және жұмсарған желатинді қосып, араластырыңыз. Қоспаны шағын шыны ыдыстарға сүзіп құйып, тоңазытқышта 3-4 сағат бойы қатырыңыз."]'::jsonb) WHERE id = '792abbe5-dddc-4848-8d97-bdcb84318aee';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Қызғылт қоқиқаз панкейктері (3 жас+)'), description_kk = COALESCE(description_kk, 'Тағамдық бояғышсыз, табиғи қызғылт түсімен балаларды қызықтыратын таңғы ас.

Пайдасы: Қызылша қан айналымын жақсартып, иммунитетті қолдайды. Ал сұлы баланы ұзақ уақыт тоқ әрі сергек ұстайды.'), category_kk = COALESCE(category_kk, 'Қосымша тағам'), tags_kk = COALESCE(tags_kk, ARRAY['baby_food']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Қызылша езбесі: 1 ас қасық (піскен қызылшадан)","Жұмыртқа: 1 дана","Сұлы ұны: 3 ас қасық","Сүт: Жарты шай стақаны","Бал: Өте аз (тәттілік беру үшін)"]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Барлық ингредиентті блендермен біркелкі, қызғылт түсті қамыр болғанша араластырыңыз. Майсыз табада шағын дөңгелектер түрінде екі жағын да пісіріңіз."]'::jsonb) WHERE id = '3c637a80-dd91-4c2f-bf85-45f21dbc4610';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Метеорит энергия шарлары (5 жас+)'), description_kk = COALESCE(description_kk, 'Балабақшаға немесе саябаққа барғанда өзіңізбен бірге алып жүруге ыңғайлы, қантсыз «шоколадты» энергия көзі.

Пайдасы: Құрма мен какао жылдам қуат береді, ал жаңғақтар мен орман жаңғағы Омега-3 майларының арқасында тері мен шашты нәрлендіреді.'), category_kk = COALESCE(category_kk, 'Қосымша тағам'), tags_kk = COALESCE(tags_kk, ARRAY['baby_food']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Жұмсақ құрма: 8-10 дана (сүйегі алынған)","Сұлы: Жарты стақан","Какао (қантсыз): 1 ас қасық","Орман жаңғағы немесе күнбағыс дәні: 2 ас қасық."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Барлық ингредиентті блендермен жабысқақ масса болғанша ұсақтаңыз. Қолыңызбен кішкентай «метеориттер» жасаңыз. Үстіне кокос жаңқасын да себуге болады. Тоңазытқышта 30 минут ұстап, ұсыныңыз."]'::jsonb) WHERE id = '13882a92-abb0-49d4-b8c0-e8f4f9c2ea1b';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Зығыр мен чиа пудингі'), description_kk = COALESCE(description_kk, 'Дайындауға небәрі 2 минут кететін, таңғы асқа немесе тіскебасарға арналған, ас қорытуға пайдалы әрі ұзақ уақыт тоқ ұстайтын пудинг.

Пайдасы: Чиа мен зығыр тұқымдары өз салмағынан бірнеше есе көп суды сіңіріп, ісінеді, асқазанда тоқтық сезімін тудырады және қандағы қант деңгейін реттейді.'), category_kk = COALESCE(category_kk, 'general'), tags_kk = COALESCE(tags_kk, ARRAY['general']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Чиа тұқымы: 2 ас қасық","Зығыр тұқымы (ұнтақталған): 1 ас қасық","Бадам сүті (немесе кокос сүті): 1 стақан","Табиғи ваниль сығындысы және 1 шай қасық бал."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Барлық ингредиентті құтыға салып, жақсылап араластырыңыз. 10 минуттан кейін түйіршіктеніп қалмауы үшін қайта араластырып, тоңазытқышқа қойыңыз (кемінде 2 сағатқа немесе түні бойы). Үстін жемістермен безендіріп, жеңіз."]'::jsonb) WHERE id = '9a57e53c-6cc6-4002-bebc-5ba8dd87a146';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Тоскана күні'), description_kk = COALESCE(description_kk, 'Италияның әйгілі "Melanzane alla Parmigiana" тағамының қуырылмай дайындалатын жеңіл әрі пайдалы нұсқасы.

Пайдасы: Баялды — антиоксиданттардың мол көзі. Дәстүрлі қуырудың орнына пеште пісірілетіндіктен, калориясы өте төмен, ал италиялық ірімшіктердің құрамындағы ақуыздың арқасында тойымды.'), category_kk = COALESCE(category_kk, 'жалпы'), tags_kk = COALESCE(tags_kk, ARRAY['жалпы']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Баялды: 2 үлкен дана (ұзынынан туралған)","Табиғи томат (қызанақ) пастасы: 2 стақан (сарымсақ және насыбайгүлмен дәмделген)","Моцарелла және Пармезан ірімшігі: Үккіштен өткізілген","Балғын насыбайгүл, зәйтүн майы."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Баялды тілімдеріне зәйтүн майын жағып, пеште жұмсарғанша (15 минут) пісіріңіз. Шұңғыл пеш ыдысына лазанья секілді қабаттап: қызанақ тұздығын, баялдыны, ірімшік пен насыбайгүлді салыңыз. Үстіңгі ірімшік қызарғанша 190 градуста 20 минут пісіріңіз."]'::jsonb) WHERE id = '9e271ac6-efc7-4123-9cc8-b60e93936503';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Анарлы йогурт тақташасы'), description_kk = COALESCE(description_kk, 'Көздің жауын алатын балмұздақ баламасы. Салқын әрі қытырлақ.

Пайдасы: Анар дәндері әйелдердегі эстроген теңгерімін қолдауға көмектесетін фитоэстрогендер мен антиоксиданттарға бай. Ал йогурт — пробиотик көзі.'), category_kk = COALESCE(category_kk, 'Пайдалы тәттілер'), ingredients_kk = COALESCE(ingredients_kk, '["Йогурт (грек йогурты немесе сүзбе йогурт): 1.5 стақан","Бал: 1 ас қасық","Анар дәндері: Жарты стақан","Пісте: 2 ас қасық (ұсақталған)."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Йогуртты балмен араластырып, майлы қағаз төселген жалпақ ыдысқа (0.5 см қалыңдықта) жайыңыз. Үстіне анар дәндері мен пісте сеуіп, мұздатқышта 3 сағат ұстаңыз. Қатқаннан кейін шоколад секілді қолмен сындырыңыз."]'::jsonb) WHERE id = '80d2e83c-c415-4e59-854e-3c904d65b0ff';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Тауық еті мен киноа қосылған ақуызды боул
(9 ай+)'), description_kk = COALESCE(description_kk, 'Қимыл-қозғалысы артып, еңбектей бастаған бөпелерге арналған ұзақ мерзімді қуат көзі.

Пайдасы: Тауық еті — сапалы ақуыз көзі, ал киноа — дәнді дақылдар арасында тағамдық құндылығы ең жоғары, глютенсіз суперфуд.'), category_kk = COALESCE(category_kk, 'Қосымша тағам'), tags_kk = COALESCE(tags_kk, ARRAY['бөпе_тағамы']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Тауықтың төс еті: 30 qr","Кәді: Жартысынан аз","Киноа: 1 ас қасық (алдын ала жібітіліп, жуылған)."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Тауық етін қайнатыңыз (алғашқы суын төгіңіз). Екінші суға киноа мен туралған кәдіні қосып, барлығы әбден жұмсарғанша пісіріңіз. Содан кейін блендермен ұсақтаңыз немесе шанышқымен аздап түйіршікті етіп езіңіз."]'::jsonb) WHERE id = '45628e71-5b41-431f-b26f-8283c2b308a2';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Матча мен пісте трюфелі'), description_kk = COALESCE(description_kk, 'Зат алмасуды жылдамдатып, теріні жасартуға көмектесетін кофеге арналған "premium" тіскебасар.

Пайдасы: Матча шайы — жасушалардың жаңаруын жылдамдататын күшті антиоксидант. Кешью мен пістенің құрамындағы пайдалы майлар теріні ылғалдандырады.'), category_kk = COALESCE(category_kk, 'Пайдалы тәттілер'), tags_kk = COALESCE(tags_kk, ARRAY['general']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Кешью (шикі, жібітілген): 1 стақан","Құрма: 5-6 дана","Матча ұнтағы: 1 ас қасық (және аунатып алу үшін қосымша)","Пісте: Жарты стақан (ұсақталған)"]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Барлық ингредиентті (пістенің жартысынан басқасын) блендерде жабысқақ қамыр тәрізді болғанша ұнтақтаңыз. Қолыңызбен домалақтап, жартысын матча ұнтағына, ал қалған жартысын ұсақталған пістеге аунатып алыңыз."]'::jsonb) WHERE id = 'ceb5db8c-58a7-4fde-a771-d2ed012eb9df';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Марокколық көкөніс тажины'), description_kk = COALESCE(description_kk, 'Солтүстік Африкаға тән арнайы ыдыста баяу пісірілетін, көкөністер мен жемістердің тәтті-тұзды үйлесімі.

Пайдасы: Ноқат пен көкөністер қандағы қант деңгейін реттеуге көмектесетін күрделі көмірсуларға бай. Қант қоспай, кептірілген жемістермен табиғи түрде тәттілендіріледі.'), category_kk = COALESCE(category_kk, 'general'), tags_kk = COALESCE(tags_kk, ARRAY['general']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Ноқат (піскен): 1 стақан","Сәбіз, кәді, батат (ірі туралған).","Кептірілген өрік немесе мейіз: Жарты стақан","Даршын, зире (кумин), зімбір ұнтағы, зәйтүн майы, көкөніс сорпасы."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Дәмдеуіштерді терең қазанда (немесе дәстүрлі тажин ыдысында) маймен қыздырыңыз. Көкөністерді, ноқатты және кептірілген жемістерді қосыңыз. Үстінен сорпа құйып, қақпағын жауып, баяу отта көкөністер әбден жұмсарғанша (40-45 минут) пісіріңіз. Киноа немесе кускуспен бірге ұсыныңыз."]'::jsonb) WHERE id = '71967587-de0b-4a79-8b91-69af7cbe3013';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Смузи-боул (4 жас+)'), description_kk = COALESCE(description_kk, 'Көкөністер мен жемістерді сұйық түрде ұнатуға көмектесетін, қасықпен желінетін көңілді десерт.

Пайдасы: Иммунитетті нығайтатын дәрумендерге бай. Баланың түстен кейінгі тіскебасарына таптырмас таңдау.'), category_kk = COALESCE(category_kk, 'Қосымша тағам'), tags_kk = COALESCE(tags_kk, ARRAY['baby_food']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Саумалдық: 1 уыс","Мұздатылған банан: 1 дана","Киви: 1 дана","Йогурт немесе сүт: Жарты стақан","Безендіру үшін: Киви тілімдерінен қиылған динозаврдың \"тікендері\" немесе сүйектері."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Саумалдықты, бананды, киви мен сүтті блендерде қою крем тәрізді болғанша араластырыңыз. Ыдысқа құйып, бетін киви тілімдерімен динозаврдың арқасына ұқсатып безендіріңіз."]'::jsonb) WHERE id = '989c089a-7705-4f4f-aa06-64d202a23310';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Қытырлақ балық таяқшалары(2 жас+)'), description_kk = COALESCE(description_kk, 'Дүкенде сатылатын мұздатылған балық таяқшаларының қуырылмаған, 100% табиғи нұсқасы.

Пайдасы: Балық бөпенің миы мен көзінің дамуына қажетті Омега-3 май қышқылдарымен қамтамасыз етеді.'), category_kk = COALESCE(category_kk, 'Қосымша тағам'), tags_kk = COALESCE(tags_kk, ARRAY['baby_food']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Ақ балық филесі (мысалы, сибас — сүйексіз): 100 гр (ұзынша кесілген)","Жұмыртқа: 1 дана (шайқалған)","Сұлы ұны (аунату үшін)","Зәйтүн майы, аздап тұз."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Балық тілімдерін алдымен жұмыртқаға, содан кейін сұлы ұнына аунатыңыз.","Пісіруге арналған қағаз төселген пеш табасына орналастырып, үстіне өте аз зәйтүн майын жағыңыз.","190 градуста 15 минут, қытырлақ болғанша пісіріңіз."]'::jsonb) WHERE id = 'cf74a166-77b4-4cd9-978f-5f84fbaf4d6d';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Супермен кесадильясы(5 жас+)'), description_kk = COALESCE(description_kk, 'Ішіне көкөністер жасырылған, балалар қолмен жегенді ұнататын мексикалық дәмді тағам.

Пайдасы: Қара үрме бұршақ пен тауық еті ақуызға, ал ірімшік сүйекті нығайтатын кальцийге бай.'), category_kk = COALESCE(category_kk, 'Қосымша тағам'), tags_kk = COALESCE(tags_kk, ARRAY['baby_food']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Тұтас бидай ұнынан жасалған лаваш (тортилья): 1 дана","Голланд ірімшігі (үгітілген): 2 ас қасық","Қара үрме бұршақ (піскен) және жүгері: 1 ас қасық","Талшықтап бөлінген тауық еті: 1 ас қасық","Саумалдық (өте ұсақ туралған): Бірнеше жапырақ."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Лаваштың бір жартысына ірімшік, тауық еті, үрме бұршақ, жүгері және саумалдықты жайыңыз. Екінші жартысын үстіне бүктеңіз (жарты ай пішінінде). Ыстық табада ірімшік еріп, лаваш қытырлақ болғанша екі жағын да қуырыңыз. Үшбұрыштап кесіп, дастарқанға ұсыныңыз."]'::jsonb) WHERE id = '495abf5b-aca7-4840-8cc2-c8a7f267da78';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Батат пен жасымық карриі'), description_kk = COALESCE(description_kk, 'Қабынуға қарсы дәмдеуіштерге бай, вегандық әрі глютенсіз үнді асханасының классикалық тағамы.

Пайдасы: Карри мен куркума иммунитетті нығайтады, ал батат тағамға табиғи әрі жібектей жұмсақ тәтті дәм береді.'), category_kk = COALESCE(category_kk, 'general'), tags_kk = COALESCE(tags_kk, ARRAY['general']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Батат (тәтті картоп): 1 үлкен дана (текшелеп туралған)","Қызыл жасымық: 1 стақан","Кокос сүті (консервідегі қою түрі): 1 стақан","Карри ұнтағы: 1 ас қасық","Саумалдық: 1 уыс."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Пиязды, сарымсақты және карри ұнтағын майға қуырыңыз. Үстіне батат, жасымық, кокос сүті және 2 стақан су қосыңыз. Көкөністер толық піскенше баяу отта қайнатыңыз. Оттан алар кезде саумалдықты қосып, араластырыңыз."]'::jsonb) WHERE id = '405b0576-a236-4ed8-8698-3423fb1d2ff0';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Көкөністі тефтельдер (1 жас+)'), description_kk = COALESCE(description_kk, 'Көкөніс жеуден бас тартатын балаларға арналған, көкөністері ішіне «жасырылған» жұмсақ тефтельдер.

Пайдасы: Қызыл ет темірге деген қажеттілікті өтеуге көмектеседі, ал жасырылған көкөністер ағзаны тағамдық талшықтармен және дәрумендермен қамтамасыз етеді. Баланың өз қолымен ұстап жеуіне өте ыңғайлы.'), category_kk = COALESCE(category_kk, 'Қосымша тағам'), tags_kk = COALESCE(tags_kk, ARRAY['baby_food']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Майсыз тартылған сиыр еті: 150 qr","Кәді мен сәбіз: Әрқайсысының төрттен бірі (өте ұсақ үккіштен өткізіліп, шырыны сығылған)","Пияз: Өте кішкентай бөлік (үккіштен өткізілген)","Зәйтүн майы."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Барлық азық-түлікті жақсылап илеңіз. Грек жаңғағындай кішкентай тефтельдер жасаңыз. Пісіру қағазы төселген пеште 180 градуста 20-25 минут бойы кептіріп алмай пісіріңіз."]'::jsonb) WHERE id = '2369413b-697e-4e19-93a2-ff9c61cde8f7';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Көкөніс фрилері (5 жас+)'), description_kk = COALESCE(description_kk, 'Зиянды картоп фрилерін алмастыратын, пеште пісірілген түрлі түсті әрі қытырлақ көкөніс таяқшалары.

Пайдасы: Сәбіз бен батат — А дәрумені мен бета-каротиннің мол көзі, олар көз бен тері саулығын сақтауға көмектеседі.'), category_kk = COALESCE(category_kk, 'Қосымша тағам'), tags_kk = COALESCE(tags_kk, ARRAY['baby_food']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Батат, сәбіз, кәді: Әрқайсысынан жарты данадан","Зәйтүн майы: 1 ас қасық","Кептірілген жалбыз немесе жебіршөп, аздап тұз."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Көкөністерді бірдей көлемде ұзынша таяқша (сиқырлы таяқша) түрінде тураңыз. Маймен және дәмдеуіштермен араластырып, пеш табасына қатарлап қойыңыз. 200 градуста 20-25 минут, шеттері қызарғанша пісіріңіз."]'::jsonb) WHERE id = 'a67b3fb0-1d8c-4568-bbb8-eea9c5b74c3a';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Алтын матча эликсирі'), description_kk = COALESCE(description_kk, 'Қабынуға қарсы әсері бар куркума мен қуат беретін матчаның керемет үйлесімі.'), category_kk = COALESCE(category_kk, 'Пайдалы сусындар'), tags_kk = COALESCE(tags_kk, ARRAY['general']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["1 шай қасық матча, жарты шай қасық куркума, бір шымшым қара бұрыш, 1 стақан жылы бадам сүті, 1 шай қасық бал."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Жылы сүтке барлық азық-түлікті қосып, жақсылап араластырыңыз және көпіршітіңіз."]'::jsonb) WHERE id = '244e5027-cbdf-4e83-8b58-62158b64f304';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Жұлдызды түн сорпасы (3 жас+)'), description_kk = COALESCE(description_kk, 'Сорпа ішкенді ұнатпайтын балаларға арналған, ішінде жұлдыздар қалқып жүретін сүйек сорпасының дәмі.

Пайдасы: Сүйек сорпасы коллаген мен кальцийге бай, балалардың бойының өсуіне және сүйектерінің нығаюына көмектеседі.'), category_kk = COALESCE(category_kk, 'Қосымша тағам'), tags_kk = COALESCE(tags_kk, ARRAY['baby_food']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Таза сүйек немесе тауық сорпасы: 2 стақан","Бөпелерге арналған жұлдыз пішінді макарон: 2 ас қасық","Сәбіз: Жарты дана (өте ұсақ жұлдыз пішінінде туралған)","Ақжелкен: Өте аз (бетіне себу үшін)."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Сорпаны қайнатыңыз, оған жұлдыз пішінді макарон мен жұлдыз пішінінде туралған сәбізді қосыңыз. Макарон толық жұмсарғанша (шамамен 8-10 минут) пісіріңіз."]'::jsonb) WHERE id = '60680ede-d11d-4b46-a277-695525f7d111';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Matcha Strawberry Cloud'), description_kk = COALESCE(description_kk, 'Әлеуметтік желілердегі ең танымал сусын. Теріні нәрлендіретін антиоксиданттар қоры.'), category_kk = COALESCE(category_kk, 'Пайдалы сусындар'), tags_kk = COALESCE(tags_kk, ARRAY['general']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["1 шай қасық матча ұнтағы (жылы суда ерітілген), 4-5 дана балғын құлпынай (езіліп, пюре жасалған), 1 стақан бадам сүті, мұз."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Стақанның түбіне құлпынай пюресін салып, үстіне мұз бен сүтті қосыңыз. Соңында ерітілген жасыл матчаны түстер қабат-қабат (астында қызғылт, үстінде жасыл) болып сақталатындай етіп ақырын құйыңыз."]'::jsonb) WHERE id = '40f5ac74-8479-42d8-bab7-5b56e15de9ae';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Бадам панкейкі және чиа тосабы'), description_kk = COALESCE(description_kk, 'Кәдімгі ұннан жасалатын панкейктердің глютенсіз әрі қантсыз «салауатты өмір» баламасы.

Пайдасы: Бадам ұны қандағы қант деңгейін күрт көтермейді (гликемиялық индексі төмен). Ал чиа тосабы өндірістік тосаптардағы артық қанттан бас тартуға мүмкіндік береді.'), category_kk = COALESCE(category_kk, 'general'), tags_kk = COALESCE(tags_kk, ARRAY['general']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Бадам ұны: 1 стақан","Жұмыртқа: 2 дана","Бадам сүті: Төрттен бір стақан","Тосап үшін: 1 стақан мұздатылған таңқурай және 2 ас қасық чиа тұқымы."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Таңқурайды қыздырып, езіңіз де, оған чиа тұқымын қосып, суытып (қоюлануы үшін) қойыңыз. Бөлек ыдыста бадам ұнын, жұмыртқа мен сүтті араластырып, табада кішкентай панкейктер пісіріңіз. Үстіне өзіңіз дайындаған қантсыз чиа тосабын құйыңыз."]'::jsonb) WHERE id = '0d809ddc-e476-418c-9f34-67e7b608cf9f';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Buffalo стиліндегі гүлді қырыққабат'), description_kk = COALESCE(description_kk, 'Американың әйгілі "Buffalo Wings" (тауық қанаттары) тағамының 100% вегетариандық әрі пайдалы баламасы.

Пайдасы: Қытырлақ фастфуд жегіңіз келгенде таптырмас таңдау. Мұнда тауықтың орнына талшыққа бай гүлді қырыққабат пайдаланылады және майға қуырудың орнына пеште пісіріледі.'), category_kk = COALESCE(category_kk, 'жалпы'), tags_kk = COALESCE(tags_kk, ARRAY['жалпы']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Гүлді қырыққабат: 1 бас (гүлшоғырларға бөлінген)","Тұтас дәнді бидай ұны мен су: Қамыр дайындау үшін (құймақ қамырының қоюлығындай)","Ащы Buffalo тұздығы (немесе кез келген ащы тұздық+сары май қоспасы)."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Гүлді қырыққабаттың гүлшоғырларын ұн мен су қоспасына батырып, пеш табасына тізіңіз. 200 градуста 20 минут пісіріңіз. Пештен шығарып, үстіне ащы тұздық құйыңыз да, жиектері қытырлақ болғанша тағы 10 минут пеште пісіріңіз."]'::jsonb) WHERE id = '287fe4e5-acde-487e-8549-304293001ae7';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Андалусия самалы — испан гаспачосы'), description_kk = COALESCE(description_kk, 'Испанияның оңтүстігінен шыққан, пісіруді қажет етпейтін салқын, балғын әрі дәруменге бай қызанақ сорпасы.

Пайдасы: Бұл — нағыз "гүлдер мен көкөністерден" жасалған детокс. Ликопеннің (қызанақ) және C дәруменінің (бұрыш) арқасында теріні күннің зиянды сәулелерінен іштен қорғауға көмектеседі.'), category_kk = COALESCE(category_kk, 'жалпы'), tags_kk = COALESCE(tags_kk, ARRAY['жалпы']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Өте піскен қызыл қызанақ: 4-5 дана","Қияр: 1 дана (салқындатылған)","Жасыл болгар бұрышы: Жарты дана","Қызыл пияз бен сарымсақ (өте аз)","Бірінші сығымдалған зәйтүн майы (2 ас қасық) және алма сірке суы (1 ас қасық)."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Барлық азықты блендерге салып, үстіне зәйтүн майын, сірке суын және аздап тұз қосыңыз. Толықтай сұйық (сорпа) күйге жеткенше араластырыңыз. Тоңазытқышта мұздай болғанша кемінде 2 сағат ұстаңыз."]'::jsonb) WHERE id = '0732d705-b1b2-4b26-b8dc-748f80e0f06a';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Gold Mac & Cheese (2 жастан+)'), description_kk = COALESCE(description_kk, 'Балалар жақсы көретін ірімшікті макаронның көкөніс қосылған өте пайдалы нұсқасы.

Пайдасы: Классикалық ұнды әрі майлы тұздықтың орнына асқабақ пен сәбізден жасалған тұздық қолданылады. A дәрумені мен кальцийге бай.'), category_kk = COALESCE(category_kk, 'Қосымша тағам'), tags_kk = COALESCE(tags_kk, ARRAY['бөпе_тағамы']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Тұтас дәнді бидайдан жасалған макарон (мүйізше немесе бантик пішінді): 1 стақан","Асқабақ пен сәбіз (пісірілген): Әрқайсысы жарты стақан","Сүт: Жарты стақан","Чеддер (Cheddar) немесе голланд ірімшігі: 3 ас қасық үгітілген"]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Макаронды суда толық піскенше қайнатып, суын сүзіңіз.","Піскен асқабақты, сәбізді және сүтті блендерде біркелкі, қызғылт сары крем (тұздық) болғанша араластырыңыз.","Тұздықты ыстық табаға құйып, үстіне үгітілген ірімшікті қосып ерітіңіз. Соңында макаронды тұздыққа қосып, араластырыңыз."]'::jsonb) WHERE id = '6a513f71-83a0-47b7-94eb-0de33be5ff6d';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Перу севичесі'), description_kk = COALESCE(description_kk, 'Латын Америкасының балық отқа пісірілмей, тек цитрус қышқылының әсерімен «пісетін» сергітетін әрі ақуызға бай тағамы.

Пайдасы: Қосымша май мүлде жоқ, таза ақуыз барынша көп. Бұл — диета ұстанатындардың ең сүйікті тағамдарының бірі.'), category_kk = COALESCE(category_kk, 'жалпы'), tags_kk = COALESCE(tags_kk, ARRAY['жалпы']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Ақ балықтың сүбесі (өте балғын және сүйексіз): 200 qr (ұсақ текшелерге туралған)","Лайм шырыны: Жарты стақан (жаңа сығылған)","Қызыл пияз: Жарты дана (жұқа жарты сақина етіп туралған)","Балғын күнзе, ащы халапеньо бұрышы (қалауыңыз бойынша), тұз."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Шикі балық текшелерін шыны ыдысқа салып, үстіне лайм шырынын құйып, аздап тұз қосыңыз. Шырын балықтың түсін ағартып, оны «пісіреді». Тоңазытқышта 20-30 минут ұстаңыз. Дастарқанға қояр алдында пияз бен күнзені қосып, араластырыңыз."]'::jsonb) WHERE id = '53cbba9d-f39f-4a00-950a-386243d164bd';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Скандинавиялық Smørrebrød'), description_kk = COALESCE(description_kk, 'Дания мен Норвегиядан шыққан, қара бидай нанымен дайындалатын ашық сэндвич өнері.

Пайдасы: Қара бидай наны — күрделі көмірсу (қандағы қант деңгейін күрт көтермейді). Ал албырт — скандинавиялықтардың ұзақ өмір сүру құпиясы саналатын Омега-3 көзі.'), category_kk = COALESCE(category_kk, 'жалпы'), ingredients_kk = COALESCE(ingredients_kk, '["Қара, дәнді қара бидай наны: 1 үлкен тілім","Кілегейлі ірімшік (лабне): 1 ас қасық","Ысталған немесе тұздалған албырт (лосось): 2-3 тілім","Қызыл пияз сақиналары, балғын аскөк, шалғам тілімдері."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Нанның үстіне кілегейлі ірімшік жағыңыз. Балық тілімдерін толқын тәрізді етіп орналастырыңыз. Үстін пияз сақиналарымен, жұқа туралған шалғаммен және мол аскөкпен безендіріп, әдемілеп ұсыныңыз."]'::jsonb) WHERE id = 'dded217d-3179-4368-8e13-255ed13ea4cf';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Киноа таббулесі (Ливан асханасы)'), description_kk = COALESCE(description_kk, 'Дәстүрлі булгурдың орнына глютенсіз әрі ақуызы көбірек киноа қолданылатын Таяу Шығыстың танымал салаты.

Пайдасы: Жеңіл, тағамдық талшық пен C дәруменіне (ақжелкеннің мол болуының арқасында) бай. Қандағы қант деңгейін реттейді.'), category_kk = COALESCE(category_kk, 'жалпы'), tags_kk = COALESCE(tags_kk, ARRAY['жалпы']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Киноа (пісірілген және салқындатылған): 1 стақан","Балғын ақжелкен (өте ұсақ туралған): 2 үлкен бума","Балғын жалбыз: 1 шағын бума","Қызанақ: 2 дана (ұсақ текшелерге туралған)","Көк пияз: 3-4 тал","Салқын сығымдалған зәйтүн майы, мол лимон шырыны және тұз."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Терең ыдыста барлық туралған көк пен көкөністі піскен киноамен араластырыңыз. Үстіне молынан зәйтүн майы мен лимон шырынын құйып, жақсылап араластырыңыз. Тоңазытқышта кемінде 30 минут тынықтырыңыз."]'::jsonb) WHERE id = '23f9812f-031f-4161-95cf-ce2d96da0985';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Үнді жасымық пюресі'), description_kk = COALESCE(description_kk, 'Вегетариандардың сүйікті тағамы — дәмдеуіштердің күшімен денені іштен жылытатын алтын түсті үнді бұқтырмасы.

Пайдасы: Куркума мен зімбір ағзадағы қабынуды азайтуға көмектеседі. Ал жасымық өсімдік ақуызының арқасында ұзақ уақыт тоқтық сезімін сақтайды.'), category_kk = COALESCE(category_kk, 'general'), tags_kk = COALESCE(tags_kk, ARRAY['general']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Қызыл немесе сары жасымық: 1 стақан","Пияз, сарымсақ, балғын зімбір.","Куркума және карри ұнтағы: Әрқайсысы 1 шай қасықтан.","Қызанақ: 1 дана","Кокос сүті: Өте аз мөлшерде (үстіне құю үшін)."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Пиязды, сарымсақты, зімбірді және дәмдеуіштерді майға салып, хош иісі шыққанша қуырыңыз. Туралған қызанақ пен жасымықты қосыңыз. Су құйып, жасымық толық езіліп, пюре тәрізді бұқтырма болғанша пісіріңіз. Үстіне кокос сүтін құйып, күнзе себіңіз."]'::jsonb) WHERE id = 'f1edbb7c-89ad-49b8-9c59-42461d445810';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Неміс картоп салаты'), description_kk = COALESCE(description_kk, 'Майонезі көп ауыр салаттарды алмастыратын, қыша мен сірке суы қосылған керемет жеңіл неміс салаты.

Пайдасы: Салқындатылған картоп пребиотик болып саналатын "резистентті крахмалға" айналады (ішекке пайдалы). Майонез болмағандықтан, холестеринге қатысты мәселе туғызбайды.'), category_kk = COALESCE(category_kk, 'general'), tags_kk = COALESCE(tags_kk, ARRAY['general']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Картоп: 3-4 дана (пісірілген, салқындатылған, тілімделген)","Қызыл пияз: 1 кішкентай бас (ұсақ туралған)","Балғын ақжелкен немесе аскөк","Тұздық үшін: 1 ас қасық дәнді қыша, 2 ас қасық алма сірке суы, 3 ас қасық зәйтүн майы, тұз, қара бұрыш."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Жылы немесе толық салқындатылған картоп тілімдеріне пияз бен көкті қосыңыз. Қышаны, сірке суын және майды құтыға құйып, жақсылап шайқау арқылы тұздық дайындаңыз да, салатқа араластырыңыз."]'::jsonb) WHERE id = 'bfa226ee-4fae-4a95-b348-aee056cab96b';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Shrek''s Mac & Cheese (3 жас+)'), description_kk = COALESCE(description_kk, 'Әдемі жасыл түсімен бірден назар аударатын, құрамында жасырынған саумалдық бар ірімшікті макарон.

Пайдасы: 3 жастағы балалардың көбі саумалдықты шикі немесе піскен күйінде жеуден бас тартады. Осы тұздықтың арқасында олар байқамай-ақ темірді молынан қабылдайды.'), category_kk = COALESCE(category_kk, 'Қосымша тағам'), tags_kk = COALESCE(tags_kk, ARRAY['baby_food']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Макарон: 1 стақан","Саумалдық: 1 үлкен уыс","Сүт: Жарты стақан","Моцарелла немесе Гауда ірімшігі: 2 ас қасық (үккіштен өткізілген)."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Макаронды пісіріп, суын төгіңіз. Саумалдық пен сүтті блендермен біркелкі, түйіршіксіз жасыл сұйықтық болғанша араластырыңыз. Осы жасыл сүтті ыстық табаға құйып, ірімшікті қосып ерітіңіз. Соңында макаронды қосып, жақсылап араластырыңыз."]'::jsonb) WHERE id = '82a7ccbd-e708-435c-afe7-61fd5589966e';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Алтын жарқыл тонигі'), description_kk = COALESCE(description_kk, 'Ағзадағы қабынуды басып, аурулардан қорғайтын таңғы тоник.

Пайдасы: Куркума — қабынуға қарсы әсері күшті табиғи құрал. Терінің қызаруын және буындардың ауырсынуын азайтып, терінің табиғи жарқылын қайтарады.'), category_kk = COALESCE(category_kk, 'Пайдалы сусындар'), tags_kk = COALESCE(tags_kk, ARRAY['general']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Жылы су: 1 стақан","Куркума ұнтағы: Жарты шай қасық","Қара бұрыш: Бір шымшым (куркуманың қанға сіңуі үшін міндетті)","Лимон шырыны және 1 шай қасық табиғи алма сірке суы"]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Барлық ингредиентті жақсылап араластырып, таңертең жылы күйінде (тамақ пен асқазанды күйдірмейтіндей температурада) асықпай, ұрттап ішіңіз."]'::jsonb) WHERE id = '55d6317c-4bcb-4a93-943a-dda17af68226';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Түрлі түсті кәуапшалар(5 жас+)'), description_kk = COALESCE(description_kk, 'Көкөніс пен етті түрлі түсті ойын секілді бірге ұсынатын кәуапшалар.

Пайдасы: Балаларға ақуыз бен дәрумендерді бір мезгілде қызықты тәсілмен жегізудің ең ыңғайлы жолы.'), category_kk = COALESCE(category_kk, 'Қосымша тағам'), tags_kk = COALESCE(tags_kk, ARRAY['baby_food']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Тауықтың төс еті: 100 qr (қуырылған немесе пісірілген, текшелеп туралған)","Түрлі түсті болгар бұрышы (қызыл, сары), черри қызанағы және қияр (қалың етіп туралған).","Ұшы доғал ағаш таяқшалар (шпажкалар)."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Таяқшаларға кезекпен черри қызанағын, тауық етінің текшесін, сары бұрышты, қиярды және қайтадан тауық етін тізіңіз. Түстердің кемпірқосақ секілді орналасуына мән беріңіз."]'::jsonb) WHERE id = 'd945cba8-c55e-4693-91cb-3385f3ce8b99';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Песто тұздығы қосылған кәді спагеттиі'), description_kk = COALESCE(description_kk, 'Қамыр тағамының дәмін сездіретін, бірақ мүлде салмақ қоспайтын ғажайып паста.

Пайдасы: Калориясы өте төмен. Песто тұздығындағы зәйтүн майы мен насыбайгүл — күшті антиоксиданттар, олар жасушалардың жастығын сақтайды.'), category_kk = COALESCE(category_kk, 'түскі ас'), tags_kk = COALESCE(tags_kk, ARRAY['general']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Кәді: 2 орташа (арнайы құралмен спагетти тәрізді туралған)","Песто тұздығы: 2 ас қасық (езілген балғын насыбайгүл, зәйтүн майы, жаңғақ, сарымсақ)","Черри қызанағы: 4-5 дана."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Кәді спагеттиін табада аздап зәйтүн майына салып, небәрі 2-3 минут қуырыңыз (тым қатты пісірмеңіз, қытырлақ күйінде қалсын). Оттан алып, песто тұздығымен және екіге бөлінген қызанақтармен араластырыңыз."]'::jsonb) WHERE id = '4562e352-5778-4e1f-951e-cc27bf63469a';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Алтын жасымық пен зімбір сорпасы'), description_kk = COALESCE(description_kk, 'Зат алмасуды жандандырып, бойды жылытатын қысқы түскі ас.

Пайдасы: Зімбір мен куркума ағзадағы қабынуды (ісіну, безеу, буындардың ауыруы) азайтады, ал қызыл жасымық ұзақ уақыт тоқтық сезімін береді.'), category_kk = COALESCE(category_kk, 'түскі ас'), tags_kk = COALESCE(tags_kk, ARRAY['general']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Қызыл жасымық: 1 стақан","Балғын зімбір: Орман жаңғағындай (үккіштен өткізілген)","Куркума: Жарты шай қасық","Сәбіз, пияз.","Кокос сүті: 2 ас қасық (қалауыңызша, үстіне құю үшін)."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Барлық көкөніс пен жасымықты суға салып, жұмсарғанша қайнатыңыз да, блендермен езіңіз. Куркума мен зімбірді қосып, тағы біраз қайнатыңыз. Ыдысқа құйған кезде үстіне кокос сүтін тамшылатып құйыңыз."]'::jsonb) WHERE id = '9dca9acb-e3bc-495a-9af1-62c75bc63dca';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Тәтті картоп пен үрмебұршақ'), description_kk = COALESCE(description_kk, 'ПМС (етеккір алдындағы) кезеңінде тәттіге деген құмарлық пен көңіл күйдің өзгеруін реттеуге көмектесетін рецепт.

Пайдасы: Тәтті картоп пен қара үрмебұршақ магнийге бай, жүйке жүйесін тыныштандырады, түйілуді азайтады және ұзақ уақыт тоқтық сезімін береді.'), category_kk = COALESCE(category_kk, 'түскі ас'), tags_kk = COALESCE(tags_kk, ARRAY['general']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Тәтті картоп (батат): 1 дана (ортасынан бөлініп, пеште толық пісірілген)","Қара үрмебұршақ (немесе қызыл): 2 ас қасық (пісірілген)","Жүгері: 1 ас қасық","Авокадо езбесі (гуакамоле) және лайм шырыны."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Піскен, іші жұмсарған тәтті картоптың ортасына қара үрмебұршақ пен жүгеріні салыңыз. Үстіне авокадо езбесін салып, лайм шырынын сығыңыз."]'::jsonb) WHERE id = '0298f702-76b2-4fe4-995b-506dab64f0f1';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, '«Қонжық» пюресі(1 жас+)'), description_kk = COALESCE(description_kk, 'Етті шайнауы қиын балаларға арналған, ауызда еритін, нәрлі әрі шырынды қысқы тағам.

Пайдасы: Ұзақ уақыт пісірілген ет жеңіл қорытылады, ал сорпасы сүйектің дамуына пайдалы.'), category_kk = COALESCE(category_kk, 'Қосымша тағам'), tags_kk = COALESCE(tags_kk, ARRAY['baby_food']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Сиыр еті: 50 qr (өте ұсақ, бұршақ көлеміндей текшелер)","Сәбіз бен картоп: Жарты данадан (текшелеп туралған)","Қызанақ: Төрттен бір бөлігі (үккіштен өткізілген)","Зәйтүн майы және су."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Етті зәйтүн майына салып, түсі өзгергенше қуырыңыз. Үстіне қызанақ пен су қосып, жұмсарғанша пісіріңіз (қысымды қазанда пісірген дұрыс). Содан кейін сәбіз бен картопты қосып, көкөністер езіліп кетердей жұмсарғанша пісіріңіз."]'::jsonb) WHERE id = 'a7eb16f8-9a88-4ac0-92d3-fb7d3da355e0';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Ноқатты блонди'), description_kk = COALESCE(description_kk, 'Құрамында ноқат бар екеніне ешкім сенбейтін, карамель дәмі бар ұнсыз кекс.

Пайдасы: Бұл тәтті ақуыз бен күрделі көмірсуларға бай. Глютеннен болатын іштің кебуін тудырмайды, кешкі жаттығудан кейін (бұлшықеттердің қалпына келуі үшін) шаймен тамаша үйлеседі.'), category_kk = COALESCE(category_kk, 'Пайдалы тәттілер'), tags_kk = COALESCE(tags_kk, ARRAY['general']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Консервіленген ноқат: 1 стақан (жақсылап жуылып, қабығы аршылған)","Жержаңғақ пастасы: 3 ас қасық","Бал немесе үйеңкі шәрбаты: 3 ас қасық","Ваниль, қопсытқыш.","Шоколад түйіршіктері (қара шоколад)."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Шоколадтан басқа барлық ингредиентті блендерде біркелкі тегіс қамыр болғанша араластырыңыз. Шоколад түйіршіктерін қосып, шағын төртбұрышты кекс қалыбына құйыңыз. 175 градуста 20 мин. пісіріңіз. Жылы кезінде тілімдерге бөліңіз."]'::jsonb) WHERE id = '4b5bc08b-15b1-4187-aa19-05b7b3bb4ae4';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Брокколи мен сиыр етінен соте'), description_kk = COALESCE(description_kk, 'Бүкіл әлем сүйіп жейтін әйгілі Азия (Қытай) асханасының ең пайдалы классикалық тағамдарының бірі.

Пайдасы: Темір (еттен) мен кальций/С дәрумені (брокколиден) тамаша үйлесім табады. Тез дайындалады.'), category_kk = COALESCE(category_kk, 'жалпы'), tags_kk = COALESCE(tags_kk, ARRAY['жалпы']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Сиыр еті (сүбе еті, өте жұқа туралған): 250 гр","Брокколи: 1 бүтін бас (гүлшоғырларына бөлінген)","Соя тұздығы (тұзы аз): 3 ас қасық","Балғын зімбір мен сарымсақ (ұсақталған).","Күнжіт майы мен күнжіт дәні."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Табада (вокта) етті қатты отта тез қуырып, бөлек алып қойыңыз. Сол табаға брокколи, сарымсақ пен зімбірді салып, 3-4 минут сотелеңіз (брокколи қытырлақ күйінде қалуы керек). Етті қайта салып, соя тұздығын қосыңыз да, 1 минут араластырыңыз. Үстіне күнжіт сеуіп, оттан алыңыз."]'::jsonb) WHERE id = 'cdafe114-fffe-4d67-b795-0770d33715ea';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Зығыр дәні мен бадам ұнынан жасалған крекер'), description_kk = COALESCE(description_kk, 'Дүкенде сатылатын зиянды чипсілерді алмастыратын, 100% глютенсіз, көмірсусыз (Keto) үй крекерлері.

Пайдасы: Бадам ұны Е дәруменіне бай, ал зығыр дәні ішектің жұмысын тамаша реттейді.'), category_kk = COALESCE(category_kk, 'жалпы'), tags_kk = COALESCE(tags_kk, ARRAY['жалпы']::text[]), ingredients_kk = COALESCE(ingredients_kk, '["Бадам ұны: 1 стақан","Зығыр дәні (ұнтақталған): 3 ас қасық","Су: 3 ас қасық","Зәйтүн майы: 1 ас қасық","Тұз және кептірілген тасшөп."]'::jsonb), instructions_kk = COALESCE(instructions_kk, '["Барлық азық-түлікті бір ыдысқа салып илеп, қамыр дайындаңыз. Қамырды майлы қағаздың екі парағының арасына қойып, оқтаумен өте жұқа (чипсі сияқты) етіп жайыңыз. Пышақпен шаршыларға кесіп, 170 градус пеште 15-20 минут қытырлақ болғанша пісіріңіз."]'::jsonb) WHERE id = 'd73926c7-3c66-41bd-88a6-1a28c3a2f959';
UPDATE public.admin_recipes SET title_kk = COALESCE(title_kk, 'Какао мен Maca сиқыры'), description_kk = COALESCE(description_kk, 'Әйел гормондарының тепе-теңдігін қолдап, бақыт гормонының деңгейін көтеретін жылы сусын.

