UPDATE public.baby_crisis_periods SET title_kk = COALESCE(title_kk, 'Бірқалыпты ауысулар әлемі'), description_kk = COALESCE(description_kk, 'Бөпе бірқалыпты қимылдауды және бір әрекеттен екіншісіне ауысуды үйренеді'), symptoms_kk = COALESCE(symptoms_kk, '["Көбірек жылау","Ұйқының бұзылуы","Үнемі қолда болғысы келу"]'), tips_kk = COALESCE(tips_kk, '["Қимыл-қозғалыс жаттығулары","Ақырын тербету","Массаж"]') WHERE id = 'f8fc8a04-d9e6-4b79-b565-8cbc1c9ccb94';
UPDATE public.baby_crisis_periods SET title_kk = COALESCE(title_kk, 'Оқиғалар әлемі'), description_kk = COALESCE(description_kk, 'Бөпе себеп-салдар байланысын және оқиғалардың ретін түсіне бастайды'), symptoms_kk = COALESCE(symptoms_kk, '["Сізден мүлде ажырағысы келмеу","Көңіл күйдің құбылуы","Тәбеттің төмендеуі","Түнде ояну"]'), tips_kk = COALESCE(tips_kk, '["«Ку-ку» ойыны","Тұрақты күн тәртібі","Көбірек сабыр сақтау"]') WHERE id = '4f00fc01-ffca-4cb6-a186-c3cae46fe443';
UPDATE public.baby_crisis_periods SET title_kk = COALESCE(title_kk, 'Қарым-қатынастар әлемі'), description_kk = COALESCE(description_kk, 'Бөпе заттардың арасындағы қашықтық пен өзара байланысты түсіне бастайды'), symptoms_kk = COALESCE(symptoms_kk, '["Ажырасудан қорқу","Қорқынышты түстер","Бейтаныс адамдардан ұялу"]'), tips_kk = COALESCE(tips_kk, '["Жанында болу","Жұбататын сүйікті заттар","Біртіндеп алыстауға үйрету"]') WHERE id = '5c97a8c2-5724-4bd6-97dd-fe1b7f05c200';
UPDATE public.baby_crisis_periods SET title_kk = COALESCE(title_kk, 'Санаттар әлемі'), description_kk = COALESCE(description_kk, 'Бөпе заттарды, адамдарды және эмоцияларды санаттарға бөле бастайды'), symptoms_kk = COALESCE(symptoms_kk, '["Долдану","Өзімшілдік таныту","Шектеулерді сынау"]'), tips_kk = COALESCE(tips_kk, '["Заттардың атауын айту","Топтастыру ойындары","Нақты шекаралар белгілеу"]') WHERE id = 'f13911eb-137a-4fe7-be01-bccf1325e4e6';

-- ── baby_daily_info → kk (1457 sətir) ──
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Ұзақ жүктілік кезеңінен кейін бөпеңізді ақыры бауырыңызға бастыңыз. Anacan отбасы ретінде бөпеңізбен өткізетін әрбір бақытты күніңізде жаныңыздан табыламыз! 😊 Бөпеңіздің дүниеге келген сәттен бастап тәуліктің басым бөлігін ұйқымен өткізетінін байқап та үлгерген боларсыз. Тіпті кейде бұған алаңдауыңыз да мүмкін. Ұйқының жаңа туған бөпенің денсаулығы, өсуі мен дамуы үшін аса маңызды қажеттілік екенін білгеніңіз жөн. Бөпеңіз емізу мен жөргегін ауыстырудан басқа уақытының барлығын дерлік ұйқымен өткізеді. Ұйқы кезінде ағзасында бөлінетін мелатонин гормоны бөпенің иммундық жүйесін нығайтып, гипофиз безінің өсу гормонын көбірек бөлуіне ықпал етеді. Алайда бөпеңіз өскен сайын оның ұйқы ұзақтығы қысқарады. Сондықтан осы күндері мүмкіндігінше көбірек демалып алғаныңыз пайдалы.') WHERE id = '31cd50a4-c6f5-4862-b0ff-2fa89b11b67b';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіз дүниеге келгенде оның терісінен ақшыл, майлы әрі крем тәрізді қабатты байқаған боларсыз. Верникс казеоза деп аталатын бұл жұқа қорғаныш заттың 80%-ы судан тұрады және құрамында липидтер мен ақуыздар мол. Бұл майлы қабаттың тері бетіне таралуы босану болған жүктілік аптасына және босану тәсіліне қарай әртүрлі болуы мүмкін. Әдетте мерзімінен кеш туған бөпелерде бұл қабаттың бір бөлігі теріге сіңіп үлгереді. Ал 37 аптаға дейін туған бөпелердің терісінде бұл қабаттың қалыңырақ болатыны байқалады. Верникстің құрамында микробтарды жоятын қорғаныш жасушалары және бөпе ағзасының табиғи иммунитетін қолдайтын 40-қа жуық түрлі ақуыз бар. Сондықтан бөпеңізді туғаннан кейін кемінде 24 сағат шомылдырмай, терісінің осы қабатты жақсылап сіңіруін күткеніңіз жөн.') WHERE id = '01b8c794-e427-40d5-a912-edbb2df87798';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіз дүниеге келген сәттен бастап күшті рефлекстерге ие. Олардың ішіндегі ең маңыздысы, әрине, қоректенуіне мүмкіндік беретін сору рефлексі. Бөпенің ұртына немесе аузының жиегіне қол тигізгенде, ол бірден сол жаққа бұрылып, қорек көзін іздей бастайды. Сору рефлексі — бөпенің қоректенуге және эмоциялық қажеттіліктерін қанағаттандыруға мүмкіндік беретін механикалық қимыл. Бұл рефлекс бөпе әлі құрсақта жатқанда, дамуының 14-ші аптасында қалыптаса бастайды. Ауыз қуысы мен таңдай сүйегі жетіліп, ұрттағы вакуум тудыратын бұлшықет құрылымы қалыптасқан кезде ол толық жүзеге асады. Жүктіліктің өте ерте кезеңінде пайда болатын осы рефлексті бөпе құрсақта жатқан уақыт бойы жаттықтырады. Соның арқасында бөпеңіз дүниеге келген алғашқы сәттен-ақ қоректенуге қажетті тәжірибе мен дағдыға ие болады.') WHERE id = '4db7f0d9-f7be-435d-a305-5bea20ce135c';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіз дүниеге келгеннен кейін Сізді көп адамның арасынан түйсікпен таниды. Бұл түйсіктің қалыптасуына Сіздің иісіңіз бен даусыңыз көмектеседі деп есептеледі. Бөпеңізбен қауышқан алғашқы күндері оны жиі емізіп, көзіне қарап сөйлесіп, нәзік жанасуыңыз керек. Бөпеңізбен әрбір жанасу сәті ағзаңызда окситоцин гормонының бөлінуіне ықпал етеді. Окситоцин сүтті сүт безінің ұшына қарай жеткізетін бұлшықет жасушаларының жиырылуын қамтамасыз етеді. Бөпеңізді қоректендіруге көмектесетін тағы бір гормон — мидағы гипофиз безі бөлетін пролактин. Осы екі гормон өзара үйлесімді жұмыс істеп, бөпе емген кезде сүттің бөлінуін және емізік ұшына келуін қамтамасыз етеді.') WHERE id = 'a25dea37-57a2-46fc-889c-23e73ad36d76';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіз дүниеге келгеннен кейін бірден дәрігер оның денсаулығын тексереді. Сонымен қатар босанғаннан кейінгі алғашқы минуттарда дәрігер бөпенің аяғына оның алғашқы екпесі — В гепатитіне қарсы вакцинаны егеді. Егер Сіз В гепатитінің тасымалдаушысы болсаңыз, бөпеңізге вакцинамен бірге иммуноглобулин де енгізіледі. Бұдан бөлек, алғашқы 1 ай ішінде бөпеңізге В гепатитіне қарсы вакцинадан басқа екпе салынбайды. Содан кейін бөпеңіз ауруханадан шықпай тұрып педиатр оның денсаулығын жан-жақты тексереді. Сондай-ақ аурухана тағайындаған мейіргер алғашқы күндері бөпеге қалай күтім жасау керектігін және неге назар аудару қажет екенін түсіндіреді. Берілген ақпараттың барлығы бөпеңізге дұрыс күтім жасауға көмектесетін аса маңызды кеңестер болады.') WHERE id = '0d9fa9e8-940a-4ec4-b501-2f30433e0030';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіздің бойы мен салмағы оның жалпы денсаулығы туралы мәлімет береді. Ал бас шеңберін өлшеу ми қызметін бағалау үшін өте маңызды. Алғашқы өлшеулерде бөпенің бас шеңбері әдетте 32 см мен 37 см аралығында болады. Бұл көрсеткіштер мидың сау дамып жатқанын білдіреді. Бас шеңберінің ұлғаюы ми дамуының көрсеткіші болғандықтан, оған мұқият назар аудару қажет. Бөпеңіздің бойын, салмағын және бас өлшемін жүйелі түрде бақылап отыру міндетті. Сондықтан білікті педиатр тауып, онымен бірге бақылау кестесін құруыңыз керек. Дамуын бақылау үшін туғаннан кейін шамамен 5-ші, 14-ші және 30-шы күндері жоспарлы тексеруге дәрігерге бару ұсынылады.') WHERE id = '8c627179-a029-49ba-9226-4fa26ffce0a7';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Жаңа туған бөпелер қарны аша бастағанда, бірден жыламай, алдымен қимылдай бастайды. Одан кейін біртіндеп мазасыздануы мүмкін. Егер осы белгілерден кейін де қарны тоймаса, жылай бастайды, ал аш жүрген уақыты ұзарған сайын жылауы да күшейе түседі. Осы кезеңде бөпені бірден тамақтандыруға тырысу кейде оның емшектен немесе бөтелкеден бас тартуына себеп болуы мүмкін. Сондықтан жылап жатқан бөпеңізді алдымен қолыңызға алып тыныштандырып, содан кейін тамақтандырғаныңыз жөн. Қолыңызға алсаңыз да бөпеңіз тынышталмаса, оны түрегеп тұрып емізіп көруге болады. Сіз бен бөпеңіз әлі де бір-біріңізге үйреніп жүргендіктен, оның әрекеттерін бақылап, не қалайтынын түсінуге тырысыңыз.') WHERE id = '9e7fdf66-075d-494d-b199-11e006ca39c4';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Босанғаннан кейін бөпеңіздің ең маңызды қорегі — ана сүті омырауыңыздан бөліне бастайды. Сондықтан алғашқы апталарда сұйықтықты мол ішіп, мүмкіндігінше күйзелістен аулақ болуыңыз керек. Осы аптадан бастап Сізде де, бөпеңізде де ішке газ жиналуына байланысты шағымдар пайда болуы мүмкін. Бөпенің іш кебуі мен түйілуін жеңілдету үшін дәрігер ұсынатын газға қарсы тамшылар әдетте 1-айдан кейін беріледі. Сондықтан газ түзетін тағамдардан аулақ болуға тырысып, ас мәзіріңізге қантсыз компоттарды, жаңа сығылған жеміс шырындарын және көкөніс сорпаларын қосыңыз. Сүт пен сүт өнімдері, бұршақ тұқымдастар, апельсин және мандарин сияқты қышқыл жемістер іштің кебуі мен түйілуіне себеп болуы мүмкін. Сондықтан бұл тағамдарды аз мөлшерден байқап, мәзіріңізге қосқаныңыз жөн. Егер сүт өнімдері газ түзілуіне себеп болса, лактозасыз сүтті пайдалануға болады.') WHERE id = 'bbfc25e1-805a-4de5-a48e-49b8bc100ff1';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіздің ұйқы режимінің қалыптасуына біраз уақыт қажет болуы мүмкін. Алғашқы айларда әдетте күні бойы ұйықтап, оянып жүретін бөпенің күн мен түнді ажырата алмауы да ұйқы режимінің қалыпқа келуін кешіктіреді. Бөпенің шамадан тыс шаршауы және ұйқысының қанбауы оның жылауына себеп болады. Алғашқы айларда тәулігіне 15-16 сағатқа дейін ұйықтауы тиіс бөпеңіз ұйықтай алмаса, қатты мазасызданады. Сондай-ақ қатты шу мен көру арқылы әсер ететін тітіркендіргіштердің көп болуы да оның ұйықтауына кедергі келтіріп, жылауына әкелуі мүмкін. Бөпенің ұйқы режимі 8-12-апталар аралығында біртіндеп қалыптаса бастайды. Емізу аралықтарының ұзаруы да осы режимнің қалыптасуына көмектеседі. Алайда әр бөпе әртүрлі болғандықтан, кейбірінің ұйқы режиміне кешірек бейімделуі қалыпты жағдай.') WHERE id = 'a4331c8d-b2a0-435c-af06-870f5fad8fab';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіз дүниеге келген сәттен бастап адам дауысына өте сезімтал болады. Бұл дыбыс жиіліктерінің диапазонына байланысты деп есептеледі. Сонымен қатар 9 ай бойы құрсағыңызда ол көбіне ағзаларыңыз жұмыс істеген кезде шығатын дыбыстарды және Сіз сөйлегендегі даусыңызды естіді. Бөпеңізді тыныштандыру үшін осыны пайдаланып, онымен жиі сөйлесіңіз. Даусыңызды және қолыңызға алған кезде жүрегіңіздің соғысын естіген бөпе өзін жайлы әрі қауіпсіз сезінеді. Сондай-ақ бөпеңіз сезімдері мен қажеттіліктерін білдіру үшін түрлі дыбыстар шығара бастаған болуы мүмкін. Бөпеңізбен тиімді қарым-қатынас орнату үшін оның шығарған дыбыстарына ұқсас дыбыстармен жауап бергеніңіз маңызды. Осылайша бөпеңіз қарым-қатынас жасау үшін сөйлеуді және дыбыстарды пайдалануды үйрене бастайды.') WHERE id = '1ec6d652-1eca-417a-9067-3ad2a20a5f4b';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпелердің шамамен 20%-ы дені сау болғанына қарамастан, тоқтаусыз жылау ұстамаларына тап болуы мүмкін. Колика деп аталатын бұл жағдай әдетте кешкі уақытта басталып, бөпені бірнеше сағат бойы тыныштандыру мүмкін болмайды. Коликаның себебі әлі толық анықталмағанымен, ол ас қорыту жүйесінің толық жетілмеуіне, кейбір аллергиялық реакцияларға немесе жүйке жүйесіне байланысты болуы мүмкін деп есептеледі. Егер дәрігер бөпеңізге колика диагнозын қойса, алаңдауыңыз қалыпты. Ең алдымен, бұл жағдайдың уақытша екенін білгеніңіз жөн. Әдетте 3-айдың соңында мұндай жылау ұстамалары азая бастайды және көп ұзамай басылады. Бөпеңіз жылаған кезде оны тыныштандырудың әртүрлі тәсілдерін қолданып, қайсысы көмектесетінін анықтаңыз. Жиі қолданылатын тәсілдерге жылы суға шомылдыру, ішіне жылы сүлгі қою немесе фен сияқты бірқалыпты қайталанатын дыбыс шығаратын құрылғыларды қосу жатады.') WHERE id = 'd6246f09-676f-479b-ac15-8f1e83a043b1';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңізбен бірге тағы 1 айды артқа тастадыңыз! Бөпеңіздің екпе күнтізбесінің 1-айында алғашқы дозасы туғаннан кейін бірден салынатын В гепатитіне қарсы екпенің екінші дозасы егіледі. Екпе салынған аяғында қызару мен ісіну пайда болуы мүмкін. Мұндай жағдайда алаңдамаңыз. Сондай-ақ бөпеңіздің дене қызуы қысқа уақытқа көтеріліп, екпеден кейін мазасыздануы мүмкін. Бұл — жиі кездесетін әрі зиянсыз жанама әсерлер. Әсіресе мазасыздық екпе алған бөпелердің барлығында дерлік байқалуы мүмкін. Екпеден кейін дене қызуы әдетте 38 градустан аспайды. Дәрігеріңіздің кеңесімен ұзақ уақыт түспеген дене қызуын төмендету үшін шәрбат немесе суппозиторий қолдануға болады. Сирек кездескенімен, бөпеңізде әдеттен тыс белгілер бар деп ойласаңыз, дәрігеріңізбен хабарласуды ұмытпаңыз.') WHERE id = '418e11ce-7ef6-4382-bb9b-0ee9fe10e295';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңізді жатқызғанда оның үнемі бүктетіліп жататынын байқаған боларсыз. Ана құрсағында 9 ай бойы ұрық қалпында жатқандықтан, бұл әдеті әлі біраз уақыт сақталады. Шамамен 2-ші айда бұл қалып біртіндеп азайып, 3-ші айда толығымен жоғалады. Ана құрсағындағы қауіпсіз әрі тұйық ортадан кейін сыртқы әлем оған қорқынышты және түсініксіз болып көрінуі мүмкін. Сондықтан ол үнемі Сізбен жанасып, жақын болғысы келеді. Оған уақыт беріңіз, біртіндеп үйренеді. Сіздің иісіңізді сезетін құшағыңыз ол үшін ең қауіпсіз жер екенін ұмытпаңыз. Ана мен бөпе арасындағы берік байланыс алғашқы күндерден-ақ қалыптасады. Қарны ашқанда немесе жөргегін ауыстыру қажет болғанда күттірмей, қажетін бірден өтеп беріңіз. Біраз уақыт сыртқы дүниені ұмытып, бар назарыңызды бөпеңізге арнаңыз.') WHERE id = '990edf71-6742-4577-9d2f-dadba792cf8a';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңізбен бірге өткізген алғашқы апта да артта қалды. Уақыт неткен тез өтеді, солай емес пе? 😊 Жүктілік кезінде бөпенің ішегі стерильді болады және онда ешқандай зиянды ағза болмайды. Егер босану кесарь тілігі арқылы өтсе, ас қорытуға көмектесетін бактериялар бөпенің ішек флорасында дәл осы күннен бастап қалыптаса бастайды. Ал табиғи босану кезінде бұл үдеріс 4-ші күннен басталады. Бұл бактериялардың бір бөлігі пайдалы, ал бір бөлігі зиянды. Олардың екі түрінің де болуы ас қорыту жүйесінде тепе-теңдік қалыптастырып, бір-бірінің шамадан тыс көбеюіне жол бермейді. Яғни бұл ағзалар бөпенің ішек флорасының тепе-теңдігін сақтау үшін маңызды.') WHERE id = 'ea7ac5e6-2b68-47b7-9578-f87a52623334';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Сүтім аз деп ойлап, өзіңізді қинамаңыз, аяулы ана. Бөпе дүниеге келгенде оның асқазаны небәрі бір шие көлеміндей болады. Сондықтан сүтіңіз жетпейді деп алаңдамаңыз. Босанғаннан кейінгі күндері асқазаны үлкейіп, қазір шамамен бір өріктей, яғни көлемі 50 ml шамасында болады. Сол себепті Сізге аз болып көрінетін сүт шын мәнінде оның тоюына толық жетеді. Асқазаны әлі кішкентай болғандықтан, бөпеңіз аз-аздан, бірақ жиі емгісі келеді. Егер емгеннен кейін құсса, бұл әдетте асқазанының сыйымдылығынан артық ішкен кезде болады. Яғни халық арасында айтылатын «сүтіңіз жақпайды» деген сөз — жай ғана аңыз, оған сенбеңіз.') WHERE id = 'f7f368ac-9bca-4520-b0e3-f83cfbd455a4';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Босанғаннан кейін бірден келетін сүт уыз (колострум) деп аталады. Бұл — қою, сарғыш түсті, бөпені инфекциялардан қорғайтын антиденелерге бай әрі ақуыздық құндылығы жоғары өте бағалы тағам. Босанғаннан кейін шамамен 5-7 күн өткенде оның орнын өтпелі сүт басады. Өтпелі сүттің құрамында уызға қарағанда май мен лактоза көбірек болады, яғни оның қуаттылығы жоғары. Сүттің бұл түрі шамамен 14-ші күнге дейін бөлінеді. Ал босанғаннан кейін 2 апта өткен соң нағыз жетілген сүт келе бастайды. Бұл сүт суға да, ақуызға да, майға да өте бай.') WHERE id = '4794b2b1-e590-4e29-b9bf-54af8c8dcab5';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеге күтім жасау, әсіресе алғаш рет ана атансаңыз, бастапқыда қорқынышты көрінуі мүмкін. Қолыңыздан келмейді деп ойласаңыз, қателесесіз. 😊 Бұл жаттанды сөз сияқты естілгенімен, уақыт өте келе бөпеңізге еш қиналмай күтім жасайтын боласыз. Осындай күтім шараларының бірі — кеуіп, түсуге жақындаған кіндік қалдығына күтім жасау. Кіндік бауы арқылы жүктілік бойы бөпенің қоректенуі мен дамуына қажетті оттегі және қоректік заттар жеткізіледі. Ұзындығы шамамен 50 см болатын кіндік бауын босанғаннан кейін дәрігер 2 см қалдырып кеседі. Бөпенің кіндік қалдығы 5-ші және 15-ші күн аралығында түседі. Кіндік түскенге дейін де, түскеннен кейін де оған дұрыс күтім жасамасаңыз, осы жерден инфекция жұғу қаупі артуы мүмкін. Бұл қауіпке байланысты дәрігеріңіз ұсынған 70 пайыздық спирт ерітіндісімен кіндік аймағын күніне екі немесе үш рет сүртіп, желдетіп отыру қажет.') WHERE id = '403ffca4-6096-4cf2-9210-17a6a3a59df5';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпе басының денесіне қарағанда үлкенірек болуы — толығымен қалыпты жағдай және бұл денсаулығында қандай да бір мәселе бар дегенді білдірмейді. Сондай-ақ басының пішіні біркелкі болмай, қисықтау көрінуі мүмкін. Бұған бөпенің бас сүйектері босану үдерісінің жеңіл өтуі үшін әлі толық қатаймағаны себеп. Әлі қатаймаған бас сүйектері талшықтары мол шеміршек тінінен тұрады. Сонымен қатар бөпенің миы әрі қарай дамуы үшін осы ашық аймақтар қажет. Орта есеппен бөпе дүниеге келген айдың соңына дейін оның басы қалыпты дөңгелек пішінге келеді. 6 еңбек саңылауымен дүниеге келген бөпенің 2-ші айының соңына қарай алдыңғы жоғарғы еңбегінен басқасының бәрі жабылады. Ал алдыңғы жоғарғы бөлікте орналасқан үлкен еңбек бөпенің 7-ші айында қатая бастайды және 2 жасқа толғанға дейін жабылады.') WHERE id = '878511ba-a575-4d79-8fa5-80ca329e838e';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Босанғаннан кейінгі кезеңде жыныс аймағының тазалығына ерекше көңіл бөлуіңіз керек. Босанғаннан кейін бұл аймақ инфекция тудыратын бактерияларға өте сезімтал болатынын ұмытпаңыз. Әсіресе табиғи босану кезінде эпизиотомия (тілік) жасалса, дәрігеріңіз ұсынған антисептикалық кремдермен күтім жасау қажет болуы мүмкін. Ал кесарь тілігінен кейінгі алғашқы апталарда тігіс орналасқан аймаққа ерекше назар аударуыңыз керек. Операция жасаған дәрігердің ұсынымдарын ескеріп, тексерулерді өткізіп алмаңыз. Душ қабылдағанда судың тым ыстық болмауын қадағалаңыз және міндетті түрде жаныңызда біреу болғанда ғана душқа кіріңіз. Егер кесарь тілігі арқылы босансаңыз, душ қабылдау кезінде тігістерді қорғап, сол аймаққа инфекция түспеуін қадағалауыңыз керек.') WHERE id = '146cc0cd-e1d3-412a-82e1-01fb76131db8';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіз күн ішінде жиі жылауы мүмкін, кейде жылауы тіпті ұстама түрінде болуы ықтимал. Әсіресе оны тыныштандыра алмаған сәттерде мұндай жылау ұстамалары өзіңізді дәрменсіз сезіндіруі мүмкін. Сабыр сақтап, бөпеңіздің Сізбен байланыс орнатуының жалғыз жолы әзірге жылау екенін ұмытпаңыз. Бөпенің жылауына көптеген себеп болуы мүмкін. Мысалы, киімі жайсыздық тудыруы, тоңуы немесе ыстықтауы ықтимал. Әсіресе алғаш рет ана атанғандар бөпесі ауырып қалады деп қорқып, оны қажеттен тыс қалың киіндіруі мүмкін. Тепе-теңдікті сақтау үшін бөпеңізге өзіңіз кигеннен бір қабат артық киім кигізсеңіз жеткілікті.') WHERE id = '92bf1f12-3409-4d88-8829-221346b3ee91';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Дене жанасуы бөпеңізбен араңыздағы байланыстың қалыптасып, нығаюы үшін өте маңызды. Сізбен дене арқылы жанасқан бөпеңіз құрсағыңызда жатқанда естіген алғашқы дыбыс — жүрек соғысыңызды тыңдап тынышталады. Сондай-ақ бұл әдіс оның терең әрі жайлы ұйықтауына көмектеседі. Әлемнің көптеген мәдениетінде бөпелер дүниеге келе салысымен жалаңаш күйінде анасының кеудесіне жатқызылады. Ғылыми зерттеулерге сәйкес, алғашқы дене жанасуы бөпенің негізгі биологиялық қажеттіліктерінің өтелуіне ықпал етеді. Бұл жанасу бөпенің болашақ психологиясы мен мінез-құлқы қалыптасатын аса маңызды кезеңді қамтиды. Зерттеулер анасымен жиі жанасатын бөпелердің 3-ші және 6-шы айларда тек ана сүтімен қоректену көрсеткіші 2 есе жоғары екенін көрсетті. Сол зерттеуде осы әдістің арқасында бөпелердің 2 жасқа толғанға дейін басқа бөпелерге қарағанда 12 есе аз жылайтыны да айтылған.') WHERE id = 'c9ec86c3-ffa1-4c34-8c50-574a23ddec68';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Босанғаннан кейінгі алғашқы күндерде осы кезеңге тән, түсі ашық қызыл және мөлшері етеккір кезіндегі қан кетуге жуық бөліндінің болуы қалыпты. Лохия деп аталатын бұл бөлінді 1-2 апта ішінде тоқтауы да, 6 аптаға дейін жалғасуы да мүмкін. Күн өткен сайын бөліндінің мөлшері азайып, түсі өзгереді. Босанудан кейінгі кезеңнің соңына қарай ол ақшыл түсті бөліндіге айналады. Осы кезеңде жыныс аймағына күтім жасау үшін гигиеналық төсемені жиі ауыстырып, интимдік аймаққа арналған арнайы тазартқыш құралдарды қолдануыңыз керек. Босанудан кейінгі кезеңдегі шамадан тыс әрі ұзаққа созылған қан кету жатыр ішінде плацента тінінің қалуын немесе инфекцияның пайда болуын көрсетуі мүмкін. Бұл жағдай сирек кездескенімен, белгілер байқалса, оларды елеусіз қалдырмай, міндетті түрде дәрігеріңізбен кеңесіңіз.') WHERE id = '8438f645-667d-4bb4-ad8d-04104669e5fa';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Жаңа туған бөпелер анасына өте мұқтаж, ал олардың ең жақсы дамыған сезімдерінің бірі — жанасуды сезіну. Бөпенің жанасуға деген қажеттілігі ең жақсы өтелетін сәттер — ол Сіздің иісіңізді сезетін емізу кезі. Өмірінің алғашқы айларында бөпеңіз тек қарны ашқанда ғана емгісі келмейді. Өзін қауіпсіз сезінетін жалғыз жер Сіздің иісіңізді сезе алатын жер болғандықтан, ол емшек еміп жатып ұйықтағысы келуі мүмкін. Сондықтан емуге деген қажеттілік қарнын тойдырумен қатар, эмоциялық тұрғыдан да өте маңызды. Бөпелер әлеуметтік қарым-қатынасқа тек үш айдан кейін түсе бастайды. Сол себепті «қолға үйреніп кетеді» деген жаңсақ түсінікке бола бөпеңізден алшақ болмаңыз. Алғашқы айларда бөпеңізді жиі құшақтау оның сыртқы ортаға бейімделуін жеңілдетіп, қауіпсіздік сезімін нығайтады.') WHERE id = 'a82a92d2-bea2-44d6-bcce-77b7bcd63519';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Босанғаннан кейін жатырыңыз әлі де жүктілікке дейінгі қалыпты мөлшерінен едәуір үлкен болады. Қазір жатырыңызды әдетте кіндік тұсында немесе одан сәл жоғарырақ сезуіңіз мүмкін. Шамамен 1 ай ішінде жатырыңыз бұрынғы мөлшеріне толық оралады. Босану кезінде салмағы шамамен 1500 грамм болған жатыр күн сайын біртіндеп кішірейіп, жүктілікке дейінгі кезеңдегідей қайтадан 60 грамға дейін төмендейді. Кейде, әсіресе емізу кезінде, окситоцин гормонының әсерінен жатырдың жиырылуына байланысты ауырсыну болуы мүмкін. Босанудан кейінгі алғашқы күндері біршама қатты болатын бұл толғақ тәрізді ауырсынулар күн өткен сайын бәсеңдей бастайды. Мұндай жиырылулар қалыпты деп саналады және тіпті жатырдың ішкі қабатының тазаруына көмектеседі.') WHERE id = '79a8c317-465e-48a5-8158-982eb6d5f890';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Сүт бездерінде өндірілетін ана сүті — бөпеңізге бере алатын ең құнды нәрсе. Оның құрамында ақуыздың екі түрі, майлар, көмірсулар, әртүрлі дәрумендер және бөпеңіздің вирустар мен бактерияларға қарсы күресуіне көмектесетін антиденелер бар. Ана сүтіндегі майлар бөпенің миының дамуына, энергия алуына және майда еритін дәрумендердің сіңуіне қажет. Осындай қасиеттерінің арқасында ана сүті — бөпеңізге қажетті барлық қоректік заттарды қамтамасыз ететін және алғашқы 6 айда басқа ешқандай тағамды қажет етпейтін ең жақсы қорек. Ал жасанды қоспалар ана сүті жеткіліксіз болған жағдайда бөпені тамақтандырудың жалғыз баламасы болып саналады. Көпшілігінің негізгі құрамдас бөлігі сиыр сүті болып табылатын бұл қоспалар табиғи сүтке кейбір заттарды қосу немесе одан белгілі бір заттарды алып тастау арқылы өндіріледі. Алайда олардың құрамында ана сүтімен салыстырғанда казеин ақуызы көбірек болғандықтан, бөпеңіздің ағзасында баяу қорытылады.') WHERE id = 'a9c4f35f-77e6-4302-9bda-fc0e36e3f3da';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпенің туған кездегі салмағы алғашқы күндері 10% төмендеуі мүмкін. Осыдан кейін ол ең кеш дегенде 10-күнге дейін туған кездегі салмағына қайта жетуі тиіс. Нәрестелік кезең — бөпеңіздің бүкіл өміріндегі ең жылдам даму кезеңі. Алғашқы айларда бөпеңіздің бойы 2 см-ден 6 см-ге дейін өсіп, салмағы 700 грамнан 1500 грамға дейін артуы мүмкін. Бұл көрсеткіштер бөпенің жынысына қарай әртүрлі болуы мүмкін екенін, сондай-ақ шала туған бөпелерде белгілі бір уақыт бойы өсу қарқыны баяуырақ болатынын естен шығармаңыз. Сонымен қатар алғашқы айларда бөпенің бұлшықеттері, рефлекстері мен дене қимылдары да бойы мен салмағының өсуіне сай өте жылдам дамиды. Сондықтан осы кезеңде бөпеңіздің дамуын қолдайтын дұрыс ынталандыруларды қамтамасыз етіп, дәрігеріңізге жүйелі түрде қаралып тұруыңыз қажет.') WHERE id = '379e34a9-be36-4930-a59c-af93a24eb449';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Жаңа ана атанған әйелге бөпенің жаялығын ауыстыру алғашында өте қорқынышты көрінуі мүмкін. Жаялықты ауыстырмас бұрын қажет заттардың барлығын қолыңыз жететін жерге дайындап, қолыңызды жуып бастауыңыз керек. Үйренісу кезеңінде мейіргерлерден, жақындарыңыздан және туыстарыңыздан көмек сұрай аласыз. Туғаннан кейінгі алғашқы бірнеше айда бөпеңіздің жаялығын жиі ауыстыру қажет болады. Дегенмен бөпеңіз ұйықтап жатқанда жаялығы қатты суланбаған болса, оны тек жаялығын ауыстыру үшін оятудың қажеті жоқ. Сондықтан түнде емізу кезінде бөпеңіз мазасызданбаса, түні бойы жаялығын ауыстырмай-ақ қоюға болады. Ұйықтап жатқан бөпені мазалау оның ұйқысын бөлетіндіктен, қайта ұйықтап кетуі қиын болуы мүмкін.') WHERE id = 'd0704bed-eb75-4a28-b892-e481bca3aba6';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіз дүниеге келгеннен кейін кіндік қалдығы шамамен 10-14 күн ішінде толық кеуіп, түседі. Алайда кейбір жағдайларда бұл мерзім ұзағырақ болуы мүмкін. Егер бөпеңіздің кіндік қалдығы әлі түспесе, міндетті түрде жақын жердегі балалар дәрігеріне жүгінуіңіз керек. Кіндік қалдығының 20 күн өткеннен кейін де түспеуі бөпенің иммундық жүйесінде белгілі бір мәселелер бар екенін көрсетуі мүмкін. Бөпеңізді шомылдырғанда кіндік аймағын суламауға тырысыңыз, ал суланып қалса, міндетті түрде құрғатыңыз. Ылғал болып қалған кіндік қалдығы уақытында түспеуі және әртүрлі инфекцияларға себеп болуы мүмкін. Сонымен қатар кіндіктің тез әрі дұрыс түсуі үшін дәрігер ұсынбаса, ешқандай дәрі немесе лосьон қолданбаңыз.') WHERE id = '46a30d17-6906-4dd1-9f3a-fa10b39a15db';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Күні бойы бөпеңізбен жиі жақын байланыста болып, оны емізуіңіз жаңа ортаға бейімделуін едәуір жеңілдетеді. Тіпті ең заманауи инкубатордың өзі бөпеге ана құшағындай тиімді қамқорлық көрсете алмайтыны бұрыннан белгілі. Жақын байланыс кезінде сезілетін жанасу, жылу мен иіс бөпеңізбен арадағы эмоциялық байланысты нығайтады. Сондай-ақ мұндай байланыс емізуді сәтті жалғастырудың маңызды факторы болып саналады. Осы кезеңде қалыптасқан берік сезімдік байланыс бөпенің психикалық және физикалық дамуын жылдамдатады. Бұған қоса, балалық шақтың кейінгі кезеңдерінде оның бойында сенім сезімінің қалыптасуы үшін өте маңызды. Ендеше, барлық жұмысыңызды кейінге қалдырып, бөпеңізбен көбірек теріге-тері жанасып тұрыңыз! 😊') WHERE id = 'd3f6fa0e-5b44-4a86-8dac-648c5ea0fb9f';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Босанғаннан кейінгі кезең әйелдің босанғаннан кейінгі шамамен 6 аптасын қамтиды. Әсіресе бөпеңізге және жаңа өмірге үйренуге тырысатын осы уақытта көңіл күйіңіз кейде құбылуы мүмкін. Бұл кезеңде жүктілік кезінде зат алмасу мен репродуктивтік жүйеде болған өзгерістер біртіндеп қалпына келеді. Гормондар деңгейі мен жатырдың көлемі жүктілікке дейінгі күйіне жылдам оралады. Шамамен 9 ай бойы баяу жүрген физиологиялық және гормондық өзгерістердің 6 апта сияқты қысқа мерзімде кері қайтуы психологиялық жағдайыңызға әсер етуі мүмкін. Егер босануыңыз ауыр өткен болса, бұл кезеңді әдеттегіден қиынырақ өткеруіңіз мүмкін. Бұл қиын үдерістің уақытша екенін қабылдаңыз және өзіңізді жақсы сезінбесеңіз, жақындарыңыздан немесе маманнан көмек сұраудан тартынбаңыз.') WHERE id = 'ee31cac0-139c-4b54-962e-0e0cfd50ac5a';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Дұрыс емізу қалпын таңдау бөпенің ана сүтінен барынша пайда алуы үшін де, Сіздің денсаулығыңыз үшін де өте маңызды. Емізу кезінде ыңғайлы жайғасып, арқаңыз бен беліңізді жастықпен тіреп отырыңыз. Сондай-ақ емізіп отырған жақтағы қолыңыздың астына биіктеу тірек қойып, бүкіл емізу барысында қолыңызды көтеріп ұстаудан сақ болыңыз. Емізгенде бөпені мүмкіндігінше өзіңізге жақын, жүзін өзіңізге қаратып ұстаңыз. Бөпенің денесін білегіңіздің ішкі жағына, ал басын шынтақтың иілген тұсына орналастырған дұрыс. Дұрыс қалыпты таңдау бөпенің дамуы үшін де шешуші мәнге ие. Өйткені бөпені дұрыс емес қалыпта ұстап емізе берсеңіз, оның мойны тез ауырып, емуін ертерек тоқтатуы мүмкін.') WHERE id = '4be7fa1f-7739-407d-aa85-d7577ebd4d3a';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіздің іші кеуіп, мазалай бастауы мүмкін. Оның дене қимылын бақылаңыз: әсіресе аяқтарын ішіне қарай тартып, қызарып, жылап, велосипед тепкендей қимылдаса, іші кеуіп ауырып тұрған болуы ықтимал. Егер бұл белгілер емізгеннен немесе тамақтандырғаннан кейін пайда болып, бөпе тынышталмаса, себебі ішіндегі газ болуы мүмкін. Мұны байқау қиын емес: іші кепкен бөпе мазасызданып, емгісі келеді, бірақ аз уақыттан кейін қайта жылай бастайды. Сондай-ақ іші кепкен бөпенің қарны қатты әрі кебіңкі көрінеді. Оны қимылдату ішектеріндегі газдың тарауына көмектесіп, жағдайын жеңілдетуі мүмкін. Іштің кебуі мен шаншуы қатты мазаласа да, бұл — уақытша кезең. Сондықтан сабыр сақтап, оның өтіп кететінін есте ұстаңыз. Осындай сәттерде бөпені тыныштандыру үшін тыныш бөлмеге апарып, онымен жұмсақ дауыспен сөйлесіңіз, жарықты өшіріп, ішіне массаж жасаңыз — бұл жақсы әсер етеді.') WHERE id = '16924675-e88b-458a-9fb7-e716fc169d02';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпені жүйелі түрде шомылдыру оның иммунитеті мен терісінің саулығы үшін өте маңызды. Алайда шомылдыру кезінде ескеру қажет бірнеше жайт бар. Олардың ең маңыздысы — судың температурасы. Бөпені шомылдыратын судың температурасы шамамен 37 градус болуы керек. Бұдан салқын немесе ыстық су бөпенің терісіне зиян келтіріп қана қоймай, ауырып қалуына да себеп болуы мүмкін. Ал бөлме температурасын 22-24 градус аралығында ұстаңыз. Тағы бір маңызды мәселе — ваннадағы судың деңгейі. Бір сәтке назарыңыз бөлінсе, бөпе қолыңыздан сырғып кетуі мүмкін, сондықтан судың тереңдігі 15 см-ден аспауы керек. Жуындыру кезінде бөпенің басы мен денесін бір мезетте суламауға тырысыңыз. Басынан жылу өте жылдам жоғалады. Бөпе тоңып қалмауы үшін алдымен денесін жуып, содан кейін ғана басын жуып, шомылдыруды аяқтаңыз.') WHERE id = '9a3356cb-31bb-4c91-8c4b-755f5e18597d';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Егер бөпеңіз негізінен ана сүтімен қоректенсе, оның үлкен дәреті айтарлықтай сұйық болуы мүмкін. Алайда кейде бөпеде іш қату немесе іш өту мәселесі де кездеседі. Бөпелердің ішектері өте сезімтал болғандықтан, ас қорыту мәселелері жиі кездеседі. Сол себепті іш қату, іш өту және іштің кебуі сияқты жағдайлар физиологиялық тұрғыдан қалыпты саналады. Әсіресе қоспаны қорыту ана сүтіне қарағанда қиынырақ әрі ол ас қорыту жүйесінде ұзағырақ сақталатындықтан, кейде іш қатуы жиі кездесетін жағдай. Барлық бөпедегідей, Сіздің бөпеңіздің де ішегінің жұмысы мен үлкен дәретке бару жиілігі өзгеше болуы мүмкін. Кейбір бөпелер күніне бірнеше рет, ал кейбірі 5 күнде бір рет үлкен дәретке отырады. Егер нәжісі жұмсақ болса, қатты күшенбесе, салмағы қалыпты қосылып, жалпы жағдайы жақсы болса, алаңдаудың қажеті жоқ.') WHERE id = '315efeec-966c-4318-a08f-5aee7f235a22';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Күн райы жақсы кезде бөпені далаға алып шығу Сізді сергітіп қана қоймай, оның дамуына да қолдау көрсетеді. Даладағы ауа мен дыбыстардың өзгеруі, қоршаған ортаның әсері бөпеңізді тыныштандырудың өзгеше тәсілі болуы мүмкін. Бөпемен далаға шығу көптеген аналарға қиын көрінуі ықтимал. Шын мәнінде, бұл тек дағдыға байланысты. Бөпеңізбен бірге далаға неғұрлым жиі шықсаңыз, уақыт өте өзіңізді соғұрлым еркін сезінесіз. Далада уақытты жайлы әрі көңілді өткізу үшін қажетті заттарды өзіңізбен бірге алуды ұмытпаңыз. Олардың ең маңыздысы, әрине, бөпе күтіміне үнемі қажет жөргек, жөргек ауыстыратын төсеніш және ылғалды майлық. Сондай-ақ бөпе құсып қалуы мүмкін екенін ескеріп, қосымша алжапқыш пен бір жиынтық киім алғаныңыз пайдалы болады. Ендеше барлық шаруаңызды кейінге қалдырып, бөпеңізбен бірге таза ауаның рақатын көріңіз! 😊') WHERE id = '1dffb4b0-c92d-41f6-b1a5-adde26593736';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Ана сүтінің құнарлылығы мен мөлшерін арттыратын ең маңызды фактор — ішетін суыңыздың мөлшері. Сүтіңіз азаймай, тұрақты бөлінуі үшін күніне кемінде 2-3 литр сұйықтық ішіп, әр емізгеннен кейін жоғалтқан сұйықтықтың орнын толтыруыңыз керек. Сондай-ақ жеткілікті мөлшерде су ішу жүктілік кезінде қосқан салмақтан тезірек арылуға көмектеседі. Ағзаңызға қажетті барлық қоректік заттарды жеткілікті мөлшерде қабылдау сүттің көбеюіне де, артық салмақтан арылуға да септігін тигізеді. Күнделікті ақуыз қажеттілігін өтеу үшін өсімдік және жануар текті ақуыз көздерін қатар қолдана аласыз. Алайда қазір бөпеңіздің іші жиі кебетін кезең болғандықтан, тұтынатын тағамдарыңыздың құрамына назар аударғаныңыз жөн. Сонымен қатар бөпені неғұрлым жиі емізсеңіз, сүтіңіз соғұрлым көбейіп, тұрақты бөлінетінін ұмытпаңыз.') WHERE id = '8b7bb2b5-f77d-4347-879b-67f02bacb220';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Сіздің бөпеңіз де барлық нәресте сияқты өмірінің алғашқы айларында өте нәзік болады. Иммундық жүйесі әлі толық қалыптаспағандықтан, кейбір ауруларға қарсы қорғанысы әлсіз болуы мүмкін. Айлар бойы күткен балаңызды бауырыңызға басып, бақытқа бөленсеңіз де, ол мазасызданған кезде көңіліңіздің түсіп, алаңдауыңыз — табиғи жағдай. Әсіресе бөпеңіздің денсаулығына қатысты қандай да бір мәселе туындаса, қатты уайымдауыңыз мүмкін. Алайда бұл кезеңде өзіңізді кінәламаңыз, бар күшіңізді қиындықтарды еңсеруге, бөпеңізге және өзіңізге қамқорлық жасауға бағыттаңыз. Қысқасы, уайымға берілмей, бақытты болуға тырысыңыз. Бөпеңіз Сіздің көңіл күйіңізді сезетінін және оның эмоциялық жағдайы Сіздің күйіңізбен тығыз байланысты екенін ұмытпаңыз.') WHERE id = '90453aab-3c85-45f7-a53b-d1654064425e';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңізді ұйықтатқанда құсу мен тұншығу қаупін азайту үшін қауіпсіз ұйқы қағидаларын сақтау қажет. Бөпені әрдайым шалқасынан, қатты әрі тегіс төсекке жатқызыңыз. Етпетінен немесе қырымен ұйықтату қауіпсіз емес. Басының бір жағы жалпайып қалмауы үшін бөпе ояу әрі Сіздің бақылауыңызда болған кезде оны етпетінен жатқызып, басын әр бағытқа бұруға ынталандыруға болады. Ұйықтайтын жерде жастық, жұмсақ төсеніш, тіреуіш, ойыншық және басқа бос заттар болмауы керек. Қырымен жатқызу үшін арқасын жастықпен тіреуге немесе көлбеу төсек қолдануға болмайды, өйткені олар тұншығу қаупін арттыруы мүмкін. Бөпеңіздің бас пішініне қатысты алаңдасаңыз, дәрігермен кеңесіңіз.') WHERE id = '82ca4410-dc4b-42c9-8de1-8024396fe373';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Құрсақта 9 ай бойы сыртқы орта әсерінен қорғалған бөпеңіздің иммундық жүйесі дүниеге келгеннен кейінгі өмірге әлі толық бейімделмеген болады. Жүктілік кезінде Сіздің ағзаңыздан плацента арқылы, ал босанғаннан кейін емшек сүтімен берілетін антиденелер бөпеңізді кейбір жұқпалардан қорғауға көмектеседі. Әсіресе уыз бен ана сүтінің құрамындағы қорғаныш заттар бөпенің иммундық жүйесін қолдайды. Сондықтан медициналық көрсетілім болмаса, дәрігердің кеңесінсіз қосымша қоспалар бермеңіз. Алғашқы айларда емізу жиілігіне қатысты қатаң ереже жоқ, негізгі бағдар — бөпеңіздің аштық белгілері мен сұранысы. Емізгеннен кейін де бөпеңіз тоймағандай көрінсе, алғашқы айларда емуге деген қажеттілік тек аштықтан емес, табиғи ему рефлексі мен тыныштануға деген мұқтаждықтан да туындайтынын ескеріңіз.') WHERE id = '376e500c-ed21-4d44-817e-05fcffb83c34';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Осы айда бөпеңізге емханадан тегін алуға болатын немесе дәрігер ұсынған D дәрумені тамшысын бере бастауыңыз керек. D дәруменінің негізгі көзі — күн сәулесі, ал белгілі бір уақыт күн сәулесінде болу ағзаның бұл қажеттілігін 90% қамтамасыз ете алады. Алайда ғылыми зерттеулерге сәйкес, D дәруменінің тапшылығы кең таралған денсаулық мәселелерінің бірі саналады. D дәрумені бөпеңіздің қалыптасып келе жатқан иммундық жүйесін реттеуге қатысады. Ағзадағы D дәруменінің жеткілікті қоры, әсіресе аутоиммунды аурулар тұрғысынан маңызды. Өмірінің алғашқы күнінен бастап ана сүтін немесе сүт қоспасын ішетін бөпеңіз басқа дәрумендердің басым бөлігін жеткілікті мөлшерде алғанымен, D дәрумені тағам арқылы оның ағзасына қажетті мөлшерде түспеуі мүмкін. Сондықтан бұл тапшылық міндетті түрде дәрігер тағайындаған D дәрумені қоспасымен толықтырылуы керек.') WHERE id = '4c2feb95-7f80-4a6f-9d8b-18f61f673c70';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Жүктілік кезінде ағзаңызда болған өзгерістердің босанғаннан кейін біртіндеп бұрынғы қалпына келу үдерісі босанудан кейінгі қалпына келу кезеңі деп аталады. Оның бастапқы кезеңі босанғаннан кейінгі 40 күнді немесе 6 аптаны қамтиды. Алайда босанудан кейінгі толық қалпына келу әр әйелде әртүрлі өтіп, бұдан да ұзаққа созылуы мүмкін. 9 ай бойы армандаған ғажабыңызды енді құшағыңызға алып отырсыз. Дегенмен ұйқысыздық, шаршау, денедегі ауырсыну, өзіңізге және үй шаруасына уақыт таба алмау әлі де жалғасып, бәріне үлгермей жүргендей сезім тудыруы мүмкін. Кейде еш себепсіз ашуланып, айналаңыздағы адамдарға қатқыл жауап беруіңіз ықтимал. Қысқасы, босанудан кейінгі психологиялық жағдай күрделі және оны тек 40 күнмен шектеу дұрыс емес. Жақындарыңызға сезімдеріңізді айтып, олардан түсіністік пен қолдау сұраңыз. Бұл үдерістің уақытша екенін ұмытпаңыз. Әр әйел өз бөпесі үшін ең жақсы ана. Кез келген қиындықта Сіздің жаныңыздан табыламыз. 😊') WHERE id = 'bad42002-8275-46dc-b1ad-174066cad7e7';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Егер бөпеңізді алып жүруге немесе жатқызуға арналған арнайы орындық секілді құралдарды пайдалансаңыз, оның үстіңгі жағына бөпеге зиян келтірмейтін, назар аударарлық ойыншықтарды қауіпсіз қашықтықта орналастыра аласыз. Бұл заттар бөпеңіздің назарын аударып, көру және қабылдау қабілеттерінің дамуына ықпал етеді әрі айналасын түсіну дағдысын жетілдіреді. Жарық шығаратын, дыбысы бар және қимылдайтын ойыншықтар бөпеңізге қатты ұнауы мүмкін. Жаңа нәрселерді зерттеу оны әрі қызықтырады, әрі көңілін көтереді. Сонымен бірге айналасындағы түрлі түсті ынталандырғыштарды көру оның өзін және қоршаған ортаны танып-білуіне көмектеседі. Алайда мұндай заттарды таңдағанда мұқият болыңыз. Теледидар сияқты қозғалысы, түсі және дыбысы көп экрандар бөпеңіздің назарын аударғанымен, олардың дамуына кері әсер етуі мүмкін.') WHERE id = '3ad7f64e-f78d-46bd-a402-26a3f15d1d22';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Алғашқы кезде бөпеңіздің емізу кезінде ұйықтап қалатынын байқауыңыз мүмкін. Көптеген ана сияқты бұл Сізге де ұнауы ықтимал. Алайда абай болыңыз: егер бұл әдетке айналса, бөпеңіз ембей ұйықтай алмай қиналуы мүмкін. Бөпеңіз осы тәртіпке үйреніп қалса, ембей ұйықтағысы келмейді. Сондықтан оның ұйқысы келіп, мазасыздана бастағанын сезген бойда бесігіне жатқызып, ұйықтатудың басқа тәсілдерін қолданып көруіңіз керек. Бөпеңіз жаңа тәсілдерге үйренгенше алғашында жылауы мүмкін. Бірақ берілмей жалғастырсаңыз, уақыт өте келе оның үйренгенін көресіз. Егер осы әрекеттер кезінде бөпеңіз ұйықтауға қатты қарсылық білдірсе, оны тыныштандырып, содан кейін қайтадан өздігінен ұйықтап көруіне мүмкіндік беріңіз.') WHERE id = '9210140f-4b86-4445-aa81-e541ebeace13';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Жатырыңыз 9 ай бойы бөпеңізге өте жылы әрі жайлы орта болды. Босанғаннан кейін оның кенеттен шу мен жарыққа толы сыртқы әлемге келуі кішкене күйзеліс тудыруы мүмкін. Сондықтан жаңа ортаға бейімделуіне біраз уақыт қажет болады. Бөпеңізді ұйықтатқанда оның әлі де жатырдағыдай жиырылып, эмбрион қалпында жатқанын байқасаңыз, себебі дәл осы. Шамамен 1 ай ішінде бұл әдеттің азайғанын байқайсыз. Осы бейімделу кезеңінде бөпеңіз Сізге бұрынғыдан да көбірек мұқтаж. Оны құшағыңызға алғаныңыз, сүйгеніңіз, онымен сөйлескеніңіз, қысқасы, көңіл бөлгеніңіз оған қатты ұнайды әрі ағзасында бақыт гормондарының бөлінуіне ықпал етеді.') WHERE id = 'd3c1171d-ec50-4947-af33-82084d44686e';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Күндер жылдам өтіп жатыр, ал Сіз күн сайын ана болуға біртіндеп үйреніп келесіз. Бөпеңізбен араңыздағы байланыс сөзбен айтып жеткізгісіз сүйіспеншілік пен оны барынша қорғауға деген күшті сезім түрінде қалыптасып та үлгерген шығар. Алайда мұндай сезім әр әйелде бірден және бірдей пайда болуы керек деген түсінік дұрыс емес. Әр адамның сезімі әртүрлі болады, сондай-ақ босану кезіндегі күйзеліс пен босанғаннан кейінгі кезеңге байланысты кейбір әйелдерге бөпесімен жақын байланыс орнату үшін уақыт қажет болуы мүмкін. Егер кейде бөпеңізді бөтенсініп қалсаңыз, бұл үшін өзіңізді кінәламаңыз. 9 ай бойы қаныңызда біртіндеп көбейген гормондар деңгейінің босанғаннан кейін қысқа мерзімде күрт өзгеруі психологиялық жағдайыңызға әсер етуі мүмкін. Егер бірнеше апта өтсе де, бөпеңізді әлі де бөтенсінсеңіз, бұл босанудан кейінгі депрессияның белгісі болуы ықтимал. Мұндай жағдайда міндетті түрде дәрігеріңізбен кеңесіп, психологиялық көмек алуға кеңес береміз.') WHERE id = '08ca900e-fc32-45d6-bd75-a4633391d4f9';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпелер дүниеге келгеннен кейін белгілі бір апталарда қарқынды өсу және даму кезеңдерін, яғни өсу секірістерін бастан өткереді. Қазір өтіп жатқан 5-апта — осындай өсу секірісі алғаш рет болатын кезең. Сондықтан осы күндері бөпеңіздің әдеттегіден көбірек жылауы, мазасыз әрі қыңыр болуы, ұйқысының бұзылуы немесе тәбетінің өзгеруі — толығымен қалыпты жағдай. Тәбетінің артуы оның өсу үшін көбірек энергияға мұқтаж болуымен де, осы қажеттілікті өтеу үшін жиі еміп, сүттің түзілуін арттыратын гормондардың бөлінуін ынталандыруға тырысуымен де байланысты. 5-аптадағы осы өсу секірісі кезінде бөпеңіз сезім мүшелерін белсенді пайдаланып, айналасындағының бәрін аңғара бастайды. Қысқасы, бөпеңіз өз әлемінің тек тамақтану мен ұйқыдан тұрмайтынын түсіне бастайды. Соның салдарынан көптеген жаңа әсерге тап болып, кейде мазасыздануы мүмкін. Небәрі бірнеше күнге созылатын бұл кезеңді барынша сабырмен өткізуге тырысыңыз және оның уақытша екенін ұмытпаңыз.') WHERE id = '3c3db532-5b9a-41a9-8a5e-67563130c5c0';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіздің сыртқы әлемдегі алғашқы айы аяқталған соң, оның айналасына бұрынғыдан да қызыға қарай бастағанын байқаған шығарсыз. Бөпеңіз әсіресе айналасындағы қызықты заттарға, ірі пішіндерге, ашық әрі қарама-қарсы түстерге назар аудара бастайды. Босанғаннан кейінгі алғашқы күндері көзін қысқа уақытқа ғана ашатын бөпеңіз енді ұзағырақ ояу жүреді. Бұл оның қоршаған ортаны танып-білуге қажетті сезім мүшелерін пайдалана бастағанын білдіреді. Ояу жатқан қысқа уақыттарында бөпеңізге түрлі түсті маталарды көрсетіп, қолына тигізу арқылы әртүрлі ойындар ұйымдастыра аласыз. Мұндай ойындардың оған қатты ұнайтынын көресіз. Сондай-ақ көру қабілеті әлі толық қалыптаспағандықтан, Сізді жақсырақ тануы үшін жүзіңізді оған жақындатып, мұқият қарауына мүмкіндік беріңіз. 😊') WHERE id = '676e6646-3ff2-4bc0-82e0-4614c3d8096a';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпелерде «сүт қабыршағы» деп аталатын және бас терісінде қабыршақты, қабыршақтанған дақтардың пайда болуына әкелетін гнейс — алғашқы айларда жиі кездесетін тері жағдайы. Қызарып, қабыршақтанған бұл бөртпелер маңдайға, құлақтың артына, мойынға және қолтыққа дейін таралуы мүмкін. Егер бөпеңізде сүт қабыршағы пайда болса, алаңдаудың қажеті жоқ. Әдетте ол қышытпайды және бөпені мазаламайды. Кейде жөргегін ауыстырған кезде қабыршақтанудың жөргек аймағына да таралғанын байқауыңыз мүмкін. Сирек жағдайда жөргек аймағындағы бұл жағдайға зеңдік инфекция қосылуы ықтимал. Сүт қабыршағының нақты себебі белгісіз болғанымен, оған генетикалық бейімділік, теріде табиғи түрде тіршілік ететін ашытқы тәрізді саңырауқұлақтар, тітіркендіргіш заттар, құрғақ әрі суық ауа райы сияқты факторлар әсер етуі мүмкін.') WHERE id = 'dc08af3a-ac5d-4bd3-9ab0-537157d76301';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпенің көз бұлшықеттері әлі толық дамымағандықтан, көзінің қиғаштануы біраз уақытқа дейін сақталуы мүмкін. Кейде бір көзі, кейде екі көзі де бір мезетте сыртқа қарай ауытқуы ықтимал. Бір затты бақылауға тырысқанда, екі көзі бір-біріне параллель қозғалмауы мүмкін. Көздің мұндай ауытқуы жалған қылилық деп аталады. Жалған қылилық көз саңылауының физиологиялық тұрғыдан кең болуына байланысты да пайда болады. Көпшілік ойлағандай, бөпенің бұл жағдайы оның көру қабілетіне немесе көзінің дамуына әсер етпейді. Өскен сайын мұрын сүйегі қалыптасып, қабақтары өз орнына келгенде, бұл көрініс түзеледі. Ал кейбір бөпелер бет құрылысына байланысты қыли болып көрінгенімен, шын мәнінде көздері бір бағытқа қарайды. Егер бұл жағдай Сізді алаңдатса, көз жеткізу үшін бөпеңізді балалар офтальмологына тексерте аласыз.') WHERE id = 'f12655d4-4f11-4cf4-949d-d3c74399a9bf';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпелерде кездесетін тағамдық аллергиялардың ең жиі таралғаны — сүтке, яғни сиыр сүтіне аллергия. Бұл бөпе ағзасының сиыр сүтіндегі бета-лактальбумин ақуыздарына аллергиялық реакция беруінен туындайды. Дайын қоспалардың (смесялардың) көпшілігінде осы ақуыз болғандықтан, жасанды қоспамен қоректенетін бөпелерде мұндай аллергия жиі кездеседі. Алайда бұл мәселе тек жасанды қоспамен шектелмейді: ана сүтімен қоректенетін бөпелерге де анасы сүт өнімдерін тұтынған жағдайда сүт арқылы берілуі мүмкін. Сондай-ақ мұндай аллергиясы бар бөпелердің көпшілігінде ешкі сүтіне және соя негізіндегі сүттерге де сезімталдық пайда болуы ықтимал. Сиыр сүті аллергиясының ең айқын белгілері: алғашқы айларда шамадан тыс жылау және іштің қатты кебуі, тамақтанғаннан кейін құсу, салмақ қоспау, нәжісте ұйыған қанның болуы және іш қату. Егер бөпеңізден осы белгілерді байқасаңыз және сиыр сүтіне аллергия бар деп күмәндансаңыз, міндетті түрде дәрігеріңізбен кеңесіңіз.') WHERE id = '06a7caf5-4128-4600-83b6-7c3d296c2485';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіздің іші кебуінің алдын алу немесе ауырсынуын жеңілдету үшін бірнеше әдісті қолдануға болады. Бөпені мүмкіндігінше ана сүтімен емізу ас қорыту жүйесіне ең қолайлы қорек болғандықтан, ас қорыту үдерісінің жеңіл өтуіне көмектеседі. Соның арқасында бөпенің ішегінде газ аз жиналып, газды ыдырататын бактериялар тиімдірек жұмыс істейді. Емізу аралығын кемінде 2 сағат етіп реттегеніңіз жөн. Бұл сүттің майлылығын арттырып, бөпенің дамуын қолдайды әрі ішкен сүтінің жеңіл қорытылуына көмектеседі. Бөпені тым ыстық немесе суық жерде ұстамауға және бірнеше қабат тар киім кигізбеуге тырысыңыз. Мұндай жағдайлар бөпенің ас қорытуы мен қан айналымына кері әсер етіп, ішегінде газ жиналуына себеп болуы мүмкін. Сондай-ақ әр тамақтандырғаннан кейін бөпенің кекірігін шығарып, асқазанында ауа қалмағанына көз жеткізіңіз.') WHERE id = '37fe650b-ff02-444b-9514-314d6f5df25d';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Ұйқы уақыты біртіндеп реттеле бастаған бөпеңіз қазір әлдеқайда қимылдап, Сізге жауап бере бастады. Ол Сізбен қатар әкесін және жиі көретін адамдарын да танитынын қимылдарымен көрсете алады. Мұның басты себептерінің бірі — көзінің бұрынғыдан жақсырақ көре бастауы. Соның арқасында ол айналасын зерттеп, көргендеріне жауап бере бастайды. Бөпе 2-ші айын аяқтағанда, қосқан салмағына қарай беті, қолдары мен аяқтары біртіндеп томпайып, толысады. Қысқасы, ол енді жаңа туған бөпе кейпінен шыға бастады. Дегенмен әрбір дені сау бөпенің бойы мен салмағы әртүрлі қарқынмен өсетінін білгеніңіз жөн. Ұйқы тәртібі қалыптасып, сапалы ұйықтауы үшін енді оны түнде әдейі оятып емізудің қажеті жоқ. Бөпеңіз аш болмаса, емізу үшін немесе мазасы кетпесе, жөргегін ауыстыру үшін ояту оның ұйқы сапасын төмендетуі мүмкін.') WHERE id = '6bb455df-6ea4-41c3-8194-cb7bda47e257';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпені дұрыс қалыпта емізбегенде, тек бөпеңізде ғана емес, Сіздің ағзаңызда да кейбір мәселелер туындауы мүмкін. Солардың ең жиі кездесетіні — мастит. Мастит — дене қызуының көтерілуі, әлсіздік, шаршау, емшектің ауыруы мен қызаруы сияқты белгілермен байқалатын, сүт өзектерінің бітелуінен туындайтын денсаулық мәселесі. Әдетте инфекциямен қатар жүретін бұл жағдайда сүт өзектері әбден толғанда емшек босатылмаса, өзектер бітеліп қалады. Осындай жағдайға тап болсаңыз, дәрігеріңіздің кеңесімен емізу кезінде қолдануға болатын ауырсынуды басатын дәрі ішуіңізге болады. Сонымен қатар ауырсынуға қарамастан, мастит пайда болған емшекті босату өте маңызды. Дұрыс емделсе, мастит қысқа уақытта басылып, бөпеңізді емізуді қауіпсіз жалғастыра аласыз. Алайда қажетті ем жүргізілмесе, емшектегі бітелу ағзаңыздың сүт өндіруін тоқтатуына әкелуі мүмкін.') WHERE id = '68a7f9bc-02a4-47e7-80eb-cfc071e562a7';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңізбен бірге екі айды артқа тастадыңыз. 3-ші айдың алдыңғы айларға қарағанда жеңілірек өтетініне және өзіңізді тәжірибелірек сезінетініңізге сенімді бола аласыз. Бөпеңіз өмірінің алғашқы айларында өте жылдам дамиды және айына 700 грамнан 1500 грамға дейін салмақ қосуы мүмкін. Басқаша айтқанда, бөпе аптасына кемінде 150-200 грамм салмақ қосады деп күтіледі. Осы есептеулерге сәйкес, осы аптаның соңында бөпенің орташа салмағы 4 пен 6 кг аралығында болады. Бөпенің жөргегін күніне орта есеппен 5 рет сулауы оның жеткілікті тамақтанып жүргенін және қосымша тағамды қажет етпейтінін көрсетеді. Сондай-ақ бойы ай сайын орта есеппен 1.5-2 см өсетінін ескерсек, қазір оның бойы 57-62 см аралығында болуы мүмкін. Мұның бәрі орташа көрсеткіштер екенін және әр бөпеде әртүрлі болуы мүмкін екенін ұмытпаңыз. Бұл мәселеде Сіз үшін басты өлшем дәрігеріңіздің пікірі болуы керек.') WHERE id = 'c4b87e12-4678-4aea-8944-a0c3b90a105f';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бұл кезеңде есту қабілеті айтарлықтай дамығандықтан, бөпеңіз Сіздің даусыңызға және тыныштандыратын әуендерге жымиып жауап беруі мүмкін. Сонымен қатар, әсіресе кенеттен шыққан қатты дыбыстарға бет әлпетін өзгертіп, денесін керіп, қолдарын екі жаққа жайып, кейін кеудесіне тартып, жылау арқылы мазасызданғанын білдіруі мүмкін. Бөпеңіз әлі құрсағыңызда жатқан кезінен-ақ Сіздің жүрек соғысыңызды, өзінің анасы мен әкесінің даусын және айналадағы түрлі дыбыстарды сезіп, жадында сақтай бастайды. Дүниеге келгеннен кейін жадында қалған осы дыбыстарды есту оған тыныштандыратын әсер беруі мүмкін. Әсіресе мазасызданған сәттерінде баяу әуен қосып, бөпеңізбен жұмсақ үнмен сөйлесу оны жұбатады. Сондай-ақ осы тыныштандыратын әсерді пайдалану үшін, әсіресе ұйықтар алдында бесік жырын айту бөпеңіздің когнитивтік дамуына пайдалы болады. Айтпақшы, бөпелердің қайталанатын сөздері бар бесік жырларын көбірек ұнататынын да еске салғымыз келеді. 😊') WHERE id = '187e9ca9-650d-40db-aa1f-2e28314ee7e9';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңізде іш кебуінің пайда болуына көптеген түрлі себеп болуы мүмкін. Осы себептерді білу іштің бүріп ауыруымен күресуде Сізге көп көмектеседі. Іш кебуінің ең белгілі себептері — шамадан тыс жиі және ретсіз тамақтандыру. Ішек микрофлорасы әлі қалыптасып жатқан бөпеңізге тамақтану тәртібін орнату ішектегі пайдалы бактериялардың қолайлы жағдайда жұмыс істеуіне мүмкіндік береді. Бұл бөпеңіздің ішінің бүріп ауыруын жеңілірек өткізуіне көмектеседі. Алғашқы 6 айда бөпелердің асқазанында тек сүтті қорытуға арналған ферменттер бөлінеді. Сондықтан тек ана сүтін немесе құрамы ана сүтіне барынша жақын нәрестелерге арналған қоспаларды қолдануыңыз керек. Сүт пен сүт негізіндегі тағамдардан бөлек берілетін тәтті су, қою жеміс шәрбаты, бал және тосап сияқты өнімдер бөпеңіздің ас қорыту жүйесіне қосымша салмақ түсіруден басқа пайда әкелмейді. Сондай-ақ кейбір дәрілер іштің кебуін күшейтуі мүмкін болғандықтан, дәрігеріңіздің кеңесінсіз дәрі беруден бас тартуыңыз керек.') WHERE id = 'a098a0a5-9cf9-4830-b539-70c7b71e29f4';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Күндер неткен жылдам өтіп жатыр, солай емес пе? Бөпеңіз жаңа туған сәбиге тән бастапқы кезеңнен өтіп, айналасындағы әлемді жақсырақ тани бастады. Бұл кезеңде ол өзіне қол тигізгенді, еркелеткенді және құшаққа алғанды қатты ұнатады. Жүктілік бойы денеңізде өмір сүрген бөпеңіз үшін Сіздің құшағыңыз ең сүйікті жері болса керек. Әсіресе қорыққанда немесе мазасызданғанда, оны ең жылдам тыныштандыратын жер — Сіздің құшағыңыздағы қауіпсіз мекен. Сіздің немесе әкесінің құшағында ұйықтағанда, дене бітіміңізге бейімделіп, өзіне жайлы ұя жасап алғандай болады. Ал алдағы 1-2 айда ол еркіндікке ұмтылып, құшаққа тығыла берудің орнына өз кеңістігін кеңейтуге тырысады. Сондықтан кейде қиын болса да, құшақтасып өткізетін осы күндердің әр сәтінен ләззат алуға тырысыңыз. :)') WHERE id = '3ff154d9-4a5e-4705-b55a-c139a97509b8';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Күндіз жиірек оянатын бөпеңіз енді түнде ұзағырақ ұйықтай бастайды. Бөпеңіздің дұрыс ұйқы тәртібін қалыптастыру және өздігінен ұйықтап кетуіне көмектесу үшін, ұйқысы келген кезде оны әлі ояу қалпында бесігіне ақырын жатқызуыңыз керек. Ұйқыдағы бұл жағымды өзгерістер оның күн мен түнді ажырата бастауына байланысты. Осы әдетті нығайту үшін Сізге бірнеше кеңесім бар. Ең бастысы — күндіз бөпеңіз жатқан бөлмені жарық әрі белсенді күйде ұстау. Ал кешке бөлмелер мен бөпеңіз жатқан жерлерді бәсең жарықтандырып, тыныш қимылдап, сыбырлап сөйлегеніңіз жөн. Осы шағын өзгерістер бөпеңіздің тұрақты әрі сапалы ұйықтауын қамтамасыз ететін ең маңызды факторлардың бірі.') WHERE id = '854dcb61-ea42-4d37-9176-c3af87b58986';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Босанғаннан кейінгі қалпына келу кезеңі аяқталғандықтан, көңіл күйіңіздің құбылуы, уайым мен өзіңізді жеткіліксіз сезіну біртіндеп азая бастауы керек. Босанудан болған шаршау мен әлсіздік басылып, отбасыңызға қосылған бөпеңізге барған сайын көбірек үйреніп келесіз. Егер табиғи жолмен босансаңыз, эпизиотомия тігістері тұсында немесе дәретханаға барғанда әлі де кейде жайсыздық сезінуіңіз мүмкін, бірақ қуық пен ішек қызметін бақылауыңыз айтарлықтай жақсарған. Дегенмен қынаптың құрғауы және гормондық өзгерістерге байланысты жыныстық қалаудың төмендеуі әлі біраз уақыт жалғасуы мүмкін. Гормондарыңыз негізінен бұрынғы қалпына келгенімен, жас ана рөліне және өзгерген өміріңізге толық бейімделу үшін әлі де уақыт қажет. Егер бұл өзгерістерді еңсеру қиын болып жатқанын сезсеңіз, міндетті түрде дәрігеріңізден көмек сұраңыз.') WHERE id = '56bf65a1-60b7-4dfd-848c-0b69df37fbad';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Қазір бөпеңіз үшін де, өзіңіз үшін де денсаулығыңызға көңіл бөлу өте маңызды. Инфекцияларға қарсы тұра алатын мықты иммундық жүйенің басты шарты — теңгерімді тамақтану. Босанғаннан кейін қалған артық салмақтан арылу үшін қатаң әрі жылдам нәтиже беретін диеталарды ұстанбауыңыз керек. Дәрігеріңіз жүктілік кезінде қабылдаған дәрумендерді тағы біраз уақыт жалғастыруды ұсынуы мүмкін. Ағзаңыздың A, C, D және E дәрумендеріне деген қажеттілігін өтеумен қатар, сүтіңіздің сапасы үшін мырыш, омега және темір сияқты пайдалы заттарды да қабылдауыңыз керек. Бұл қажеттіліктерді өтеу үшін жемістер мен көкөністерді өз маусымында және балғын күйінде тұтыну өте маңызды. Әсіресе тамақтану мәзіріңізге мырыш пен селенге бай өнімдерді қосу арқылы иммундық жүйеңізді жылдың барлық мезгілінде мықты ұстай аласыз.') WHERE id = '8b8bfabb-ad49-47f5-ad53-ea528bf3b3c1';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Түстердің бөпенің психологиясына, энергиясына және дамуына әсер ететіні ғылыми тұрғыдан дәлелденген. Әсіресе түстерді ажырата бастаған бөпеңіз осы кезеңнен бастап айналасындағы реңктерге сезімтал бола түседі. Түстердің ықпалы тек көңіл күймен шектелмейді. Оның бөлмесінде, киімінде, тіпті ойыншықтарында қолданылатын кейбір түстер ми жұмысын белсендіреді, ұйқы әдеттеріне әсер етеді және есте сақтау қабілетін нығайтады. Сондықтан түстердің тілін білу өте маңызды. Мысалы, көк түстің қою реңктері көңілсіз әсер қалдыруы мүмкін, ал ашық реңктері бөпеңізді тыныштандырып, жүйке жүйесінің демалуына көмектеседі. Кірпіш және топырақ түстес реңктер бөпенің өзін жайлы сезінуіне ықпал етеді, ал қою қызыл түс мазасыздық тудыруы мүмкін. Жалпы, жылы түстер бөпеңіз үшін сергек әрі белсенді орта қалыптастырса, суық түстер көбіне тыныштандырып, демалдырады.') WHERE id = '1a3eb5d8-5f3e-4a88-8c08-5b1025f3faf7';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Егер етеккіріңіз басталса, сүтіңіздің мөлшерінен және бөпеңіздің ана сүтіне реакциясынан кейбір өзгерістерді байқауыңыз мүмкін. Бұл ағзаңыздағы етеккір циклін реттейтін гормондық өзгерістердің сүттің түзілуі мен құрамына аздап әсер етуінен болады. Алайда бұл өзгерістерге бола емізуді тоқтатудың қажеті жоқ. Етеккірдің басталуы бөпеңізді емшектен шығару керек дегенді білдірмейді; бұл кезеңде емізу толықтай қауіпсіз. Әсіресе овуляция күндері сүт құрамындағы натрий мен хлорид мөлшері артып, калий мен лактоза азаяды. Соның салдарынан сүтіңіздің дәмі сәл тұздырақ немесе тәттілігі азырақ болуы мүмкін. Сондай-ақ овуляция кезінде және қан кету басталар алдында эстроген мен прогестерон гормондарының деңгейі өзгеретіндіктен, кеудеңіздің керілгенін және сезімтал болғанын байқауыңыз мүмкін.') WHERE id = '94e7a1fa-9551-4f9b-be28-3651b7e35a86';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бұл кезеңде бар назарыңыз бөпеңізде болғандықтан, қайта жүкті болу туралы ой Сізді қорқытуы мүмкін. Емізу кезеңінде бала көтеру ықтималдығы төмендегенімен, толығымен жойылмайды. Босанғаннан кейінгі алғашқы айларда овуляция үдерісі жүктілік кезіндегідей біраз уақытқа тоқтайды. Алайда халық арасында тараған "емізу жүктіліктен қорғайды" деген пікірге толық сеніп, сақтанбау дұрыс емес. Егер бөпеңіз тек ана сүтімен қоректенсе, етеккіріңіз 6-8 айға кешігуі мүмкін. Ал бөпеңіз қоспамен тамақтанса, босанғаннан кейін 3 аптадан соң овуляция мен етеккір қайта басталуы ықтимал. Етеккіріңіз келмесе де, жүкті болу қаупі шамамен 1-2% екенін және овуляция алғашқы қан кетуден бұрын да болуы мүмкін екенін ұмытпаңыз. Сондықтан жаңа жүктілікті жоспарламасаңыз, әр жыныстық қатынас кезінде контрацепция әдістерін қолдану маңызды.') WHERE id = 'a67e120d-50f6-40f7-8148-f8a30d4ac88d';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіздің арқасын сипағанда қолыңызға сезілетін қаттылық немесе түктер Сізді алаңдатуы мүмкін. Халық арасында бұл құбылыс "тікен" деп аталғанымен, оны ересектердегі өкше сүйегінің өсіндісімен шатастырмау керек және әдетте ол қауіпті емес. Бөпелерде жиі кездесетін, бірақ көбіне көзге байқала бермейтін мұндай түктер қыз балаларда көбірек кездеседі және әдетте шомылдырған кезде сезіледі. Медициналық тұрғыдан оның зияны дәлелденбеген. Дегенмен бұл жағдай Сізді алаңдатса немесе бөпеңіз мазасызданып жүр деп ойласаңыз, оны тыныштандыру үшін массаж жасай аласыз. Массаж кезінде бөпенің нәзік терісін тітіркендірмейтін, химиялық қоспалары жоқ табиғи майларды қолдану керек. Мұндай майлармен жасалған массаж бөпені тыныштандырып қана қоймай, түктердің түсуіне де көмектеседі. Қолайлы майлар мен күтім жөнінде дәрігеріңізден де кеңес ала аласыз.') WHERE id = 'd55543a0-5e2c-48fc-9829-ce7e9fdddd6c';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Кез келген бөпедегідей, Сіздің бөпеңізді киіндіру де нағыз шытырман оқиғаға айналуы мүмкін. Кішкентайыңыз бір орында тұрмай, қол-аяғын үнемі қимылдататындықтан, әсіресе қыс айларында киімін ауыстыру көп уақытыңызды алуы мүмкін. Сондықтан уақытыңызды үнемдейтін, кигізуге оңай әрі ыңғайлы киімдерді таңдаған жөн. Сатып алу кезінде бөпенің басы оңай өтетін, жағасы кең киімдерге басымдық беріңіз. Бөпенің терісі ересектердікіне қарағанда әлдеқайда сезімтал болғандықтан, міндетті түрде құрамында мақтасы бар және аллергия тудырмайтын бұйымдарды таңдаңыз. Қауіпсіздік те өте маңызды: бөпе жұтып қоюы мүмкін үлкен түймелерден және ұшы матамен жабылмаған қатты сыдырмалардан аулақ болыңыз. Бөпелер қызығушылықпен мұндай түймелерді жұлып алып, аузына салуы мүмкін. Сондай-ақ артық баулар, таспалар мен шілтерлер де бұл кезең үшін аса қолайлы таңдау емес.') WHERE id = 'b8aa2eab-ff56-4ab9-8b20-121fbd2d3ec4';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Елімізде ең жиі кездесетін қаназдық түрі — темір тапшылығы анемиясы. Темір — адам ағзасы үшін аса маңызды элемент. Әсіресе қарқынды өсу кезеңдерінде жасушалар мен тіндердің темірге қажеттілігі артады. Сондықтан бөпелер ең жылдам өсетін 6-24 ай аралығында темір тапшылығы жиі кездеседі. Бөпеңіз 6 айға толғанға дейін ана сүтін емсе, өз рационыңызға құрамында темір бар тағамдарды қосуыңыз маңызды. Ал қоспамен қоректенетін бөпелер үшін қоспаның құрамындағы темір мөлшеріне назар аудару керек, бұл жөнінде дәрігеріңізден кеңес ала аласыз. 6-айдан кейін ана сүті ғана жеткіліксіз болғандықтан, қосымша тағам енгізгенде темірге бай мәзір дайындауыңыз керек. Таңғы асқа берілетін жұмыртқаның сарысы темірге өте бай. Сондай-ақ бөпеңізге дайындайтын көкөніс сорпаларына қой немесе сиыр етін қосуды ұмытпаңыз.') WHERE id = 'd050305e-c358-4c29-9151-2db694755a43';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпенің қол-көз үйлесімі мен дамуы үшін қолғаптарын шешетін уақыт келді. Қолғапты ұзақ уақыт кигізу бөпенің қоршаған ортамен байланыс орнатуына және дамуына кері әсер етуі мүмкін. Қолдарын мұқият зерттей бастаған бөпеңіз енді Сіз берген затты ұстап, аузына апаруы мүмкін. Жұдырығын түйіп, қолына түскеннің бәрін аузына салуға тырысу арқылы бөпеңіз заттарды танып-біледі. Мұндай тәжірибе оның зияткерлік дамуында өте маңызды рөл атқарады. Зияткерлік қабілет көбіне бөпенің белсенді қимылдары мен әрекеттері арқылы жинаған тәжірибесінің негізінде қалыптасады. Қолдар — бөпенің айналасын зерттеп, ақыл-ойын қалыптастыратын ақпаратты жинауына көмектесетін алғашқы құрал. Сондықтан бөпеңізді бұл әрекеттерге ынталандыру өте маңызды. Оның назарын аударатын әрі ұстай алатын ойыншықтар, түрлі түсті маталар және сылдырмақ секілді дыбыс шығаратын заттар арқылы дамуына қолдау көрсетіңіз.') WHERE id = '42c11358-bbe1-48ad-b54d-e26f562016b7';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіздің миы бесік жырына, әнге, музыкаға, тіпті сырттан естілетін дыбыстарға да жауап бере алатындай деңгейде дамыған. Оның миы сау әрі дұрыс дамуы үшін күнделікті өміріңізде музыкаға да орын бергеніңіз жөн. Сонымен қатар бөпеңізге ән немесе бесік жырын айту араларыңыздағы байланысты нығайтады. Зерттеулерге сәйкес, ерте жастан музыка тыңдаған бөпелердің миы мен сөйлеу қабілеті басқа бөпелерге қарағанда жылдамырақ дамиды. Сондай-ақ мұндай балалардың болашақта музыкалық аспаптарға қызығушылық таныту ықтималдығы жоғарылайтыны байқалған. Бөпеңіз құрсақта жатқан кезінен-ақ Сіздің даусыңызды басқа адамдардың даусынан ажырата алғандықтан, оған ән мен бесік жырын айту бірге көңілді әрі сапалы уақыт өткізуге мүмкіндік береді, сондай-ақ оның сөздік қоры мен тілдік қабілетінің қалыптасуын жеделдетеді. Әсіресе бөпеңіз ұйықтауға қиналса, классикалық немесе баяу әуен оны тыныштандырып, ұйықтауын жеңілдетеді.') WHERE id = '161206e9-2801-48d5-bf23-ba2c2a393a9f';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіз себепсіз жылап, соңғы күндері мазасыздығы күшейіп кетті ме? Бөпеңіздің екінші қарқынды даму кезеңіне, яғни даму секірісіне қош келдіңіз. 😊 8-аптадағы даму секірісі аяқталғаннан кейін бөпеңіз жаңа дағдыларды меңгеретін қызықты кезең басталады. Осы даму секірісі кезінде бөпеңіз өз денесін жақсырақ танып, қолдары мен аяқтарын зерттей бастайды. Енді оның қолдары мен саусақтарын соруға тырысқанын, ал қолына бір зат бергенде оны ұстау үшін саусақтарын еркін пайдалана алатынын байқайсыз. 😊 Жаңа туған кезімен салыстырғанда қимылы артқан бөпеңізді құшағыңыздан төсекке жатқызғанда, ол өздігінен ермек таба бастауы мүмкін. Бөпеңіз алыстағыны әлі анық көрмесе де, ашық түсті заттар, пішінді ойыншықтар мен жарықтар оның назарын аудара бастайды. Бөпеңіз үшін сыртқы әлемді белсендірек зерттейтін кезең басталғандықтан, оның назары тез бөлініп, соның салдарынан емуді азырақ қалауы мүмкін. Мұндай жағдайда оны тыныш әрі қараңғылау бөлмеде немесе ұйықтар алдында емізу тиімдірек болуы мүмкін.') WHERE id = 'ba812bc8-8097-4c97-a28f-220a769e0dd9';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіз енді Сізге саналы әрі шынайы әлеуметтік жымиыспен жауап бере бастайды. Бұл кезеңде оның мойын бұлшықеттері жылдам дамитындықтан, омыртқасының дұрыс қалыптасуы үшін күн сайын бақылауыңызбен қысқа уақыт етпетінен жатқызып жаттықтыру өте маңызды. Қабылдау қабілеті жақсарған бөпеңіз енді түрлі түсті заттарды көзімен қадағалап, кішкентай дыбыстар шығару арқылы Сізбен алғаш рет қарым-қатынас жасауға талпынады. Осы кезеңде салынуы мүмкін 2 айлық жоспарлы екпелерден кейін бөпеңізде пайда болған жеңіл мазасыздық пен тәбеттің төмендеуін оны жиі емізіп, құшақтап тыныштандыру арқылы жеңілдете аласыз.') WHERE id = '3c33ef6c-ad69-4a43-8495-e0ff0a641f32';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпелердің шашсыз немесе шашты болып дүниеге келуі қалыпты жағдай. Егер бөпеңіз шашты болып туса, әсіресе осы кезеңде шашының тез түсе бастауы Сізді біраз алаңдатуы мүмкін. Бөпеңіздегі бұл жағдай гормондық өзгерістерге байланысты шаш түсуі — «телогенді эффлувиум» деп аталады. Жүктілік кезінде бөпенің шаш түбірлері үнемі өсу және даму кезеңінде болады. Ал туғаннан кейін гормондардың әсерінен шаш түбірлері біраз уақыт тынығу кезеңіне өтеді. Кейбір бөпелердің шашы тіпті айтарлықтай сиреп, тақырланып қалуы мүмкін. Әсіресе бөпеңізді үнемі бір қалыпта жатқызсаңыз, басының жастыққа тиетін тұстарында шаштың көбірек түскенін байқауыңыз мүмкін. Бұл — қоректік заттардың тапшылығына байланысты емес физиологиялық үдеріс. Бөпеңіз шамамен 6 айға толғанда шашының түсуі азайып, түскен шаштың орнына жаңасы өсе бастайды.') WHERE id = '902d6d84-5a76-4be3-852e-11ae4442029d';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Осы күндері бөпеңіздің үнемі мазасызданғанын, өзін тыныштандыру үшін жиі емгісі келетінін, тіпті емшектен ажырағысы келмейтінін байқауыңыз мүмкін. Бұл белгілер бөпеңіздің іші желденіп жүргенін көрсетуі мүмкін. Физиологиялық тұрғыдан қалыпты саналатын бұл жағдай кейбір бөпелерде жеңіл өтсе, басқаларында шаншуға себеп болуы мүмкін. Әсіресе 8-аптадағы даму секірісі аяқталып, миының дамуы жеделдеген кезде бөпенің миы денесіндегі бұлшықеттерді, буындар мен жүйкелерді сезіне бастайды. Бұған дейін бөпе желді еріксіз әрі оңай шығаратын. Ал енді бөпеңіз бұл бұлшықеттерді саналы түрде басқаруға тырысады. Жел шығару үшін қажетті бұлшықеттерді қалай жиырып, қалай босаңсыту керегін үйренуіне біраз уақыт қажет. Алғашқы айларда бөпеңіз бұл бұлшықеттерді толық басқара алмай, оларды үнемі ширықтырып ұстайтындықтан, желді оңай шығара алмайды. Соның салдарынан іші шаншиды. Осындай қиын сәттерде бөпеңізді тыныштандырып, бұл кезеңнің уақытша екенін есте ұстаңыз. Алдағы апталарда миы дами түскен сайын, бөпеңіз бұл бұлшықеттерді басқаруды үйреніп, желді оңайырақ шығара алатын болады.') WHERE id = 'f2315e81-cb4e-4e16-ad43-3687f3cbaef0';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіздің ең жақсы дамыған сезімі әлі де сипап-сезу болып табылады. Сондықтан бөпеңізбен үнемі тері арқылы жанасу араларыңыздағы байланысты нығайтады. Өмірінің алғашқы айларында ерекше маңызды болатын сипап-сезу бөпеңіздің қоршаған ортамен байланыс орнатуына және оны танып-білуіне көмектесетін негізгі факторлардың бірі. Осы тұрғыдан алғанда, бөпеңізге массаж жасау, оны сипау және теріңізді терісіне тигізу — араларыңыздағы байланысты дамытудың ең тиімді әрі табиғи тәсілдері. Бөпеңіздің қоршаған ортамен қарым-қатынасы оған қол тигізгенде, сипағанда және құшаққа алғанда басталады, соның арқасында оның психоәлеуметтік дамуы да қолдау табады. Ел арасында тараған «қолға үйреніп кетеді» деген қорқынышпен бөпені құшаққа алмау — өте қате түсінік және ана мен бөпе арасындағы қарым-қатынасқа зиян келтіреді. Бөпеңіздің сипап-сезуін ынталандыру және дене жанасуын жалғастыру оның қауіпсіздік сезімін дамытып қана қоймай, сүттің бөлінуін арттырып, емізудің сәтті болуына ықпал етеді. Сондай-ақ зерттеулерге сәйкес, жиі құшақтап, массаж жасалған бөпелердің салмағы мен бойы басқа бөпелерге қарағанда көбірек өсетіні байқалған.') WHERE id = 'aa7f3500-7164-43a7-9fa5-208e7d522806';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпелерде жағымсыз иісті іш өту, тоқтамайтын құсу және қызба түрінде байқалатын ротавирустық инфекция, әсіресе алғашқы айларда бөпеңіз үшін өте қауіпті болуы мүмкін. Құрылысы дөңгелек болғандықтан «рота» деп аталған бұл вирус асқазан қышқылына төзімді. Асқазаннан өтіп, аш ішекке жеткен ротавирус ондағы жасушаларды зақымдап, көбейе бастайды. Вирустың шабуылына ұшыраған иммундық жүйенің жауабы салдарынан дене қызуы 39°C-ге дейін көтерілуі мүмкін. Ротавирустық инфекцияның белгілері вирус жұққаннан кейінгі 48 сағат ішінде басталады. Ол өздігінен басылатын сулы іш өту түрінде де, қауіпті деңгейдегі қызба мен құсу қатар жүріп, ағзаның қатты сусыздануына әкелетін іш өту түрінде де байқалуы мүмкін. Бұл инфекция ағзада сұйықтықтың айтарлықтай жоғалуына себеп болатындықтан, әсіресе бөпелерді ауруханаға жатқызып, көктамыр арқылы емдеу қажет болуы ықтимал. Ротавирусқа қарсы вакцина бөпені бұл инфекциядан 100% қорғамаса да, аурудың әлдеқайда жеңіл өтуіне көмектесетіндіктен, оны салдыру өте маңызды. Дәрігерлердің барлығы дерлік бұл вакцинаны салдыруды қатаң түрде ұсынады.') WHERE id = '1b640d9c-64b4-46e3-adef-12469bcc8075';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіздің ара-тұра көп мөлшерде құсуы Сізді алаңдатуы мүмкін. Мұндай құсу әдетте алғашқы айларда, бөпе тамақтанғаннан кейін көп ұзамай болады. Туғаннан кейінгі алғашқы бірнеше күнде басталатын бұл мәселе асқазан мен өңештің арасындағы сфинктердің, яғни қақпақшаның әлі толық жетілмеуінен туындайды. Бөпе дамыған сайын құсу 3-4 ай ішінде тоқтауы мүмкін, бірақ кейде ол екі жасқа толғанға дейін жалғасады. Тамақтану кезінде ауамен араласқан сүт немесе сүт қоспасы өңешпен кері көтеріліп, құсу ықтималдығын арттыруы мүмкін. Егер бөпеңізде осындай жағдай байқалса, оны қалай тамақтандырып жүргеніңізге назар аударған жөн. Емізгенде немесе сүт қоспасын бергенде бөпенің толықтай шалқасынан жатуы, ауа жұтуы, тым баяу немесе тым жылдам емуі құсуды күшейтуі мүмкін. Сонымен қатар бөпеңіз тойғаннан кейін кекіртіп, жұтқан ауасын шығару құсу жағдайларын едәуір азайтады.') WHERE id = '5fefb883-23f7-42f1-b985-be875f76a7d5';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңізді инфекциялардан қорғайтын ең күшті құралдар — Сіздің сүтіңіз бен салдырған вакциналарыңыз. Дүниеге келген сәттен бастап ана сүті арқылы алған антиденелер оның иммундық жүйесінің негізін қалыптастырып, аурулардан қорғайды. Алайда бұл табиғи қорғаныстың әсері біраз уақыттан кейін әлсірейтінін ұмытпаңыз. Осы кезеңде бөпеңізге вакцина салынбаса, микробтар мен вирустарға тап болған кезде оның ағзасы олармен күресуге жеткілікті күшті болмауы мүмкін. Әлемде жыл сайын вакцина арқылы алдын алуға болатын аурулардан миллиондаған адам қайтыс болады. Балалық және нәрестелік кезеңдегі аурулардың басым бөлігі — жұқпалы аурулар. Олардың кейбірі ауыр індеттер мен асқынуларға әкелуі мүмкін. Сондықтан бөпеңіздің екпе күнтізбесін дәл сақтау оның өмір бойы мықты иммунитетке ие болуы үшін өте маңызды, аяулы ана.') WHERE id = '9a1ea20d-ced6-455d-9f64-c58e6cf75bea';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіз дүниеге келгеннен кейін, әсіресе алғашқы бір жылда таңғаларлық жылдамдықпен дамиды. Кейде ол бір күнде, тіпті бір түнде өсіп кеткендей көрінуі мүмкін. Алайда бұл өсу үдерісі көбіне еш белгісіз өте бермейді. Қарқынды өсу кезеңінің кейбір физиологиялық әсерлері болады. Бөпеңізде ара-тұра ұйқының бұзылуы, ұзақ жылау ұстамалары немесе тамақтану тәртібінің өзгеруі байқалуы мүмкін; кейде себебін түсіне алмайтын жағдайларға тап болуыңыз ықтимал. Көпшілік ата-ана атанғанға дейін біле бермейтін, алайда барлық бөпеде дерлік кездесетін мұндай кезеңдер өсу секірістері деп аталады. Барлық бөпелер сияқты, Сіздің балаңызда да болатын бұл өсу секірістері — толықтай қалыпты әрі қажетті үдеріс. Мұндай кезеңдерде бөпеңіз физикалық тұрғыдан қарқынды дамып қана қоймай, қоршаған әлем туралы жаңа жаңалықтар ашады немесе жаңа дағдыларды меңгереді.') WHERE id = 'bf8343fd-c467-4ff0-b59e-adf0ca316a49';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіздің терісі ересектердікіне қарағанда жұқа, өте нәзік және сыртқы әсерлерге сезімтал. Сонымен қатар тері астындағы май қабаты біздікінен жұқа болғандықтан, ол суыққа да төзімсіздеу келеді. Сондықтан, әсіресе алғашқы айларда, бөпеңізді киіндіргенде мұқият болып, киімнің құрамына назар аударуыңыз керек. Киім бөпеңіздің терісіне тікелей тиетіндіктен, мақтадан тігілген жұмсақ әрі табиғи маталарды таңдаған жөн. Таңдаған киіміңіз оның еркін қимылдауына жеткілікті кең болып, қолы мен аяғының қозғалысын шектемеуі керек. Қан айналымы бұзылмауы үшін шұлық таңдағанда да жұмсақ әрі резеңкесі қатты қыспайтын үлгілерге басымдық беріңіз. Киім сатып алғанда оның жеңі, жағасы мен бел тұсы қатты болмауына, сондай-ақ ілгек пен түйме секілді бөлшектерінің сапасына міндетті түрде назар аударуды ұсынамыз.') WHERE id = '03d19ce6-58a4-42e4-a4c9-562747272e51';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіз күн ішінде әртүрлі себептермен әрқалай жылауы мүмкін. Ал жылаған кезде оның көзінен жас шықпайтынын байқап көрдіңіз бе? Бөпенің көз жасы өзектері мен бездері жұмыс істегенімен, әзірге көздерін қорғап, ылғалды ұстап тұруға жеткілікті мөлшерде ғана жас бөледі. Бөпенің көз жасы бездері туғаннан кейін бірден қарқынды дами бастайды және орта есеппен 2-3 айға толғанда жас ағызатындай деңгейге жетеді. Кей жағдайларда бөпелердің шамамен 5-6%-ында көз жасы өзектерінің бітелуі кездесуі мүмкін. Бұл бітелу көздің былшықтануы, жасаурауы, кірпіктердің жабысып қалуы, іріңді бөлінді және көз айналасының ісінуі арқылы байқалуы мүмкін. Көз жасы өзегінің бітелуіне көз жасы қалтасының мұрынға ашылатын бөлігіндегі жарғақшаның ашылмауы себеп болады. Бұл жағдай емделмесе, бөпенің көзі микробтарға сезімтал болады. Сондықтан бөпеңізден осы белгілерді байқасаңыз, уақыт жоғалтпай офтальмологпен кеңесуіңіз керек.') WHERE id = 'e03b8fab-73de-4cff-bd15-34280044bd83';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңізге емізік беру-бермеу туралы көкейіңізде кейбір сұрақтар болуы мүмкін. Бөпеңіз дүниеге күшті ему рефлексімен келеді. Бұл "ауыздық кезең" деп аталады және шамамен 2 жасқа дейін жалғасады. Америкалық педиатрия академиясы емізік нәрестенің кенеттен қайтыс болу синдромының алдын алуға көмектеседі деп есептейтіндіктен, оны 1 жасқа дейін қолдануға кеңес береді. Осы кезеңдегі күшті ему рефлексі бөпенің тамақтануға қатысты да, эмоциялық та қажеттіліктерін өтейді. Емізік бөпенің емуге деген физиологиялық қажеттілігін қанағаттандыруы, өзін қауіпсіз сезінуіне және тынышталуына көмектесуі, сондай-ақ ананың омырауын емуден басқа мақсатта пайдалануын шектеу үшін таңдалуы мүмкін. Дегенмен емізікті ұзақ уақыт қолдану әдетке айналуы ықтимал. Қолдану уақытын шектемесеңіз, бөпенің тамақтануына кері әсер етіп, соның салдарынан дамуының кешеуілдеуіне әкелуі мүмкін. Сондай-ақ емізікті ұзақ қолдану тіс қатарының бұзылуына және сөйлеудің кешігуіне себеп болуы мүмкін.') WHERE id = '9bf80a49-be8d-491a-9e0b-6671644690ad';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Егер бөпеңізді емізіп жүрсеңіз, етеккіріңіз әлі басталмаған болуы мүмкін. Бала емізетін аналарда етеккір босанғаннан кейін шамамен алты-сегіз аптадан соң қайта басталуы мүмкін, алайда бұл мерзім 24 айға дейін созылуы да ықтимал. Етеккірдің қайта басталу уақыты әр әйелде әртүрлі болады. Бұған ағзаңыздағы сүттің түзілуі мен бөлінуін қамтамасыз ететін пролактин және окситоцин гормондарының болуы себеп. Қанда жоғары мөлшерде болатын және сүттің түзілуін қамтамасыз ететін пролактин гормоны аналық жасушалардың жетілуіне қажетті репродуктивті гормондардың бөлінуін тежейді. Ал аналық бездерде аналық жасуша жетілмесе, етеккір де болмайды. Сондықтан бөпесін емшек сүтімен қоректендіретін аналарда етеккірдің нақты қашан қайта басталатынын алдын ала айту мүмкін емес.') WHERE id = 'ed5d9752-70a1-4d4a-938d-22777462f998';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Әсіресе бала емізу кезеңінде дәрі-дәрмек қолдануға қатысты алаңдауыңыз мүмкін. Жүктілік кезіндегідей, бала емізу кезеңінде де ағзаңыз бөпені қорғауға көмектесетін түрлі қасиеттерге ие. Ана сүті — ағзаңызда бөпенің барлық қажеттілігіне сай түзілетін ғажайып тағам. Ағзаңызда қандағы кейбір зиянды заттардың сүт өзектеріне өтуіне жол бермейтін қорғаныс жүйелері бар. Заттардың өтуін шектейтін бұл физиологиялық ерекшелік қан-сүт тосқауылы деп аталады. Қолданылатын дәрілердің кейбірі осы тосқауылдан өте алса, басқалары одан өтпейді және сүтке араласпайды. Кейбір дәрігерлер бала емізу кезінде дәрі қолдануға үзілді-кесілді қарсы болса, басқалары пайдасы мен ықтимал зиянының арақатынасын бағалайды. Сондықтан міндетті түрде дәрігеріңізбен кеңесіп, қолданатын дәрілеріңіздің құрамын сұрап, олардың бала емізумен үйлесімді-үйлесімді еместігін білуіңіз керек.') WHERE id = '23d4091f-e3fa-4f6e-82ab-2f668868b04f';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Жылау — бөпенің ең маңызды қарым-қатынас құралы. Бөпеңіз іші желденіп ауырғанда, қарны ашқанда, ұйқысы келгенде, тоңғанда, терлегенде, қолға алуды қалағанда және басқа да көптеген себеппен жылауы мүмкін. Бөпеңіздің жылау мәнері оның қажеттілігіне қарай өзгереді. Бақылай жүріп, оның қандай қажеттілікке байланысты жылағанын түсіне бастаған боларсыз. Қарны ашып жылаған бөпеңізді тамақтандырсаңыз, ол тынышталады. Бөпені өз қалауына қарай тамақтандыру өте маңызды. Бөпеңіз ұйқысында селк етіп оянып, жылауы мүмкін. Мұндай жағдайда жартылай құндақтау әдісін қолданып, қолдарын жұқа көрпемен тым қатты қыспай орасаңыз, ол тынышталады. Кейде барлық қажеттілігін өтесеңіз де, қолыңызға алғанда тынышталып, жатқызған кезде қайта жылауы дене жанасуын қалауынан болады. 9 ай бойы жатырда жатқан бөпенің туғаннан кейінгі алғашқы айларда осындай жанасуды іздеуі — табиғи жағдай. Бөпеңіз қолға үйреніп кетеді деп алаңдамаңыз. Өзін қауіпсіз сезініп, иісіңіз бен жылуыңызды сезе алатын ең сенімді жер — Сіздің құшағыңыз.') WHERE id = 'd2ed38a5-2867-473a-a048-a7488c8a0f81';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпенің тер бездері әлі толық жетілмегендіктен, ол дене температурасын реттеу үшін жеткілікті терлей алмайды. Сондықтан оны шамадан тыс ыстық жерде ұстаудан және тым қалың киіндіруден аулақ болыңыз. Бөпеңіз үшін бөлме температурасының шамамен 22-24 градус болуы жеткілікті. Үй ішінде оған кеудеше, күрте, шұлықтың сыртынан пинетка сияқты бірнеше қабат киім кигізудің қажеті жоқ. Боди немесе жұқа ішкиімнің үстінен комбинезон кигізіп, аяғына бір жұп шұлық кигізсеңіз жеткілікті. Алайда бөпеңіз шала туған болса, дене жылуын әлі толық сақтай алмайтындықтан, оған бір қабат артық киім кигізу қажет болуы мүмкін. Киімі жеткілікті екенін білу үшін желкесін немесе ішін ұстап көріңіз. Бөпелердің қолы мен аяғы әдетте салқын болады, сондықтан олардың тоңған-тоңбағанын анықтағанда бұл Сізді жаңылыстыруы мүмкін. Бөпе денесіндегі жылудың негізгі бөлігі басы арқылы жоғалады. Мұның алдын алу үшін үйде оған тым қалың емес баскиім кигізуге болады. Алайда түнде ұйықтаған кезде ауа жетпей, тұншығып қалу қаупі бар болғандықтан, оны міндетті түрде баскиімсіз жатқызу керектігін ұмытпаңыз.') WHERE id = '48c1b6b4-184f-478a-85ac-ef677c12d146';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Әр бөпе үшін ең дұрыс тағам — өз анасының сүті, өйткені ол дәл бөпенің қажеттіліктеріне сай түзіледі. Алайда кейде денсаулыққа немесе жеке жағдайларға байланысты аналар емізе алмайды. Мұндай жағдайда ең жақсы балама — бөпелерге арнайы әзірленген бейімделген сүт қоспалары. Бұл қоспалар сиыр немесе ешкі сүтінің құрамын заманауи технологиялар арқылы өзгертіп, ана сүтіне ұқсату жолымен өндіріледі. Табиғи сиыр сүті құрылымы жағынан ана сүтіне ұқсағанымен, зерттеулер оның қорытылуы қиын әрі құрамы бөпелерге сәйкес келмейтінін көрсетеді. Сондықтан дәрігерлер сиыр сүтін 1 жасқа дейін беруге кеңес бермейді. Нарықта алғашқы бір жылға арналған қоспалардың сиыр сүті негізіндегі, соя негізіндегі немесе ақуызы ыдыратылған түрлері бар. Сиыр сүті негізіндегі қоспалар бөпеге қажетті қоректік заттармен байытылады, ал соя негізіндегілері әдетте сиыр сүтінің ақуызына аллергиясы бар бөпелерге ұсынылады.') WHERE id = '54371049-7cba-412e-931d-3ce67181ed5e';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөбегіңіз әлдеқайда қимылшыл бола түсті! 😊 Мұның басты себептерінің бірі, әрине, оның бұлшықеттерінің дамуы. 3 айға жақындаған бөбегіңіздің белсендірек болғанын қазірдің өзінде байқаған шығарсыз. Осы кезеңде басын тік ұстай бастап, жатқан жерінен шамамен 45 градусқа дейін көтеріле алатын бөбегіңіз қарқынды даму кезеңіне қадам басты. Қимыл-қозғалысының артуына оның айналасын зерттеуге деген құштарлығы да әсер етеді. Енді ол түстерді жақсырақ ажыратып, дамып келе жатқан көру қабілетінің көмегімен айналасын танығысы келеді. Зерттеу айы деп аталатын осы кезеңде бөбегіңіз өз қолдарын зерттеп, Сіз көрсеткен заттарды ұстауға талпынып, Сізді көзімен қадағалай бастайды. Сізді және әкесін жақсы ажырата бастаған бөбегіңіз Сізбен жиірек көз түйістіруі мүмкін. Есту және көру зейіні дамығандықтан, осы айда Сіз сөйлегенде, сөзіңізді түсініп тұрғандай қарағанын байқай аласыз. Әрине, мұның бәрі күн тәртібіне де әсер етеді. Мысалы, бөбегіңіз айналасын зерттеуге көбірек қызығатындықтан, енді азырақ ұйықтауы мүмкін. Сондай-ақ оның толассыз шаттыққа толы дауыстарына да дайын болыңыз! 😊') WHERE id = '5ea89e0c-0d1c-402a-8337-a40bace39e26';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Ана сүті — ғажайып тағам. Бұл бірегей тағам бөбегіңіз өскен сайын оның қажеттіліктеріне сай көбейіп, құрамы өзгеріп отырады. Сүт өндіруге қажетті сүт жолдарының қалыптасуы жүктіліктің алғашқы сәттерінен басталады. Бірінші триместр бойы дамитын сүт бездері, әсіресе босануға жақын күндері сүтке толып, бөпенің келуіне дайындалады. Босанғанға дейін сүттің сүт жолдарына түспеуі және қосымша сүт өндірісінің тежелуі плацента бөлетін гормондар арқылы реттеледі. Ал емізу кезеңінде ағзаңыздан бөлінетін окситоцин мен пролактин гормондары сүттің тұрақты бөлінуін және емізу үдерісін қамтамасыз етеді. Ана сүті бөпеңіздің алғашқы 6 айда қажет ететін ақуыз, май, темір және дәрумендер секілді барлық қоректік заттарға деген қажеттілігін өтейді, ал 6 айдан кейін оның дамуы үшін қосымша тағамға біртіндеп көшу қажет. Бөпеңіздің асқазанының сыйымдылығы мен калорияға қажеттілігі артқан сайын, сүтіңіздің мөлшері мен құрамындағы қоректік заттардың концентрациясы да жоғарылайды. Осылайша бөбегіңіз емізу кезеңі аяқталғанға дейін ана сүтінің пайдасын барынша алады.') WHERE id = 'e67478e1-350c-4cf1-9917-9b4bd3ed801c';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Заманауи технологиялар мен медициналық білімнің арқасында жақын арада қайта жүкті болуды жоспарламайтын әйелдер үшін контрацепцияның көптеген әдісі бар. Солардың ішінде жиі таңдалатын контрацептивтік таблеткалардың құрамында эстроген болғандықтан, емізіп жүрсеңіз, олар сүт мөлшерін азайтуы мүмкін және сондықтан ұсынылмайды. Ал құрамында эстроген жоқ таблеткаларды босанғаннан кейін 6 аптадан соң қауіпсіз қолдануға болады. Үш айлық инъекция деп аталатын контрацепция әдісінің құрамында прогестерон бар және ол емізу кезеңінде қауіп төндірмейді. Үш айлық инъекциядан айырмашылығы, ай сайынғы инъекциялардың құрамында эстроген бар, сондықтан оларды емізу кезеңінде қолдану ұсынылмайды. Имплант — тері астына енгізілетін, үш жыл бойы жүктіліктен қорғайтын гормоналды әдіс. Имплант құрамындағы гормон ана сүтіне өткенімен, бөпеңізге әсер етпейді. Дәрігерлер жиі ұсынатын әдіс — жүктіліктен қорғау тиімділігі өте жоғары, спираль деп аталатын жатырішілік құрал. Гормонды және гормонсыз түрлері бар спиральді босанғаннан кейін 6 аптадан соң орнатуға болады.') WHERE id = 'e001d0c5-46e0-40b1-82c7-a4a7f2a5f692';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөбегіңізге киім таңдау — басқа істер сияқты өзіндік қыр-сыры бар, мұқияттылықты қажет ететін мәселе. Киім таңдаудағы ең маңызды жайттардың бірі — қауіпсіздік. Қауіпсіздік үшін бөбектің киімдерінде түйме немесе ұзын бау болғанынан гөрі, батырмалы әрі қарапайым үлгілерді таңдағаныңыз өте маңызды. Сондай-ақ ағзада уытты зат ретінде жиналып, канцерогендік әсер етуі мүмкін бояуы шығатын киімдерден аулақ болып, сапалы өнімдерді таңдауыңыз керек. Бөпеңіздің ағзасы оған зиян келтіруі мүмкін кез келген затқа қарсы қорғаныс механизмін қалыптастырады. Аллергия да дәл осы қорғаныс механизмінің іске қосылуы нәтижесінде пайда болады. Киім өндірісінде қолданылатын бояғыш заттар бөбегіңізде аллергия тудыруы мүмкін болғандықтан, стандарттарға сәйкестігі сертификатталған өнімдерді таңдағаныңыз жөн. Мұндай сертификаты бар өнімдер бөпеңіздің ағзасына зиян келтіруі ықтимал күмәнді заттарға тексеріледі және қауіпсіздік нормаларына сай өндіріледі. Сондықтан осы стандарттарға сәйкес келетін киімдерді бөбегіңізге алаңдамай кигізе аласыз.') WHERE id = '8bcfa34a-ab3b-47cd-8082-d8d412e4c0f8';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөбегіңізбен бірге өткізіп жатқан 3-айыңыз! Бөбегіңізбен жаңа кезеңге қадам басқан осы айда Сізді қатты қуантатын тосынсыйларға дайын болыңыз. Бөбегіңіздің қимыл-қозғалыс дағдылары дамып, енді қолына берген заттарды аз уақыт болса да ұстай алады. Оның үстіне, бұл енді рефлекс емес, саналы әрекетке айнала бастайды. Қолдарындағы қармау рефлексі біртіндеп жоғала бастағанымен, аяқтарындағы қармау рефлексінің жоғалуына әлі бірнеше ай қажет. Рефлекстен саналы әрекетке көшу кезінде байқалатын тағы бір өзгеріс бөбегіңіздің тамақтануына қатысты. Жаңа туған нәрестеге тән, бетіне тигенде аузын ашу рефлексі осы айдан бастап біртіндеп саналы әрекетке айналады. Яғни бөбегіңіз аш болмаса, енді аузын ашпайды. Бұл мінез-құлық өзгерістері, әрине, бөбегіңіздің миының қарқынды дамуының арқасында жүзеге асады.') WHERE id = '327fd5ec-447f-4d93-a81c-c3fdb4d5f652';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Осы айда өтетін жоспарлы тексерулер кезінде дәрігер бөпеңіздің кейбір даму көрсеткіштерін бағалайды. Олардың біріншісі әрі ең маңыздысы — бөпенің басын ұстай алуы. Өйткені 3 айға толған бөпелер осы кезеңде басын еркін басқарып, тік ұстап және 45 градусқа дейін көтере алуы керек. Ал еңбегі әлі қатайып, жабылмауы тиіс. Еңбектің ашық болуы бөпенің миы дұрыс дамуын жалғастыруы үшін өте маңызды. Ми дамуының тағы бір көрсеткіші — басының өлшемі. Осы айдан бастап бөпенің бас айналымы орта есеппен 37-43 см аралығында болуы керек. Дәрігер тұрақты бақылап отыратын басқа көрсеткіштер — бойы мен салмағы. Осы айда бөпенің салмағы 4200-7500 грамм, ал бойы 55-65 см аралығында болуы мүмкін. Бұл сандардың орташа көрсеткіштер екенін және әр бөпеде әртүрлі болуы мүмкін екенін ұмытпаңыз. Көрсеткіштер төменгі және жоғарғы шектерден шықпаса, бөпенің дамуына алаңдаудың қажеті жоқ.') WHERE id = '76c150ee-bf0f-46cc-b728-a8452683e29c';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіздің үшінші өсу секірісі, яғни қарқынды өсу кезеңі осы күндері басталуы тиіс. Сондықтан бөпеңіз мазасызданып, ұйқысы бұзылып немесе тәбеті өзгерсе, ешқашан абыржымаңыз. Үшінші өсу секірісі бөпенің туған күні мен болжамды босану күні арасында айырмашылық болғанымен, орта есеппен 12-апта шамасында өтеді. Осы секірістен кейін бөпеңіз дыбыстарға көбірек қызығушылық танытып, есту қабілетінің сезімталдығы артқандықтан, тіпті дауыс ырғағындағы өзгерістерді де байқай бастайды. Сонымен қатар бөпенің ми бағанындағы естуге жауап беретін жасушалар дыбыстың қай бағыттан шыққанын анықтап, соған сәйкес әрекет ете бастайды. Бұл бөпеңіз енді дыбыс шыққан жақты ажыратып, сол бағытқа бұрыла алады дегенді білдіреді. Осы кезеңдегі тағы бір өзгеріс — бөпенің өз дауысын тани бастауы. Өз дауысын таныған бөпеңіз әртүрлі дыбыстарды түрлі қарқынмен шығарып, Сізді таңғалдыруы мүмкін. Көңілді уақыт өткізіңіздер! 😊') WHERE id = '7157ab6b-c70f-4177-b181-d8ea3a2d459e';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Егер бөпеңізді сүт қоспасымен тамақтандырсаңыз немесе емшек сүтіңіз жеткіліксіз болғандықтан қосымша қоспа берсеңіз, ең маңызды мәселелердің бірі — бөтелке таңдау. Бөтелке таңдауға бөпенің денсаулығы үшін немқұрайды қарауға болмайды. Дұрыс бөтелке бөпенің жақсы тамақтануына көмектесіп қана қоймай, қолдануға ыңғайлы болғандықтан, Сіздің де жұмысыңызды едәуір жеңілдетеді. Таңдау кезінде бөпенің емшек емген кездегідей аузын кең ашып тамақтануына мүмкіндік беретін үлгілерге басымдық берген жөн. Сонымен қатар таңдаған бөтелке ас қорыту жүйесіне артық салмақ түсірмеуі және шаншуға байланысты іш кебуін азайтатыны клиникалық тұрғыда дәлелденген болуы керек. Бөтелкенің материалы, көлемі, пішіні, коликке қарсы қасиеті, емізігінің пішіні мен тесіктерінің саны — назар аударатын маңызды сипаттамалар. Осы кезеңде бөпеңізге көлемі 240-260 ml, ағыны орташа және ауа өткізетін клапаны бар емізікпен жабдықталған бөтелкелерді таңдаған жөн.') WHERE id = '20a065b0-2b51-4884-b57e-e72acfd3836c';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіздің өсу және даму қарқыны жасына қарай өзгеріп отырады. Кейбір кезеңдерде баяу өссе де, өсу секірісі, яғни қарқынды даму кезеңі басталғанда өсу жылдамдығы артады. Өсу қарқыны баяулаған кезде бөпенің тәбетінің төмендеуі ғылыми тұрғыдан қалыпты жағдай болып саналады. Бөпе өмірінің алғашқы жылында өте жылдам өседі, сондықтан әдетте араласуды қажет ететіндей күрделі тәбетсіздік мәселесі кездеспейді. Дегенмен тісі шығып жатқанда және айналасын зерттей бастаған кезеңде тәбеті қысқа уақытқа төмендеуі мүмкін. Тіс шығару үдерісі әр бөпе үшін дерлік қиын кезең болып саналады. Осы кезде мазасызданып, ауырсынуды сезінген бөпенің ретсіз әрі аз тамақтануы қалыпты. Алайда аз тамақтануды тәбетсіздікпен шатастырмау маңызды. Жаңа босанған ана үшін бұл жағдай алаңдаушылық тудырса да, шын мәнінде абыржудың қажеті жоқ. Бұған қоса қосымша тағамды ерте бастаған бөпелерде ас қорыту жүйесінің әлі дайын болмауынан туындайтын аллергиялық реакциялар да тәбеттің төмендеуіне себеп болуы мүмкін.') WHERE id = '87f56862-dda9-454a-a541-34481c8ca235';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңізбен бірге көптеген түрлі іспен айналыса аласыз. Айналасымен белсенді қарым-қатынас жасай бастаған бөпеңізге көңіл бөлу — оның болашағы үшін жасай алатын ең жақсы инвестицияңыз. Иіс сезу қабілеті өте жақсы дамыған бөпеңізге ми жасушалары тиімдірек жұмыс істеуі үшін бір-біріне ұқсамайтын түрлі иістерді иіскетуге болады. Бөпенің сөйлеу қабілеті дамуы үшін онымен жиі сөйлесіп, қарым-қатынас жасау керек. Оның мүмкіндігінше әртүрлі сөздерді естуі маңызды. Бөпеңізбен үнемі сөйлесіңіз, есімін танып үйренуіне көмектесу үшін оны жиі атымен атаңыз, құшақтап, сүйіңіз. Өзін жақсы көретінін және оған көңіл бөлінетінін сезген бөпе физикалық әрі психологиялық тұрғыдан дені сау болып өседі. Бөпеңізбен үйден шықпай, тек физиологиялық қажеттіліктерін өтеумен шектелмей, оған жаңа әсер алуға мүмкіндік жасағаныңыз жөн. Далаға шығып, таза ауада күннің жылуын сезінуіне мүмкіндік беріңіз. Далаға шыға алмаған кездерде балконнан немесе терезеден сыртқа бірге қарауға болады. Мұндағы басты мақсат — қимыл-қозғалыс арқылы бөпенің қабылдау қабілетін дамыту, сезім мүшелерін белсенді қолдануына жағдай жасау және жадын жаттықтыру.') WHERE id = 'd229dd79-f389-4db8-9b5a-34c760b0f5c0';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіздің жөргегін ауыстырған кезде терісінің қабыршақтанғанын, қызарғанын немесе қабынғанын байқасаңыз, оған жеңіл зең инфекциясы жұққан болуы мүмкін. Мұндай реакцияларды тудыратын зеңдер — ылғалды ортада жылдам көбейетін микроскопиялық ағзалар. Олардың көбеюіне жылу мен ылғал қажет. Қолайлы орта пайда болғанда олар оңай таралады. Бөпенің жөргек астындағы аймағы сияқты сумен жанасып, ылғал болып қалатын жерлерде зеңнің пайда болу ықтималдығы жоғары. Сондықтан бөпенің жөргек астын тазалағаннан кейін ылғал қалдырмай, жақсылап құрғату керек. Бөпенің терісіндегі зең инфекциясын жөргек бөртпесінен ажырату үшін дәрігердің тексеруі маңызды. Сыртқы белгілеріне қарағанда, зең пайда болған аймақтарда терінің қабыршақтануы байқалады. Жөргек бөртпесі бар бөпелерде, әсіресе антибиотиктер дәрігердің бақылауынсыз қолданылғанда, зең инфекциясының пайда болу қаупі өте жоғары. Сондықтан бөпенің терісінде пайда болған жөргек бөртпесіне мұқият әрі ұқыпты қарау керек.') WHERE id = 'b63be385-2a69-41af-ad23-38c2f405d961';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіз қолдарын сағаттап бас деңгейінде ұстап, қызыға қарап жүр ме? Оның «Иә!» дегенін естіп тұрғандаймыз. 😊 Осы апталарда әрбір ана дерлік бөпесінің қолдарын зерттеп қарап, аузына апаратынын байқайды. Бөпенің даму кезеңінде мұндай әрекет жасауы — қалыпты жағдай, оған кедергі келтірмеу керек. Қолдарын қалағанынша аузына апара берсін. 😊 Қолдары мен саусақтарына қызығушылығы артқан бөпеңіз, әсіресе шалқасынан жатқанда, қолдарын көтеріп, қозғалта отырып қарайды. Тіпті қолдарын жылдам қимылдатып, өз қозғалысын көзімен және басымен бақылауы мүмкін. Осы кезеңдерден өткен сайын бөпеңіз қолдарын пайдалы құрал ретінде басқаруды үйреніп, оларды айналасындағы заттарды зерттеу үшін қолдана бастайды. Сізге тек оның қолдарының таза болуын қадағалап, ауыз қуысын жарақаттап алмауы үшін тырнақтарын уақтылы қысқартып отыру қажет. Зерттеуі қызықты болсын! 😊') WHERE id = 'caffa322-fe7d-4bfd-9362-04360cd00a6c';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, '3 айлық бөпенің миында естеліктер мен тәжірибелер қалыптаса бастайды. Алғашқы кезеңде олар үнемі қайталанатын әрекеттер арқылы қалыптасады. Бөпеңіз бұрын көрген адамдарды, заттарды және бет әлпеттерін есінде сақтап, ажырата бастағандықтан, жыласа, өзіне назар аудартатынын біледі. Осы айдағы ең тамаша өзгерістердің бірі — Сіз жымиғанда, ол да күлімсіреп жауап беруді үйренеді. Күлкіге дайын болыңыз. 😊 Негізінде, есте сақтау қабілеті бөпеңіз әлі құрсағыңызда жатқанда-ақ қалыптаса бастайды. Есту қабілеті дамыған сәттен бастап дыбыстарды қабылдап, жадында сақтайтын бөпеңіз дүниеге келгеннен кейін Сіздің даусыңызды басқа дауыстардан оңай ажырата алады. Ал енді қарқынды дамып келе жатқан миының арқасында жадында сақталған ақпаратты түсініп, оған жауап бере алады. Мысалы, 3 айлық бөпе анасы көрсеткен заттың бейнесін жадында 7 күнге дейін сақтап, оны қайта көрсеткенде танығанын білдіретін реакция танытуы мүмкін.') WHERE id = 'a7c25396-4991-4496-8a65-64211f7dd866';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Қарқынды дамып келе жатқан жүйке жүйесі мен сезім мүшелерінің арқасында бөпеңіз қоршаған ортамен көбірек әрекеттесе бастады. Сондықтан оның бір орында жатқысы келмеуі, жалғыз қалғанда жылауы және үнемі қолда жүргісі келуі — қалыпты жағдай. Кейде Сізді шаршатуы мүмкін бұл жағдайға мүмкіндігінше түсіністікпен қарап, бөпеңіздің айналасын зерттеуіне көмектесуіңіз керек. Бөпеңізді алып жүргенде оны әртүрлі қалыпта ұстау бұлшықеттерінің дамуына ықпал етеді әрі оған өте ұнайды. Сонымен қатар, осылайша ол Сізбен және айналасындағы адамдармен дұрыс қарым-қатынас орнатуды үйренеді. Осы айда бөпеңіздің ұйқысы, ойыны және тамақтануы сияқты әрекеттері біртіндеп белгілі бір тәртіпке түседі. Сондықтан 3-ші ай Сіз үшін де, бөпеңіз үшін де бетбұрыс кезеңі болып саналады. Бөпеңізбен ойнап, бірге уақыт өткізіп, оған жиі күлімсіреуді жалғастырыңыз. Онымен сапалы уақыт өткізуіңіз қамқорлық танытатыныңызды білдіреді және оның психикалық тұрғыдан сау дамуы үшін өте маңызды.') WHERE id = 'c7c7ac0c-0d6e-4513-8d30-65a89768a3af';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіздің үлкен дәретке отыру жиілігі азайғанын біраз уақыттан бері байқап жүрген боларсыз. Бөпелердің үлкен дәретке отыру әдеті әртүрлі болуы мүмкін және олардың көпшілігі қалыпты саналады. Егер бөпеңіз тек емшек сүтімен қоректенсе, аптасына бір рет үлкен дәретке отыруы да, күніне 5-6 рет отыруы да қалыпты. Сондай-ақ емшек сүтімен қоректенетін бөпенің нәжісі әдетте сары түсті, сұйық әрі аздап түйіршікті болады. Егер бөпеңіз қоспамен қоректенсе және іші қатпаса, оның 3-4 күнде бір рет немесе күніне 5 ретке дейін жұмсақ нәжіс шығаруы да қалыпты. Қоспамен қоректенетін бөпенің нәжісі сары да, жасыл да болуы мүмкін. Тамақтану тәсілінен бөлек, қолданатын қоспаның брендін ауыстырғанда немесе антибиотик қабылдау кезінде бөпеңіздің үлкен дәретке отыру жиілігі өзгеруі мүмкін. Бұл жерде назар аударатын негізгі нәрсе — нәжістің консистенциясы. Егер нәжіс қатты, құрғақ және бөлшектеніп шықса, бөпеңіздің іші қатқан болуы ықтимал. Бөпеңіздің осы жағдайдан мазасызданып, жайсызданып жүргенін байқасаңыз, мүмкіндігінше тезірек дәрігеріңізге хабарласқаныңыз жөн.') WHERE id = '0aa04f59-8956-4168-94d6-7cbf1b5d04b5';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бұл кезеңде бөпеңіздің қол-көз үйлесімі айтарлықтай дамыды. Ұстау қабілетінің арқасында ойыншықтар мен заттарды қолымен ұстай алатынын түсінген бөпеңіз осы әрекеттерге назар аудара бастайды. Мысалы, бөпеңіз қолына ұстаған сылдырмақты өзі қаламайынша оңайлықпен жібермейді. Тіпті оның дыбыс шығаратынын түсінсе, сілкіп көруі мүмкін. Мұндай әрекеттер себеп-салдар байланысын түсіну тұрғысынан бөпенің ақыл-ой дамуындағы алғашқы қадамдардың бірі саналады. Бөпеңіз анықтаған осы байланыстардың барлығы көп ұзамай іс жүзінде қолданыла бастайды және ол ұстаған заттарын аузына апаруға тырысады. «Оралдық кезең» деп аталатын бұл сатыда бөпенің алғашқы рефлекстерінің бірі — сору рефлексі арқылы қызыққан және зерттегісі келген нәрсенің бәрін аузына апаратыны байқалады. Бұл кезең бөпе бір жасқа толғанға дейін жалғасады. Осы уақыт аралығында бөпеңіз сыртқы әлеммен бүкіл денесі, әсіресе аузы арқылы танысады. Сондықтан бөпе жұтып қоюы мүмкін барлық ұсақ заттарды алып тастап, оны ұзақ уақыт жалғыз қалдырмауыңыз керек.') WHERE id = '60021b19-b43c-4324-8e67-4e9b5d399b4d';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Емізу немесе бөтелкемен тамақтандыру кезінде бөпеңіз шалқайып, жылайтын болса, ол емшектен немесе тамақтанудан бас тартып жүрген болуы ықтимал. Мұндай жағдайда бөпеңіз қарны ашса да, әртүрлі себептермен емгісі келмеуі мүмкін. Мұның ең жиі кездесетін себептерінің бірі — мұрынның бітелуі. Мұрыны бітелгенде бөпе аузымен тыныс алуға тырысады, сондықтан қарны ашса да, емшекті қайта-қайта жіберіп қоюы немесе мүлдем алмауы мүмкін. Егер бөпеңіздің мұрны бітелсе, емізер алдында аспиратормен тазалау немесе дәрігер ұсынған мұрынға арналған тамшыны қолданып, еркін тыныстауына жағдай жасау керек. Сонымен қатар, бөпе үйренген күн тәртібінің бұзылуы және емізу уақытының өзгеруі оның мазасыздануына әрі емуден бас тартуына себеп болуы мүмкін. Емізу техникасының дұрыс болмауы да бөпеңіздің емшекті дұрыс ұстауын қиындатады. Дұрыс емізу әдістері туралы ақпарат алып, бөпеңіз емшекті ыңғайлы ұстай алатын әртүрлі қалыптарды байқап көру арқылы оның қайта емуіне көмектесе аласыз.') WHERE id = '923618b2-185f-4d48-8595-207ec8b1f1d7';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіздің тамақтанғаннан кейін құсуы физиологиялық тұрғыдан көп жағдайда қалыпты құбылыс болып саналады. Дегенмен оны бақылау маңызды. Әсіресе алғашқы айларда бөпеңіз тамақтанғаннан кейін көп ұзамай еш қиналмай, аузы тола құсуы мүмкін. Өскен сайын бұл жағдай сирей түседі және әдетте сегіз айға келгенде тамақтан кейінгі құсу тоқтайды. Тамақтану кезінде бөпенің ауа жұтуы, тым жылдам немесе тым баяу емуі, тамақтанғаннан кейін кекіртілмеуі құсуға себеп болуы мүмкін. Тамақтандыру техникасындағы осы қателіктер түзетілсе, бөпеңіздің құсуы да тоқтайды. Құсу әдетте тамақтанғаннан кейін болады, себебі өңештің төменгі бөлігінде орналасқан және асқазан ішіндегісінің кері шығуына жол бермейтін бұлшықет физиологиялық тұрғыдан әлі толық қалыптаспаған. Құсу туғаннан бастап байқалуы мүмкін, алайда шамамен 4-ші айда жиілеп, әр 4 бөпенің шамамен 3-еуінде кездеседі. 6-шы айдан кейін әдетте азаятын бұл құсу қатты тағамға көшкен кезде толығымен жоғалады.') WHERE id = '94ce13b4-bc4e-480c-a364-11de1e4c0330';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіздің ішіне жел жиналып, мазасыздануының екі негізгі себебі бар. Біріншісі — бөпенің асқазанындағы пайдалы бактериялар емшек сүтінің немесе қоспаның құрамындағы қорытылмаған қоректік заттарды ыдыратқан кезде түзілетін газ. Екінші себеп — бөпенің жылағанда, жұтынғанда, емгенде немесе бөтелкемен тамақтанғанда жұтатын ауасы. Сондай-ақ бөпеңізді емізетін болсаңыз, өзіңіздің ас қорыту жүйеңізде газ түзілуіне себеп болатын тағамдарды тұтынуыңыз да бөпеңіздің ішіне жел жиналуына әкелуі мүмкін. Сондықтан рационыңызда мұндай азық-түліктерді азайтқаныңыз пайдалы. Бөпеңіздің іші желденіп ауырмауы үшін қолдануға болатын көптеген шара бар. Соның бірі — бөпенің қатты ашығып кетуін күтпеу. Қажет мөлшерден артық ашыққан бөпелер сүтті жылдам ішетіндіктен, көп ауа жұтады. Егер бөпеңізді бөтелкемен тамақтандырсаңыз, емізіктегі тесіктің тым кішкентай немесе тым үлкен болмауын қадағалау арқылы ішке жел жиналуын барынша азайта аласыз.') WHERE id = '14cce317-1232-45b9-96bd-2281d87ef8be';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіздің тамақтануына енгізетін бірнеше өзгеріс рефлюкстің алдын алып, болашақта мәселе туындау қаупін барынша азайтады. Олардың ішіндегі ең маңыздысы — тамақтандыру жиілігі мен тәртібі. Бөпеңізді тамақтандырғанда оны мүмкіндігінше тік қалыпта ұстауыңыз керек. Жиі, бірақ аз мөлшерде тамақтандыру бөпеңіздегі рефлюксті азайтып, ас қорыту үдерісінің жеңіл өтуіне көмектеседі. Тамақтану арасында және одан кейін бөпені жоғары лақтыру немесе домалату сияқты қатты қимылдардан аулақ болып, керісінше, әр тамақтанғаннан кейін оны шамамен 20 минут тік ұстауыңыз керек. Сондай-ақ бөпеңіздің жөргегін ауыстырғанда, оның тым қатты тартылмауын қадағалаңыз. Жөргекті тым қатты тағу бөпенің ішіндегі қысымды арттырып, құсуға себеп болуы мүмкін. Бөпеңіз ұйықтағанда басын сәл биіктету үшін жұқа жастық қолдану желдің шығуын жеңілдетіп, ықтимал тұншығудың алдын алады. Темекі түтінімен тыныстау басқа зиянды әсерлерімен қатар рефлюкске де себеп болатындықтан, бөпеңізді одан қорғау да өте маңызды.') WHERE id = '4db7b0e8-8a13-4223-9f1c-396106b58bfc';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіз өсіп келе жатқанда ең жақсы дамығанын қалайтын қасиеттердің бірі, әрине, оның зердесі мен миының дамуы. Бұл дамуды қолдаудың өте тиімді тәсілдерінің бірі — оған кітап оқу. Осы кезеңде бөпеңізді кітаптармен таныстырып, кітапқа қызықтыру оның мектеп жасына жеткенде оқу үлгеріміне, негізгі сөйлеу дағдыларына, тіл білімі мен ой қорыту қабілетіне негіз қалайды. Сондай-ақ мектеп жасына дейін кітапқа қызыққан балалардың оқу үлгерімі жоғары болатыны ғылыми тұрғыдан дәлелденген. Сіз бөпеңізге кітап оқығанда, ол сөйлеуге қажетті негізгі дыбыстарды Сізден үйреніп, сөйлеу дағдыларының негізін қалыптастырады. Бұған қоса, белсенді қарым-қатынас кезінде бөпеңіз араларыңыздағы жақын байланыстың арқасында дұрыс қарым-қатынас жасау тәсілдерін мектепке барудан әлдеқайда бұрын үйренеді. Кітаптардан дұрыс құрылған сөйлемдерді жүйелі әрі тұрақты естіген сайын, бөпеңіздің сөйлеу кезеңінде грамматикалық ережелерді меңгеруге бейімділігі де мектепке дейінгі жастан бастап дамиды. Сондықтан өзі оқуды бастамай тұрып, оған қазірден бастап кітап оқып беруіңіз өте маңызды.') WHERE id = '847c3222-1e8f-4ee7-af36-660c53f7b72c';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіз көз алдыңызда таңғаларлық жылдамдықпен өсіп келеді. Күн сайын жаңа дағдыларды үйреніп, оларды Сізге көрсетеді. 😊 Оның жаңа дағдыларды меңгеруіне, шығармашылығы мен миының дамуына қолдау көрсету үшін таңдайтын ойыншықтарыңыздың маңызы зор. Осы кезеңде айналасына қызығушылығы арта түскен бөпеңізге жаңа әрі өзгеше ойыншықтар алып беруді немесе бар ойыншықтармен ойнаудың басқа тәсілдерін ойластыруды қарастыра аласыз. Ойыншық таңдағанда оның жасына сай келетінін және тұлғалық қасиеттеріне қалай әсер ететінін ескеруіңіз керек. Ғылыми зерттеулер бөпелер ойнайтын ойыншықтардың олардың дамуында үлкен рөл атқаратынын көрсетеді. Мектепке дейінгі кезеңге дейін ойнаған әрбір ойыншығы оның қоршаған ортамен байланыс орнатуы мен тұлғалық дамуы үшін маңызды. Сондықтан ойыншық таңдағанда оның барлық сезім мүшелеріне әсер етуіне, қимыл-қозғалыс дағдыларын дамытуына, қиялын ұштауына және әлеуметтік дағдыларын қолдауына назар аударыңыз.') WHERE id = '86e946c1-ab86-4301-9ac4-7f795adc1bfa';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіздің сезім мүшелері жақсы дамыған және іске қосылуын күтіп тұрған миллиондаған ми жасушасы бар болғандықтан, ол туған сәтінен бастап барлық ақпаратты қабылдап, есте сақтай бастайды. Дүниеге келген кезде тірі қалуына көмектесетін бірнеше рефлексі ғана болған бөпеңіз қысқа уақыт ішінде еңбектеу, сөйлеу және жүру сияқты көптеген дағдыларды меңгереді. Зерттеулерге сәйкес, бөпенің осы ғажайып дағдыларды жылдам үйренуінің негізгі себептерінің бірі — күндізгі ұйқы. Күндіз ұйықтау бөпенің демалуына және жаңа нәрселерді үйренуіне мүмкіндік беріп қана қоймай, басынан өткергендерін жадында бекітуге көмектеседі. Ұйқы уақытының тұрақты болуы бөпенің жүру, сөйлеу сияқты маңызды дағдыларды уақтылы меңгеруіне ықпал етеді. Уақыт өте келе ұйқы ұзақтығы қысқарады, ал айналасын зерттей бастаған бөпеңіз кейде ұйықтағысы келмеуі мүмкін. Осы айларда бөпеңіз әдеттерді оңай қалыптастырады, сондықтан оның ұйқы тәртібін қазірден реттеуге кеңес береміз. 😊') WHERE id = '12adf52f-ce6e-45aa-88f8-a01f2005b356';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпенің шаш түбірлері ана құрсағында жатқанда-ақ, шамамен бірінші триместрде дами бастайды. Дүниеге келетін күнге дейін лануго деп аталатын түктер жылу жоғалтудан қорғау үшін бөпенің басында қалыңдай түседі. Бұл түктердің қалыңдығы мен өсу ұзақтығы генетикалық факторларға байланысты әртүрлі болуы мүмкін. Сондықтан бөпенің қалың немесе сирек шашпен, тіпті шашсыз туылуы — қалыпты жағдай. Шын мәнінде, бөпенің шашының аз не қалың болып туылуы денсаулыққа қатысты қандай да бір мәселенің белгісі емес. Әсіресе осы айларда бөпенің шашы қарқынды түсуі мүмкін. Тіпті басының артқы, желке тұсында шашы сиреп, тақырлануы да ықтимал. Бұған бөпенің үнемі бір қалыпта жатуы немесе туғаннан бастап 6-айға дейін тынығу кезеңіне өтетін шаш фолликулдары себеп болуы мүмкін. Бөпеңіздің шашын қиюға қимасаңыз да, мамандар уақыты келгенде оның қалың не сирек екеніне қарамастан, шашын қиюға кеңес береді.') WHERE id = '1a637264-ed95-4fa6-842a-a26e3ce3729a';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіздің миы ана құрсағында жатқан кезден бастап үздіксіз дамиды. Туғаннан кейін бұл үдеріс одан әрі жеделдей түседі. Мидың ең қарқынды даму кезеңі — 0-48 ай аралығы. Осы уақытта бөпеңізге қоршаған ортаны танып-білу үшін түрлі тәжірибе қажет, өйткені ол солар арқылы үйренеді. Мұндай тәжірибенің маңызды бөліктерінің бірі — бөпенің қызығушылығын оятып, дамуына көмектесетін ойыншықтар. Түрлі түсті, пішіні әртүрлі әрі қызықты ойыншықтар бөпенің миындағы нейрондарды белсендіріп, олардың арасында байланыс қалыптастырады және қоршаған ортаны түсінуіне көмектеседі. Күнделікті қолданатын заттардан айырмашылығы, ойыншықтар шығармашылық қабілетті арттырып, енді қалыптасып келе жатқан қиял әлемінің дамуына ықпал етеді. Бұл кезеңде бөпенің есту қабілеті көру қабілетіне қарағанда басымырақ болады. Сондықтан алғашқы 6 айда дыбыс шығаратын ойыншықтар бөпеңіз үшін пайдалырақ. Мысалы, жеңіл әрі әртүрлі дыбыс шығаратын ойыншықтарды, кереуеті мен ойын төсенішіне ілінетін музыкалық ойыншықтарды және қолына ұстай алатын сылдырмақтарды таңдауға болады.') WHERE id = '341dbb77-f89b-4786-ae5e-27fe6c263105';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Алғашқы 1-2 айда бөпеңіздің қолдары әдетте жұдырық болып түйіліп тұрса, қазір ашыла бастағанын байқадыңыз ба? 3-айда ол өз қолдарына қызығушылық таныта бастайды. Қолдарын жиі қимылдатып, оларға қарау және қозғалту сүйікті істерінің біріне айналады. Қолдарын зерттей отырып, бөпенің көру қабілеті де дамиды. Бұл кезеңді одан да қызықты ете аласыз! Білегіне тағылатын дыбысты ойыншықтар алып, оның зерттеу сапарына қолдау көрсете аласыз. Бірақ мұны міндетті түрде бақылауыңызбен жасау керек, өйткені кішкентай қолдар өте жылдам қимылдайды.') WHERE id = 'ad6180ec-951a-4399-9c9f-0798090c6244';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бұл кезеңде бөпеңіз туа біткен көптеген рефлекстерін әлі де қолдануы мүмкін. Ырықсыз қимылдар деп аталатын бұл рефлекстер бөпе өскен сайын жойылып, олардың орнын күрделірек қозғалыс дағдылары мен ерікті қимылдар басады. Бөпе үшін маңызды рефлекстер: ему және іздеу рефлексі, Моро рефлексі, тонустық мойын рефлексі, қадам басу рефлексі, қармау рефлексі, Бабинский рефлексі, бүгу рефлексі, жұтыну және лоқсу рефлекстері. Бұл рефлекстердің кейбірі осы кезеңде жойылса, басқалары бәсеңдей бастауы мүмкін. Мысалы, іздеу және ему рефлекстері бөпе дүниеге келген сәттен байқалады және тіршілік ету үшін қажет қоректену инстинктіне байланысты пайда болады. Дамудың шамамен 2-4 айлары аралығында, әсіресе күндіз, бұл рефлекстердің орнын ерікті әрекеттер баса бастайды. Яғни енді бөпенің бетінен сипағанда аузын ашпайтынын, ал тамағын жақындатқанда ғана аузын ашатынын байқауыңыз мүмкін.') WHERE id = 'f9a31ada-1c4c-4cc8-a19f-e08982dace02';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңізбен сапалы уақыт өткізу дегеніміз — уақыттың ұзақтығына емес, мазмұнының пайдасына мән беріп, онымен өзара әрекеттесу. Осы тұрғыдан алғанда, бөпеңізбен бір бөлмеде болсаңыз да, қандай да бір белсенділік пен көңіл бөлу болмаса, бұл сапалы уақыт болып саналмауы мүмкін. Бөпенің дамуы үшін сапалы уақыт өткізудің негізгі шарттарының бірі — туған сәтінен бастап онымен жайлы, қамқор әрі жұмсақ үнмен асықпай, анық сөйлесу және жасап жатқан әр әрекетіңізді түсіндіріп отыру. Бөпеңіз әлі сөйлеуге және айтқан сөздеріңізді түсінуге қажетті физикалық әрі ақыл-ой дамуына жетпесе де, осы кезеңде естіген әртүрлі сөздерді жадында сақтай бастайды. Онымен жиі сөйлесуіңіз және сөйлескенде түрлі сөздерді қолдануыңыз болашақта тілінің дамуы, сөйлеу қабілеті мен ақыл-ойының жетілуі үшін өте маңызды. Мысалы, бөпеңіздің жаялығын ауыстырған кезде үндемей қалмай, не істеп жатқаныңызды оған кезең-кезеңімен айтып отырыңыз. Бұл тәсілді күнделікті өміріңіздің әр сәтінде қолдану бөпеңіздің сөздік қорының молаюына көмектесіп, зияткерлік дамуын ынталандырады.') WHERE id = 'b5b55ba0-7239-4a48-97b0-39887b3f6198';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпенің ми жасушалары жаңа тәжірибе жинаған сайын дамиды. Сіз де бұл дамуды қолдау үшін бөпеңізге жиі жаңа тәжірибе ұсынуыңыз керек. Мысалы, онымен жаңа ойындар ойнау, іс-әрекеттеріңізге басқа ойыншықтар немесе қимылдар қосу ми жасушалары арасындағы байланыстардың қалыптасуын жеделдетеді. Тіпті қолындағы ойыншықтармен ойнаудың басқа тәсілін көрсету немесе оған әдетте көретін заттардан құрылымы өзгеше бұйымдарды таныстыру да дамуына айтарлықтай ықпал етуі мүмкін. Осындай әрекеттер кезінде бөпеңізге ұсынылған жаңа тәжірибелерді жиі қайталауға мүмкіндік беріңіз. Бөпеңіз қандай да бір әрекетті қайталаған сайын, жаңа тәжірибе оның жадында жақсырақ бекиді. Бөпеңіз белсенді үйрену кезеңіне көшкендіктен, оған әрдайым оң көзқараспен қарап, белгілі бір күн тәртібін қалыптастыруға тырысыңыз. Жалпы, бөпелердің бақытты сәттерді және сол сәттерді еске түсіретін кез келген белгіні жадында сақтауға бейім болатыны байқалған. Бөпеңіз Сіздің эмоциялық күйіңізді қатты сезінетіндіктен, онымен уақыт өткізгенде көңілді әрі бақытты болуыңыз оған да жағымды әсер етеді.') WHERE id = '6974552e-5545-418f-9e3a-c5909451e194';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Әр бөпе өзіне тән қарқынмен өсіп, даму кезеңдерінен әр уақытта өтеді. Сондықтан бөпеңіздің дамуын басқалармен салыстырудың еш мәні жоқ. Бөпеңіз сөйлеуге қатысатын мүшелерін әлі саналы түрде немесе физикалық тұрғыдан басқара алмаса да, уақытының көп бөлігін Сіздің даусыңызды тыңдаумен өткізеді. Сізді тыңдай отырып, ол тілге қатысты түрлі ақпаратты жадында сақтайды. Сондықтан сөйлеуіне әлі уақыт қажет болса да, әртүрлі қажеттілігін білдіру үшін жылау үнін өзгертіп, күліп немесе "уілдеп" жауап беруі мүмкін. Бөпеңіз өз сүйіспеншілігін білдіру және өзіне көрсетілген қамқорлыққа жауап беру үшін тамақтандыру немесе жөргегін ауыстыру кезінде аяқтарымен сермеп не дыбыс шығарып әрекет етуі мүмкін. Бұл ретте әр бөпенің өзіндік ерекшеліктері болады. Кейбір бөпелер мағыналы дыбыстар шығаруға үнемі талпынса, басқалары оған толық дайын болғанша күтуі мүмкін. Зерттеулерге сәйкес, бөпемен қарым-қатынас жасау тәсілі оның тілінің дамуына әсер етеді. Бөпеңіздің дамуына қолдау көрсету үшін онымен жиі сөйлесуге, ойын ойнауға, кітап оқуға және сөйлескенде қарапайым әрі түсінікті тілді қолдануға кеңес береміз. 😊') WHERE id = '51f1030e-fc36-4b12-b1d7-a64348ea081b';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бұл кезеңде бөпеңізбен бірге уақыт өткізуге әрі оның дамуына қолдау көрсетуге көмектесетін көптеген іс-әрекет бар. Мысалы, әртүрлі дыбыстарды естуі үшін қолайлы орта жасай аласыз. Дыбыс шығаратын ойыншықтарды немесе сылдырмақтарды бөпеңіздің оң және сол жағында сілкіп, дыбыс шыққан жаққа қарауға ынталандыра аласыз. Әсіресе көңіл күйі жақсы кезде, шомылдырғаннан немесе емізгеннен кейін оған әртүрлі жануарлардың дауысын тыңдатуға болады. Алдымен мысық пен ит сияқты таныс жануарлардың дауысын, содан кейін жылқы, ара, есек секілді басқа жануарлардың дауысын тыңдата аласыз. Ол үшін интернет пен танымдық кітаптарды пайдалануға болады. Тіпті бұл дыбыстарды өзіңіз де сала аласыз. Бөпеңіздің әртүрлі дыбыстарға қалай жауап беретінін бақылаңыз. Бірге өткізген осы уақыттың оған қаншалықты ұнайтынын көресіз. 😊') WHERE id = 'e2c4c53d-e6ae-41f3-83d4-6473c78c7fb7';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіз аударылуды бастап кеткен болуы мүмкін. Тіпті кейбір бөпелер бұдан да ерте аударыла бастайды. Алайда бөпеңіз әлі аударылмаса, алаңдаудың қажеті жоқ. Әр бөпе бірегей және олардың даму қарқыны да әртүрлі болуы мүмкін. Бөпеңіздің еркін аударылуы бас және мойын бұлшықеттерінің дамуына байланысты. Басы мен мойнын басқара алған кезде бөпеңіз отыру, еңбектеу және жүру сияқты қимыл-қозғалыс дағдыларының да негізін қалыптастырады. Аударылуға ынталандыру үшін оны жұмсақ жерге етпетінен жатқызып, жаттығуына мүмкіндік бере аласыз. Шала туған бөпелердің бұлшықет және жүйке жүйесі өзгеше жетілетіндіктен, басы мен мойнын басқаруды кешірек меңгеруі мүмкін. Егер бөпеңіз мерзімінен бұрын дүниеге келсе, оның аударылуды үйренуіне 9-шы айға дейін уақыт бар. Оның үстіне, кім біледі? Мүмкін, ол аударылу кезеңін өткізіп жіберіп, бірден отыра бастайтын шығар? 😊') WHERE id = '4f657a4a-e832-4fda-9834-e8fa08bd9d44';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіздің аузынан сілекей ағуы, кез келген нәрсені аузына салуға тырысуы... Мұның себебін Сіз де білетін шығарсыз. Осы айдан бастап бөпеңіздің тіс жару кезеңі басталады. Күлген кезде күлкісіне көрік қосатын тістерін көру, әрине, өте сүйкімді. Алайда тіс жару кезеңі бөпелердің көпшілігі үшін ауыр өтеді. Бұл бөпеңіздің мазасыздануына, қызыл иегінің ісінуі салдарынан ауырсынуына себеп болуы мүмкін. Тіс жарудың ең белгілі белгісі, әрине, сілекейдің көп бөлінуі. Сондай-ақ қолына түскеннің бәрін тістеуге тырысуы, дене қызуының сәл көтерілуі, емшектен немесе тамақтан бас тартуы да осы кезеңнің белгілеріне жатады. Бұл белгілер бірнеше ай бұрын байқалуы мүмкін немесе тұқым қуалаушылыққа байланысты ешбір белгісіз-ақ осы айда тістері көрінуі ықтимал. Тіс жару кезінде бөпеңіздің дене қызуының 37 градусқа дейін көтерілуін дәрігерлер қалыпты деп санайды және араласуды қажет етпейді. Алайда бөпеңіздің дене қызуы 38 градусқа немесе одан жоғары көтерілсе, бұл тіс жарудың белгісі емес, сондықтан дәрігеріңізбен кеңесу қажет.') WHERE id = 'fd702e8d-6a0f-4f31-a1a0-b330e1d04288';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіздің шашын үйде қиюды шешсеңіз, ескеру қажет бірнеше жайт бар. Ең алдымен, шашын қиюға кіріспес бұрын бөпеңіздің қарны тоқ екеніне және іш кебуі сияқты ешқандай жайсыздық сезінбейтініне көз жеткізіңіз. Өйткені өзін жайсыз сезінген бөпе мазасызданып, кенет қимылдауы мүмкін, ал бұл қауіпті жарақатқа немесе шашының дұрыс қиылмауына әкелуі ықтимал. Егер бөпеңіз отыра алса, оны тамақтандыру орындығы сияқты ыңғайлы жерге отырғызып немесе құшағыңызда демеп, қозғалтпай ұстай аласыз. Шашын қию үшін ұшы өткір емес кішкентай қайшыны қолдану керек. Сондай-ақ көңілін бөлу үшін сүйікті ойыншығын беру және шашын қию кезінде онымен үнемі сөйлесу оның тыныш отыруына көмектеседі. Шашын қиғанда құлақ, мойын және маңдай тұстарында аса сақ болыңыз. Қажет болса, көмекшіңізден бөпеңіздің басын қозғалтпай ұстап тұруын сұрай аласыз. Жұмыс аяқталмайынша, бөпеңізді қайшымен жалғыз қалдырып, қасынан кетпеңіз. Сондықтан бастамас бұрын сүлгі, тарақ сияқты қажетті заттардың бәрін алдын ала дайындап қойыңыз.') WHERE id = '4c05c1b9-816f-4b3a-9570-73a5e8523f06';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңізді алғаш рет құшағыңызға алған күнді кеше ғана болғандай есіңізде сақтап жүрген шығарсыз. Уақыт неткен жылдам өтеді, солай емес пе? 😊 4-ші айға толған бөпеңіз өсіп келе жатқанын сездіре бастайды. Ол Сіздің үнемі көңіл бөлгеніңізді қалайды және ойнағанды жақсы көретінін әр мүмкіндікте байқатады. Етпетінен жатқанда қолдары мен шынтақтарына сүйеніп көтеріліп, кеудесіне дейін бойын тіктей алады және басын 90 градусқа көтере алады. Қатты дауыстап күлуі және назар аударту үшін айқайлауы да осы кезеңде едәуір жиілейді. Тіпті бөпеңіздің отыруға барынша талпынып жүргенін байқауыңыз мүмкін. Кейбір мамандар бөпені 6-шы айға дейін отырғызуды құптамаса, басқа дәрігерлер әр бөпенің дамуы әртүрлі екенін айтады. Сондықтан бөпеңізді бақылап, оның не қалайтынын түсінуге тырысу өте маңызды. Отыруға талпынып жүрген бөпені сүйемелдеп, өте қысқа уақытқа отырғызу оны қатты қуанта алады. Дегенмен әр бөпе өзінше дамитындықтан, бұл мәселе бойынша дәрігеріңіздің пікірін алған дұрыс. 😊') WHERE id = '2ec8f436-2faa-47d9-bf8d-3c7a85cda289';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Алдағы апталар Сізге де, бөпеңізге де біршама қиын болуы мүмкін. 14-19-апталарды қамтитын төртінші даму секірісі кезеңі — ең ұзаққа созылатын даму сатыларының бірі. Көптеген бөпелер осы өсу кезеңінің алдында емшек емуден немесе қоспадан бас тартуы мүмкін. Ұйқы тәртібі енді реттелді дегенде, бөпеңіз ұйықтауға қарсылық көрсете бастауы ықтимал. Сондай-ақ үнемі қолда болғысы келіп, мазасызданатын бөпеңіз Сізді біраз шаршатуы мүмкін. Алайда бұл қиын кезең аяқталған соң, бөпеңіздің өмірінде мүлде жаңа кезең басталады. Ол енді оқиғалардың реттілігін түсіне бастайды. Мысалы, бөпеңіз бір затты көргенде, ол назарын аударып, бөпеңіз оны мықтап ұстап, зерттегісі келуі мүмкін. Біраз уақыт қолында ұстағаннан кейін, затты жақынырақ танып-білу үшін аузына салуы ықтимал. Осы өсу секірісінің соңында бөпеңіздің айнаға қарағанда өзін танып, өзіне жымиғанын байқауыңыз мүмкін. Тойғанын түсіне бастаған бөпеңіз жеткілікті мөлшерде сүт ішкеннен кейін емуді тоқтатуы мүмкін, бұл құсу мәселесін барынша азайтуға көмектеседі.') WHERE id = '57457675-a7c5-476e-b444-66d0b8d0364f';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, '4-айдағы дәрігер тексеруінде бөпеңіздің дамуын бағалау үшін оның бойы, салмағы, басының өлшемі, көру қабілеті, арқа және мойын бұлшықеттері тексеріледі. Бұл кезеңде бөпеңіздің салмағы 4800-9100 грамм, ал бойы 58-69 см аралығында болуы керек. Көрсеткіштердің төменгі немесе жоғарғы шегіне жақын болуы бөпеңізде қандай да бір даму мәселесі бар дегенді білдірмейді. Бұл кезеңде бас шеңбері 39-45 см аралығында болады. Бас шеңбері мидың сау дамуының көрсеткіші болғандықтан, оның осы аралықта болуы өте маңызды. Көру қабілеті толық қалыптасқандықтан, бөпеңіз енді заттардың шынайы түстерін көре алады. Бұл қоршаған ортаны одан әрі қызықты ете түседі; бөпеңіз ұйықтауға және емуге жұмсайтын уақытын азайтып, айналасына көбірек қызығуы мүмкін. Сонымен қатар 4-ай ұзақ өсу секірісін қамтитындықтан, осы дамудың аясында ұйқы регрессиясы байқалуы мүмкін. Сондықтан бөпеңізге бұрынғыдан да көбірек көңіл бөлуіңізге тура келуі ықтимал. Бірге өткізетін уақыттан ләззат алуға тырысыңыз. Уақыттарыңыз көңілді өтсін! 😊') WHERE id = '3e04c60c-ae8b-4665-9ca2-95ef5bdb8192';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіздің 4-айдағы тексеруінде салынуы тиіс екпелер — 2-айда салынған туберкулезге қарсы екпеден басқа екі екпенің екінші дозалары. Олар — пневмококкқа (менингитке) қарсы екпе және дифтерия, көкжөтел, сіреспе, Hib инфекциясы мен полиомиелитке қарсы бес компонентті құрама екпе. Егер бөпеңізге ротавирусқа қарсы екпенің алғашқы дозасы 2-айында салынса, екінші дозасы осы айда салынуы керек. 4-айдағы екпелерден кейін бөпеңіздің қызуы көтеріліп, мазасызданса, дәрігер ұсынған қызу түсіретін дәріні бере аласыз. Әр бөпеде әртүрлі болғанымен, әдетте екпеден кейін 2-4 сағаттан соң дене қызуы көтерілуі мүмкін. Қызу кейде 2-3 күнге дейін созылуы ықтимал. Сондай-ақ барлық екпеден кейін ине салынған жердің ауыруы, ісінуі және қызаруы байқалуы мүмкін. Бөпеңіздің мазасыздығы мен жайсыздығын азайту үшін ине салынған жерге салқын компресс басып, дәрігердің кеңесімен құрамында парацетамол бар дәрілерді ауырсынуды басатын құрал ретінде қолдана аласыз.') WHERE id = 'ecec54a9-6b16-4860-9c1c-01c24cd2eac2';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіз қазір белсенді үйрену кезеңінде, сондықтан оның барлық жаңа тәжірибеге қызығушылықпен жауап беретінін байқауыңыз мүмкін. Осы даму сатыларының бірі — сөйлеу дағдысының негізі қаланатын кезең. Ол Сіздің даусыңызға жауап беріп, естіген дыбыстарына еліктегенді ұнатады. Әсіресе қуанған кезде жіңішке дауыспен шыңғырып, қатты күліп, «а-гу» деген дыбыстар шығаруы мүмкін. Бөпеңіздің сөйлеу қабілетін дамыту үшін онымен жиі сөйлесуге кеңес береміз. 😊 Төрт айлық бөпеңіз айналасындағы нәрселерге қатты қызығатындықтан, оның назары жиі басқа жаққа ауып кетуі мүмкін. Мысалы, тамақтану кезінде басқа бір нәрсе назарын аударса, ол емуін тоқтата тұруы ықтимал. Кейде ұйықтағысы келмеуінің себебі де осы болуы мүмкін. Сабырлы болыңыз, өйткені ол үшін әлем өте үлкен әрі зерттейтін дүние көп! 😊') WHERE id = '0479afbe-b14f-457d-b226-70e3d4f9bf7b';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Осы күндері бөпеңіз етпетінен жатқан кезде бір қырына, тіпті шалқасынан аударылып, Сізді таңғалдыруы мүмкін. Арқа және мойын бұлшықеттерінің дамуы арқасында оның аударылуға талпынысы көбіне сәтті болады. Тіпті осы айдан бастап бөпеңіз отыруға әрекеттенуі мүмкін. Кейбір дәрігерлер бөпені 6 айға дейін отырғызбауға кеңес бергенімен, әр баланың дамуы әртүрлі екенін ұмытпау керек. Бөпеңіздің миы мен денесі дайын болғанда, яғни бұлшықеттері жеткілікті дамып, тепе-теңдігін басқара алғанда, ол өзі отыру қалпына келе бастайды. Егер бөпеңіз денесін көтеріп, отыруға тырысса, тым ұзақ отырмауы шартымен оған мүмкіндік бере аласыз. Қолынан келгенін көру оны қуантып, ынталандырады. Дегенмен арқасын сүйеп қоюды ұмытпаңыз. Кейбір бөпелер осы айда отыра бастағанымен, олардың арқа бұлшықеттері әлі де тіреусіз отыратындай күшті емес екенін есте ұстаған жөн.') WHERE id = '3e15f79b-7870-4c1b-9ff8-0d7695190d48';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіздің салмағы туған кездегі салмағынан орта есеппен екі есе артты. Егер оны емізіп жүрсеңіз, кейде сүтіңіз жеткіліксіз деп ойлауыңыз мүмкін. 4 және 5-айлар бөпеңіздің денесі қарқынды дамитын кезең болғандықтан, оның энергияға қажеттілігі артады. Осы өскен қажеттілікті өтеу үшін қосымша тағам бере бастауды ойлауыңыз мүмкін. Алайда бұл кезеңде бөпеңіздің ішек микрофлорасы қатты тағамды қорытуға әлі дайын емес екенін ұмытпаңыз. Қосымша тағам бөпені қатты тағамға үйрету мақсатында өте аз мөлшерде беріледі және ішектің дұрыс дамуы үшін оны 6-айдан кейін бастаған жөн. Дүниежүзілік денсаулық сақтау ұйымы (ДДСҰ) алғашқы 6 ай толғанға дейін бөпеге тек ана сүтін, ал ана сүті болмаса, жалғыз балама ретінде сүт қоспасын беруді ұсынады. Кез келген қосымша тағамды 6 айға дейін бастау бөпеңізде қаназдық, ас қорыту бұзылысы, іштің кебуі мен түйілуі, асқазан және ішек мәселелерін туындатуы мүмкін. Сондықтан қосымша тағамды бастауға асықпаңыз, Anacan.') WHERE id = '63dc3b2b-9b88-4480-8d80-226d9607b848';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіз осы күндері алғаш рет аунауы мүмкін. Әдетте бөпелер мұны шамамен 4 айлығында етпетінен жатып, бір жағына қарай аунау арқылы жасайды. Бөпелердің барлығы дерлік мұны істей алатынын түсінген сәтте қайта-қайта қайталағысы келеді, осылайша тоқтаусыз аунау басталады. Дегенмен кейбір бөпелер аунағаннан кейін қорқып, біраз уақыт қайтадан әрекет жасауға жүрексінуі мүмкін. Бөпенің дөңгелек әрі иілгіш қарны бұл қимылды оңай жасауына едәуір көмектеседі. Аунауын ынталандырып, арқа бұлшықеттерін нығайту үшін бөпеңізді созылу қимылдарына қызықтыра аласыз. Мысалы, ойыншыққа немесе басқа бір затқа қол жеткізуге талпынуы оның аунауына мүмкіндік береді. Алайда аунаған кезде етпетінен жатып, дем ала алмайтын қалыпта қалмауын немесе құлап кетуі мүмкін жерде болмауын мұқият қадағалаңыз және мұндай жаттығулар кезінде оны жалғыз қалдырмаңыз.') WHERE id = '74e1e965-f81e-44cc-a407-7883c6451cc2';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Алғашқы айлармен салыстырғанда бөпеңіз азырақ тамақтанып жүргендей көрінуі мүмкін. Бұл алаңдатқанымен, шын мәнінде табиғи үдеріс. Оның негізгі себебі — бөпеңіздің енді ему тәсілін жақсы меңгеруі. Енді ол қысқа уақыт ішінде көбірек сүт еме алады. Яғни қарны тезірек тояды. Сондықтан бөпеңіздің күн ішіндегі емізу саны 4-5 ретке дейін азаюы мүмкін. Сондай-ақ осы айдағы өсу секірісі оның тамақтануында қысқа мерзімді болса да кейбір өзгерістер туғызуы ықтимал. Енді бөпеңіздің қимыл-қозғалысын бақылап, қарны ашқанын оңай түсіне алатындықтан, тамақтану уақытын соған сай реттей аласыз. Мысалы, 4-айдан бастап бөпеңізді емізу үшін ұйқысынан оятудың қажеті жоқ. Сонымен қатар келесі емізуге дейін шамамен 4 сағат үзіліс жасау бөпеңіздің ана сүтінің құрамындағы қоректік заттарды жақсырақ алуына мүмкіндік береді.') WHERE id = 'ea6d6e3a-c957-436f-ac9c-f0c52e449526';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіз Сізді, жүзіңізді, бет әлпетіңізді, қысқасы, онымен қарым-қатынас жасаған әрбір сәтіңізді бақылауын жалғастырады. Үнемі бақылап, қадағалауы оның қоршаған әлемді танып-білуін байытып, жан-жақты дамытуға көмектеседі. Бөпеңіздің әрбір жаңа жаңалығы миындағы жүйке жасушалары арасында байланыс орнатуға ықпал етеді, соның нәтижесінде ол ақпаратты әлдеқайда жылдам қабылдап, үйрене бастайды. Мұндай байланыстардың қалыптасуы үшін қолына берген сылдырмақтың дыбыс шығаруы, ойыншықтарының пішінін зерттеуі, тіпті Сізді көзімен қадағалауының өзі жеткілікті. Бөпеңіз бет қимылыңызды, дауыс ырғағыңызды, тіпті іс-әрекетіңізді де мұқият бақылауға тырысады. Бұл оның Сізді бұрынғыдан да жақсы түсіне бастағанын білдіреді. Сондықтан оған бөлген назарыңыздың нәтижесін осы айлардан бастап-ақ байқай аласыз. Бір-біріңізбен қарым-қатынас жасап, оған көңіл бөлген әрбір сәт араларыңыздағы байланысты одан әрі нығайтады.') WHERE id = '170aa164-55dd-45ac-8848-491ec6187f44';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіздің мұрны суық тию, жыл мезгілінің ауысуы, тұмау немесе аллергия салдарынан жиі бітелуі мүмкін. Мұрынның бітелуі оның тыныс алуын қиындатып қана қоймай, тамақтануы мен ұйқы тәртібіне де кері әсер етуі ықтимал. Тіпті емшектен бас тартудың ең жиі кездесетін себептерінің бірі — дәл осы мұрынның бітелуі. Өйткені бөпе тыныс алу үшін аузын ашуға мәжбүр болады және, әрине, емгісі келмейді. Бөпеңізге айтарлықтай жайсыздық тудыратын бұл жағдайды жеңілдету үшін дәрігер ұсынған балаларға арналған мұрын спрейлерін, физиологиялық ерітіндіні және бөлме ылғалдандырғышын пайдалана аласыз. Тұзды су деп те аталатын, құрамында химиялық қоспалары жоқ физиологиялық ерітінділер (изотониялық натрий хлориді) бөпеңіздің мұрнын қысқа уақытта ашуға көмектеседі. Әсіресе алғаш рет ана атансаңыз, оны қолдану Сізге қиын көрінуі мүмкін. Егер физиологиялық ерітінді жеткіліксіз болса, бөпелерге арнайы жасалған мұрын аспираторларын да пайдалануға болады.') WHERE id = '9c8572cd-a48b-4b37-a542-edfc74817a74';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіздің физикалық дамуына және еңбектеу кезеңіне дайындалуына көмектесетін, мамандар ұсынған бір жаттығу бар. Tummy time (етпетінен жату уақыты) деп аталатын бұл жаттығуды бөпеңізді етпетінен жатқызу арқылы жасай аласыз. Ол бөпенің әдетте сирек қолданылатын арқа бұлшықеттерін дамытып, сонымен қатар аяқ, мойын, иық және іш бұлшықеттерін нығайтады. Қимыл-қозғалыс дағдыларын дамытатын бұл жаттығулар бөпенің басында пайда болуы мүмкін пішін өзгерістерінің (жалпақ бас синдромының) алдын алуға да көмектеседі. Осы кезде айналасына ойыншықтар қойып, бөпеңіздің миында жан-жақты байланыстардың қалыптасуына ықпал ете аласыз. Бөпеңіз етпетінен жатудан тез жалығуы немесе назары басқа жаққа ауып кетуі мүмкін, сондықтан жанында болып, қызығушылығын әртүрлі бағытқа аударыңыз. Онымен сөйлесу, тақпақ айту, сүйікті ойыншықтарын көрсету және тыныштандыратын музыка қосу бұл үдерісті едәуір жеңілдетеді. Көңілді уақыт өткізіңіздер! 😊') WHERE id = '3d1db687-2705-4040-8e81-a914b3ab0052';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіздің миындағы миллиардтаған жүйке жасушасының арқасында оның білім мен дағдыларды ең белсенді меңгеретін кезеңі туғаннан бастап 48 айға дейін созылады. Сондықтан осы аралықта бөпеңізбен сапалы әрі жоспарлы түрде қарым-қатынас жасауыңыз оның дамуына үлкен серпін береді. Зерттеулерге сәйкес, сәби кезінде дұрыс дамыған балалар мектеп жасында оқу үлгерімі жағынан жақсы көрсеткіштерге қол жеткізеді, ал бұл олардың өміріне айтарлықтай ықпал етеді. Туғаннан бастап бөпеңізбен өткізген уақытыңыз бен осы кезеңдегі сапалы өзара әрекеттесу оның миы мен эмоциялық дамуына көптеген оң әсер береді. Бөпеңізге көңіл бөліп, бірге сапалы уақыт өткізуіңіз оның орталық жүйке жүйесінің дамуын қолдайды. Бұл оның өзіндік «мен» сезімін нығайтып, басқа адамдармен сенімді байланыс орнатуына көмектеседі, өзіне деген сенімін арттырып, өзін бағалы сезінуіне мүмкіндік береді. Ендеше, жұмыстарыңызды сәл кейінге қалдырып, бөпеңізбен уақыт өткізуге қалай қарайсыз? 😊') WHERE id = '4e220ec0-af8b-4430-ab5f-7ff3954ffb65';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіздің сілекей бездері белсендірек жұмыс істей бастағандықтан, аузына сілекей жиналып, оны әлі басқара алмауына байланысты сілекейінің ағуы — қалыпты жағдай. Бұл белгілер тіс жару кезеңінің жақындағанын да білдіруі мүмкін; қызыл иегі қышыған бөпеңіз қолын аузына жиі апаруы ықтимал. Мамандар бұған кедергі жасамай, керісінше, бөпеге өз қолдарын зерттеуге мүмкіндік беруге кеңес береді. Алайда қолына түскеннің бәрін аузына салуға тырысатын бөпе ұсақ заттарды жұтып қоюы мүмкін екенін ұмытпаған жөн. Әсіресе оңай сынатын және бөлшектеніп кететін ойыншықтардан аулақ болып, ол ойнайтын әр заттың таза әрі зарарсыздандырылғанына көз жеткізуіңіз керек. Қызыл иегі қышығандықтан бәрін кеміргісі келетін бөпеңіз Сіз байқамай қалған сәтте қауіпті заттарды аузына салуы мүмкін. Тұншығу қаупінің алдын алу үшін ойыншықтарды мұқият таңдап, қауіпсіздік шараларын күшейтуіңіз қажет.') WHERE id = 'ff292524-4cb1-4b4f-9235-43064f330adc';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіз енді бір қырынан екінші қырына аунай алады, өз орнында айнала алады, жатқанда басын 45 градусқа дейін көтеріп, басы мен денесін оңға-солға қозғалта алады. Бұл қимылдар — дамудың қалыпты барысының бір бөлігі. Тіпті оны етпетінен жатқызғанда, алға қарай еңбектеуге ұқсас қимыл жасағанын байқауыңыз мүмкін. Барлық бала секілді бөпеңіз де жаңа дағдыларды үйренуге және үйренгенін қайта-қайта қайталауға өте ынталы. Алайда әр бөпенің дамуы өзінше жүретінін ұмытпаңыз; егер бөпеңіз осы дағдылардың кейбірін әлі меңгермесе, алаңдамаңыз. Сондай-ақ оның дамуына дұрыс қолдау көрсету үшін кейбір жайттарға назар аударуыңыз керек. Соның бірі — жүріс арбасын (ходунок) пайдалану. Үнемі қозғалып, айналасын зерттегісі келетін бөпеңіз кейде Сізді шаршатса да, шешімді жүріс арбасынан іздемеген жөн. 6 айға толмаған және әлі отыруға дайын емес бөпені бұған мәжбүрлеу немесе жүріс арбасына отырғызу болашақта еңбектеу және бауырлап жылжу секілді маңызды дағдыларға қажетті бұлшықеттердің дамуына кедергі келтіруі мүмкін.') WHERE id = 'ea44cd71-5051-4dfc-bbf3-dac92612f0a6';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Сізді жиі ойландыратын мәселелердің бірі — бөпеңізді түнгі ұйқыға қалай киіндіру керектігі болар. Бөпеңіз қазір белсенді қимылдайтындықтан, үстіне жапқан көрпені жиі ашып тастауы мүмкін. Бөпелердің барлығы дерлік шамадан тыс ыстықты ұнатпайды және ыстықта мазасызданады. Бөпеңіз ұйықтайтын бөлмедегі температураны 22-24 градус, ал ылғалдылықты 40-60% аралығында ұстаған дұрыс. Оны түнгі ұйқыға дайындағанда мақтадан тігілген ұйықтайтын қап кигізіп, маусымға қарай ішінен жұқа мақта пижама кигізуге болады. Киімі жеткілікті ме, жоқ па екенін білу үшін дене температурасын қолтығынан өлшей аласыз. Егер температурасы 36.2 мен 37.2 градус аралығында болса, бөпеңіз тоңып жатқан жоқ. Температурасы бұдан төмен болса, бұл оның тоңғанын білдіреді, мұндай жағдайда үстіне тағы бір қабат киім кигізуге болады.') WHERE id = '3719fbec-0855-4e9e-bd59-1324c629c2ce';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіз енді таныс адамдарды ажырата алады және айналасындағыларға қызығушылық танытады. Әсіресе өзі танитын адамдарға күлімсіреп жауап берсе, таңғалмаңыз. 😊 4-ші айда бөпеңіз көптеген жаңа дағдыларды меңгереді. Бұл дағдылар оның физикалық әрі ақыл-ой дамуын қамтиды. Қол мен көз үйлесімі айтарлықтай жақсарған бөпеңіз енді қарым-қатынастан бұрынғыдан да көбірек ләззат алады. Қолдарына бірнеше минут бойы таңырқап қарауы, Сіздің шашыңызды тартуы және қолына түскеннің бәрін аузына салуы да осыған байланысты. Сіздің көмегіңізбен заттарға қол созып, ұстаған ойыншықтарын қармай алатын бөпеңізбен көптеген қарапайым ойын ойнауға болады. Сонымен қатар ай сайынғы дамуына сай әзірленген белсенділік ойыншықтарын пайдалану оның физикалық және ақыл-ой дамуына қолдау көрсетеді. Ойыншық таңдағанда, себеп-салдар байланысын түсінуге көмектесетін түрлеріне басымдық беруді ұсынамыз.') WHERE id = 'aeb00407-e412-4f78-961f-30f7b120bf0d';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіз үшін сыртқы әлем — шеті мен шегі жоқ зерттеу кеңістігі, сондықтан бұған түсіністікпен қарайтын кез әлдеқашан келді. Үнемі қолда болғысы келуі, ұйықтаудан немесе емуден бас тартуы, бір орында отырмауы және жиі ойнағысы келуі — қалыпты жағдай. Сонымен қатар дене жаттығуларын жасау және қимылдау бөпеңіздің физиологиялық дамуы үшін өте маңызды. Бөпеңізге жаттығу жасату үшін оны тобықтарынан ұстап, аяқтарын ақырын бүгіп, жоғары-төмен қозғалта аласыз. Сондай-ақ екі қолынан ұстап, кеудесінің тұсында біріктіріп, айқастыра ашып-жұмуға болады. Осы қимылдар кезінде бөпеңіз өзін жайлы сезінуі үшін онымен сөйлесіп, жиі күлімсіреуді ұмытпаңыз. Бірге өткізген бұл сәттер бөпеңіз үшін әлеуметтенудің ең пайдалы тәсілдерінің бірі болады.') WHERE id = '77bdf252-33eb-455c-b59d-8af7012e078c';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Мерзімінде туған көптеген бөпе үш айлық кезінде-ақ қатты тағамға дайын болуы мүмкін. Алайда қатты тағамға көшуді қиындататын «тілмен итеру» рефлексі әдетте төртінші айдан бастап бәсеңдей бастайды. Негізінде ему қызметінде маңызды рөл атқаратын бұл рефлекс бөпеңіздің Сіз берген тағамды тілімен итеріп шығаруына себеп болады. Осы айдан бастап бөпеңіздің ас қорыту жүйесі кейбір тағамдарды қорыта алады. Алайда бұл — дамудың біртіндеп жүретін кезеңі және бөпеңіздің қатты тағамға толық дайын екенін білдірмейді. Бұл мәселеге қатысты ДДСҰ ұсынысы мынадай: егер бөпе салмақ жоғалтпай, дені сау болып өсіп жатса, 6-шы айға дейін тек ана сүтімен емізуді жалғастыру қажет. Егер 6-шы айға дейін ана сүті аз болып, бөпе айына 500 грамнан аз салмақ қосса, кейінгі кезеңге арналған сүт қоспалары тамақтану рационында негізгі орын алуы керектігін ұмытпаңыз. 6 ай толғаннан кейін де негізгі қорек ана сүті болып қалуы керек. ДДСҰ 9 айлық бөпе рационының 70%-ін ана сүті құрауын ұсынады.') WHERE id = '8360a204-f867-4fb6-bb2c-9a237526ca1c';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Егер қызыңыз болса, оның құлағын қай кезде тескен дұрыс деген сұрақ туындауы мүмкін. Бөпелердің құлағын тесуге арналған нақты ай аралығы жоқ. Бұл көбіне жеке таңдауға байланысты болғанымен, дәрігеріңізбен кеңесе аласыз. Бөпелердің шеміршегі әлі өте жұмсақ болғандықтан, осы айларда сырға тағу азырақ ауыртады. Алайда әлемге танымал кейбір педиатриялық ұйымдар екпе күнтізбесінің әлі аяқталмауына және күтім жасаудың қиындығына байланысты осы айларда құлақ тесуді ұсынбайды. Дегенмен құлақ тесу процедурасы дұрыс жасалып, одан кейінгі күтім талапқа сай жүргізілсе, бөпеңізде қандай да бір денсаулық мәселесінің туындау ықтималдығы өте төмен. Егер бөпеңіздің құлағын тесуге шешім қабылдасаңыз, қабынудың алдын алу үшін тағылатын сырғаның тот баспайтын болаттан немесе мүмкіндігінше алтыннан жасалғанына назар аударуды ұсынамыз.') WHERE id = '622d780e-3a5e-48fd-b009-10a81d465be2';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіздің үнемі емгісі келуі, әсіресе жаңа туған кезеңде жиі кездескенімен, мұндай жағдайдың кез келген уақытта болуы мүмкін екенін ұмытпаңыз. Мамандардың пікірінше, 2 жасқа дейін жалғастыру ұсынылатын емізу үдерісі Сіз бен бөпеңіздің арасында ерекше байланыс қалыптастырады. Сондықтан бөпеңіз Сізге жақын болуға деген табиғи қажеттілігіне байланысты жиі емгісі келуі, емген күйі ұйықтап қалуды қалауы және күні бойы емшектен ажырағысы келмеуі мүмкін. 4-ші айдан бастап газ мәселесі азайғанымен, кейбір бөпелерде ол 6-шы айға дейін жалғасуы мүмкін. Бөпеңіздің іші газдан түйіліп ауырғанда, өзін қауіпсіз сезіну үшін Сізге ең жақын жерде — құшағыңызда жатып, емшек еміп тынышталғысы келуі мүмкін. Сондай-ақ бөпеңіздің қимыл-қозғалысы артқан сайын энергияға деген қажеттілігінің өсуі де емуге деген ықыласын күшейтеді. Күні бойы жиі емізу кезіндегі дене жанасуы бөпеңіздің Сізге деген бауыр басуын арттырады. Яғни бөпеңізде ешқандай мәселе болмаса да, оның үнемі емгісі келуі тері арқылы жанасуға көбірек мұқтаж екенін білдіруі мүмкін.') WHERE id = '15a9163c-c7da-40c2-a76c-38c778e04718';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Егер бөпеңіздің терісінде пішіні әртүрлі бөртпелер пайда болса, бұл аллергиялық экзема болуы мүмкін. Аллергия — негізінде зиянсыз затты бөпе ағзасының бөгде әрі қауіпті деп қабылдап, оған реакция беруі. Аллергия тудыратын фактор міндетті түрде тағам болмауы мүмкін екенін ұмытпаңыз. Үстел үстіндегі шаң, маусым ауысқанда пайда болатын тозаң, тіпті темекі түтіні де бөпеңізде аллергиялық реакция тудыруы мүмкін. Егер бөпеңізде бөртпе, қызару немесе нәжісінде қан нүктелері сияқты белгілерді байқасаңыз, дәрігеріңізбен кеңескен жөн. Өйткені көпшілік бөпе үшін пайдалы тағам не қауіпсіз зат аллергиясы бар бөпеге тиісті шара қолданылмаса, елеулі мәселелер туғызуы мүмкін. Аллергия әдетте иммундық жүйедегі кейбір бұзылыстарға байланысты пайда болады және тұқым қуалауы да мүмкін. Яғни Сізде бар аллергияның бөпеңізде де болу ықтималдығы бар.') WHERE id = 'e82d9ae2-ed27-40cb-9366-8cbbd0962327';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіздің дені сау болып өсіп, дұрыс дамуы үшін оның тамақтануы өте маңызды. Алайда кейде ол емшектен немесе сүт қоспасынан бас тартуы мүмкін. Әсіресе емізетін ана болсаңыз, бөпеңізді шыдамдылықпен әрі жиі емізуді ұсынамыз. Бас тартудың себептері арасында тіс жару, даму дағдарысы кезеңіне өту немесе мұрынның бітелуі секілді көптеген фактор болуы мүмкін. Алдағы айларда бөпеңіздің қажеттіліктеріне сай тамақтану тәртібіне өзгерістер енгізе аласыз, алайда қазіргі кезеңде нақты режим қалыптастыру үшін оны мәжбүрлемеуіңіз керек. Бөпеңіз тамақтан бас тартқан кезде бұл мәселенің біраз уақыттан соң шешіліп, бәрі қалпына келетінін білгеніңіз жөн. Мұндай жағдайда аш қалып қояды деп алаңдап, қатты тағамға ерте көшпеуге кеңес береміз. Бөпеңіз 180 күнге толғаннан кейін ғана қосымша тамақ бере бастағаныңызға көз жеткізіңіз және міндетті түрде оның белгілерін бақылап, дайын болуын күтіңіз. Сондықтан бүкіл үдеріс бойы бөпеңізге шыдамдылықпен қарап, оны түсініп, қажеттіліктеріне жауап беруіңіз керек.') WHERE id = '63e83115-0a58-4fb8-af8e-8058860fc7f2';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіз қазір өтіп жатқан 0-12 айлық кезең мидың сау дамуы үшін аса маңызды. Осы кезеңде оның қандай ортада өсуі, айналасындағы адамдармен, әсіресе Сізбен қалай қарым-қатынас жасауы миының қалыптасуына негіз қалайды. Осы тұрғыдан алғанда, бөпеге әсер ететін ынталандырушы факторлардың қаншалықты қолайлы әрі алуан түрлі болуы оның танымдық, эмоциялық, әлеуметтік және физикалық дамуына ықпал ете береді. Сіз бен бөпеңіздің арасындағы қарым-қатынасты оның сезім мүшелері ынталандырушы әсер ретінде қабылдайды. Мұндай әсерлер неғұрлым көп болса, бөпеңіз соғұрлым жақсы дамиды. Оның дамуы үшін мұндай ынталандыруларды жеткілікті ұсынып, онымен үнемі өзара әрекеттесіп отыруыңыз керек. Кейбір ғылыми зерттеулерге сәйкес, бөпелердің миын дамытатын ең маңызды фактор — адам дауысы. Ендеше бүгін баяу музыка қосып, бөпеңізге массаж жасаңыз және сол кезде оған күніңіздің қалай өткенін, қандай оқиғаларды бастан өткергеніңізді әрі оны қаншалықты жақсы көретініңізді айтып беріңіз. Уақыттарыңыз көңілді өтсін! 😊') WHERE id = 'b51f395b-32bc-4a20-bb23-ec95e7590add';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Нәрестелік және балалық шақта ең жиі кездесетін тері ауруларының бірі — атопиялық дерматит, яғни экзема. Бұл тері ауруын қоздыратын факторларға бактериялар, жуғыш заттар, маусымдық өзгерістер және әртүрлі аллергендер жатады. Бөпеңізде мұндай жағдайдың пайда болуына жол бермеу үшін кейбір сақтық шараларын қолдануыңыз керек. Терісі өте сезімтал болатын осы кезеңде оны жүннен тігілген киімдерден, шаң мен құмнан, сабыннан, құрамы таза емес косметикалық өнімдер мен жуғыш заттардан аулақ ұстаған жөн. Жаңа сатып алынған киімді жумай кигізу де осы тері мәселесін тудыруы мүмкін. Сондықтан бөпеңіздің сезімтал терісі үшін мақтадан тігілген киімдерді таңдаңыз және шомылдырған кезде тітіркендіруі мүмкін үйкелеу қимылдарын жасамаңыз. Нәрестелік шақта экзема түрінде байқалатын бұл тері ауруының алдын алу шаралары жасалмаса және пайда болған кезде емделмесе, болашақта тыныс алу жолдарының аллергиясына, демікпеге және қол экземасына ұласуы мүмкін.') WHERE id = '31c813fe-83a6-475d-b451-c6545ed0cadd';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Жасанды қоспаны бөпеңізді тамақтандырудың негізгі көзі ретінде де, ана сүті жеткіліксіз болған жағдайда дәрігердің кеңесімен қосымша тағам ретінде де бере аласыз. Алайда бөпеңізге жасанды қоспаны қандай да бір жолмен берсеңіз, ескеру қажет маңызды жайттар бар. Солардың ең бастысы – әрине, құрамы ана сүтіне барынша жақын қоспаны таңдау. Бұл ретте дәрігеріңіздің кеңесіне құлақ асып, қоспалардың құрамын мұқият зерттеуіңіз керек. Әсіресе бұрын естімеген немесе дәрігеріңіз ұсынбаған брендтердің өнімдерін пайдаланудан аулақ болып, қоспаны өндіруші компанияның этикалық қағидаларды сақтауына мән бергеніңіз жөн. Бұл кезеңде әртүрлі брендтердің қоспаларын әлі де байқап көре аласыз. Уақыт өте келе бөпеңіз сүйсініп ішетін әрі ішек мәселелерін тудырмайтын қоспаны міндетті түрде табасыз. Иммундық жүйенің дамуы мен ішек микрофлорасының саулығы үшін таңдаған қоспаңыздың құрамында лактобактериялар мен бифидобактериялар секілді пайдалы микроорганизмдері бар пробиотиктердің болуына назар аударыңыз. Сондай-ақ бөпеңізге беретін қоспаның құрамында май қышқылы болып саналатын LC-PUFA болса, ол цитокиндердің түзілуін арттырып, иммундық жүйенің реттелуіне ықпал етеді.') WHERE id = '20390cc9-8cbc-4417-abec-6230f65f2f2f';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіз үшін әрі өте көңілді, әрі оның дамуына аса маңызды бір әрекет бар: айнаға қарау! 😊 Әдетте үлкендер бөпені айнаға көрсетуден тартынғанымен, дәрігерлер мұны ерекше ұсынады. Бөпенің айнаға қарауы өз бейнесін көріп, өзін танып-білуіне көмектеседі және миының дамуына зор үлес қосады. Бұл әрекетті алғаш рет жасайтын уақытты дұрыс таңдағаныңыз жөн. Бөпе мазасыз немесе көңілсіз болса, айнадан қорқып қалуы мүмкін. Сондықтан оның көңіл күйі жақсы, қарны тоқ (бірақ тым тойып алмаған) кез осы ойынға өте қолайлы. Айна алдына тұрып, бөпеңізге көзін, қолын, аяғын, қолдарының бөліктерін және аузын көрсетіп, дене мүшелерімен таныстырыңыз. Таныстырғаннан кейін олардың әрқайсысына кезекпен қол тигізіп, әрекетті қайталаңыз. Бұл бөпеңіз үшін өте қызықты ойын болатынына сенімдіміз. Көңілді уақыт өткізіңіздер! 😊') WHERE id = 'b0d88192-6e24-4e64-b343-6477a77e7840';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңізді емізгенде оның аузын дұрыс пайдалана алмайтынын, емізу ұзаққа созылатынын, жиі үзіліс жасайтынын, мазасызданатынын және күтілгендей салмақ қоспай жүргенін байқадыңыз ба? Жауабыңыз «иә» болса, бөпеңіздің тіл жүгеншесі қысқа болуы мүмкін. Дәрігерге тексертуге кеңес береміз. Тіл жүгеншесінің қысқалығына байланысты бөпелер емген кезде емшекті аузымен толық қамти алмайды, жеткілікті қоректенбейді және соның салдарынан салмақ жоғалтуы мүмкін. Сондай-ақ сүтті немесе бөтелкеден ішкен қоспаны тілімен кері итере алмайтындықтан, тамақтануға қатысты кейбір бұзылыстар туындауы ықтимал. Тіл жүгеншесі – тілді ауыз қуысының түбіне жалғап тұратын тін қатпары. Тіл еркін қозғалуы үшін бұл тін тілден аздап ажырап тұруы қажет. Кейде, әсіресе тұқым қуалайтын ерекшелікке байланысты, мұндай ажырау болмай, тілдің қимылы шектеледі. Дәрігерлер мұны әрдайым тексере бермеуі мүмкін, әрі оны байқау да оңай емес. Дегенмен бөпеңіздің дәрігері диагнозды кеш қойса да, бұл емдеуге болатын жағдай.') WHERE id = '2904fd26-1eca-4d37-8e98-2e316a3eec9b';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіздің тісі шығатын уақыт жақындап қалды, ал кей жағдайда оған әлі бірнеше ай болуы мүмкін. Тіс жару кезеңінде бөпеңіздің қызыл иегі қатты қышып, сілекейі ағып, қолын үнемі аузына сала беруі және қолына түскеннің бәрін шайнағысы келуі мүмкін. Қышуды жеңілдету үшін тіс қышытқышты, ауырсынуға қарсы дәрігердің кеңесімен тіс гелін, ал аққан сілекей үшін алжапқышты қолдана аласыз. Сонымен қатар Сізге де, бөпеңізге де қиын тиетін бұл кезеңді үйдегі заттардың көмегімен жеңілдетуге болады. Қалай дейсіз бе? Үйдегі таза ауыз сүртетін майлықтарды пайдаланыңыз! Майлықты аздап сулап, салқындауы үшін тоңазытқышқа біраз уақытқа салып қойыңыз. Оның салқын әрі тығыз болуы бөпеңіздің ауырсынуын жақсы басуға көмектеседі. Майлықты бөпеңіздің қолына бергенде, оны міндетті түрде бақылауда ұстауға кеңес береміз.') WHERE id = '8cafc042-a915-4258-a3c2-d05a6d6f4956';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіз ана сүтімен немесе жасанды қоспамен қоректенсе де, оның ағзасына су қажет пе деген сұрақ ойыңызға келуі мүмкін. Жалпы қабылданған пікір бойынша, қосымша тағам енгізілгенге дейін бөпеге қосымша су қажет емес. Себебі алғашқы 6 айда негізгі қорегіне қоса су берілсе, бөпенің шөлдеу сезімі азаяды. Шөлдемеген бөпе ана сүтін немесе жасанды қоспаны аз ішеді, ал бұл энергия тапшылығы мен дамудың кешеуілдеуіне әкелуі мүмкін. Сондықтан бөпеңізге суды жүйелі түрде беруді қосымша тағам енгізе бастаған кезде қолға алған жөн. Жейтін тағамның мөлшері артып, қоюлығы көбейген сайын бөпе ағзасының сұйықтыққа деген қажеттілігі де жоғарылайды. Осы кезде сұйықтық қажеттілігін өтеудің ең пайдалы жолы – су беру. Берілетін судың мөлшері туралы дәрігеріңізбен кеңесуді ұмытпаңыз.') WHERE id = '8768c9bb-7bc9-40eb-8d2e-760fead026b4';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бірге өткізген қызыққа толы 5 ай... Уақыт неткен жылдам өтеді, солай емес пе? 😊 Күн сайын дамып, Сізді үнемі таңғалдыратын бөпеңіздің бесінші айы да ерекше әрі өте қызықты өтеді. Бұл кезеңде бөпеңіздің сезім мүшелері ересек адамдікіндей дерлік дамып үлгерген. Соның арқасында оның қарым-қатынас жасау және өзін білдіру қабілеті қарқынды дамиды. Яғни енді бөпеңіздің сезімдерін бұрынғыға қарағанда жеңілірек түсіне аласыз. 5-ші айдан бастап бөпеңіз қуанышын, нені ұнататынын немесе ұнатпайтынын, мазасыздығын, сүйіспеншілігін және назар аударуды қалайтынын Сізге анық көрсете бастайды. Мысалы, Сізді немесе (жасанды қоспамен қоректенсе) бөтелкесін көргенде тамақтанатын уақыт келгенін түсініп, толқуы және қуанышын айқайлап білдіруге тырысуы мүмкін. Сондай-ақ есте сақтау қабілеті мен сезімдерінің дамуы нәтижесінде ол енді бейтаныс адамдардан мазасызданып, оларға сақтықпен қарай бастауы мүмкін.') WHERE id = '12aa96ec-7101-441e-a8b6-16b0a453ee5a';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіз алғашқы 4 аймен салыстырғанда осы айда белсендірек қозғалатындықтан, салмақты азырақ қосуы қалыпты жағдай. Сондықтан алғашқы айлардағыдай айына 800-1200 грамм салмақ қосады деп күтпеуіңіз керек. 5-ші айдағы бөпе үшін 450-750 грамм қосу жеткілікті саналады және ерекше жағдайлардан басқа кезде қосымша қолдау қажет емес екенін көрсетеді. 5-ші айдан бастап бөпенің салмағы 5100-9000 грамм, ал бойы 58-70 см аралығында болуы мүмкін. Ұлдар мен қыздардың бойы мен салмағының өсуінде аздаған айырмашылықтар болатынын және әр бөпенің дамуы өзінше ерекше екенін ұмытпаңыз. Егер осы көрсеткіштерге қарап, бөпеңіздің салмағы немесе бойы жеткіліксіз не шамадан тыс деп ойласаңыз, дәрігеріңізбен кеңесуді ұсынамыз. Сондай-ақ бөпенің жүктіліктің нешінші аптасында дүниеге келгені, туған кездегі бойы мен салмағы да бұл көрсеткіштерге әсер етуі мүмкін екенін естен шығармаңыз.') WHERE id = '57b48e89-533e-4812-870a-767029538ffe';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіз енді назарын аударған және көру аймағындағы заттарды алу үшін көбірек әрекет етеді. Яғни қызықтырған затты көргенде толқып, күлуі, оған қарай созылуға тырысуы немесе алақанын соғуы мүмкін. Көру және қабылдау қабілеті айтарлықтай дамығандықтан, әртүрлі түстер мен пішіндерді көруі ойында байланыстар құруына және оларды түсінуіне көмектеседі. Сонымен қатар осы айда бөпеңіздің қарым-қатынасқа көбірек ұмтылатынын байқайсыз. Алдыңғы айларда оның қарқылдап күлгенін естімеген болсаңыз, осы айда есту ықтималдығы өте жоғары. Қарым-қатынасқа бейімделе бастаған бөпеңіз қытықтағанда күліп, шыңғыруы мүмкін. Қуанған сәттерінде өздігінен былдырлап, көңілді дыбыстар шығаруы ықтимал. Бөпені күлдірудің тағы бір жолы — оның жымиғанына күлімсіреп жауап беру. Бұл айда бөпелер бір-біріне қарап күлгенді өте жақсы көреді. Бөтелкесін еміп жатқанда, Сіз басқа біреумен сөйлескенде, ән қосқанда немесе қандай да бір дыбысты естігенде, бұл оның көңілін көтереді. "Агу"лау, шыңғыру және күлімдеп күлу — бөпеңіздің сөйлеуге жасаған алғашқы қадамдары. 😊') WHERE id = '57cd3a11-aa81-4f90-bfb2-f69a0e71ee24';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Осы кезеңде айналасында болып жатқан жайттарға көбірек назар аудара бастаған бөпеңіз дыбыстарды ажыратып, қоршаған ортадағы дыбыстарға жауап бере бастайды. Осы айдан бастап бөпенің психологиялық күйі ерекше көңіл бөлуді қажет ететін мәселелердің бірі саналады. Бөпеңіз енді өзіне көңіл бөлгеніңізді қалағанда, іші пысқанда немесе Сізбен байланыс орнатқысы келгенде, назарыңызды аудару үшін кенеттен шыңғырып немесе қатты дауыстап жылауы мүмкін. Бөпенің назар аудартуға бағытталған мұндай әрекеттері оның себеп-салдар байланысын сәтті түсіне бастағанын көрсетеді. Сондықтан бөпеңізбен сабырлы сөйлесіп, оған көңіл бөле бастағаныңызда, ол жылауын бірден тоқтатып, Сізге күлімсіреуі мүмкін. Бұл бөпеңіздің жаман мінезі емес, сондықтан алаңдаудың қажеті жоқ. Ол әлі сөйлеу дағдысын толық меңгермегендіктен, мазасыздық тудыратын жағдайларда осылайша назарыңызды аударып, мәселесін жеткізуге тырысады.') WHERE id = 'c9b55f11-f202-4070-8d6a-fc7359809c90';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпелердің бойы мен салмағын бақылау сияқты, бас шеңберін қадағалау да маңызды. Бас шеңберін өлшеу — бөпенің миының дамуы туралы түсінік беретін жоспарлы процедура. Осы айдан бастап бөпенің бас шеңбері 39 см мен 45 см аралығында болуы керек. Бас шеңберінің тиісті мәндер аралығында ұлғаюы мидың сау дамуының көрсеткіші саналады. Бөпелердің ми дамуындағы кейбір мәселелер көбіне бас шеңберінің қалыпты мөлшерден өзгеше болуы нәтижесінде анықталады. Алайда бөпеңіздің бас шеңберінің өсуі аз немесе көп болса, бірден үрейленбеңіз. Бұл жағдайды тамақтанумен байланыстыруға болмайды, сондай-ақ көрсетілген сандардың қатаң қағида емес екенін ескерген жөн. Барлық бөпелер сияқты, Сіздің бөпеңіздің де өзіндік өсу әлеуеті бар. Генетикалық тұрғыдан шағын денелі бөпелердің дені сау болса да, бас өлшемі кішірек болуы мүмкін; ал ірі бөпелердің бас өлшемі сүйек құрылымына байланысты үлкенірек болуы ықтимал.') WHERE id = '7475597a-0083-4ac8-af52-e9ec4b5f2395';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіз енді шалқасынан жатқанда аяқтарын жоғары көтеріп, оларға таңдана қарайды! Аяқтарын зерттеп жүрген бөпеңіз көп ұзамай оларды ұстай бастайды. Біз ескерттік 😊 Осы кезеңде бөпенің сезім мүшелерін ынталандыратын ойындарды таңдау оның дамуын қолдау үшін өте маңызды. Сонымен қатар бөпенің өз денесін танып-білуіне көмектесетін ойындар да бұл кезеңде өте пайдалы болады. Бөпеңіздің шұлығын шешіп, табанын ақырын қытықтаңыз. Оның Сізге күлімсіреп жауап беретінін көресіз. 😊 Қытықтау және соның нәтижесінде бір-біріңізге күлу бөпеңізбен арадағы қарым-қатынас пен жылылықты нығайтатын әлеуметтік байланыс қалыптастырады. Сондай-ақ бөпені қытықтағанда оның қарқылдап күлуі араларыңыздағы эмоциялық байланысты да күшейтеді. Бірақ барлық нәрсенің шектен тыс болғаны зиян екенін де еске саламыз! :)') WHERE id = '85434c2c-c541-44d1-bc15-24301977fe06';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпені түнде тамақтандыру алғашқы айлардағыдай қазір де маңызды. Егер бөпеңіз түнде оянса, қажеттілігіне қарай оны әр 3-4 сағат сайын емізуіңіз немесе бөтелкемен тамақтандыруыңыз керек. Алайда бөпеңіз ұйықтап жатса және денсаулығында қандай да бір мәселе болмаса, тек тамақтандыру үшін оны оятуды ұсынбаймыз. Қарны ашқанда ол мұны Сізге өзі-ақ білдіреді. Болашақта дұрыс ұйқы режимін қалыптастыруы үшін оны ұйықтар алдында немесе оянғаннан кейін бірден тамақтандырмау қажет болуы мүмкін. Сондықтан бөпенің өздігінен ұйықтап кетуіне мүмкіндік беріп, оны қолдауыңыз керек. Егер бөпеңізді емізіп жатып ұйықтауға үйретіп қойсаңыз, оған біраз уақыт беріп, сабыр сақтаңыз. Көп ұзамай бәрі реттелетініне сенімді болыңыз! :)') WHERE id = '25c161ab-8831-4065-a3ec-22240c22edb0';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпелердің тіс жару кезеңі әдетте 5-ші айдан басталады. Егер бөпеңіздің әлі тісі шықпаса, осы айда тіс жаруға байланысты мазасыздық болуы мүмкін. Тіс жару — табиғи процесс, алайда бұл кезеңде бөпеңіз қатты мазасыздануы ықтимал. Мұндай жайсыздық қызыл иектің қышуынан туындайды және кейде ауырсынуға әкелуі мүмкін. Бөпенің алғашқы тістері әдетте 5-9-шы айлар аралығында шығады. Кейбір бөпелердің алғашқы тісі 3-ші айда шықса, енді бірінде бұл процесс 13-14-ші айға дейін созылуы мүмкін. Егер бөпеңіздің денсаулығында кінәрат болмаса, тіс жару жылдамдығы оның өсуі мен дамуына тікелей байланысты емес. Бұл көбіне генетикаға байланысты және бөпеңіздің тіс жаруы Сіздің және екінші ата-анасының сәби кезіндегідей өтуі ықтимал.') WHERE id = '2b63b86d-359a-4b54-8d2d-d3bc2859ca20';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпенің шашы өте нәзік әрі сезімтал, сондықтан шаш күтімі күнделікті тазалықтың маңызды бөлігі болуы керек. Бөпеңіз қалың немесе сирек шашпен тууы мүмкін. Тіпті шашсыз туып, шашы енді өсе бастауы да ықтимал. Қалай болғанда да, бөпенің шашы мен бас терісі ерекше күтімді қажет етеді. Бөпеңізді жаз айларында күн сайын, ал қыс айларында екі немесе үш күнде бір рет шомылдыра аласыз. Аллергияның, қызарудың немесе қышудың алдын алу үшін құрамында химиялық заттары бар дүкен өнімдерін қолданбаған жөн. Құрамында парабендер, сульфаттар, синтетикалық хош иістендіргіштер және бөпенің терісін тітіркендіруі мүмкін зиянды заттар жоқ өнімдерді пайдалануыңыз керек. Құрамы таза өнім табу қиын болса, сапалы табиғи қатты сабындарды немесе сұйық кастилия сабынын таңдауға болады.') WHERE id = '9f4a8a9d-785a-42f3-bcb2-0880d1571c96';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпені қосымша тағамға көшіру уақыты болжамды босану күнінен кейінгі 180 күнге сәйкес келеді. Бұл 6-шы айдың соңы қосымша тағаммен таныстыру үшін ең қолайлы уақыт екенін білдіреді. Кейбір жағдайларда дәрігердің кеңесімен қосымша тағамды ертерек бастауға болады, өйткені бөпелер бұл кезде жұту рефлексін меңгеріп үлгереді. Дегенмен ішек микрофлорасының саулығы үшін, егер дамуында кідіріс болмаса, тағы біраз күткен дұрыс. 5-ші айда бөпеңізге беретін қосымша тағам міндетті түрде сұйық күйде болуы керек; езбе беруге әлі ерте. Табиғи көкөніс сорпаларының сұйық бөлігі мен аллергия тудырмайтын жеміс шырындары бөпеңізге жарауы мүмкін. Тағамдық аллергия қаупіне байланысты бөпеңіз алғаш рет дәмін көретін тағамды 1 шай қасықтай өте аз мөлшерде беру ұсынылады.') WHERE id = '57b7991c-272a-4ed5-898c-f9700be1db2a';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңізге массаж жасау оның қан айналымын жақсартып, бұлшықеттері мен сүйектерінің жақсырақ дамуына көмектеседі. Сондай-ақ іштің кебуі мен түйілуі (колик) сияқты мәселелерді жеңілдетіп, бөпені тыныштандырады. Бөпеге массаж жасаудың негізгі мақсаты — дұрыс әдістер арқылы оны босаңсыту және массажды жүйелі түрде жасап, оның өсуіне, ақыл-ойы мен қимыл-қозғалысының дамуына оң ықпал ету. Әсіресе 4-ші айдан кейін жасалатын қарапайым жаттығулар бөпенің дамуы үшін өте маңызды. Массажды күн сайын бөпеңіз аш емес, тыныш әрі массажға дайын кезде жасауыңыз керек. Ең қолайлы уақыт — тамақтанғаннан кейін 1-1.5 сағат өткен соң. Массажды бастамас бұрын қолыңыздағы әшекейлерді шешуді ұмытпаңыз, тырнағыңыздың ұзын болмауын қадағалаңыз, қолыңыз таза әрі жылы болуы керек. Сондай-ақ массаж кезінде бөлме температурасын қолайлы деңгейде ұстап, бөпені ешқашан жалғыз қалдырмаңыз. Уақытты көңілді өткізіңіздер! 😊') WHERE id = '98edcdb5-d642-4617-8cc5-e7bd1fc8f734';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпелердің тіс жару кезеңін жеңіл өткізуі үшін тіс гельдері жиі қолданылады. Алайда ауырсынуды басатын дәрілер мен гельдерді қолданбай-ақ, тіс жару белгілерін азайтудың көптеген тиімді тәсілі бар. Тіс қаситын ойыншықтар бөпеңізге ұнайтын әрі көмектесетін пайдалы құралдар. Оларды тоңазытқышта салқындатқанда әсері күшейетінін ұмытпаңыз. 😊 Сондай-ақ мұндай ойыншықтардың қызыл иекке жанасуы массаж жасап, салқындату арқылы бөпенің ауырсынуын жеңілдетуі мүмкін. Тағы бір тәсіл ретінде бөпенің аузын сүртетін майлығын дымқыл немесе құрғақ күйінде тоңазытқышқа жарты сағат салып, кейін шайнауы үшін беруге болады. Салқын заттың қызыл иекке жанасуы бөпенің ауырсынуын, ісінуін және сезінетін қысымын азайтуы мүмкін. Алайда екі тәсілде де бөпеге микроб жұғу қаупін ескеріп, заттарды мұқият зарарсыздандыруды ұсынамыз. 😊') WHERE id = '61a39689-4f67-40ed-b7d3-3829e2076603';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Осы айда бөпеңіз тәулігіне орта есеппен 15 сағат ұйықтайды. Әдетте оның 10 сағаты түнгі, ал 5 сағаты күндізгі ұйқыға тиесілі. Алайда кейбір себептерге байланысты бөпеңіз азырақ ұйықтауы, ұйықтай алмай қиналуы немесе ұйқы кезінде жиі оянуы мүмкін. Ұйықтар алдында бөпені шомылдыру — оның ұйқыға оңай кетуіне көмектесетін ең жақсы әдеттердің бірі. Бұған қоса, ұйықтар алдында босаңсытатын массаж жасау, ертегі оқу немесе түрлі түсті кітаптың суреттерін бірге қарау сияқты әрекеттерді де ұйқы алдындағы рәсімге қосуға болады. Ұйқыға дайындау кезінде бөлмедегі жарықтың бәсең (ала-көлеңке) болуы бөпенің ұйықтауын едәуір жеңілдетеді. Қалыпты жағдайда бөпеңіз түнде қарны ашса, тамақтану үшін оянуы мүмкін. Түнде тамақтандыру бөпенің дамуы үшін әлі де өте маңызды. Сондықтан алаңдамаңыз және бөпеңіздің әлі де қарқынды өсу кезеңінде екенін ескеріңіз.') WHERE id = '388b1d4a-2870-47fb-8a38-2987cb7bbaf9';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіз дыбыс шығарудың қыр-сырын толық меңгере бастады. Ол қолына түскен кез келген затты сілкіп, дыбыс шығаруға тырысуы мүмкін, ал Сіз оған осы жаңалығын зерттеуге көмектесе аласыз. Бөпелер дыбыс шығаратын ойыншықтардың ішінде сылдырмақтарды ерекше жақсы көреді. Дүкендерден түсі мен пішіні әртүрлі сылдырмақтарды табуға болады. Сонымен қатар үйдегі заттардан да ойыншықты оңай жасап алуға болады. Ол үшін екі пластик стақан жеткілікті. Стақандардың ішіне үйдегі құрғақ дәнді дақылдарды (күріш, жасымық және т.б.) салыңыз. Ішіндегісі төгіліп қалмауы үшін стақандардың аузын мөлдір таспамен мықтап жабыстырыңыз. Әртүрлі дыбыс шығару үшін ірі және ұсақ дәндерді пайдалануға болады. Мысалы, күріш дәндері жіңішке, ал үрме бұршақ дәндері жуан дыбыс шығарады.') WHERE id = 'c96c4837-c392-4247-ae1b-3dcef1d0e562';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Соңғы күндері бөпеңіз әлдеқайда қимылдап кеткен сияқты, солай емес пе? Осы кезеңде оның қол-аяқ бұлшықеттері едәуір нығайды. Еңбектеуді, аунауды және заттардан ұстап қозғалғанды үйреніп жүрген бөпеңіздің бұлшықеттері қимылдаған сайын дами түседі. Ол қазір өте белсенді болғандықтан, қауіпсіздік үшін оның қозғалысын белгілі бір аумақпен шектеген жөн. Мысалы, оны биік жерде жалғыз қалдырмаңыз, маңайындағы үшкір және кесетін заттарды алып тастаңыз. Бөпеңіз қызықтырған кез келген затты бас бармағы мен басқа саусақтарын қысқыш тәрізді пайдаланып ұстай алады. Ұстаған затын танып-білу үшін аузына салғысы келеді. Сондықтан тұншығу қаупін тудыратын ұсақ ойыншықтарды, тиындарды және моншақ секілді заттарды қолжетімді жерде қалдырмауды ұсынамыз.') WHERE id = '5d03d27f-629c-43d8-acc3-6fa2f69ef287';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіз Сіздің жанасуыңыз бен онымен орнатқан байланысыңызға өте сезімтал. Оның терісінде жанасуды сезіп, миы мен жүйке жүйесіне белгі беретін миллиондаған ұсақ жүйке ұштары бар. Бұл жүйке ұштары бөпенің қолтығы, өкшесі, іші мен мойны секілді сезімтал аймақтарында көбірек орналасқан. Бөпенің дәл осы жерлеріне қол тигізгенде жүйке ұштары қозады, соның нәтижесінде ми қытықтану, дененің түршігуі және күлу сияқты реакциялар туғызады. Бұл кезде бөпенің қан қысымы жоғарылап, жүрек соғысы жиілейді және миы белсендірек жұмыс істейді. Мысалы, бөпеңізді қытықтау әрі көңілді, әрі оның жанасу сезімін жақсырақ түсінуіне көмектеседі. Күлу — бөпенің әзіл сезімін дамытудағы алғашқы қадам екенін ұмытпаңыз. 😊') WHERE id = '541bc5b2-12fd-4d41-9d69-7d5b93ee3f92';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Осы айларда бөпеңіз әдетте отырған қалыпта болғанды ұнатады. Әлі отыруға талпынбаса да, бұл — уақыт еншісіндегі мәселе! 😊 Бөпеңіз отырғанда тепе-теңдігін сақтап, денесін тіреу үшін қолдарын пайдаланады, ал арқа бұлшықеттері толық жетілмегендіктен, сәл бүкірейіп отыруы мүмкін. Кейбір дәрігерлер отырғызу жаттығуларын 6 айға дейін бастамауға кеңес береді. Дегенмен кейбір мамандар бөпенің қалауы мен даму ерекшелігіне қарай икемді тәсіл ұстануы мүмкін. Қалай болғанда да, бөпенің қауіпсіздігі үшін отырғызып көру уақытын қысқа ұстаған және оны тізеңізге отырғызған дұрыс. Бөпеңіз күн сайын күшейіп келе жатса да, әзірге оны тіреусіз отырғызуға тырысу кейбір қиындықтарға әкелуі мүмкін. Оның дамуы туралы ең дұрыс ақпаратты дәрігеріңіз береді. Сондықтан отырғызу, қосымша тағам мен дәрумендер секілді мәселелерде дәрігеріңізбен кеңесіп әрекет етіңіз. 😊') WHERE id = '3d5e88a5-68ba-47fd-b5a0-88c276587011';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпенің дені сау болып өсіп, дұрыс дамуы үшін құнарлы тамақтану өте маңызды. Ол дүниеге келген сәттен бастап ақуыздарды, көмірсуларды, майларды, дәрумендер мен минералдарды теңгерімді түрде және жасына сай мөлшерде алуы керек. 0-12 ай аралығы ең қарқынды өсу кезеңі болғандықтан, оның энергияға қажеттілігі жоғары болады. Осы кезеңде бөпенің ағзасында жаңа тіндер түзіліп, бұлшықеттері дамитындықтан, ақуыздарға, минералдар мен дәрумендерге қажеттілігі артады. Дене тіндерінің өсуі ақуыздың үздіксіз синтезделуін қажет ететіндіктен, бөпеңіздің сапалы ақуыз алуы өте маңызды. Сіздің сүтіңіз — бөпеңіз үшін керемет ақуыз көзі, ал оның құрамындағы ақуыздардың қорытылу деңгейі 95%-ға дейін жетуі мүмкін. Сондықтан емізу кезеңінде Сіздің де пайдалы әрі теңгерімді тамақтану тәртібін ұстануыңыз бөпенің қалыпты дамуын қамтамасыз ету үшін өте маңызды.') WHERE id = '896cbb45-0cf7-4486-ad2b-a52c32d44051';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Қазір қандай да бір дағдарыс кезеңі болмаса да, бөпеңіз ұйықтай алмай қиналуы мүмкін. 5 айлық бөпенің ұйқы тәртібі күн сайын жаңа қимыл дағдыларын меңгеруіне байланысты біраз бұзылуы ықтимал. Бөпеңіз жаңадан меңгерген дағдыларын қайталап үйрену үшін ұйқы мен тамақтанудан бас тартып, Сізді таңертең ерте оятуы мүмкін. Егер бөпеңіз оянғанда жыламай, төсегінде өздігінен ойнап жатса, кешке ұйықтатарда жанына ұйқыға арналған сүйікті ойыншығын қоюға болады. Біраз уақыттан кейін бөпеңіз осы ойыншықты көрген сайын ұйықтауға бейімделе бастайды. Бұл әдет дұрыс қалыптасуы үшін ойыншықты төсектен шығармай, тек ұйықтайтын уақыт келгенде жанына қою керек. Ұйқыға арналған ойыншықты таңдағанда оның органикалық жіптен немесе матадан жасалғанына, құрамында зиянды бояулардың және бөпе жұтып қоюы мүмкін ұсақ бөлшектердің жоқ екеніне көз жеткізіңіз.') WHERE id = '1fa3a9be-2b21-41b0-8e90-923545dc6c0e';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Осы кезеңде бөпеңізді ұйықтату қиын болып жүргенін білеміз. Жаңа туған кезде бөпеңіздің қарнын тойдырып, жөргегін таза ұстау оның жақсы ұйықтауы үшін жеткілікті еді. Алайда қазір айналасындағы әлемді жақсырақ түсініп, сезімдері дамып келе жатқан бөпеңізді ұйқыға дайындау қиындауы мүмкін. Сондықтан оның тек физикалық қажеттіліктерін өтеу өздігінен ұйықтап кетуі үшін енді жеткіліксіз. Миы өте белсенді жұмыс істейтін бөпеңізді ұйқыға дайындаған кезде оны кез келген шудан оқшаулау керек. Теледидардың немесе адамдардың сөйлескен дауысы оны ояу ұстауы мүмкін. Бөпеңіз жайлы ұйықтап кетуі үшін осы кедергілерді жою қажет. Сондай-ақ бөлменің тым ыстық немесе тым суық болуы ұйықтауын баяулатып, ұйқы сапасын төмендетуі мүмкін. Бөпеңіз ұйықтайтын бөлмедегі қолайлы температура — 22-24°C. Тәтті ұйқы! 😊') WHERE id = '1a8c9918-d018-4b4c-8f7f-c8a0898c2b43';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Осы айда бөпеңіздің даму деңгейіне сай бірге жасай алатын көптеген әрекет бар. Қазірден-ақ уақыттарыңыз көңілді өтсін! 😊 Алдымен айнаға ерекше қызығушылық танытатын бөпеңізбен айна алдында ойнап көрсеңіз қалай? Қолыңызға айна алып, оның алдында тұрғанда бөпеңіздің қолдарына ойыншық допты кезек-кезек беріңіз. Осылайша біраз уақыттан кейін бөпеңіз ойыншықты бір қолынан екіншісіне ауыстыруды үйренеді. Тағы бір әрекет ретінде бөпеңіздің назарын аударатын түрлі түсті допты еденге соғып, жоғары-төмен секіртіңіз. Бөпеңіз назарын аударған допты көзімен бақылауды тез үйренеді. Содан кейін қолыңыздағы допты қабырғаға қарай домалатып, қабырғаға тиіп, кері қайтуын көрсетіңіз. Бөпеңіз доптың қабырғадан кері серпілгенін бақылау арқылы үйренеді.') WHERE id = 'd9644453-95a5-4346-bbea-e0599b06e143';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Қосымша тағамға көшу кезеңіне біршама жақындаған осы күндері назар аударуыңыз керек маңызды мәселелердің бірі — бөпеңіздің пребиотиктерді жеткілікті мөлшерде алуы. Пребиотиктер бөпеңіздің ағзасындағы иммундық функцияларды жақсартып, ауруларға төзімділігін арттырады әрі ас қорыту жүйесіне пайдалы. Сондай-ақ қосымша тағаммен бірге қабылданатын пребиотиктер пребиотиктердің ең құнды көзі саналатын ана сүтінің қызметін де қолдайды. Пребиотиктер мен пробиотиктерге бай тағамдардың бірі — йогурт. Йогурт — сүтті ашыту арқылы алынатын, түсі ақ, қою консистенциялы сүт өнімі. Ол сүт құрамындағы лактозаның йогурт ашытқысының әсерінен ішінара сүт қышқылына айналуы нәтижесінде ұйыған сүттен жасалады. Кальцийге, ақуызға, B12 және B6 дәрумендеріне бай болғандықтан, йогурт — ана сүтімен бірге бөпеңіздің ағзасының төзімділігін қолдайтын ең маңызды тағамдардың бірі.') WHERE id = '67e55468-7559-4a60-ab60-67f55f552e34';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіздің киімдерін жуған кезде ескеруіңіз керек бірнеше жайт бар. Олардың ішіндегі ең маңыздысы — кір жууға арналған құралдардың қасиеттері мен оларды дұрыс таңдау. Сатылымдағы кейбір кір жуғыш құралдар мен сабындардың тіпті ересектерде аллергия туғызуы мүмкін екенін ескерсек, бөпеңіздің сезімтал терісі үшін бұл қауіп одан да жоғары. Мамандар сәби кезінде қолданылатын кейбір химиялық заттардың тіпті бірнеше жылдан кейін де аллергиялық реакция туғызуы мүмкін екенін ерекше атап өтеді. Сондықтан бөпеңіздің киімдерін жуған кезде мата жұмсартқыштарды, ағартқыштарды және теріні тітіркендіретін хош иісті өнімдерді қолданбағаныңыз жөн. Сатылымда бөпелерге арнайы шығарылған көптеген кір жуғыш құралдар мен түйіршіктелген сабындар бар. Солардың арасынан иіссіз түрлерін таңдасаңыз, терінің ықтимал тітіркенуінің алдын алуға көмектеседі.') WHERE id = 'abaadbfc-c35e-4cb0-b8bc-31d98a9f8ecf';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Күндізгі ұйқы бөпеңіз үшін өте маңызды және осы кезеңде ол күндіз 4-5 сағат ұйықтауы керек. Зерттеулерге сәйкес, жасына сай күндіз жеткілікті ұйықтайтын бөпенің түнде әлдеқайда ұзақ ұйықтайтыны анықталған. Мамандардың пікірінше, әсіресе күндізгі алғашқы екі ұйқы ең пайдалы болып саналады. Бұл алғашқы екі ұйқы бөпеңізге күш беріп, ағзасын қалпына келтіруге көбірек ықпал етеді. Сондай-ақ бөпелер күндізгі басқа ұйқыларға қарағанда алғашқы ұйқыға оңайырақ кетеді. Сондықтан күннің алғашқы сағаттарындағы осы пайдалы ұйқы уақытын өткізіп алмай, бөпеңіз ұйқысы келгенін білдіретін белгілерді көрсеткен бойда ұйықтауына көмектесіңіз. Алайда бөпеңіздің күндіз қажетті мөлшерден артық ұйықтауы түнгі ұйқысына кері әсер етуі мүмкін екенін ұмытпаңыз.') WHERE id = '59732708-2d13-4639-9614-435d122c79cb';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, '6-шы ай — бөпеңіздің өміріндегі ең маңызды бетбұрыс кезеңдерінің бірі. Өзін дербес тұлға ретінде сезіне бастаған бөпеңіз енді өзгелермен қарым-қатынас жасаудың қыр-сырын да үйрене бастайды. Осы тұрғыдан алғанда, бөпеңіз алғаш рет өз болмысына қатысты белгілерді аңғарады. Бұл — ақыл-ой дамуындағы өте маңызды жетістік. 😊 Сезімдерін белсенді пайдаланумен қатар, ол жадында жинақталған тәжірибелер негізінде өзіндік қорытынды жасай бастайды. Мысалы, енді ойыншықтарының арасынан ең ұнататынын таңдап, оны Сізге де білдіре алады. Сондай-ақ бөпеңіз біраз уақыттан бері анық көре бастағанымен, осы айдан бастап тіпті өте күрделі бейнелерді де қабылдай алады. Соның арқасында ол жаңа пішіндер мен текстураларды да тиімді ажырата алады.') WHERE id = 'b6d7faf8-f7c6-4e9e-a7ff-43facd4aa9db';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіз үшін ойын және ойнап өткізген уақыт — әрі өте көңілді әрекет, әрі оның дамуы үшін аса маңызды үдеріс. Сондықтан ойынды бөпеңізбен бірге көңілді уақыт өткізудің бір түрі деп қана қабылдамаңыз. Бірге ойнап өткізген уақыт — баға жетпес білім алу және үйрену кезеңі. Оның үстіне, бөпеңіздің сезімдері жақсы қалыптасып келе жатқандықтан, ойын арқылы ол энергиясын дұрыс жұмсап қана қоймай, қоршаған ортаны да танып-біледі. Ойынның тағы бір маңызды қызметі — бөпеңізге заттарды, ұғымдарды, сондай-ақ заттардың ұқсастықтары мен айырмашылықтарын үйренуге көмектесу. Сондықтан бөпеңіз ойнап жүріп, түрлі дағдыларды меңгереді және үйренеді. Жасына сәйкес түстерді, пішіндерді, атаулар мен өлшемдерді дұрыс қабылдауы кейінгі жылдары қарым-қатынастарды, әлеуметтік рөлдер мен еліктеуді үйренуіне және тұлғасының қалыптасуына көмектеседі.') WHERE id = '64ce3005-26f0-4a9c-b4db-77907d346329';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіздің қызуы аздап көтеріліп, қолына түскен әр затты аузына салып шайнағысы келе ме, құлағын уқалай ма, тәбеті төмендеп, сілекейі көп аға ма? Егер жауабыңыз «иә» болса, құттықтаймыз! Бір жұп маржандай тіске қол жеткізуге аз-ақ қалды. 😊 Бұлар — тіс жару белгілері. Бөпеңіз 5-айға толғанда, тістерінің шығуы кез келген сәтте басталуы мүмкін. Алғашқы тістері шықпай тұрып, қызарып, ісінген әрі ауыратын қызыл иегі оны мазалауы ықтимал. Бұл белгілер шығуға дайын тұрған тістің қызыл иекті жарып өтуінен, яғни тіс жаруынан шамамен 3-7 күн бұрын пайда болады. Жақсы жаңалық — тіс қызыл иектен алғаш көрінген сәтте бұл мазасыз белгілер бірден басылады. Есте сақтайтын маңызды жайт: бөпеңізден байқалған белгілердің тіс жаруымен байланысты екеніне сенімді болмасаңыз, міндетті түрде дәрігеріңізбен кеңесіңіз.') WHERE id = 'd5ac321f-14e0-45ad-ab92-652807702fa6';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіз қысқа уақыт ішінде жылдам дамып келе жатса да, оның денесін зиянды әсерлерден қорғайтын пайдалы микроорганизмдер, яғни тері флорасы әлі толық қалыптаспаған. Терісінің pH деңгейі әлі де жоғары, ал теріні қаптап тұратын қорғаныш кератин қабаты толық жетілмеген. Қышқылдығы төмен әрі қорғаныш тосқауылы әлі толық қалыптаспағандықтан, бөпеңіздің терісі микробтар мен химиялық заттарға сезімтал болады. Сондықтан оның терісіне тиетін киімдердің жуылу температурасына, кір жуғыш құрал мен мата жұмсартқышты таңдауға ерекше мән беруіңіз керек. Мысалы, киімдерді жуған кезде бөпеңіздің сезімтал терісі қызарып, қышымауы үшін құрамы табиғи кір жуғыш құралдарды таңдаған маңызды. Сондай-ақ құрамында хош иістендіргіштер секілді көптеген химиялық заттар болатындықтан, мата жұмсартқыштарды қолданбағаныңыз жөн. Бөпеңіздің киімдеріндегі микробтарды толық жою үшін жуғаннан кейін оларды міндетті түрде үтіктеуді ұмытпаңыз.') WHERE id = 'd86eb88e-f066-48c6-be2d-d43e207dbd2c';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Егер ұлыңыз болса, оны қашан сүндеттеу керектігі туралы ойыңызда біраз сұрақ болуы мүмкін. Сүндеттеу — әлемде ежелгі заманнан бері жасалып келе жатқан операциялардың бірі. Бұл процедура кезінде несеп шығару өзегінің аузын жауып тұратын күпек терісі кесіп алынады. Статистикаға сәйкес, әлемдегі әрбір үшінші ер адам сүндеттелген. Сүндеттеудің қашан, қалай және кім тарапынан жасалатыны өте маңызды. Бөпе дүниеге келген сәттен бастап ата-ананы толғандыратын бұл мәселе бойынша ең қолайлы жасқа қатысты түрлі пікір бар. Ең қолайлы жас аралығы туралы нақты ғылыми дәлел болмаса да, кейбір мамандар психологиялық жарақаттың алдын алу үшін сүндеттеуді ерте жаста жасауды ұсынады.') WHERE id = '05f311d5-ad4e-4d35-963b-6bea5a4bcff4';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіздің басындағы еңбекке (былқылдақ жерге) байланысты сол тұсына қол тигізуге қорқуыңыз мүмкін. Баста барлығы 6 еңбек болады. Олар басқа аймақтар сияқты қатты болмағандықтан, аналар көбіне қол тигізуден қорқады. Алайда еңбек берік дәнекер тіннен тұрады және бөпеңіздің миын сенімді түрде қорғайды. Сондықтан бөпеңізді шомылдырғанда, шашын тарағанда немесе басынан ұстағанда алаңдаудың және ол жерге қол тигізуден қорқудың қажеті жоқ. Еңбек бөпеңіздің қауіпсіздігі үшін маңызды болумен қатар, бас сүйегін жарақаттан қорғайтын дулыға қызметін де атқарады. Әдетте еңбек 9-18 ай аралығында ешқандай араласусыз өздігінен жабылады. Бұл үдеріс 24 айға дейін созылуы немесе еңбек одан ертерек жабылуы мүмкін. Мұндай жағдайлар әдетте мәселе туғызбайды, дегенмен сақтық үшін дәрігеріңізбен кеңескен пайдалы.') WHERE id = '8c311ff4-c1cb-4399-88d9-4dbb31f984b6';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіздің ми жасушалары арасында байланыстардың қалыптасуы нәтижесінде оның қабылдау қабілеті айтарлықтай дамыды. Соның арқасында ол енді жаңа дағдыларды меңгере бастайды. Ең қызығы — бөпеңіз өз атын атап, оны шақырып жатқаныңызды түсінеді! 😊 Дүниеге келген сәттен бастап оны атымен атауы осы дыбыстарды миына жазып, есте сақтауына көмектеседі. Бір дыбыстарды жиі естіген бөпеңіз енді өз атын тани алады. Дамудың тағы бір нәтижесі — ол отбасы мүшелерін бөтен адамдардан ажырата бастайды. Сондықтан бөпеңіз бөтен адамды көргенде тосырқап, жағдайды түсінуге тырысқан кезде ернін бүрістіріп, жылауы мүмкін. Тіпті айналаны азан-қазан етуі ықтимал. Дайын болыңыз, біз ескерттік! 😊') WHERE id = '2af2018e-44d1-408e-a2eb-5673d76e91c6';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бұл айда Сіз бен бөпеңізді жаңа тәжірибелер мен өзгерістер күтіп тұр. Бөпеңізді аурулардан қорғау үшін туғаннан бастап екпелерін уақытында салдыру өте маңызды. Екпе арқылы бөпенің ағзасына алдын алу көзделген ауру қоздырғышының әлсіретілген бактериялық немесе вирустық түрі енгізіледі. Бұл үдеріс иммунитет қалыптастыруға бағытталған, нәтижесінде бөпенің ағзасы сол ауруларға қарсы антиденелер түзе бастайды. Осылайша, бөпеңіз болашақта бұл микробтармен кездескенде, оның ағзасында қуатты қорғаныс механизмі дайын болады. 6-шы айдағы екпе күнтізбесіне В гепатитіне қарсы екпенің үшінші дозасы, бес компонентті біріктірілген екпенің үшінші дозасы және ОПВ (ауыз арқылы берілетін полиомиелитке қарсы вакцина) екпесінің бірінші дозасы кіреді. Сонымен қатар, бөпеңіз алғаш рет алатын полиомиелитке қарсы екпе де осы тізімге енгізілген. Осымен бөпеңіздің алғашқы 6 айға арналған екпе күнтізбесі аяқталады.') WHERE id = '95f9ad1b-63d6-45ba-b708-bf282b104620';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Екпелер кейде мазасыздық, құсу, дене қызуының көтерілуі немесе жылау сияқты реакциялар тудырғанымен, бөпеңізді төменде айтылатын ауыр аурулардан қорғау үшін өте қажет. Алдымен, полиомиелитті "полио" вирусы қоздырады. Бұл вирус жүйке жүйесін зақымдап, салдануға, тіпті өлімге әкелуі мүмкін. Ол кез келген жаста кездескенімен, әсіресе иммунитеті толық қалыптаспаған 3 жасқа дейінгі балаларға қауіп төндіреді. Денсаулық сақтау органдарының қатаң бақылауы мен екпе науқандарының арқасында, бақытымызға орай, бұл аурудың таралуы едәуір шектелді. Ал дифтерия — тыныс алу жолдарын, ас қорыту жүйесі мен жүректі зақымдайтын және өлімге әкелуі мүмкін ауыр ауру. Сіреспе тот басқан металл, лас топырақ немесе үшкір құралдардан жарақат алған кезде жұғып, жүйке жүйесіне тікелей әсер ететін қауіпті ауру. Менингит өлім қаупінің жоғары болуымен қатар, мүгедектік, ақыл-ой дамуының тежелуі, кереңдік және соқырлық сияқты ауыр салдарға әкелуі мүмкін. Сондықтан екпе — бөпеңіздің дені сау болашағын қорғайтын ең сенімді қалқан.') WHERE id = '2ec370c7-9d55-4f76-86f5-a1d0c2080600';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Күн сайын жаңа қимылдарымен Сізді таңғалдырған бөпеңіз арқа бұлшықеттерінің дамуының арқасында енді тірексіз отыруға дайындалып жүр. Егер оның отыруға дайын екенін байқап, бұған сенімді болсаңыз, аздап көмектесе аласыз. Алдымен оны тізеңізге отырғызып, қолынан ұстап, басын тік ұстауын қадағалаңыз. Содан кейін диванға отырғызып, айналасына жастықтар қойып, тепе-теңдігін сақтауға көмектесе аласыз. Бұл жаттығулар кезінде бөпеңіз кейде шаршап, бір жағына қарай құлап кетсе де, алаңдамаңыз. Бұлшықеттері нығайып, тепе-теңдікті сезінуі дамыған сайын, оның отыру уақыты да ұзара түседі. Біраз уақыттан кейін оның тепе-теңдігін өз бетінше сақтап, тірексіз отырғанын көресіз. Сол кезде жастықтар да қажет болмайды! 😊') WHERE id = '4613232a-c667-47df-9951-c91586b62ee3';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, '6-шы ай — Сіз бен бөпеңіз үшін жаңалықтар мен тосынсыйларға толы ерекше кезең. Бөпеңізді қосымша тағаммен таныстыратыныңызға қатты қуанып жүргеніңізді білеміз! Дүниежүзілік денсаулық сақтау ұйымы (ДДСҰ) мен денсаулық сақтау мамандары бөпелердің 180 күні толғаннан кейін ас қорыту жүйесі қосымша тағамға дайын болатынын айтады. Алғашқы 6 ай бойы бөпеңізді тек ана сүтімен немесе сүт қоспасымен тамақтандырдыңыз. Енді оның ағзасы құрамы әртүрлі тағамдармен танысады, сондықтан кейбір аллергиялық реакциялар болуы мүмкін. Сол себепті қосымша тағамға біртіндеп көшіп, ас қорыту жүйесіне артық салмақ түсірмеу үшін асықпауға кеңес береміз. Біздің "Рецепттер" бөліміміз осы дәмді саяхатта Сізге көп көмектеседі. Ас болсын! 😊') WHERE id = '1057a1b2-3687-4581-b2fe-6f0fca8b4778';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Сіз бен бөпеңіз үшін өте қызықты қосымша тағам кезеңі басталды! Бәрі дайын ба? Бөпеңіздің қосымша тағамға дайын екенін көрсететін ең маңызды белгі — әрине, оның өздігінен отыра алуы. Сондықтан Сізге жақсы тамақтандыру орындығы қажет болады. Оны жай ғана орындық деп қарамаңыз: бұл бөпеңіз үшін тек тамақ ішетін орын емес. Бөпеңізді тамақтандыру орындығында ас ішуге үйретудің көптеген маңызды себебі бар. Ең алдымен, мұндай орындық бөпеңіздің Сізбен бір үстел басында отыруына мүмкіндік береді. Отбасы мүшелерімен бірге бір дастарқан басында отыру бөпеңізбен көбірек қарым-қатынас орнатуға және араларыңыздағы байланысты нығайтуға көмектеседі. Тамақтандыру орындығын таңдағанда оның қауіпсіз, ыңғайлы, жеңіл әрі сапалы материалдан жасалғанына міндетті түрде назар аударыңыз.') WHERE id = 'f8f5f75d-b030-4498-b7d5-7b4bc417016c';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Осы айдан бастап бөпеңіздің тәуліктік ұйқы ұзақтығы шамамен 13 сағат болады. Күндіз екі рет ұйықтауы қалыпты. Ал түнде 6-7 сағат үзіліссіз ұйықтай алады. Бөпеңіз өскен сайын оның ұйқыға деген қажеттілігі біртіндеп азаяды. Бұл өсуге ықпал ететін гормондардың негізінен түнгі ұйқы кезінде бөлінуімен байланысты. Осы кезеңде бөпеңіздің өздігінен ұйықтауға дағдылануы да күтіледі. Яғни оны әлі де тербетіп, емізіп немесе көтеріп жүріп ұйықтататын болсаңыз, мұны біртіндеп азайтып, жақын арада тоқтатуға кеңес береміз. Кейбір мамандар бөпелердің түнгі ұйқы режимін дұрыс қалыптастыруы үшін әр жылаған сайын бірден араласпауға кеңес береді. Сондықтан бөпеңіздің қарны тоқ, жөргегі таза және еш жері мазаламайтынына сенімді болсаңыз, әр жылаған сайын бірден әрекет етпеуге болады. Әр жылаған сайын қолға алынған бөпе өздігінен ұйықтауды үйрене алмайды.') WHERE id = '790745e1-b64b-4611-b8ea-ced2bd5bd141';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіз үшін ең маңызды қорек көзі әлі де Сіздің емшек сүтіңіз немесе сүт қоспасы болып қала береді. Қосымша тамаққа көшу кезеңінде емізуге немқұрайлы қарауға да, оны азайтуға да болмайды. Дәрігер басқаша кеңес бермесе, 6-8 ай аралығында қосымша тағамдар тек дәмін таттыру және біртіндеп үйрету мақсатында беріледі; бұл кезеңде емшек сүті негізгі қорек болып қала береді. Қосымша тамаққа көшкен кезде бөпеңіздің дамуындағы кейбір белгілерді де бақылауыңыз керек. Мысалы, осы кезеңде оның басын тік ұстауы, отыра алуы, қол мен көз қимылының үйлесімділігі дамуы күтіледі. Алғаш рет жаңа дәмдермен танысқан бөпеңіз тағамды тілімен итеріп шығаруы немесе жеуден бас тартуы мүмкін. Бұл — қалыпты жағдай әрі уақыт өте басылатын рефлекс. Біртіндеп бөпеңіздің аузын ашу, жұту және шайнау дағдылары дамиды. Сондықтан өтпелі кезеңде бөпеңізді мәжбүрлемеңіз және беретін қосымша тағамдарыңыз емшек сүтін тек толықтыратынын ұмытпаңыз.') WHERE id = '28ae02f7-da1a-49dd-85b2-b82676a86611';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіз бұл кезеңде дене, таным және тіл дамуы жағынан өте жылдам ілгерілейді. Оның әрбір жаңа қимылы мен әрекеті Сізді де қатты қуантатыны анық. Ересектерге қарағанда бөпелер дамудың маңызды кезеңдеріне тән дағдыларды өте қысқа мерзімде меңгере алады. Мысалы, кеше ғана тірексіз отыра алмаған бөпеңіздің бүгін өздігінен еркін отырғанын көріп қалуыңыз мүмкін! 😊 Сонымен қатар бөпеңіз 6 айлық балаларға тән даму қадамдарының кейбірін меңгеріп, ал басқаларын әлі жасай алмауы мүмкін. Бұл алаңдауға себеп емес, өйткені әр бөпе өзіне тән қарқынмен дамиды. Егер бөпеңіз әлі тірексіз отыра алмайды немесе тепе-теңдігін толық сақтай алмайды деп ойласаңыз, сабыр сақтаңыз; көп ұзамай оның бұл дағдыларды да меңгергенін көресіз! 😊') WHERE id = '6188303f-604c-4619-8980-cdb921290253';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Қосымша тамаққа көшу кезеңінде бөпеңізде іш қатпау үшін кейбір жайттарға назар аударып, алдын алу шараларын қолдана аласыз. Ең алдымен, іш қатудың қандай да бір даму немесе денсаулық мәселесіне байланысты екенін анықтау үшін дәрігеріңізбен кеңесіңіз. Бұған қоса, бөпеңізді жылы суға шомылдыру және ішіне массаж жасау ішектің белсендірек жұмыс істеуіне көмектеседі. Дәрігеріңіздің кеңесімен мәзіріне іш қатуға көмектесетін кептірілген өрік (өрік қағы), қара өрік, қою жасыл жапырақты көкөністер мен алмұрт сияқты тағамдарды қоса аласыз. Кептірілген жемістерді жылы суға салып қойып, сол суды күні бойы ішкізу де пайдалы. Осы уақыттың бәрінде бөпеңізді жиі емізуіңіз керек. Ал емізбесеңіз, сүт қоспасының мөлшерін азайтпай, сұйықтықты жеткілікті ішуін қадағалаңыз. Сондай-ақ бөпеңізді жеңілдету үшін анус аймағына қандай да бір әрекет жасау (тітіркендіру) ұсынылмайды, өйткені бұл әдетке айналуы мүмкін, сондықтан одан аулақ болған жөн.') WHERE id = 'e2db0876-de2c-4046-9525-ff64acf7b248';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, '6 айлық бөпеңіз енді тірекпен немесе тірексіз отыра алады, аунай алады және өте қысқа уақыт болса да аяғынан тік тұра алады. Бұл қимылдар әр бөпеде әр уақытта дамитындықтан, уақыты келгенде кейбір жаттығулар арқылы оған көмектесуіңіз қажет болуы мүмкін. Бөпеңізді шалқасынан еденге немесе төсекке жатқызып, жанында болған кезде аунауына көмектесе аласыз. Сізге қарай ұмтылған балапаныңызды құшақтап, жетістігін мақтаңыз. Егер ол қимылдамаса, ынталандыру үшін оны етпетінен жатқызып, қайтадан шалқасынан аудара аласыз. Бұған қоса, қолмен ойналатын ойындар оның сипап сезу қабілетін дамытып қана қоймай, өз бетінше көңіл көтеруіне де тамаша мүмкіндік береді. Бөпеңізді алдыңызға отырғызып, саусақтарыңызды дәл көз деңгейіне әкеліп, кезекпен көрсете және бір-бірлеп санай аласыз. Көңілді уақыт өткізіңіздер! 😊') WHERE id = '8d36fd03-563f-4c3d-92c7-c802cd459f32';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Қосымша тағамдарға көшіп жатқан осы кезеңде бөпеңізге алма, шабдалы, алмұрт сияқты жемістердің, сондай-ақ картоп, сәбіз және асқабақ тәрізді көкөністердің езбесі мен шырынын беруді таңдауыңызға болады. Сонымен қатар үйде өзіңіз дайындаған айранға дәрігердің кеңесімен дәріханадан сатып алынған пробиотик ұнтағын қоса аласыз. Қосымша тағам ретінде беруге болмайтын өнімдердің басында сиыр сүті, қантты және тұзды тағамдар тұр. Сиыр сүті ерте жаста ішекте жасырын қан кетуге себеп болуы мүмкін. Сондай-ақ құрамында темірдің жеткіліксіз болуы және бөгде ақуыздарға байланысты аллергия туғызу қаупі бар болғандықтан, оны 1 жасқа дейін бермеу керек. Дайын тағамдарға бөпеңіздің мәзірінде орын жоқ екенін де ұмытпаңыз. Сонымен қатар бөпеңізге беретін тағамдарды құмшекердің орнына тосап немесе жеміспен тәттілеуді таңдаңыз.') WHERE id = 'bdbf69c9-7362-46c7-9230-c6195ba35de7';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Зерттеулерге сәйкес, бөпелердің ынталандыру деңгейі бірқалыпты ортада жақсырақ дамитыны байқалған. Сондықтан бөпеңізді әртүрлі текстуралармен, пішіндермен және дыбыстармен таныстыру оның миына жаңа ақпараттың келуіне мүмкіндік береді. 6 айлық бөпеңізге арналған мұндай сенсорлық жаттығулар оның ақыл-ойының дамуы үшін өте маңызды. Осы кезеңде ойнайтын «ку-ку» ойыны, ұйқасты бесік жырлары мен саусақ қуыршақтары көңілді болып қана қоймай, бөпеңіздің дамуына да үлес қосады. Бөпеңіздің алдына қойған әрбір жаңа затты өз бетінше зерттеуіне мүмкіндік беріп, оның қасиеттерін танып-білуіне жеткілікті уақыт бергеніңізге көз жеткізіңіз. Мысалы, бұл шыны стақан мен қасық болуы мүмкін. Осы заттарды бөпеңіздің екі қолына беріп, зерттеуіне мүмкіндік жасаңыз және олармен қалай дыбыс шығаруға болатынын көрсетіңіз. Бөпеңіз бұл ойыннан көп көңіл көтеретініне сенімдіміз. Ойындарыңыз көңілді өтсін! 😊') WHERE id = 'e926ea15-a8f6-4559-a5e9-18bd81abc58e';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіз енді денесін тік ұстап отыра алатындықтан, оның көру аясы кеңейіп, айналасымен белсендірек әрекеттесе алады. Бұл сезім мүшелері мен қимыл-қозғалыс дағдыларының дамуына да көмектеседі. Дамуы жалғасқан сайын, ойын ойнауға және жаңа нәрселерді зерттеуге мүмкіндік беретін дүниелерге қызығушылығы арта түседі. Мысалы, ұсақ моторикасы дами бастаған бөпеңіз кішкентай заттарды саусақтарымен ұстай алады. Сондай-ақ қолындағы затты бір қолынан екіншісіне ауыстыра алады. Жанында болмаса да, көру аймағындағы ойыншықтарға қолын созып, оларды алуға тырысуы мүмкін. Қолынан түсіріп немесе жіберіп алған ойыншығын өзі ала алмаса, Сізге белгі беріп, ойыншығын алып беруіңізді сұрайды. Дегенмен бөпеңізде осы даму кезеңдерінің кейбірі әлі байқалмауы мүмкін. Бұл әр бөпенің даму үдерісі әртүрлі болатынына байланысты, сондықтан алаңдаудың қажеті жоқ.') WHERE id = '6730fee9-c4d4-4db1-af73-50d999349b75';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Осы айда дәрігеріңіздің кеңесімен немесе емханадан берілетін темір препаратын бөпеңізге бере бастауыңыз қажет. Бүкіл әлемде ең жиі кездесетін қоректік зат тапшылығы саналатын темір тапшылығы, әсіресе дамушы елдерде, денсаулық сақтаудың маңызды мәселесі болып отыр. Темір тапшылығы анемиядан бөлек, бөпелердің зияткерлік дамуына кері әсер етуі мүмкін. Ми қарқынды өсіп, негізгі психомоторлық дағдылар қалыптасатын бөпелік кезеңде пайда болған темір тапшылығы зияткерлік дамуды баяулатуы ықтимал. Зерттеулерге сәйкес, IQ деңгейі тұрақты түрде қалыпты көрсеткіштен шамамен 5 балға төмендеуі мүмкін. Сондықтан ДДСҰ 6-12 айлық бөпелерге темір препаратын беруді ұсынады. Америкалық педиатрия академиясы да 9-12 ай аралығында бөпенің темір деңгейін тексеру үшін бір рет қан талдауын тапсыруға кеңес береді.') WHERE id = 'da861e51-ae52-40b6-a6f0-c4e0e3afd9bf';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Әсіресе оңай қорытылатын ана сүтімен немесе сүт қоспасымен қоректенетін бөпелерде қосымша тағамға көшу кезінде іш қату жиі кездесуі мүмкін. Бөпеңіздің іші қатып жүр деп күмәндансаңыз, мына жайттарды мұқият оқып шығуға кеңес береміз. Ең алдымен, әр бөпенің ас қорыту жүйесі бірдей жылдамдықпен дамымайтынын ескеріңіз. 6-шы айы аяқталған соң қосымша тағам бере бастасаңыз да, іш қату пайда болуы мүмкін. Сондықтан қосымша тағам беруді біраз уақытқа тоқтатып, кейін қайтадан байқап көруге болады. Осы кезеңде бөпеңізге сұйық сорпа немесе жеміс шырынын бере аласыз. Қосымша тағам бере бастағанда банан, картоп секілді іш қатуға әкелуі мүмкін өнімдерге назар аударуыңыз керек. Осы тағамдарды бергеннен кейін бөпеңіздің іші қатқанын байқасаңыз, оларды біраз уақытқа рационнан алып тастау қажет. Сондай-ақ бөпеңіздің іші қатып, үлкен дәретке отыруы қиындағанын байқасаңыз, артқы өтіс аймағында сызат болуы мүмкін. Мұндай жағдайда дәрігеріңізбен байланысу маңызды.') WHERE id = '9037133c-00b1-4728-bfa8-d12451129dad';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіздің микробиота деп аталатын ішек флорасы қалыптасып келеді. Оның тепе-теңдігін сақтау үшін кейбір жайттарға назар аудару қажет. Егер босану кесарь тілігі арқылы өтсе, 8-ші күннен бастап, ал табиғи жолмен босансаңыз, 4-ші күннен бастап бөпенің ішек флорасында ас қорытуға көмектесетін бактериялар пайда бола бастайды. Ішек флорасындағы бұл микроорганизмдердің бір бөлігі пайдалы, ал екінші бөлігі зиянды бактериялардан тұрады. Бактериялардың екі түрінің де болуы олардың шамадан тыс көбеюіне жол бермей, ас қорыту жүйесіндегі тепе-теңдікті сақтайды. Бөпеңіздің ішек флорасын қолдау үшін пробиотиктер мен пребиотиктерді қолдануға болады. Бұл қоспалар бақыт гормоны ретінде белгілі серотониннің бөлінуін де ынталандырады. Бөпеңіздің рационына осы пайдалы бактериялары бар тағамдарды қоса аласыз немесе қаптама түрінде сатылатын пробиотиктер туралы дәрігеріңізден ақпарат ала аласыз.') WHERE id = '9e82ffd7-d409-49b6-a002-4b2672efef01';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіздің екпе күнтізбесіне енгізілген вакциналар оның ағзасында жасанды жолмен иммунитет қалыптастырады. Бұл иммунитет бөпенің ағзасына ауру тудыратын микроорганизмдерді енгізіп, иммундық жүйеге белгі беру және оны іске қосу арқылы қалыптасады. Сондықтан бөпеңіздің ағзасы алғаш рет кездескен микробтарға аздап жайсыздықпен жауап беруі мүмкін, алайда сол уақытта оның ағзасында осы ауруға қарсы иммунитет те қалыптасады. Жад жасушаларының арқасында ол сол ауруды қайта жұқтырмайды. Вакцинация кезінде бөпенің ағзасына әлсіретілген немесе өлтірілген микроорганизмдер енгізіледі. Осылайша иммундық жүйеге белгі беріледі де, бөпеңіз болашақта нағыз микробпен кездескен кезде оның ағзасы белсенді қорғануға дайын болады. Вакциналар бөпеңізді аурулардан 100% қорғамаса да, ағзасында дайын антиденелер болғандықтан, ол ауруды әлдеқайда жеңіл өткереді.') WHERE id = '6a597987-e8b8-4f14-a6ec-55936a1409ea';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, '6 айлық даму кезеңінде бөпеңіз тәулігіне шамамен 11 сағат ұйықтауы мүмкін. Бұл орташа ұйқы ұзақтығы бөпеңіз тек түнде ұйықтайды дегенді білдірмейді: күндізгі ұйқы да ол үшін әлі де өте маңызды. Америкалық педиатрия академиясының мәліметінше, бөпені өз бөлмесіне көшіріп, Сізден бөлек ұйықтауға үйретудің қолайлы кезеңі дәл осы айдан басталады. Себебі қосымша тағамға көшкен бөпенің алғашқы айлардағыдай ана сүтіне тәуелділігі біршама азаяды. Алайда бұл ауысуды тым жылдам жүзеге асыру бөпенің психологиялық дамуында кейбір қиындықтар тудыруы мүмкін. Әсіресе түнде оянған бөпенің қорқып, жылауы жиі кездеседі. Бөпеңіздің жаңа жағдайға үйренуі үшін оған уақыт беріп, бұл үдерісті біртіндеп және сабырмен жүргізуіңіз керек.') WHERE id = '68a677bc-c6fd-496b-bd7c-d65d75f316ae';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Қосымша тамақтандыру туралы ақпарат іздеген кезде «үш күн ережесі» жайлы естіген болуыңыз мүмкін. Үш күн ережесі бөпеңіз қосымша тағам жей бастаған кезеңде оның тағамдарға аллергиялық реакция беру ықтималдығын анықтау үшін өте маңызды. Соның арқасында бөпеңізде аллергия пайда болса, оған қай тағамның себеп болғанын оңай анықтай аласыз. Осы ережені қолданып, бөпеңізді 3 күн бойы бақылау арқылы берген тағамыңыздың оған қандай да бір жағымсыз әсері бар-жоғын көре аласыз. Сондай-ақ бұл уақытта бір ғана тағам берілетіндіктен, бөпеңіздің оны ұнатқан-ұнатпағанын да оңай түсінесіз. Қосымша тағамнан кейін пайда болуы мүмкін аллергиялық реакциялар терінің қызаруы және бөртпе түрінде білінуі ықтимал. Бұған қоса, іштің кебуі мен соған байланысты жылау, құсу, іш өту, мазасыздық және асқазанның ауыруы да аллергияның ықтимал белгілеріне жатады.') WHERE id = 'e67b6585-697c-442b-94c4-f4bcc520b28d';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіз енді бір орында отырғанды ұнатпайды. Сондықтан оның үнемі қимылдап жүруі — қалыпты жағдай! 😊 Осы кезеңде бөпеңіздің қолдары мен аяқтары оның назарын бұрынғыдай қызықтыра береді. Ол қолдары мен саусақтарын кезек-кезек зерттеп, олармен не істей алатынын білуге қуанады. Ал аяқтарын жоғары көтеріп, қолдарымен ұстауға тырысу — оның сүйікті әрекеттерінің бірі. Сондықтан бұл ойынды одан да қызықты ету үшін дыбыс шығаратын, түрлі түсті шұлықтар сатып алуыңызға болады. Бөпеңіз аяғындағы көңілді шұлықтарға қолын созуға тырысып, олармен ойнап, өз-өзін қызықтыра алады. Сондай-ақ қимылдағанды жақсы көретін балаңызға кең әрі ыңғайлы киім кигізуді ұмытпаңыз! 😊') WHERE id = '6e15d298-df96-4ac7-b6a2-ef5c565ec39c';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Соңғы жылдары ішек саулығына қатысты жүргізілген жан-жақты зерттеулер пробиотиктердің маңызын көрсетті. Ішек қазір «екінші ми» деп аталады әрі бүкіл ағзаға әсер етеді, сондықтан оның саулығы бөпеңіздің дұрыс дамуы үшін маңызды. Пробиотиктер ішек флорасының тепе-теңдігін сақтап, зиянды микроорганизмдердің көбеюіне жол бермейді. Сонымен қатар ана сүтімен бірге пробиотиктер иммундық жүйенің қалыптасуына ықпал етіп, бөпеңіздің гомеостаз деп аталатын ішкі тепе-теңдігін сақтайды. Осы тұрғыдан алғанда, пробиотиктер кейбір минералдар мен дәрумендердің сіңуін жақсартады, липидтер деңгейін реттейді және ішектің өткізгіштігін қалыпқа келтіреді. Мұндай пайдасын көру үшін пробиотик өнімдерді тиісті мөлшерде және жүйелі түрде тұтыну ұсынылады. Қосымша тамақтандыру кезеңінде бөпеңіздің йогурт, айран және тархана сорпасы секілді құрамында пробиотиктер бар тағамдарды үнемі тұтынуы ішек саулығы үшін өте маңызды.') WHERE id = '092895c9-69ca-40db-8ca1-d44efd327a7d';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, '6 айлық бөпеңіз дауыс ырғағының өзгеруіне жауап береді, ал дыбыс шығаратын кез келген зат оның назарын ерекше аударады! Бөпеңіздің зияткерлік дамуы және бет қимылдарын бақылап, олардың мағынасын түсінуге талпынысы қазірдің өзінде жақсы жетілген. Бұл бөпеңіздің Сіз айтқан «жоқ» сөзіне жауап бере алатынын білдіреді. Ол бет әлпетіңізге қарап, «жоқ» сөзінің жағымсыз мағына беретінін түсіне алады. Алайда бөпеңізге «жоқ» деп тым жиі айтсаңыз, ол айналасындағы әлемді жағымсыз әрі теріс орта ретінде қабылдауы мүмкін. Осы тұста «ол әлі тым кішкентай, түсінбейді» деуіңіз мүмкін. Алайда бұл — ғылыми тұрғыдан дәлелденген дерек. Бөпеңіз естігенін, көргенін және сезгенін әлі толық түсіне алмаса да, кейін пайдалану үшін миына сақтап қояды. Сондықтан бөпеңізді үнемі шектеу және «жоқ» деген сөзге үйрету оның өскенде теріс ойлайтын адам болуына әрі бастама көтеруден тартынуына себеп болуы мүмкін.') WHERE id = '2d11a5b6-a9e7-427f-af80-602cab8874a2';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Дүниеге келгеннен бері тек сүтпен қоректеніп жүрген бөпеңіз қосымша тамақтандыру басталатын осы кезеңде қою тағамдардан бас тартуы мүмкін. Сондықтан оның назарын басқа жаққа аудару үшін тамақтандырған кезде теледидар алдына отырғызу секілді теріс әдеттерді қалыптастырмаңыз. Қосымша тағамды енгізу кезінде бөпеңізге уақыт беріп, түсіністік таныту маңызды. Мысалы, тамақтандырған кезде тағамдардың атауы мен түсін айтып отыру оның қабылдау қабілетін дамытып, асты ынтамен жеуіне көмектеседі. Бөпеңіз тамақ ішуді жақсы көруі үшін аздап шығармашылық танытсаңыз жеткілікті. Тағамнан жасаған түрлі пішіндер оның қызығушылығын оятып, уақытты көңілді әрі пайдалы өткізуге мүмкіндік береді. Әсіресе бөпеңіз дәмдерді танып жатқан кезеңде әртүрлі тағамды бөлек ыдыстарға салып беру оның дәмді дұрыс қабылдауы үшін маңызды. Сондай-ақ осы уақытта сынбайтын тәрелке, шанышқы мен қасықты қолдану қауіпсіздеу болады.') WHERE id = 'b5fa9ff8-3ed0-4d85-920b-ca982ac76fc8';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Кейде бөпеңіздің Сізге біраз қиындық тудыратынын білеміз. Әсіресе оның өте белсенді екенін және үнемі жаңа нәрселерді зерттегісі келетін кезеңде жүргенін ескерсек, бұл — қалыпты жағдай. Алайда қанша жерден қиын болса да, оның әлі де Сізге толықтай тәуелді әрі сезімі бар бөпе екенін ұмытпаңыз. Барлық тіршілік иесі секілді бөпеңіз де белгілі бір деңгейде және белгілі бір уақыт бойы күйзеліске төтеп бере алады. Мысалы, бөпеңіздің жөргегі ластанғанда немесе қарны ашқанда, ағзасы мұны автоматты түрде қауіп ретінде қабылдайды. Алдымен қимылдап, мазасыздана бастаған бөпеңіздің қажеттілігі өтелмесе, оның ағзасында кортизол гормоны бөлінеді. Бұл күйзеліс механизмі бөпеңіздің ағзасында қан қысымы мен қан ағымы жылдамдығының жоғарылауына әкеледі. Бөпеңіз қарқынды даму кезеңінен өтіп жатқан осы айларда кортизол гормонының шамадан тыс бөлінуі уақыт өте келе оның әлсіреуіне, тұйықталып, айналасынан оқшаулануына себеп болуы мүмкін.') WHERE id = '79821ac2-93ff-4cf4-a7f8-8aab07a2bcca';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіздің ақыл-ойы айтарлықтай дамығандықтан, ол енді тамақ жегісі келетінін не келмейтінін мінез-құлқы арқылы білдіре алады. Бұл белгілерді мұқият бақылап, бөпеңізді түсінуге тырысу өте маңызды. Бөпеңіз қарны ашқанда әдетте мазасызданып, көңілсізденіп, жылауы мүмкін. Егер ол қатты ашығып, тамақтандыру кешіккендіктен тамақтану кезінде жыласа немесе басын басқа жаққа бұрса, қыстамаңыз: сәл күтіп, кейінірек қайтадан байқап көріңіз. Бөпелер тамақтанудың басында қатты аш болғандықтан, кейде жылап, не істерін білмей қалғандай әрекет етуі мүмкін. Бөпеңізде осындай жағдай болса, сабыр сақтаңыз. Сіздің байсалды әрекетіңіздің арқасында бірнеше қасық жегеннен кейін ол тынышталуы ықтимал. Ал бөпеңіз тойғанда немесе белгілі бір тағамды енді жегісі келмегенде, беті мен басын басқа жаққа бұрады. Осы кезде тамаққа деген ықыласын жоғалтпау үшін тамақтандыруды тоқтатуға кеңес береміз.') WHERE id = 'b20385d7-4579-4424-bf85-74e142637de4';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіз қосымша тағамдармен таныса бастаса да, бұл кезеңде оның негізгі қорегі әлі де Сіздің емшек сүтіңіз немесе сүт қоспасы екенін ұмытпаңыз. Сондай-ақ осы кезеңде бөпеңізге беретін жеміс шырындарына абай болған жөн. Әсіресе бөпеңіздің тістері шығып қойған болса, жеміс шырынының құрамындағы фруктоза тістің бұзылуына себеп болуы мүмкін. Сондықтан құрамында қант бар мұндай өнімдерді бөтелкемен емес, қасықпен және бақылап отырып берген дұрыс. Бөпеңізге дайындаған езбелер мен түйіршікті сұйық тағамдарды да оны бақылап отырып, қасықпен бере аласыз. Енді оған банан, алма, шабдалы сияқты жемістердің езбесін, картоп, сәбіз, брокколи сияқты көкөністердің езбесін, сондай-ақ дәнді ботқалар мен йогурт беруге болады. Ең маңыздысы — бұл тағамдарға мүлде тұз, қант немесе дәмдеуіш қоспау керек. Ас болсын! 😊') WHERE id = '6bf67fbd-887e-4592-8237-816fbe1d635c';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Егер тазалыққа тым қатты мән берсеңіз, қосымша тағамға көшкен бөпеңіз Сізді біраз шаршатуы мүмкін. Өйткені бұл кезеңде бөпелер өздерін де, айналасын да міндетті түрде былғайды. Оларға әлемді танып-білу үшін осылай әрекет етуге мүмкіндік беру керек. Шамадан тыс кірпияздық пен тамақтану кезіндегі шағын келеңсіздіктерге теріс реакция таныту бөпеңізді мазасыздандыруы мүмкін екенін ұмытпаңыз. Әрине, алжапқыш кигізу сияқты қарапайым сақтық шараларын қолдануға болады, бірақ соған қарамастан ол айналаның бәрін былғап үлгереді. Болашақта стақан ұстауды, қасық қолдануды және қолымен тамақ жеуді бастағанда, айнала бұрынғыдан да көбірек ластанады. Көптеген бөпе үшін ыдыстарды, қасықтар мен тағамдарды араластырып, жерге лақтыру — тәбетін ашатын көңілді ойын. Сондықтан бөпеңізді тым шектемей, жинауды жеңілдету үшін еденге жай ғана дастарқан немесе төсеніш жайып қоюға кеңес береміз! 😊') WHERE id = 'f21f46f4-fb93-42c1-b00e-d167770d53ea';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіз дүниеге келген күннен бастап 8-айға дейін күнделікті өмірде Сіз қолданатын әрбір сөзді ұзақ мерзімді жадына сақтайды. Оның есінде қалған бұл сөздер тілінің дамуына, сол арқылы ақыл-ойының жетілуіне үлкен үлес қосады. Бұл үдерісті тиімдірек ету үшін бөпеңізбен көбірек сөйлесіп, әңгімелесу кезінде ол бұрын естімеген әртүрлі сөздерді қолдана аласыз. Мысалы, үйге қажетті заттарды алу үшін дүкенге бірге барғанда, өнімдерді көрсетіп, олар туралы айтып беріңіз. Таныстырған заттарыңыздың түсі, пішіні мен өлшемі туралы айтып, оны жаңа сөздермен таныстыра аласыз! Ал сыртқа шыға алмайтын күндері оған сүйікті кітабыңызды оқып, жаңа ән ыңылдап немесе қысқа ертегі айтып беруге болады. Осының арқасында бөпеңіздің тыңдау қабілетін дамытып қана қоймай, бірге көңіл көтере отырып, оның болашағына да үлес қосасыз! 😊') WHERE id = '6715507c-2cf7-4220-9f23-3cb7294e08b4';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңізді қатты жақсы көретініңізді және оның денсаулығына қаншалықты мұқият қарайтыныңызды білеміз. Алайда оны қанша жерден пайдалы тағамдармен тамақтандырсаңыз да, қазіргі кезде жиілеп бара жатқан тағамдық аллергия салдарынан бөпеңіздің иммундық жүйесі кейбір тағамдарды қабылдамауы мүмкін. Әсіресе қосымша тағам беру кезеңінде әртүрлі өнімдермен танысып жатқан бөпеңізді мұқият бақылауыңыз керек. Аллергия белгілері тағамды тұтынғаннан кейін бірден немесе 72 сағат ішінде байқалуы мүмкін. Бөпеңіздегі тағамдық аллергия тері бөртпесі, анус маңындағы қызару, еріннің көгеруі, ысқырықты тыныс немесе асқазан-ішек жолы мәселелері түрінде көрінуі мүмкін. Аллергенді тағамға тап болған ас қорыту жүйесі құсу, іш өту, қан аралас нәжіс немесе іш қату сияқты реакциялар беруі мүмкін. Сондықтан бөпеңізге алғаш рет ұсынатын тағамдарды абайлап бергеніңізді және қандай да бір жағымсыз белгі байқалса, дереу дәрігеріңізге хабарласқаныңызды ұсынамыз.') WHERE id = 'd5afcb47-37bb-45af-b1be-9bc9b6cc67d8';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бұл айда бөпеңіздің айналаны зерттеуге деген құштарлығы мен қызығушылығы шарықтау шегіне жетеді. Ол әлі де Сізге тәуелді болғанымен, енді өз бетінше әрекет ететін кеңістігін ұлғайта бастайды. Осы айда еңбектеуге талпынысының нәтижесін көре аласыз 😊 Мұндай талпыныстар кезінде бөпеңіз өзінің дербес тұлға екенін жақсырақ түсіне бастайды. Еңбектеумен қатар, бөпеңіз үшін тағы бір жаңалық — енді заттарға қолын бұрынғыдан да жақсы соза алуы. Қозғалыс аясы кеңейген сайын, оның айналаны зерттеуге деген құштарлығы да артады. Алайда бөпеңіз қазір оралды (ауыз арқылы танып-білу) кезеңде екенін ұмытпаңыз, яғни ол танығысы келген әрбір затты аузына салуға тырысады. Сондықтан қажетті қауіпсіздік шараларын қабылдауды еске салғымыз келеді.') WHERE id = '79d6e9ac-e4be-4d51-9c67-149f74a4f03c';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бұл айда бөпеңіздің екпе күнтізбесінде ешқандай вакцина қарастырылмаған. Дегенмен дәрігер жоспарлы тексеру кезінде оның салмағын, бойын және бас айналымын өлшейді. 7-айдан бастап бөпенің салмағы әдетте 5900 грамм мен 9000 грамм аралығында болады. 7 айлық бөпелердің орташа салмағы — 8100 грамм. Алайда әсіресе шала туған бөпелерде бұл орташа көрсеткіш төменірек болуы мүмкін екенін ескерген жөн. Бұл айда бөпенің бойы 61 см мен 75 см аралығында өзгеріп, орташа есеппен шамамен 67 см болады. Бөпенің миының дамуы туралы жалпы мәлімет беретін бас айналымы бұл айда 42.8 см мен 44 см аралығында болады. Егер бөпеңіздің физикалық дамуы осы көрсеткіштерге сәйкес емес деп ойласаңыз, нақты ақпарат алу үшін дәрігеріңізге жүгіне аласыз.') WHERE id = '7ae42d6a-0c42-4144-b394-cfd8c4804b24';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпенің аштық пен тоқтық механизмі дүниеге келген сәттен бастап жұмыс істейді және ол мұны Сізге міндетті түрде қандай да бір жолмен білдіреді. Сондықтан тамақтандыру кезінде бөпені мәжбүрлемеуіңіз және ол тамақтан бас тартқан кезде алаңдамауыңыз керек. Бөпеңіз біраз уақыттан бері қосымша тағам жеп жүрсе де, оған толық бейімделу үшін әлі де уақыт қажет болуы мүмкін. Дүниеге келгеннен бері ана сүтімен немесе сүт қоспасымен қоректенген бөпеңіз қою тағамдар мен жаңа дәмдерді бірден қабылдамауы мүмкін. Егер бөпеңіздің салмағы аз немесе ол жеткілікті тамақтанбай жүр деп ойласаңыз, тек салмақ қоссын деп калориясы жоғары, бірақ пайдасыз тағамдарды көп бермеуіңіз керек. Бөпенің дамуы тек тұтынған калория мөлшері мен салмағына қарай бағаланбайды. Сондықтан оған құнарсыз, бос калориялы тағамдардың орнына тағамдық құндылығы жоғары, пайдалы ас бергеніңіз жөн.') WHERE id = 'c7406d7d-33c9-4160-91a7-a354953cf5b3';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бұл кезеңде бөпенің өздігінен, ешкімнің көмегінсіз отыруы әлдеқайда жеңілдейді. Ол өз бетінше отырып, Сіздің көмегіңізсіз ойыншықтарымен ойнай бастағанда, көзіңізге ерекше сүйкімді көрінеді. Отыруды үйреніп, оны еркін жасай алатын бөпеңіз үшін бұл кезең — әрі айналасына жаңа қырынан қарауға, әрі дербестікке қол жеткізуге мүмкіндік беретін маңызды даму сатысы. Осының арқасында бөпеңіз үшін жаңа жаңалықтардың есігі ашылып, ол айналасын басқа қырынан көре бастайды. Арқа және мойын бұлшықеттері нығайған бөпеңіз енді басы мен аяқтарының қимылын жеткілікті деңгейде басқара алады. Бұл алдағы уақытта еңбектеу, тік тұру және жүру сияқты әрекеттерді оған жеңілдетеді. Алайда бөпеңіздің ұзақ уақыт тік отыра алмайтынын және кейде құлап қалатынын байқасаңыз, уайымдамаңыз. 😊') WHERE id = 'c06b62a5-8d7b-4555-9d57-8340da61ad39';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Осы айда бөпеңіз қосымша тағаммен тамақтанудың алғашқы айын аяқтады. Бір айлық тәжірибеден кейін ол шайнау, жұту, қолына алған тағамды аузына апару және өздігінен тамақтану сияқты дағдыларды меңгерген болуы мүмкін. Егер бұл кезең Сіз ойлағандай өтіп жатпаса, бірден алаңдамаңыз. Әр бөпе бұл үдерістен оңай өтеді деген ереже жоқ. Сіз сияқты сезімде жүрген аналар көп екенін білгеніңіз жөн. Егер бөпеңіздің қосымша тағамға тәбеті жоқ деп ойласаңыз, оның тамақты ынтамен жеуі және тағамға жақсы көзқарас қалыптастыруы үшін түрлі ойындар ойнай аласыз. Мысалы, «ұшақ ұшып келеді» ойынын ойнауға немесе ән айтып отырып тамақтандыруға болады. Бұл мәселедегі ең маңызды ережелердің бірі: бөпеңіз тоқтағысы келген кезде Сіз де тоқтап, біраз үзіліс жасауыңыз керек.') WHERE id = 'ca27271b-d34b-4ce7-b5f9-f4505e118771';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бұл айда бөпеңіздің әлеуметтік дағдылары айтарлықтай дамиды. Сондықтан ол өзімен қарым-қатынас жасайтын отбасы мүшелерін мұқият бақылай бастайды. Бөпеңіз осы кезеңге дейін жадында жинақталған ақпараттың арқасында себеп-салдар байланысын құруды үйренеді. Ол қол мен аяқ қимылдарын, тіпті бет әлпетіңізді қайталауға тырысса, таңғалмаңыз! 😊 Әрине, бұл Сізге де жауапкершілік жүктейді: жақсы үлгі болу! Өйткені бөпенің білуге деген құштарлығы өте жоғары және ол бәрін зерттеп-білуге көп күш салады. Оған зиян келтіруі мүмкін жағдайларда шектеу қоя аласыз, бірақ мұны асыра сілтемеу керек. Мысалы, бөпеңіздің жұтып қоюы мүмкін көлемдегі зат оның назарын аударып, зерттеу үшін қолына алса, оны бірден тартып алудың немесе қатаң әрекет етудің орнына, жақыннан бақылап, тек шынымен қажет болғанда ғана араласқаныңыз жөн.') WHERE id = '84211613-fc78-4c1f-a816-22b155e0b89d';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, '7-айда бөпе әлі де түрлі тағамдардың дәмін татып көретіндіктен, ол қосымша тағамға көшу кезеңінде болады. Бұл аса маңызды кезең бөпенің алдағы жылдардағы, тіпті ересек жастағы тамақтану әдеттеріне әсер етеді. Бөпеңіз кейде алғаш рет татып көрген тағамнан бас тартуы мүмкін. Бұл оның сол тағамды ешқашан ұнатпайтынын білдірмейді. Мұндай жағдайда сол тағамды біраз уақытқа алып қойып, бірнеше күннен кейін қайта ұсыну керек. Тіпті сол күннің ішінде тағамды ұсыну немесе дайындау тәсілін өзгерту де көмектесуі мүмкін. Бұл кезеңде бөпенің тістері әлі шықпаған болса да, ол түйіршікті тағамдарды қызыл иегімен езіп жей алады. Сондықтан мәзірге түйіршікті тағамдарды қосудан тартынбаңыз. Сонымен қатар мұндай тағамдар ауыз бен тіл бұлшықеттерін дамытып, бөпенің сөйлеуіне де оң әсер етеді.') WHERE id = 'b07bfb17-d3e7-4626-8576-6365ec3ad72a';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, '7-айға аяқ басқан бөпенің сезім мүшелері ересек адамдікіндей дерлік дамыған. Оның көру қабілеті де толық қалыптасты деуге болады. Соның арқасында ол алыстағы адамдар мен заттарды анық көріп, ажырата алады. Сондай-ақ айналасында болып жатқан жылдам әрі күрделі әрекеттерді бақылап, дұрыс қабылдайды. Кеңістіктің тереңдігін сезінуі толық қалыптасқандықтан, алыстан өзіне қарай келе жатқан затты көзімен қадағалап, оны ұстау үшін алға ұмтылуы мүмкін. 7 айлық бөпенің есту қабілеті де көру қабілеті сияқты жақсы дамыған. Енді ол дыбыстың қайдан шыққанын бірден түсініп, дыбыс шыққан жаққа тікелей бұрыла алады. Дегенмен баяу немесе алыстан естілген дыбысты тыңдау үшін біраз уақыт тынышталып, еш реакция білдірмей қалуы мүмкін.') WHERE id = 'e80c4140-2676-446b-a5dc-f1e0f240ee47';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Қосымша тағамға көшу кезінде жиі жіберілетін қателіктердің бірі — бөпеге әр тамақтанған сайын дерлік сорпа тәрізді сұйық тағам беру. Әсіресе сүйек сорпасынан дайындалған көженің пайдасы, әрине, өте көп. Алайда бөпенің тамақтану рационында сорпа негізгі орын алмауы керек. Түйіршікті әрі бөпенің шайнауына көмектесетін тағамдарды тым кеш беру кейбір жағымсыз жағдайларға әкелуі мүмкін. Өйткені мұндай тағамдар бөпенің тамақтану дағдысын қалыптастырып қана қоймай, ауыз қуысы мен тіл бұлшықеттерін де дамытады. Сондықтан блендерден өткізіліп, толықтай езбе күйіне келтірілген тағамдарды ұзақ уақыт бермеген жөн. Әйтпесе тіс шығару кезеңінде қатты тағамға көшу қиындап, бөпеңіз түйіршікті тағамды бөтенсіп, жеуден бас тартуы мүмкін.') WHERE id = '0eb37995-3090-4435-b8b9-edf48f0b68fb';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіз енді алдыңғы айлардағыдай тек дауысты немесе дауыссыз дыбыстарды жеке-жеке айтпайды. 7-айға аяқ басқан бөпеңіз дауысты және дауыссыз дыбыстарды біріктіріп, буындар құрайды әрі «бабабаба», «мамамама», «какакака» сияқты дыбыстар шығара алады. Бөпенің тілдік дамуын одан әрі қолдап, ынталандыру үшін бірнеше әрекет жасай аласыз. Мысалы, бөпенің көңіл күйі жақсы кезде ол шығарған дыбыстарды қайталап көріңіз. Бөпеңіз Сізге қарап, сөйлеу мәнеріңізді мұқият бақылайды және Сізге еліктеуге тырысады. Сөйлеген кезде ауыз қимылдарын сәл анық көрсету маңызды, өйткені осылайша бөпе дыбыс шығарғанда тілдің, еріннің және таңдайдың қалай қозғалатынын бақылай алады. Ендеше жұмыстарыңызды бір-екі сағатқа кейінге қалдырып, бөпеңізбен бірге көңілді уақыт өткізуге дайындалыңыз! Көңілді уақыт тілейміз 😊') WHERE id = '50599786-43fc-4007-9b26-bc49949f135e';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіз емшек сүтімен немесе сүт қоспасымен бірге қосымша тағам да жей бастады. Сондықтан оның салмағы көбірек қосылуы керек деп ойлауыңыз мүмкін. Алайда бұл олай емес. Бөпеңіз қазір әлдеқайда белсенді қимылдайды және өсуі жалғасып жатса да, алғашқы айлардағыдай көп салмақ қосады деп күтілмейді. Осы айда бөпеңіздің салмағы орта есеппен 350-400 грамға артады. Бұл сандар дамуын бақылауға арналған орташа көрсеткіштер ғана. Әр бөпенің өзінше дамитынын ұмытпаңыз: генетикасы, жынысы және зат алмасу ерекшеліктері көрсеткіштерге әсер етуі мүмкін. Жалпы қабылданған қағида бойынша, бөпенің 5 айлығында туған кездегі салмағы екі есе, ал 12 айлығында үш есе артады деп күтіледі.') WHERE id = '0bf43d37-a329-4f54-80f4-b9fdb2e13965';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Осы уақытқа дейін бөпеңізді көптеген жаңа дәммен таныстырдыңыз. Дегенмен кейбір тағамдарды неге әлі беруге болмайтыны туралы сұрақтарыңыз болуы мүмкін. Бұл бөпенің ас қорыту жүйесінің дамуына және ішектерінің дайындығына тікелей байланысты. Мысалы, көптеген ата-ананы сиыр сүтін неліктен рационға қоспау керектігі қызықтырады. Сиыр сүтінің құрамында дәрумендер мен минералдар мол болғанымен, ол бөпенің әлі толық жетілмеген бүйрегіне артық күш түсіреді. Сонымен қатар сиыр сүті бөпе ағзасына қажетті дәрумендердің орнын толық толтыра алмайды, бұл дамудың кешеуілдеуіне және өсудің баяулауына әкелуі мүмкін. Бұған қоса, сиыр сүтінде йод пен мырыш аз, ал бұл бөпенің зияткерлік дамуына кері әсер етуі ықтимал. Осы себептердің барлығына байланысты сиыр сүтін бөпеңіз 12 айға толғаннан кейін ғана тамақтану рационына біртіндеп енгізген дұрыс.') WHERE id = 'e49d6509-b260-4b7c-8420-cc63289843b1';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіз қысқа уақыт ішінде қандай үлкен даму жолынан өтті десеңізші, әрі ол Сізді әлі де таңғалдыра береді! 😊 Өкінішке қарай, бұл өзгерістердің барлығы Сізді үнемі қуанта бермеуі мүмкін. Мысалы, бөпеңіздің енді Сізден бөлек қалғысы келмейтінін және бұған қатты қарсылық білдіретінін байқауыңыз мүмкін. Сізді алаңдатуы ықтимал бұл жағдай бөпеде ажырау мазасыздығының (ажыраудан қорқудың) қалыптасқанын көрсетеді. Кейбір аналар үшін бұл мәселе болып көрінбеуі мүмкін, бірақ қажетті шаралар қабылданбаса, болашақта қиындық тудыруы ықтимал. Біраз уақыттан кейін Сіз қасында болмаған кезде оның көңілсіз болып, өзін қауіпсіз сезінбеуіне әкелуі мүмкін. Бұған жол бермеу үшін бөпеге күтім жасауға отбасы мүшелерін тартып, оны осындай жағдайға біртіндеп үйретуіңіз керек. Мысалы, бүгін кешкі асты бөпеге Сіздің орныңызға жұбайыңыз беріп, тамақтанғаннан кейін онымен оңаша уақыт өткізсін.') WHERE id = 'ee5d1f29-7924-4191-bd02-dbcf16926418';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Жұмысқа қайта оралуыңыз керек болса, бөпеңіздің психологиялық жағдайы мен күтіміне қатысты алаңдауыңыз мүмкін. Бөпелерде әдетте 6-айдан басталатын ажырау үрейі 12-айда шарықтау шегіне жетеді. Бұл үшін өзіңізді кінәлі сезінбеңіз, өйткені бұл — бөпенің дамуындағы қалыпты үдеріс. Жұмысқа оралуға аз уақыт қалғанда, қысқа мерзімге ажырап жүруге жаттыққан пайдалы болуы мүмкін. Бөпеңіз Сіздің кететініңізді түсінбесе де, онымен мейірімді әрі көңілді түрде қоштасып, қайта оралатыныңызды айтуыңыз керек. Мұндай жаттығулар кезінде бөпеңіз жатырқамауы үшін оны Сіз де, ол да танитын жақын адамыңызға қалдыра аласыз. Бөпеңізді сеніп тапсыратын адаммен алдын ала бірге уақыт өткізу бұл үдерісті едәуір жеңілдетеді.') WHERE id = '99e99257-b0ed-4e0f-b789-5eb260e3fd9d';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Тамақтану — бөпенің ең маңызды физиологиялық қажеттіліктерінің бірі. Сондықтан дұрыс әрі жеткілікті тамақтану бөпенің дамуы тежелмей, дені сау болып өсуінің негізгі шарты саналады. Алайда бөпеңіз әрдайым тамақты қарсылықсыз жей бермеуі мүмкін. Бөпеңіз үшін үлкен ықыласпен дайындаған пайдалы тағамдарыңыз кейде сол күйі қоқысқа кетуі ықтимал. Мұндайда ең алдымен бөпеңізбен тартыспауыңыз керек. Қайсарланып тұрып алсаңыз, оны табиғи әрі физиологиялық қажеттілік болып саналатын тамақтанудан одан әрі алыстатуыңыз мүмкін. Бұл Сіз бен бөпеңіздің арасына салқындық түсіруі де ықтимал. Сондықтан сабыр сақтап, қажет болған жағдайда не істеуге болатынын дәрігеріңізбен кеңесуіңіз керек.') WHERE id = '2f28f952-bd75-47db-822c-9ba614e24ba2';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпенің тамақтану және дастарқан басында отыру әдеттерін қалыптастыру кезеңінде оның ортақ дастарқанға қашан қосылатыны маңызды. Мамандар бөпелер ең кеш дегенде 9-айға дейін ата-анасымен бірге дастарқан басында отыруы керек деп есептейді. Сондықтан тамақтанатын уақыт келгенде, әсіресе бүкіл отбасыңызбен дастарқан басына жиналсаңыздар, бөпеңізді де бірге отырғыза аласыз. Ол үшін үстел жанына қойылатын арнайы тамақтандыру орындығы өте қолайлы. Бөпеңіздің тамақтандыру орындығында отырып, Сіздің және отбасының басқа мүшелерінің қалай тамақтанатынын бақылауы ол үшін өте пайдалы тәжірибе болады. Себебі мамандардың пікірінше, бақылау және көргенін қайталау — бөпелердің үйренуіндегі ең маңызды тәсілдердің бірі. Сондай-ақ тамақтану кезінде теледидарды қоспау және дастарқан басында жағымды орта қалыптастыру бөпеңіздің тамаққа деген ынтасын арттырады.') WHERE id = '2c9b0188-9d07-406a-bc48-6a8ce20aef72';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Өмірінің алғашқы айларында бөпеңіз қатты ұнатқан ойын төсенішінің аумағы енді еркінірек қозғалғысы келетін кішкентайыңызға тар әрі қызықсыз болып көріне бастайды. Белсенді қимылдай бастаған және жаңа нәрселерді зерттеуді бәрінен де жақсы көретін бөпеңіз үшін шектеліп отыру өте жалықтырады. Сондықтан оны ойын төсенішіне қойғанда, сол жерде қалғысы келмей, қарсылық білдіруі мүмкін! Мұндай сәтте оның еркіндік үшін дауыс көтеруін қалыпты қабылдап, өз қарсылығын білдіруіне мүмкіндік беруіңіз керек. Бөпеңіз үшін үйіңіздің бір бөлмесін, ал мүмкіндік болса, бүкіл үйді қауіпсіз етіп бейімдей аласыз. Алайда дайындаған ортаңыз қауіпсіз болса да, үнемі қырағы болып, оны әр сәт бақылауыңыз қажет. Қимыл-қозғалысы көп бөпеңізбен бірге үй шаруаларын атқару қиын болса, жұмыстарыңыздың бір бөлігін ол ұйықтап жатқанда немесе оған басқа адам қарап отырғанда істей аласыз.') WHERE id = '45a8e0d6-4932-4235-9823-06f0b7e8f85a';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, '7-ай — бөпенің жаңа қимыл-қозғалыс дағдылары айтарлықтай дамитын кезеңдердің бірі. Сондықтан айналасын зерттеуге құмар кішкентайыңыз үшін үйдегі қауіпті заттарға ерекше назар аударуыңыз керек. Көзіне түскен нәрсенің бәрін зерттегісі келетін бөпеңізге қауіп төндіруі мүмкін электр розеткаларын арнайы қорғаныш қақпақтармен жабуға болады. Сондай-ақ еденді дымқыл қалдырмай, электр сымдары мен оған ауыр жарақат келтіруі мүмкін өткір заттар сияқты қауіптердің бәрін толық жоюыңыз қажет. Жиһаз бен терезе жақтауларының өткір бұрыштарына бағасы қолжетімді арнайы қорғаныштарды орната аласыз. Үйіңізде бөпе жете алатын баспалдақ болса, оның кіретін және шығатын тұстарына міндетті түрде қорғаныш қақпа орнатуыңыз керек. Бұл шаралардың барлығындағы мақсат — бөпеңіздің Сіз белгілеген қауіпсіз шектер аясында айналасын еркін зерттеуіне мүмкіндік беру.') WHERE id = '616cd1ae-8a43-46fd-8952-aef7ae090d0b';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Қосымша тағамға көшу кезеңінде бөпеңіздің дамуы мен денсаулығы үшін оған тағамдық құндылығы ең жоғары азықтарды бергіңіз келуі мүмкін. Алайда Сізге пайдалы тағам бөпеңізге пайдадан гөрі көбірек зиян келтіруі ықтимал. Сондықтан дәрігеріңізбен бірге жоспарлаған тамақтану тәртібін ұстанып, бөпеңіздің ас қорыту жүйесінің даму деңгейіне сай әрекет етуіңіз керек. Мысалы, дәмсіз болып қалады деп ойлап, дайындалған картоп езбесіне аздап тұз қосу кімнің ойына келмейді дейсіз? Алайда мамандар бөпелер 1 жасқа толғанға дейін тұз бермеу керектігін қатаң ескертеді. Бұл кезеңде көкөністердің құрамындағы табиғи тұздар бөпеңізге жеткілікті. Ағзаға одан артық тұз түсуі бөпенің бүйрек қызметіне кері әсер етуі мүмкін. Мұқият болыңыз!') WHERE id = '6b656aed-9031-4b22-b6b9-5ed9b49d2799';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Қосымша тағам туралы ақпарат іздеген кезде BLW ұғымын кездестірген боларсыз. "Baby Led Weaning", қысқаша BLW деп аталатын бұл әдіс соңғы жылдары ата-аналар ең көп зерттейтін тақырыптардың біріне айналды. BLW ұғымын тілімізге "бөпенің жетекшілігімен қосымша тағамға көшу" деп аударуға болады. Бұл тәсіл бөпенің өздігінен тамақтану қағидасына негізделген. BLW әдісі басын тік ұстай алатын, тамақтандыру орындығында сүйеусіз отыратын және қолына берілген тағамды аузына апара алатын бөпелерге қолайлы. Осылайша бөпеңіз көмексіз-ақ өзі қалаған тағамды қалаған мөлшерде жей алады. BLW салыстырмалы түрде жаңа әдіс болғанымен, бақылаулар оның бөпелердің дамуына оң әсер ететінін көрсетеді.') WHERE id = '3224c721-5217-4489-ba14-724ab5302d3d';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіз көз алдыңызда өте жылдам өсіп келеді, солай емес пе? Оның еңбектей бастағанын көрсеңіз, мүлде таңғалмаңыз! 😊 Сирек болса да, кейбір бөпелер осы айда еңбектей бастауы мүмкін. Ал мұны әлі байқамаған болсаңыз, бөпеңіздің дамуы кешігіп жатыр деген сөз емес, сондықтан алаңдамаңыз. Бөпеңіздің қол, аяқ және арқа бұлшықеттері едәуір нығайды, соның арқасында ол өз осінен айналу дағдысын толығымен дерлік меңгерді. Сондай-ақ бөпеңізді етпетінен жатқызғанда, ол басын бірден көтеріп, қолына сүйене отырып денесін оңай бұра алады. Кейде осы айларда бөпелер әлі де сүйеусіз отыра алмауы мүмкін. Бұл жағдайда да бөпеңіз кешігіп жатыр деп саналмайды. Әдетте бөпелердің сүйеусіз отыру дағдысы шамамен 8-ші айда толық қалыптасады.') WHERE id = '2f3bbf20-95fe-4b29-88f7-dede7edfcc73';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Зерттеулерге сәйкес, ата-анасы жиі ән айтып, бесік жырын орындайтын бөпелер кейінгі айларда сөйлеу ырғағын жақсырақ қабылдайды. Сөйлеуді қоса алғанда, бәрін еліктеу арқылы үйренетін бөпеңіздің жанында сөздерді дұрыс әрі орынды қолдану өте маңызды. Мысалы, күн суық кезде «суық» деп айтып, тоңып тұрғаныңызды қимылмен көрсете аласыз. Осылайша бөпеңіз бұл сөзді дұрыс есте сақтап, себеп-салдар байланысын оңайырақ түсінеді. Сондай-ақ бөпеңізге жақсы үлгі болу үшін, қаншалықты сүйкімді көрінсе де, онымен кішкентай бала сияқты сөздерді бұрмалап сөйлеспегеніңіз жөн. Ол естіген сөздерін анық әрі түсінікті түрде есте сақтасын. Бұл үдерісті қызықтырақ ету үшін бөпеңіз шығарған дыбыстарды қайталай аласыз. Бұл оған қатты ұнайды әрі бірге көңілді уақыт өткізесіздер.') WHERE id = '015590a4-be89-40bd-9634-b5bb65d23d50';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіз қосымша тағамға көшкен кезде BLW (бөпенің өзі басқаратын тамақтану) әдісін қолдану оның дамуына үлкен үлес қосады. Бұл әдістің белгілі бір қағидалары бар. Дәстүрлі тәсілдегідей ананың тамақтандыруы емес, бөпенің өздігінен тамақтануы маңызды. Алғашқы 6 айда тек ана сүтін немесе сүт қоспасын ішкен бөпеңізге, әсіресе өтпелі кезеңде, қосымша тағамды бірден күніне 3 рет бермеуіңіз керек. Сондай-ақ бөпеңізді бұл тағамдарды жеуге мәжбүрлемеңіз және бас тартқан жағдайда қыстамаңыз. Күніне бір реттен бастап, біртіндеп көбейтіңіз, ал ұсынатын тағамдарды бөпеңіз қолымен оңай ұстай алатындай етіп дайындаңыз. Осы уақыттың бәрінде бөпеңізді ешқашан жалғыз қалдырмай, әр әрекетін мұқият бақылауыңыз қажет. Бұл әдістің мақсаты — бөпенің дәмдерді өздігінен танып, қол-көз үйлесімін дамыта отырып, өз бетінше тамақтануды үйренуіне көмектесу.') WHERE id = 'b805a548-3277-455e-8a43-b5228959fd35';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіздің қабылдау қабілеті дамыған сайын, ол енді өзін жайлы сезінгенін немесе мазасызданғанын Сізге анық білдіре алады. Ол мұны қимылдары мен бет әлпеті арқылы көрсете бастайды. Қарым-қатынас жасау үшін көңілді немесе мазасыз екенін білдіретін дыбыстар шығаруды жалғастырады. Осы уақытқа дейін бөпеңіздің негізгі қарым-қатынас құралы жылау болса, енді тілінің дамуына байланысты өзін білдіру үшін мағынасыз буындар айта бастауы мүмкін. Сөйлеу кезінде ауыз қимылдарын тиімдірек қолдана бастағандықтан, бұл буындарды анығырақ шығарады. Мағынасыз болса да, әртүрлі буындарды айта алуы — бөпеңіз үшін маңызды кезең. Өйткені бұл дыбыстар — бөпеңіздің алғашқы шынайы диалогтерінің бастауы; ол шығарған дыбыстарымен тәжірибе жасап, жауап беріп, әлеуметтік байланыс орната бастайды.') WHERE id = '811dc858-78e1-4c23-aea6-584681b23792';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Қосымша тағам беру кезеңінде, әсіресе алғашқы кездері, бөпеңіздің шашалып қалуы Сіздің ең үлкен қорқынышыңыз болуы мүмкін. Тыныс алуына бір нәрсе кедергі келтірсе, бөпеңіз одан құтылу үшін барын салады. Егер жеген тағамы тамағына тұрып қалып, бөпеңіз жөтеле, жылай және дыбыс шығара алса, демек тыныс жолы толық бітелмеген. Бөпеңіз бұл жағдайды өздігінен жеңе алуы әбден мүмкін. Мұндайда ең дұрысы — сабыр сақтап, бөпеңізге сенімділік беру. Алайда бөпеңізде тұншығудың ауыр белгілері байқалса, 103 нөміріне қоңырау шалып, дереу алғашқы көмек көрсету арқылы тыныс жолын ашуға тырысуыңыз керек. Сондықтан сенімді дереккөздерден бөпелерге алғашқы көмек көрсету ережелерін үйрену өте маңызды.') WHERE id = '880904da-8e52-4e39-93ed-5f35ec843a62';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіз сөйлей бастаған кезде оның тілдік дағдылары да қатар дами бастайды. Алғашқы уақытта өзі не айтып, қалай айтып жатқанын түсінбесе де, мағынасыз дыбыстар біртіндеп нақты сөздерге айналады. Былдырлау бөпеңіздің ой-өрісінің дамуын жеделдетіп қана қоймай, дыбыстарды қайталау және есте сақтау тәжірибесін қалыптастырады. Осылайша, бөпеңіз не айтқысы келетінін ойластырып, қалауы мен қажеттіліктерін жеткізу үшін сөздер мен қимылдарды қолдануды үйренетін кезеңге аяқ басады. Дегенмен нақты сөздерді айта бастауы үшін әлі біраз уақыт қажет болуы мүмкін. Осы аралықта бөпеңіз Сізді бақылап, қайталау арқылы тілдің ережелерін меңгере береді. Сондықтан сөздерді дұрыс, анық әрі орынды қолдануыңыз өте маңызды.') WHERE id = '8f6d0ab5-b074-476e-95ce-1532c933bec4';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпе қаңқасының берік болуы сүйектерінің дұрыс дамуына байланысты. Құрсақта жатқан кезде басталатын бұл үдеріс, әсіресе өмірінің алғашқы жылында өте жылдам жүреді. 6-айдан бастап қосымша тамақ жей бастаған бөпеңіздің сүйектері мықты болуы үшін қазірден қамданғаныңыз жөн. Бұл кезеңде оның негізгі қорегі әлі де ана сүті немесе сүт қоспасы болғанымен, қосымша тамақпен бірге кальцийге бай өнімдерді де тұтынуы керек. Қосымша тамақтандыру кезеңі ілгерілеген сайын бөпеңіздің ана сүтінен алатын дәрумендері мен минералдарының мөлшері біршама азаяды. Сондықтан сүйектердің нығаюына елеулі үлес қосатын кальций өте маңызды. Бөпеңіздің ағзасы жеткілікті мөлшерде кальций алуы үшін ас мәзіріне йогурт пен жасыл жапырақты көкөністер сияқты өнімдерді енгізе аласыз.') WHERE id = '2697c6e2-7952-4ec2-98c7-54307a2fe921';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бұл кезеңде өміріңіз бұрынғыдан да қарбалас әрі күрделі болуы мүмкін. Әсіресе қазір әлдеқайда белсенді болған бөпеңізбен бірге бәріне қалай үлгереріңізді білмей, жоспарларыңызды жүзеге асыруда қиналуыңыз ықтимал. Осы кезеңде өміріңізді жеңілдетуге көмектесетін көптеген пайдалы кеңес бар. Олардың кейбірін қолдану арқылы өзіңізді біршама жеңілдете аласыз. Алдымен бөпеге күтім жасау, өз күтіміңіз және үй шаруасы бойынша бәрін ретке келтіріп көріңіз. Бөпеге күтім жасау кезінде үнемі қолданатын заттардың арнайы орны болсын. Үйде бөпеңіздің жөргегін ауыстыратын жеке орын дайындауға болады. Осылайша әр жолы жөргек, дымқыл майлық және жөргек ауыстыруға арналған төсеніш сияқты қажетті заттарды бір-бірлеп іздеудің қажеті болмайды. Сондай-ақ бөпеңізбен сыртқа шыққанда керек болатын заттарды үйден шығар сәтте ғана жинамаңыз. Ана мен балаға арналған дайын сөмкені әрдайым есікке жақын жерде ұстай аласыз.') WHERE id = 'f71171e4-2818-49d6-8552-7761b12126d4';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Осы күндері бөпеңіз ұзаққа созылатын даму секірісі кезеңіне аяқ басуы мүмкін. Сондықтан оның ұйқы мен тамақтан бас тартуы, мазасыздануы және жиі құшаққа сұрануы ықтимал. Алтыншы даму секірісі бөпенің болжамды туылу күнінен бастап есептегенде 34-37-апталар аралығында болады. Бұл кезеңнің негізгі ұғымы — санаттау. Біраз уақыттан бері айналасын зерттеп, көрген тірі/жансыз нысандардың бәрін мұқият бақылап жүрген бөпеңіз енді оларды санасында санаттарға бөле алады. Мысалы, бөпеңізбен бірге итті кездестірдіңіз делік. Сіз итті көрсетіп, «ау-ау» дедіңіз. Бөпеңіз оны санасында өзінше бір санатқа жатқызады. Бірнеше күннен кейін далада мысықты көргенде, оған да «ау-ау» деп жауап беруі мүмкін. Өйткені бөпеңіз төрт аяқпен жүретін тіршілік иелерін өз түсінігінде бір санатқа біріктірген. Мұның дұрыс емес екенін айтқыңыз келіп тұрғанын білеміз. Алайда бөпеңіздің әзірге олардың арасындағы айырмашылықты ажырата алмауы — қалыпты жағдай.') WHERE id = '18fded6c-68c1-4a2f-8a8c-2cce06aa19e7';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңізге қанша сұйықтық беру керектігін дәрігеріңіздің кеңесі мен өз бақылауларыңызға сүйеніп шеше аласыз. Егер бөпеңіз күні бойы әлсіз болса, құсса немесе тамақтан бас тартса, ағзасы сусызданды деп күдіктенуге болады. Сондай-ақ ағзаға сұйықтық жетіспегенде дене қызуы физиологиялық тұрғыдан көтеріледі. Сондықтан дене қызуын белгілі бір уақыт аралығында тексеріп отыру пайдалы болуы мүмкін. Сусызданудың негізгі белгілері: сирек әрі қою түсті зәр шығару, ауыздың құрғауы, көз жасынсыз жылау. Бұған қоса, осы кезеңде ана сүтін немесе сүт қоспасын тым азайту бөпе ағзасының сусыздануына әкелуі мүмкін. Сусызданудың алдын алу үшін атқаратын ең маңызды әрекеттердің бірі — бөпеңіздің күнделікті жеткілікті мөлшерде сұйықтық ішуін қамтамасыз ету.') WHERE id = '61c2e7d6-1d91-41c2-969b-396148013b25';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіз бір сәтке де тоқтамай, таңғаларлық жылдамдықпен дамып келеді! 8-айға аяқ басқан осы күндерден бастап ол айналасын бұрынғыдан жақсырақ түсініп, нақты мақсатына сай әрекет ете бастайды. Басқаша айтқанда, бөпеңіз енді қалауын жыламай-ақ білдіре алады. Мысалы, қарны ашқанда мазасызданып, қыңсылап немесе жылаудың орнына «мәм-мәм» (тамақ) деп анық айтқанын естуіңіз мүмкін. Шөлдегенде стақанын көріп қуанады, ал қарны ашқанда тамағын дайындап жатқаныңызды көрсе, қатты шаттанады. Бұл — бөпеңіздің дамуындағы маңызды бетбұрыс: енді ол өз қалауын Сізге қарапайым түрде түсіндіре алады. Мөлдіреген көзімен Сізден бір нәрсе сұрағанда, «иә» немесе «жоқ» деген жауабыңыздың мағынасын түсінеді. Дегенмен бұл жауаптан кейін не істейтіні толығымен өзіне байланысты. 😊') WHERE id = '1886ab50-5a60-4760-b927-fa91d9c42779';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіз жақсы ойнаумен қатар, айналасын мұқият бақылайтын болды. Ол Сізді және отбасының басқа мүшелерін зейін қойып бақылап, әрекеттер мен дыбыстарды қысқа уақыт ішінде қайталай алады. Мысалы, әкесі жұмысқа кетіп бара жатқанда Сіздің қол бұлғап қоштасқаныңыз бөпеңіздің назарын аударуы мүмкін, сонда ол да кетіп бара жатқан адамның артынан қол бұлғайды. Өйткені өзі шығаратын дыбыстар мен ым-ишаралар енді ол үшін белгілі бір мағынаға ие бола бастайды. Сондықтан бір нәрсе қажет болғанда, буындарды жиірек қайталайды. Айналасындағы адамдар мен оқиғаларды аңғара бастаған бөпеңіздің туа біткен рефлекстерін енді толықтай саналы әрі мақсатты қимылдар алмастырады. Бұл оның қысқа уақыт ішінде қаншалықты жылдам дамығанын көрсетеді. 😊') WHERE id = '980f8f43-3138-49d0-a45d-59c21bfd0cd3';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіз бұрын-соңды болмағандай қимылдайды және басқа бөпелер сияқты жөргегін ауыстырғанды мүлде ұнатпауы мүмкін. 😊 Әсіресе жөргегін ауыстырғанда, кір жөргекті шешу оған жеңілдік береді. Сондықтан таза жөргекті қайта кигізетініңізді көргенде, қол-аяғымен қарсылық көрсетуі мүмкін. 😊 Ал бөпеңіз еңбектей бастаған болса, жөргегін кигізу үшін біраз уақыт оның артынан жүгіруге тура келуі ықтимал. Қарсылық көрсеткен бөпеңізбен қасарысу оған күйзеліс тудыруы мүмкін. Сондықтан жөргек ауыстыру үдерісін қызықтырақ етіп, өз жұмысыңызды жеңілдете аласыз. Мұның ең қарапайым жолы — әрине, оның назарын басқа нәрсеге аудару. Жөргегін ауыстырғанда ән айту, не істеп жатқаныңызды айтып отыру және сүйікті ойыншығымен ойнауына мүмкіндік беру жұмысыңызды едәуір жеңілдетеді. 😊') WHERE id = 'fe2747a5-5b02-4aab-bf69-6b7fa1ec81f8';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіздің ақыл-ой белсенділігі ең қарқынды дамитын кезең басталды. Бөпеңіз жақын жердегі дыбыстарды анық естіп қана қоймай, ересектер сияқты алыстан шыққан дыбыстарды да ажырата алатындай сезімдік қабілетке ие. Көру, есту және тереңдікті қабылдау қабілеті айтарлықтай дамыған бөпеңіз айналасын жылдам зерттеп келеді. Сондықтан оның қолдары, аяқтары үнемі қозғалыста болады. Ол барлық саусағын белгілі бір мақсатпен пайдаланып, заттарды мықтап ұстай алады. Сондай-ақ шамасы жететін заттардың бәрін итеру және кішкентай саңылауларды шұқылау үшін сұқ саусағын белсенді қолдана бастайды. Сол себепті электр розеткалары сияқты бөпеңізге қауіп төндіруі мүмкін заттарға қатысты тиісті сақтық шараларын қабылдауыңыз қажет.') WHERE id = '0856b508-32f1-46be-891e-90f4409ee60b';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіз қосымша тамаққа әбден үйреніп қалды. Егер оған тағамдарды әлі де езбе түрінде беріп жүрсеңіз, енді түйіршікті тағамдарға көше аласыз. Мамандар осы айдан бастап бөпелердің шайнау дағдысы қалыптасатындықтан, қою әрі тығыз тағамдар бере бастауды ұсынады. Ұзақ уақыт бойы тек езбе және аздап түйіршіктелген тағамдар беру болашақта бөпеңізде тамақтану бұзылыстарына әкелуі мүмкін. Алайда тағамның қоюлығын бірден арттырмаған дұрыс. Өйткені тым жылдам ауысу іш қатуға және ас қорыту жүйесіндегі кейбір мәселелерге себеп болуы ықтимал. Сондықтан тағамның түйіршіктілігін күн сайын аздап арттырып, біртіндеп ауысуыңыз керек.') WHERE id = '72760305-9a29-4db8-960b-c7c0f371cc22';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Осы айдан бастап бөпеңіз ешқандай сүйеусіз өздігінен еркін отыра алады. Қол және аяқ бұлшықеттері нығайғандықтан, еңбектеу оған әлдеқайда оңай болады. Бірақ бұл әр бөпе міндетті түрде еңбектеуі керек дегенді білдірмейтінін ұмытпаңыз; бөпеңіз еңбектемесе, бұл дамудың кешеуілдеуі болып саналмайды. Сондай-ақ үйіңізде баспалдақ болса, қозғала бастаған бөпеңіз оған оңай өрмелей алатындықтан, тиісті қауіпсіздік шараларын қабылдауыңыз керек. Осы айда бөпеңіз отырған жерінен бір заттан ұстап, орнынан тұруға әрекеттенуі және әдетте сүйеніп, аз уақыт аяқта тұра алуы мүмкін. Ол әлі жүре алмаса да, қолтығынан ұстасаңыз, қадам басу рефлексін көрсетуі ықтимал. Алайда оны бұған мәжбүрлемеңіз; бөпеңіздің өз қалауы Сізге ең дұрыс жолды көрсетеді.') WHERE id = 'a563d702-5875-4391-a1d5-846178e0f653';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Енді бөпеңіздің тамақтану мәзіріне кептірілген бұршақ тұқымдастарды, жасымық пен балықты қоса аласыз. Шайнау дағдысы дамып келе жатқан бөпеңіздің ас қорыту жүйесі де күн сайын жетіліп, осы тағамдарды қабылдауға дайын болады. Кептірілген бұршақ тұқымдастар ақуызға деген қажеттілікті өтеуі және дәрумендер мен минералдарға бай болуы жағынан өте маңызды. Ал жасымықтың құрамында темір, B дәрумені, фолий қышқылы және әртүрлі минералдар мол. Тағамдық құндылығы қызыл етпен шамалас жасымық бөпеңіздің дұрыс тамақтануы үшін таптырмас өнім. Сонымен қатар жаңа дағдыларды меңгеріп жатқан бөпеңізге Омега-3 май қышқылдары өте қажет. Оның мәзіріне қосатын балықтың құрамында A және D дәрумендерімен қатар, Омега-3 май қышқылдары да мол.') WHERE id = '5436fc4f-86ab-41cc-af9e-5a2f20f1be86';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіз енді қарапайым әрі даму деңгейіне сай жаңа ойындарды оңай үйрене алады. Сондықтан оны нағыз ойынқұмар кезеңге аяқ басты десек, қателеспейміз. Сізге сәттілік! 😊 Бөпеңіздің бұл қабілетін дамыту үшін онымен жиі ойнауға болады. Ол Сізді қызығушылықпен бақылап, мұқият тыңдайды. Сондай-ақ қол икемділігі едәуір дамыған бөпеңіз жерден тапқан ойыншығын саналы түрде қолына алып, емін-еркін ойнай алады. Алғашқы айлармен салыстырғанда өзін дербес сезіне бастаған балақай жоғалтып алған немесе түсіріп алған ойыншықтарын іздеп, оларды Сізден сұрамай-ақ өзі ала алады. Ол ойыншықтар мен айналасынан тапқан заттарды сілкіп, соғып немесе лақтырып, дыбыс шығаратынын не шығармайтынын тексеруі мүмкін. Тіпті ойыншықпен ойнап болмаған болса, оны қолынан алуыңызға жол бермей, қарсылық білдіреді.') WHERE id = 'fe525d42-0a0a-48cc-aa11-ecad88d56b2a';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңізге үйреткіш стақанды қашан бере бастау керектігі туралы сұрақтарыңыз болуы мүмкін. Дұрыс уақыттың келгенін бөпеңізді бақылау арқылы ғана түсіне аласыз. Егер оның тілмен итеру рефлексі жоғалса, демек, ол үйреткіш стақанды қолдануға дайын. Тілмен итеру рефлексі — алғашқы айларда бөпенің аузына түскен бөгде затты тілімен автоматты түрде сыртқа итеруі. Негізінде бұл рефлекс бөпеңіз үшін өте маңызды, өйткені ол тұншығып қалу қаупінен қорғайды. Орта есеппен 4-ші айдан бастап бұл рефлекс бәсеңдейді, ал 6-8-ші айлар аралығында толығымен жоғалады. Бұл рефлекстің жоғалуы — бөпеңіздің бөтелкенің орнына стақаннан су ішуге дайын екенінің алғашқы белгісі.') WHERE id = '52c260d9-9803-4e1b-9fc5-0c188ff2d7d3';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, '8 айлық бөпелердің салмағы орта есеппен 8000 грамм шамасында болады. Сонымен қатар бөпенің салмағы 6300 бен 11000 грамм аралығында болуы мүмкін. Алайда әсіресе осы айда қимыл-қозғалысының артуына байланысты салмақ қосуы баяулап, ай соңында таразыдағы көрсеткіш орта есеппен 250-650 грамға ғана артуы мүмкін. Егер бөпеңіз мерзімінен бұрын дүниеге келсе, ол құрдастарын қуып жетуі мүмкін. Ал әлі қуып жетпесе де, алаңдамаңыз, әлі кеш емес. Салмақ көрсеткіштерінің осындай кең ауқымда болуы қыздар мен ұлдардың бойы мен салмағының өсуіндегі айырмашылықтарға да байланысты. Бөпеңіздің салмақ қосуына немесе салмақ қосу қарқынының баяулауына қатысты дәрігерге айтпай, ешқандай әрекет жасамауыңыз керек. Әр бөпенің дамуы өзінше ерекше екенін ұмытпаңыз: ең төменгі немесе ең жоғарғы шектегі бөпелер де толықтай сау болуы мүмкін.') WHERE id = '639ac35e-714a-47fc-b5c3-a25af9dcd029';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіз біраз уақыт бұрын басталған қосымша тағамға әбден үйреніп қалды, бірақ ана сүтін немесе жасанды қоспаны қабылдауды да жалғастырып жүр. Әсіресе осы кезеңде бөпенің қанша қосымша тағам жеуі немесе қанша сүт ішуі керектігін есептеу шаршатуы мүмкін. Алайда біраз уақыт бойы бөпеңіздің негізгі қорегі Сіздің сүтіңіз немесе жасанды қоспа болып қала беретінін ұмытпау керек. Осы айдан бастап қажеттілігі қимыл-қозғалысы мен зат алмасу жылдамдығына қарай өзгергенімен, оған тәулігіне орта есеппен 850 калория қажет. Бөпеңіздің ішек саулығын сақтау үшін ол осы калорияның жартысынан көбін әлі де сүттен алуы керек. Осы тепе-теңдікті сақтау және шатаспау үшін бөпеңіз ашыққан кезде алдымен оны емізіңіз немесе сүтін беріңіз. Содан кейін оған аса үлкен емес мөлшерде құнарлылығы жағынан теңгерімді ас дайындаңыз. Бұл кезеңде бөпеңіздің қажеттілігіне қарай тағам мөлшерін арттыра аласыз.') WHERE id = 'aaf40c8d-b2ab-4458-8b62-ca1e766f4975';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіз қосымша тағамды шамамен 2 ай бұрын жей бастаса да, 2 жасқа дейін оның негізгі қорегі әлі де ана сүті болып қала береді. Сіз беретін қосымша тағамдар тек тіскебасардың орнын басады. Сондықтан сүт беруді азайту бөпеңіздің дамуын баяулатуы мүмкін. Егер соңғы кезде бөпеңіздің тәбеті жоқ деп ойласаңыз, мұндай жағдайға тап болған жалғыз Сіз емес екеніңізді еске салғымыз келеді. 😊 Белсенді ойын кезеңіне аяқ басқандықтан, бөпеңіз тамақтану және ұйқы сияқты қажеттіліктеріне көп уақыт бөлгісі келмеуі мүмкін. Сондықтан оның ең сүйікті ісі — ойынды тамақтану уақытымен біріктіре аласыз! Тамақтануды қызықты ету үшін тағамды тартымды етіп тәрелкеге салып, ас ішкен кезде ку-ку немесе ұшақ ұшып келеді сияқты ойындар ойнай аласыз. Сондай-ақ саусаққа киілетін қуыршақтарды да қолдануға болады. Көңілді уақыт өткізіңіздер! 😊') WHERE id = 'd21c1f6a-5fc9-4cad-8563-f3edc47a4f56';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Осы айдан бастап бөпеңіздің бас айналымының төменгі шегі 41 см, ал жоғарғы шегі 47 см болады. 8 айлық бөпенің бас айналымы орта есеппен шамамен 44 см болады. Бас айналымының өсуі ми дамуының көрсеткіші болғандықтан, оны жүйелі түрде өлшеп отыру қажет. 8-ші айдағы бөпенің бойы 62 см мен 77 см аралығында болуы мүмкін. Сондай-ақ осы кезеңде бөпеңіздің еңбегі қатая бастағанын байқауыңыз мүмкін. Әдетте 12-18 ай аралығында жабылады деп күтілетін еңбек кейбір бөпелерде 8-ші айда-ақ жабыла бастайды. Егер мидың дамуы жалғасып жатса, бұл физиологиялық тұрғыдан қалыпты жағдай саналады және алаңдаудың қажеті жоқ.') WHERE id = '4019cfbc-4717-4ff6-83d7-b0dd34ad99d7';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіз жасына сай кейбір даму дағдыларын әлі көрсетпей жүргендей көрінуі мүмкін. Әр бөпенің өсу және даму қарқыны әртүрлі болғандықтан, мұндай жағдай да әрқалай болады. Дамудың кешеуілдеуі деп отыру, еңбектеу, жүру, тік тұру және сөйлеу сияқты дағдылардың баяуырақ қалыптасуын айтады. Көбіне бұл уақытша даму кідірісі болады және бөпелердің басым көпшілігі қысқа мерзімде қатарластарын қуып жетеді. Жаңа дағдылар белгілі бір ретпен қалыптасқанымен, әр бөпенің өзіндік даму ырғағы бар екенін ұмытпаған жөн. Мысалы, кейбір бөпелерде отыру сияқты жалпы қимыл-қозғалыс дағдылары, ал басқаларында заттарды ұстау және қармау қабілеті ертерек дамуы мүмкін. Дегенмен көңіліңіз тыныш болуы үшін Сізді алаңдататын жайттарды дәрігеріңізбен талқылай аласыз.') WHERE id = '66787d5e-85c6-4974-9795-692e078d138d';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіз ояу уақытының басым бөлігін айналасын зерттеп, жаңалық ашуға жұмсайды. Егер бөпеңіз зерттеу барысында бір жерге сүйеніп орнынан тұрса, табанының жерге толық тиюі маңызды. Бұл аяқ бұлшықеттерінің дамуы үшін өте қажет және көпшілік ойлағандай жалпақтабандылыққа әкелмейді. Алайда тегіс жерде тайып кетпеуі және жазатайым жағдайлардың алдын алу үшін табаны сырғымайтын мәсі немесе жұмсақ аяқ киім кигізе аласыз. Далаға шыққанда бөпеңіз әлі өздігінен толық жүре алмаса да, аяғын ыстық пен суықтан қорғау үшін аяқ киім қажет болуы мүмкін. Бұл кезеңде алғашқы қадамдарға арналған арнайы аяқ киім сатып алу міндетті емес. Таңдайтын аяқ киім бөпеңіздің аяғына жақсы қонып, тобығын ұстап, тірек болса жеткілікті.') WHERE id = 'b84764db-feb1-47bf-b057-d7266054d43f';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Жүктілік кезінде Сізді ең көп қызықтырған мәселелердің бірі бөпеңіздің көзінің түсі қандай болатыны шығар. 😊 Туғаннан кейін бөпенің көзі әдетте сұр-көк түсті болып көрінеді. Бұл реңктер өте сүйкімді көрінгенімен, өкінішке қарай, уақытша ғана. Себебі көздің түсті қабаты әлі толық дамып үлгермегендіктен, түскен жарықты сол күйінде шағылыстырады. Ал осы айдан бастап пигментация үдерісі толығымен дерлік аяқталып, бөпеңіздің көздері өзінің табиғи түсіне ене бастайды. Егер бөпеңіздің көзі қоңыр түске айналса, енді оның басқа түске өзгеру ықтималдығы жоқ. Ал көзі әлі де ашық түсті болса, 12 айға толғанға дейін басқа түске өзгеруі мүмкін екенін ескерген жөн.') WHERE id = 'afcad808-5171-4e03-8941-cb9235ad0674';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіздің емшек сүтін немесе сүт қоспасын ішуі азайған сайын, тағамнан жеткілікті дәрумен алып жүр ме деп алаңдауыңыз мүмкін. Ең алдымен, кез келген дәруменді немесе тағамдық қоспаны бермес бұрын міндетті түрде дәрігеріңізбен кеңесу қажет. Сонымен қатар бөпеңізді біржақты тамақтандырудан сақтанып, ас мәзірінің алуан түрлі болуына көңіл бөліңіз. Бөпеңіздің дәрумендер мен минералдарға қажеттілігін өтеуде әсіресе маусымдық жемістер мен көкөністер маңызды. D дәрумені мен қан түзілуін қолдайтын дәрілердің (темір тамшыларының) әдетте жоспарлы түрде берілетінін және бұл стандартты шара екенін ұмытпаңыз. Егер бөпеңіз шала туған болса, салмағы аз болса немесе дамуында кешеуілдеу байқалса, дәрігер қосымша қолдау құралдарын ұсынуы мүмкін. Алайда әр бөпе әртүрлі, сондықтан ең дұрыс кеңесті Сіздің және бөпеңіздің жағдайын жақсы білетін дәрігер ғана бере алады.') WHERE id = 'a7e33135-d849-4e1d-b626-072569cf1acd';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіз енді ешкімнің көмегінсіз өздігінен еркін отыра алады. Бұл дағды оның оңай бұрылуына, жүрелеп отыруына және еңбектеуіне негіз болады. Ол еңбектей бастаған да шығар. 😊 Дегенмен кейбір бөпелердің еңбектеу кезеңін өткізіп жіберіп, бірден жүре бастауы да қалыпты жағдай. Үнемі қозғалыста жүретін кішкентайыңыз назарын аударған нәрсені көргенде, сол бағытқа қарай еңбектеп немесе жылжып баруға тырысады. Қызықтырған затын тапқан соң, оны танып-білу үшін қолына алып қарап, аузына салуы мүмкін. Сондықтан оны бұрынғыдан да мұқият қадағалап, әлі жасамаған болсаңыз, үйде қажетті қауіпсіздік шараларын қабылдауыңыз керек.') WHERE id = 'f711661c-b42b-4a2c-9389-6ca7cb481b26';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіз әлі де дамудың қарқынды секірісі кезеңінде болуы мүмкін, сондықтан кейбір қиындықтарға тап болуыңыз қалыпты. Қарқынды өсу мен жаңа дағдыларды меңгеру кейде тәбеттің төмендеуіне әкелуі мүмкін, ал кейбір бөпелерде, керісінше, тәбет айтарлықтай артады. Сол себепті кішкентайыңыз күн ішінде емшекті жиірек сұрауы мүмкін. Бұл кезеңде оған қалағанынша қосымша тағам да бере аласыз, өйткені ағзасына қарқынды даму үшін қосымша қуат қажет; бұл қажеттілік өтелмесе, ол мазасыздануы мүмкін. Сондай-ақ осы кезеңде ажырау мазасыздығы күшейіп, Сіздің жанынан кеткеніңізді қаламауы мүмкін. Мұндай сәттерде бөпеңіздің психологиялық саулығын ескеріп, оны түсінуге тырысып, сабырлы болуға кеңес береміз. 😊') WHERE id = 'a8e0d4f7-6afa-42e9-8b05-07856071a068';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпенің ұйқы режимі кей кезеңдерде өзгеріп тұруы мүмкін. Бұл айда бөпеңіз тәулігіне шамамен 14-15 сағат ұйықтайды, оның басым бөлігі түнгі ұйқыға тиесілі. Дегенмен күндізгі ұйқы бөпеңіздің дамуына оң әсер етіп, жаңа дағдыларды меңгеруіне көмектесетіндіктен, оған күндіз де ұйықтау қажет. Соңғы зерттеулер бөпелердің күндізгі алғашқы екі ұйқысы олардың дамуында ерекше рөл атқаратынын көрсетеді. Көптеген бөпелер күні бойы өте белсенді болғандықтан, енді түні бойы оянбай ұйықтай алады. Егер бөпеңіз әлі де түнде оянатын болса, алаңдамаңыз, бұл да қалыпты жағдай.') WHERE id = '71a3cc6c-7792-4d5e-b2d9-206c74922dd9';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіз әлі де қатты тағамға көшу кезеңінде, сондықтан дәмін татқан әрбір жаңа тағам ол үшін жаңа жаңалық. Егер BLW (бөпенің өздігінен тамақтануы) әдісін қолдансаңыз, бұл кезең сіздер үшін қызығырақ өтуі мүмкін. Өйткені бұл әдіс арқылы бөпе тағамдарды өзі жеп көріп, табиғи түрде зерттейді. Үстел маңы аздап шашылып, былғануы мүмкін, есесіне балақайыңыз тағамдардың дәмін, құрылымын және иісін жақсырақ ажыратып, тиімді үйренеді. Осы үдерістің арқасында ол көлем, пішін, салмақ және текстура сияқты ұғымдарды көптеген қымбат дамытушы ойыншықтарға қарағанда жақсырақ түсінеді. Сондай-ақ осылайша қол мен көз үйлесімін дамытып, болашақтағы ұсақ моторика дағдыларының негізін қалайды. Ең бастысы, Сіз бөпеңіздің өзіне деген сенімділігін арттыруға қолдау көрсетесіз! 😊') WHERE id = '55eccf49-79d1-4243-b6f7-4417e0ce8446';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңізге енді үйретуші стақан алып беруге болады! 😊 Жалпы, бөпенің бөтелкеден стақанға көшуі біраз қиын болуы мүмкін. Өйткені ол дүниеге келмей тұрып саусақтарын, ал туғаннан кейін Сізді немесе бөтелкесін емуге үйренген. Алайда бөтелкені ұзақ уақыт пайдалану белгілі бір кезеңнен кейін бөпенің ауыз қуысы мен тіс құрылысына зиян келтіруі мүмкін. Сондықтан бөтелкеден біртіндеп бас тартып, стақаннан су ішу кезеңіне көшу үшін үйретуші стақан сияқты ынталандыратын құралдарды пайдаланған жөн. Мамандар әдетте 9-шы айдан бастап бөтелкені қолдануды азайтуға кеңес береді. Дегенмен үйретуші стақанды бөпеңіздің күнделікті өміріне қазірден енгізу бұл өтпелі кезеңді жеңілдетеді.') WHERE id = 'b7595fc9-0616-4fd7-9f1c-a33935df996a';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіздің ас қорыту жүйесі мен ферменттерінің жұмысы енді анағұрлым жетілген деңгейге жетті. Бұл бөпеңізді жаңа тағамдармен таныстыратын уақыт келгенін білдіреді! 😊 Мысалы, дәрігеріңіздің кеңесімен осы айда бөпеңіздің тамақтану мәзіріне зәйтүн, бұрыш, жасыл үрмебұршақ, гүлді қырыққабат, сиыржоңышқа бұршағы және табиғи дәмдеуіштерді қосуға болады. Көптеген дәрігерлер ұн өнімдерін де осы айдан бастап бөпенің рационына енгізуге болады деп санайды. Алайда бөпеңіздің дамуы мен дене өсімін өз дәрігері жақсы білетіндіктен, оның рұқсатын алмай бұл тағамдарды бермеуге кеңес береміз. Сондай-ақ брокколи мен гүлді қырыққабат сияқты өте пайдалы көкөністерді шағын бөліктерге бөліп, буға пісіріп жұмсартып ұсына аласыз. Бұл көкөністерді бергенде, бөпеңізге оларды өзі ұстап жеуге мүмкіндік беріңіз. Ас болсын! 😊') WHERE id = '8e3dae32-3e2f-4ba0-b882-845b799e8f32';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Кейбір бөпелердің тіс жаруы еш қиындық тудырмаса да, көпшілігі үшін бұл кезең өте жайсыз өтуі мүмкін. Әдетте бөпелердің алғашқы тістері 4-8 ай аралығында жарып шығады. Алайда әр бөпе әртүрлі болғандықтан, бұл мерзім өзгеруі мүмкін. Тіпті бөпеңіздің аузында інжу моншағындай көрінетін тістері әлдеқашан шығып қойған болуы да ықтимал. Тіс жару кезеңінде бөпеңіз қолын және қолына түскеннің бәрін аузына салуға тырысады. Оның себебі — қышыған қызыл иегіне қысым түсіріп, уақытша жеңілдік сезінгісі келуі. Осы кезеңде бөпеңізге көмектесу үшін оған қатты әрі тоңазытқышта біраз уақыт салқындатылған тағамдар беруге болады. Сондай-ақ бұл үдерісті жеңілдету үшін қолыңызда әрдайым тіс қаситын ойыншық болғаны дұрыс.') WHERE id = 'fb599c82-fab1-4307-ae9d-156ed7a53d22';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіздің ұсақ моторикасы дамып келе жатқандықтан, ол енді заттарды қолымен ұстай бастады. Осы кезеңде алдыңызға қойған қасықты ұстап, пайдалануға тырысқанын байқауыңыз мүмкін. Әрине, әзірге мұны толық меңгере алмай, біраздан кейін жалығып, қайтадан қолымен жеуге кірісуі ықтимал. Осы кезеңде бөпенің тағамды қолымен мыжып, зерттеуге тырысуы оның әртүрлі тағам құрылымдарына үйренуіне көмектеседі. Сондықтан бөпеңіздің біраз уақыт тамақты қолымен жеуіне кедергі келтірудің қажеті жоқ. Айналаның аздап былғануына рұқсат бере аласыз, бірақ тамақтануды үйрену кезінде бөпеңізге алжапқыш тағып, отырған жеріне төсеніш жаюдың еш әбестігі жоқ. Өзіңіз белгілеген осы аумақтың ішінде бөпеңізге қалауынша әрекет етуге мүмкіндік беріп, қажет болмаса араласпағаныңыз жөн екенін еске салғымыз келеді. 😊') WHERE id = '42d35bcf-5e08-438b-ab99-312796c2146c';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіз аяғынан тік тұрып, жүруге қатты талпынып жүр. 😊 Осы кезеңде оған алғашқы қадамға арналған аяқкиім қажет деп ойлауыңыз мүмкін. Жүре бастаған бөпеге дұрыс аяқкиім таңдау оның табаны мен омыртқасының дамуы үшін өте маңызды. Бүкіл денесі, соның ішінде қаңқа жүйесі де жылдам өсіп келе жатқан бөпеге жүруді бастаған кезде осы дамуды қолдайтын аяқкиім қажет болады. Дегенмен аяқкиім кигізуге асықпау керек. Мамандар жүруге дайындық кезеңінде бөпелерге үй ішінде жалаңаяқ жүруге кеңес береді. Осылайша бөпеңіз жерді табанымен сезіп, жүруге жеңілірек бейімделеді.') WHERE id = '073f0168-833f-4ba2-9b9a-e5fecf81e92a';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіздің тамақ ішкенін бақылау көптеген аналар сияқты Сіз үшін де өте қызықты болуы мүмкін. Алайда бөпенің ми жасушалары ақпаратты қабылдап, өңдеуге дайын, ал өзі сезімдер мен реакцияларды үйренуге бұрынғыдан да бейім. Сондықтан оны бақылаған кезде өзіңіздің бет әлпетіңіз бен реакцияларыңызға назар аударуыңыз өте маңызды. Мысалы, бөпеңіз тамақ ішудің орнына ұзақ уақыт ойнаса, Сіздің реакцияңыз оның тағаммен одан әрі ойнауына себеп болуы мүмкін. Сол сияқты, ол тамақты жан-жаққа шашып, бұған қуанып отырғанда Сіздің әдеттен тыс немесе қатал реакцияңызды көрсе, жағдай одан сайын қиындауы ықтимал. Шамадан тыс реакция бөпе үшін өте қызық, сондықтан ол Сіздің реакцияңызды қайта көру үшін тамақты бұрынғыдан да көбірек шашуы мүмкін. Мұның әдетке айналғанын қаламасаңыз, тамақты біраз уақытқа бөпеңіздің алдынан алып қоюға немесе оны өзіңіз тамақтандыруға болады.') WHERE id = '27035cad-7cd4-42d9-90d6-1a67f36eaafc';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіздің жүруіне көмектесу үшін жүріс арбасын (ходунок) сатып алуды ойлап жүрсіз бе? Алайда аяғынан тік тұра бастаған бөпеге бірден жүріс арбасын сатып алу — үлкен қателік. Зерттеулер жүріс арбасының жүруді жылдам үйренуге еш пайдасы жоқ екенін, керісінше, оны аздап кешіктіруі мүмкін екенін көрсетті. Жүріс арбасына отырғызылған бөпелерде денені дұрыс ұстамау және салмақтың біркелкі бөлінбеуі салдарынан омыртқа проблемалары туындауы мүмкін. Сондай-ақ жамбас буынына түсетін қысымнан және бойы жетпегендіктен аяқ ұшымен итерілу қимылынан аяқ бұлшықеттері біркелкі дамымауы ықтимал. Америка Құрама Штаттарында жүргізілген зерттеуде бөпелердің өмірінің алғашқы жылында алған бас сүйек жарақаттарының 90% жағдайында жүріс арбасына байланысты жазатайым оқиғалар себеп болғаны анықталды. Біздің еліміздегі дәрігерлердің де барлығы дерлік жүріс арбасын қолдануға қарсы екені жөнінде ортақ пікірде.') WHERE id = '98a525b0-85c4-44ad-bd1f-bf93b8cfb809';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бұл кезеңде бөпеңіздің тамақтану мәзірінің негізін біртіндеп қатты тағамдар құрай бастайды. Егер әлі де езбе түрінде дайындайтын тағамдарыңыз болса, енді оларды қатты күйінде және бөпеңіз өзі ұстай алатындай етіп беруіңіз керек. Осылайша бөпеңіздің шайнау және ұстау қабілеттерін дамытып қана қоймай, қолы мен саусақтарының бұлшықеттерін де нығайта аласыз. Кейбір қатты тағамдар бөпенің ағзасында күтпеген реакциялар тудыруы мүмкін. Сондықтан қатты тағамдарды бір-бірімен араластырмай беріп, кемінде үш күн күтуіңіз керек. Аллергиялық реакция болмағанына көз жеткізгеннен кейін ғана келесі тағамға көшіңіз. Аллергия әдетте бөпенің денесіндегі бөртпе және нәжісінің консистенциясындағы өзгерістер арқылы байқалады. Сол себепті, әсіресе аллергия туғызу қаупі бары анықталған тағамдарды бермей, бөпеңізді жаңа тағамдармен кезек-кезек таныстыруыңыз керек.') WHERE id = 'e4b85e6a-69c4-455d-9f99-5bcc0f9dfafa';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіздің таңғаларлық жылдамдықпен өсіп келе жатқанын көру Сізге де, жақындарыңызға да үлкен қуаныш сыйлайтыны сөзсіз. Ал оның жымиғанына сыңғырлаған күлкісі де қосылғаны қандай тамаша? 😊 Әсіресе осы кезеңде бөпеңіз көптеген жаңа дағдыларды меңгерді, сондықтан олардың бәрін бақылап үлгеру қиын болуы мүмкін. Мысалы, бөпеңіз енді ешкімнің көмегінсіз және тіреусіз еркін отыра алады. Еңбектеуге де әбден төселгенін ескерсек, оның жаңадан меңгерген осы әрекетін үнемі қайталағысы келуі қалыпты жағдай. Осы апталарда көптеген аналар бөпелерінің бір жерден ұстап, аз уақыт аяғынан тік тұра алатынын айтады. Алайда тік тұру уақыты әр бөпенің бұлшықеттерінің дамуына қарай әртүрлі болуы мүмкін. Сондықтан бөпеңіз өзі талпынбайынша, оны мәжбүрлемеуге кеңес береміз. 😊') WHERE id = 'e8faa9c0-7a4a-4a69-af25-bd6473750397';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Қазір бөпеңіз тәуелсіздік сезімін біртіндеп сезіне бастайтын кезеңдесіз. Егер бөпеңіз еңбектей бастаса, Сізді өте белсенді кезең күтіп тұр. Ал әлі еңбектемесе, осы айда еңбектей бастауы мүмкін. Еңбектеудің арқасында бөпеңіз енді ойыншықтарына қалаған кезінде жетіп, олармен өз қалауынша ойнай алады. Алайда осы айлардан бастап кейбір бөпелердің бұрыннан ойнап жүрген ойыншықтарынан жалыға бастағанын байқауға болады. Яғни бөпеңіздің күнделікті ойыншықтары енді назарын аудармаса, ол үйдегі кез келген шкаф пен тартпаны ашып, ішін ақтара бастауы мүмкін! Өйткені бөпеңіз қазір жаңа нәрселерді зерттеуге құмар және бұрын көрмеген әрбір затпен танысуға қатты қызығады. Сондықтан бірінші кезекте бөпеңіздің қауіпсіздігіне мән беріп, оны мүмкіндігінше үнемі бақылап жүруге кеңес береміз.') WHERE id = '5cb2c5a3-52c5-4353-87cf-7a048de6a6ae';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Дүниежүзілік денсаулық сақтау ұйымы (ДДСҰ) Еуропа өңірінің әртүрлі елдерінде болып жатқан індеттерге байланысты ұсынымдарын тұрақты түрде жариялап отырады. Иммундау жөніндегі консультативтік кеңестің шешімдеріне сәйкес, бақылау стратегиясы аясында 9-11 айлық бөпелерді вакцинациялау мәселесі қарастырылады. Белгіленген қағидалар бойынша, 9 айдан асқан және 12 айға толмаған бөпелерге дәрігердің кеңесімен қызылшаға қарсы қосымша вакцина салынуы мүмкін. Бұл доза қызылшаға қарсы алдыңғы вакцинадан кейін кемінде төрт апта өткен соң салынады. Бұл жоспарлы доза болмағандықтан, жүйеде әдетте қосымша вакцина ретінде белгіленеді. Бұл туралы ең нақты ақпаратты өз учаскелік дәрігеріңізден алуды ұмытпаңыз.') WHERE id = 'b6d3d34d-c066-4ccc-9ded-29b02d7dbff4';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Осы айда жоспарлы тексеру кезінде дәрігер бөпеңіздің жалпы жағдайын бағалау үшін кейбір талдауларды тағайындауы мүмкін. Кейбір дәрігерлер бұл талдауларды 12-ші айда да тағайындайды; мұның бәрі бөпеңіздің даму және өсу қарқынына байланысты. Алдымен дәрігер бөпеңіздің бойы мен салмағын өлшейді. Егер бөпеңіздің салмағы аз қосылғанын байқасаңыз, еш уайымдамаңыз. Бұл айларда бөпелердің салмақ қосу қарқыны едәуір баяулайды, өйткені олар бұрынғыдан да көп қимылдап, айналасын зерттей бастайды. Үнемі қозғалыста болғандықтан, қабылдаған калориясының көп бөлігін жұмсайды. 9 айлық бөпенің орташа салмағы 8400 грамм, алайда бұл көрсеткіш 6600 грамнан 10.000 грамға дейін өзгеруі мүмкін. Бір айда шамамен 250-600 грамм салмақ қосуы қалыпты. Әр бөпенің өсуі әртүрлі екенін және бұл көрсеткіштер әр балада өзгеше болуы мүмкін екенін ұмытпаңыз.') WHERE id = '4fead597-2916-4787-ba40-6051f71308e8';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіз қосымша тағамға көше бастағанда, жаңа асқа үйренуі үшін оған жұмсақ, езілген тағамдар берген пайдалы. Алайда оның ас қорыту жүйесі мен қимыл-қозғалыс дағдылары қаттылау тағамдарды жеуге де біраз уақыттан бері дайын. Мысалы, бөпеңіз қолына ұстай алатындай етіп туралған банан — оңай дайындалатын әрі пісіруді қажет етпейтін тамаша таңдау. Ал алма — аналар осы кезеңде жиі ұсынатын жемістердің бірі. Ол бананға қарағанда қаттылау болғандықтан, алманы буға аздап жұмсартып, тілімдерге бөліп, бөпеңізге молынан бере аласыз. Ал кешкі асқа арнайы дайындаған котлет бөліктері ол үшін өте дәмді таңдау болады. Ас болсын! 😊') WHERE id = '366b1717-cbe7-42c2-825f-799a14209342';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Осы айдан бастап бөпеңіздің сөйлеу дағдыларында үлкен ілгерілеу байқауыңыз мүмкін. Бұл кезеңде бөпелердің барлығы дерлік мағыналы немесе мағынасыз көптеген сөздерді айта бастайды. Тіпті ұйқысынан оянғанда қасында болмасаңыз, саналы түрде «ана» деп жылауы мүмкін. Дайын болыңыз! 😊 Өйткені бұл кезеңде бөпеңіздің өз ойын білдіру қабілеті едәуір дамиды. Мысалы, Сіз оған мейірім танытқанда, ол да Сізге сүйіспеншілігін көрсете алады, ал көңілі түссе, оны Сізге сездіреді. Тіпті Сіздің мұңайғаныңызды көрсе, жаныңызға келіп, Сізді бақылау арқылы жағдайды түсінуге тырысады. Ол әлі де көптеген сөзді айта алмаса да, бұл олардың мағынасын білмейді деген сөз емес! 😊') WHERE id = '248a2f1b-11a9-4475-98d2-8e5dbff40ba0';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Әсіресе тісі шығып жүрген бөпеңіздің осы апталарда қызыл иегі өте сезімтал болады. Сондықтан қызыл иегіне тиген қасық немесе тағам оған жайсыздық тудыруы мүмкін. Сол себепті бөпеңіз тамақтанғысы келмеуі, тіпті емуден де бас тартуы мүмкін. Жалпы, тіс шығару кезеңінде бөпелердің тәбеті төмендеуі қалыпты саналады. Егер бұл үдеріс шамадан тыс ұзаққа созылмаса, уайымдаудың қажеті жоқ. Бөпеңіз тамақтан бас тартса, қаламай тұрған кезде оны ешқашан күштеп тамақтандырмаңыз. Бұл тағамға жағымсыз көзқарас қалыптастырып, болашақта тамақтану мәселелеріне әкелуі мүмкін. Осы қиын кезеңді жеңілірек өткізу үшін айран немесе йогурт қосылған сорпалар мен жаңа сығылған жеміс шырындарын ұсына аласыз.') WHERE id = '2db32885-0a8a-4d2a-bc4e-74c38a2ae5a1';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіздің зияткерлік дамуы үшін осы айда жасына сай дамытушы ойыншықтарды қарастыруға болады. Әсіресе құрастырылып, қайта ажыратылатын ойыншықтар оған заттардың көлемін түсінуге көмектеседі. Бөпеңіз бұл ойыншықтарды қолымен ұрып немесе бір-біріне соғып, жаңа дыбыстарды зерттейді. Сондай-ақ бөлшектерді біріктіру кезінде оның ұсақ моторикасы да едәуір дамиды. Алайда мұның бәрі үшін міндетті түрде қымбат ойыншықтар сатып алудың қажеті жоқ. Мысалы, бөпеңізбен бірге айнаның алдына тұрып, саусақтарыңызды бір-бірлеп көрсетіп, атауларын атай аласыз. Бірге жасайтын осы әрекеттің арқасында ол әрі көңіл көтереді, әрі үйренеді. Көңілді уақыт өткізіңіздер! 😊') WHERE id = '39e8f843-aca7-42e5-9c7e-60770bf6f46e';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіздің тісі шығып жатқандықтан, осы кезеңде ол аздап мазасыз болуы мүмкін. Барынша тыныш әрі жайлы орта қалыптастыру бұл үдерісті жеңілдетеді. Тіс қасуға арналған құралдармен бөпеңіздің қызыл иегіне массаж жасай аласыз. Әсіресе салқын заттар оны тыныштандыратындықтан, іші сұйықтықпен толтырылған және тоңазытқышта салқындатуға болатын тіс қаситын құралдарды таңдаңыз. Тіс шығу кезеңінде бөпеңіздің тамақтану және ұйқы режимі бұзылуы мүмкін. Бұл оның иммундық жүйесін әлсіретіп, инфекцияларға бейімділігін арттыруы ықтимал. Егер бөпеңіздің дене қызуы 38 градустан жоғарыласа, ол шамадан тыс мазасызданса немесе іші өтсе, міндетті түрде дәрігермен кеңесіңіз. Өйткені, көпшілік ойлағандай, бұл белгілер әрдайым тіс шығуымен байланысты бола бермейді.') WHERE id = 'fd3bdcfc-5254-4510-b9f7-837898a606a0';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпенің дамуы үшін оған күтім жасайтын адаммен орнатқан сапалы қарым-қатынасы өте маңызды. Көптеген ата-ананың ортақ мәселесі — мұндай қарым-қатынасты қалай қалыптастыруды және бірге уақытты қалай өткізуді білмеуі. Шын мәнінде, бөпеңізбен ойнайтын қарапайым «ку-ку» ойынының өзі осы мақсатқа көмектеседі. Ойын — бөпенің зияткерлік қызметтерінің дамуын қолдайтын, тіпті емдік әсері бар әрекет. Бөпеңізбен ойнау оның әлеуметтік, эмоциялық, физикалық, зияткерлік және тілдік дамуы үшін өте маңызды. Сонымен қатар онымен жиі сөйлесуіңіз, әндер мен бесік жырларын айтуыңыз, тіпті шынайы жымиюыңыздың өзі бөпенің миын белсендіреді. Мұндай зияткерлік ынталандыру мидың дамуына үлкен үлес қосады. Сондықтан әрбір мүмкіндікті тиімді пайдалануға кеңес береміз.') WHERE id = '8bad6496-e337-421c-9a82-679470e2639c';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, '9-айдан бастап бөпеңіздің шайнау рефлексі дамуы үшін ол енді түйіршікті әрі кесектері бар тағамдарды көбірек жеуі керек. Сондықтан бөпеңізге беретін қосымша тағамдарды қолымен оңай ұстап, аузына салып жей алатындай етіп дайындауыңыз қажет. Осылайша бөпеңіздің өздігінен тамақтану дағдылары да дамиды. Егер бөпеңіздің тістері әлі шықпаса, ол тіссіз шайнай алмайды деп ойлауыңыз мүмкін. Бірақ бұл қате түсінік: бөпеңіз әсіресе піскен көкөністер мен жемістер сияқты тағамдарды қызыл иегімен оңай езе алады. Осы тұрғыдан алғанда, түйіршікті әрі кесектері бар тағамдар бөпенің шайнау және ұстау дағдыларын дамыту үшін өте пайдалы. Ол үшін әсіресе BLW (бөпенің өздігінен тамақтануы) әдісінде қолданылатын тағамдарды таңдауға болады.') WHERE id = '01dbba01-d87e-4015-9ad4-7f2d6dcf5bd6';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіз үшін осы уақытқа дейін қалыптастыруға тырысқан тамақтану режимі осы айдан бастап толығымен өзгеруі мүмкін. Мұның негізгі себептерінің бірі — бөпеңіздің дербес болуға ұмтылысы. Әсіресе қасықпен беріп жүрген езбелердің орнын өзі жей алатын тағамдар басса, тамақтану режимін қайта құру қажет болуы мүмкін. Кейбір бөпелер бұл өзгеріске оңай бейімделе алмайды. Сондықтан бөпеңіз ұсынған тағамыңыздан үзілді-кесілді бас тартуы немесе қасықпен жегісі келмеуі мүмкін. Мұндай кезде өте сабырлы болып, бөпеңіз өздігінен тамақтанғысы келсе, оған түсіністікпен қарауыңыз керек. Оған қолайлы жағдай жасап, тағамның бір бөлігін немесе барлығын алдына қоя аласыз. Алғашында бөпеңіз аузына салатын бөліктердің мөлшерін дұрыс есептей алмауы мүмкін. Оның көмекке мұқтаж екенін байқаған кезде қолдау көрсете аласыз.') WHERE id = 'f4238778-2de3-481f-be1b-95a62161c1ba';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіз ойындар мен еңбектеу сияқты жаңадан меңгерген дағдыларының арқасында қарқынды дамып келеді. Өйткені бұл қимылдарды жасаған кезде оның денесіндегі әртүрлі бұлшықеттер үздіксіз жұмыс істейді. Әсіресе ұсақ бұлшықет топтарын іске қосатын ойындар кезінде (мысалы, заттарды салып-шығару, түйме тағу сияқты) ұсақ моторика да дами бастайды. Ал ірі бұлшықет топтарының жұмысы болашақта жүру, секіру және баспалдақпен көтерілу сияқты қимылдарға негіз қалайды. Қозғалыс кезінде тыныс алу тереңдеп, жиілегендіктен, бөпенің ағзасына көбірек оттегі түседі. Сондай-ақ мұндай зат алмасу өзгерістері кезінде қан айналымының жылдамдауы тіндерге қоректік заттардың көбірек жеткізілуін қамтамасыз етеді. Осының бәрін ескере отырып, көп ойнау бөпенің зияткерлік және физикалық дамуы үшін өте маңызды деп айта аламыз.') WHERE id = 'a8bbe7da-d7ed-4f71-bc81-f38a911b0996';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Осы айдан бастап бөпеңізді отбасыңызбен бірге дастарқан басына отырғыза аласыз. Мұның өте көңілді болатынына күмәніміз жоқ! 😊 Бірге дастарқан басында отыру әдеті бөпеңізге өзін отбасының бір мүшесі ретінде сезінуге көмектеседі және оның әлеуметтенуіне ықпал етеді. Сондай-ақ отбасының басқа мүшелерінің де тамақтанып отырғанын көруі Сіз ұсынған тағамдардан бас тартпауына ынталандыруы мүмкін. Бөпеңіз біраз уақыт тамақ жеудің орнына басқалардың қалай тамақтанатынын бақылағысы келуі ықтимал. Мұндай жағдайда оны тамақтануға мәжбүрлемеңіз. Аздап үзіліс жасап, кейін қайта ұсыну арқылы оның толық тоюын қамтамасыз ете аласыз. Бөпеңіздің Сіздермен бір дастарқан басында отыруы үйде дайындалған кез келген тағамды жей алады дегенді білдірмейтінін ұмытпаңыз. Әсіресе 3 жасқа толғанға дейін бөпеңізді ас қорыту жүйесіне сәйкес келетін тағамдармен тамақтандыру болашақта туындауы мүмкін көптеген денсаулық мәселелерінің алдын алады.') WHERE id = '88647028-f25e-4ac9-8691-df916cfbec6e';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіз қысқа уақыт ішінде үлкен даму жолынан өтсе де, әлі де нәрестелік кезеңде. Бұл уақытта оның ең сүйікті ісі — өз дене мүшелерімен және айналасындағы қызықты заттармен ойнау. Сондықтан ол жатқан жерге түрлі түсті, дыбыс шығаратын және қозғалатын заттарды қоюыңызға болады. Бірге жасай алатын тамаша әрекеттердің бірі — шомылдырғаннан кейін бөпеңізге киімсіз жатып, өз денесін зерттеуге мүмкіндік беру. Аяқ саусақтарын бір-бірлеп қарап, аузына салып танып көрсін. Өз денесін зерттеу бөпеңізге мүмкіндіктерінің шегін түсінуге және қолынан келетін әрекеттерге сенімді болуға көмектеседі. Содан кейін оған ән айтып отырып, жеңіл әрі босаңсытатын массаж жасай аласыз. Көңілді уақыт өткізіңіздер! 😊') WHERE id = '15555c9e-8608-4e1e-a198-d3137b747de5';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіз алғашқы айлардағыдай болмаса да, әлі де тез өсіп, дамып келеді. Оның дамуын қолдап, денсаулығын сақтау үшін жасына сай дұрыс тағамдарды мұқият таңдауыңыз керек. Тамақтану мәзірінің негізгі бөлігін әлі де ана сүті немесе сүт қоспасы құрауы тиіс. Бұған қоса, мәзіріне езілмеген, ұсақ түйіршікті жемістер мен көкөністерді, пайдалы дәнді дақылдардан жасалған макарон өнімдерін, үйде пісірген печеньелерді және қолымен ұстап жей алатын, оңай қорытылатын басқа да тағамдарды қосуға болады. Қарқынды дамып келе жатқан бұлшықеттері үшін ақуызға деген күнделікті қажеттілігін де дұрыс есептеу қажет. Балық, жақсы піскен ет, жасымық және үрмебұршақ сияқты ақуызға бай өнімдерді бөпеңіздің мәзіріне енгізе аласыз. Осы кезеңде жаңа тағамға аллергиясы бар-жоғын байқау үшін әр жолы тек бір жаңа өнім беріп, мәзірді біртіндеп кеңейткен жөн.') WHERE id = '89bec816-5357-4575-bfde-092fc39e99a9';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңізге тамақ бергенде немесе бірге дастарқан басында отырғанда, өзіңіздің де, оның да назарын аударатын заттардың бәрін алып қоюыңыз керек. Бұл қағида бөпеңіз белсенді үйреніп жүрген қазіргі кезеңге ғана емес, барлық уақытта қатысты. Әсіресе бөпеңізбен бірге дастарқан басында отыру — отбасылық қарым-қатынасты нығайтып, қанша тамақ желінгенін аңғаруға мүмкіндік беретін уақыт. Сондықтан тамақтану кезінде теледидардың өшірулі болуын, ал бөпеңіздің қолында телефон немесе планшет болмауын қадағалаңыз. Сондай-ақ тамақ әзірлеудің алдындағы дайындықты көруі үшін бөпеңізді жаныңызда ұстаңыз. Себебі еліктеу қабілеті жақсы дамыған бөпеңіз үшін бұл — табиғи үйрену үдерісі. Тамақтанар алдында қол жуу, отбасымен бірге дастарқан жаю және жинау, көтеріңкі көңіл күймен тамақтану секілді әрекеттер — арнайы күш салмай-ақ, өз үлгіңіз арқылы бөпеңізге қалыптастыра алатын әдеттер.') WHERE id = '6cc71e92-a6d5-4d2d-bf55-9c74e24a03af';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіздің ойлау қабілетін ынталандыру үшін онымен бірге сенсорлық дамыту ойындарын ойнай аласыз. Бұл атау алғаш естігенде күрделі көрінгенімен, шын мәнінде бөпеңіздің дамуын тиімді қолдайтын, тіпті емдік әсері бар тәсіл. Осылайша оның белсенді түрде үйренуіне және түрлі бағытта дамуына көмектесе аласыз. Мұны қарапайым мысалмен түсіндірейін: бөпеңізді ортаға отырғызып, айналасында қозғалуыңызға немесе қарсысына отырып, қызықты заттарды өзіңізге қарай тартып, әрі қарай итеруіңізге болады. Бөпеңізді шалқасынан жатқызып, аяғына байланған шарларды тебуіне мүмкіндік беріңіз. Сондай-ақ сипап сезу қабілетін дамыту үшін оған түкті және құрылымы әртүрлі беттерді ұстатып көріңіз. Бөпеңізге бұл ойындар өте ұнайтынына сенімдімін! 😊') WHERE id = '69152415-f884-484c-9ae7-d7f46f63d572';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіздің ас қорыту жүйесі дайын болғанымен, болашақта дені сау болуы үшін кейбір тағамдарды әзірге тұтынбағаны өте маңызды. Мысалы, ақ ұннан дайындалған тағамдардың бәрін оның мәзірінен алып тастау — дұрыс тамақтанудың негізгі шарттарының бірі. Нан мен макарон өнімдерінің кебек пен қарабидай ұнынан жасалған түрлерін таңдауға болады. Сондай-ақ осы кезеңде бөпеңізге дайын қапталған өнімдер мен тәттілерді бермеу алдағы уақытта ісіңізді едәуір жеңілдетеді. Мысалы, кейбір көкөністердің дәмін ұнатпағандықтан жемейді деп ойлап, тамағына қант қоспаңыз. Дәмдерге әлі толық үйренбеген бөпеңіз Сізге дәмсіз көрінетін тағамды ұнатуы мүмкін. Егер бастапқы кезеңде оған қант қосылған тағамдар берсеңіз, кейін оларды шектеу қиын, тіпті мүмкін емес болуы ықтимал.') WHERE id = 'f1f06dfe-2ed9-46d2-a946-2592a01f6371';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіз әлі еңбектемесе, оған дайындық жаттығуларын бастап кеткен болуы әбден мүмкін. Осы кезде оның еңбектеуге талпыныстары Сізге өте күлкілі әрі қызықты көрінуі ықтимал. 😊 Себебі бөпеңіз еңбектеуді әлі толық меңгермеген. Ол өзіне ең ыңғайлы қалыпты іздеп, барлық бөпе сияқты алдымен тек қолына сүйеніп, жер бауырлап қозғалуға тырысады. Әрине, мұның себебі — қол бұлшықеттерінің аяқ бұлшықеттеріне қарағанда күштірек болуы. Көп ұзамай аяқтары күшейіп, бұл тепе-теңдік өзгереді, бірақ бөпеңізге әлі де уақыт қажет. Сондықтан оның еденде жер бауырлап қозғалғанын немесе шаршағанда біраз уақыт жатып демалғанын көрсеңіз, алаңдамаңыз.') WHERE id = '53bde760-576b-4b67-a81b-6b925c4d3fda';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Осы айдан бастап бөпеңіздің есте сақтау қабілеті айтарлықтай дамиды. Сондықтан Сізден ерекше мұқият болуды талап ететін кейбір жайттар бар. Бөпеңіз енді ойыншықтарының қайда тұрғаны сияқты нақты ақпаратты есінде сақтай алады. Сондай-ақ біраз уақыт бұрын көрген әрекеттерін есіне түсіріп, қайталауы мүмкін. Мысалы, түскі ас кезінде Сіздің қасық қолданғаныңызды көрсе, кешке тамақты қолымен емес, қасықпен жеуге тырысуы ықтимал. Ол ойыншықтарын жинайтын қорапты немесе оларды салатын тартпаны есінде сақтап, алғашқы мүмкіндік туған сәтте соларға жетуге әрекет етуі мүмкін. Мұның бәрі дамудың өте жағымды белгілері болғанымен, белгілі бір қауіптері бар кезеңнің басталғанын да көрсетеді. Мысалы, бөпеңіз темекі шегіп тұрған адамды көрсе, кейін темекіге ұқсайтын зат тауып алып, оны аузына апару арқылы сол әрекетті қайталауға тырысуы мүмкін. Сондықтан бұрынғыдан да мұқият болып, бөпеңізге жақсы үлгі көрсету үшін бар күшіңізді салуыңыз керек.') WHERE id = 'e01a8401-6796-4fd1-8eb2-bb5e93fe04db';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіз біраз уақыттан бері күндерін жаңа туған кездегідей тек тамақ ішіп, ұйықтаумен өткізбейді. Дүниеге келгеніне тура 9 ай болды, енді ол күн сайын көз алдыңызда әлеуметтеніп, Сізбен және айналасындағы адамдармен қарым-қатынас жасай бастады. Бөпеңізде өзіндік әдеттер қалыптаса бастайды, бұл оның мінезінің қалыптасуы жеделдеп келе жатқанын білдіреді. Егер бөпеңізде дамудың секірмелі кезеңі, тіс жару немесе денсаулығына қатысты қандай да бір мәселе болмаса, түнгі ұйқысы реттеле бастауы мүмкін. Әсіресе күндіз белсенді болып, энергиясын жұмсайтындықтан, түнде әдетте оянбайды немесе өте сирек оянады. Осыған байланысты, егер бөпеңіздің ұйқы режимі әлі қалыптаспаған болса, дәл қазір оны реттеуге өте қолайлы кезең екенін еске салғымыз келеді. Бөпеңізге ұйықтайтын уақытын қалыптастыруға Сіздің де көмектесуіңіз қажет болуы мүмкін. Мысалы, күн сайын бір уақытта оны бөлмесіне апарып, ұйықтап кеткенше біраз уақыт жанында отыра аласыз.') WHERE id = '4172e48e-6df4-4725-923e-07d5217e37c6';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Осы айдан бастап бөпеңіздің күнделікті тамақтануының 50%-ін ана сүті (немесе сүт қоспасы), ал қалған 50%-ін қосымша тағам құрайды. Егер осы уақытқа дейін бөпеңізге күніне екі рет қосымша тағам беріп жүрсеңіз, енді оны үш ретке дейін көбейте аласыз. Сондай-ақ дәрігер басқаша нұсқау бермесе, бөпеңізге қалағанынша жеуге рұқсат етуге болады. Алайда қосымша тағамның мөлшері көбейген сайын, егер бөпеңізді емізіп жүрсеңіз, оның ана сүтін ішу мөлшері азаюы мүмкін. Бұған жол бермеу үшін бөпеңізді қосымша тағам берерден ең көбі бір сағат бұрын емізе аласыз. Кейбір аналар өздері дайындаған көкөніс пен жеміс езбелеріне сауылған сүтін қосатынын айтады. Осылайша бөпеңізге пайдалырақ тағам ұсынып қана қоймай, оның мұндай тағамды тәбетпен жеуіне де көмектесесіз.') WHERE id = 'da5cb5a7-cf3b-4e4d-80b2-ebbc83c6520d';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіздің таңдамалы қабылдау қабілеті айтарлықтай дамыды. Соның арқасында ол басын бұрып іздемесе де, дыбыстың қайдан шығып жатқанын ажырата алады. Егер әлі басталмаса, осы айдан бастап бөпеңіз бейтаныс адамдарға салқын қарап, оларды жатырқай бастауы мүмкін. Бұл кезеңде бөпелер әртүрлі әрі қызықты мінез-құлық көрсете алады. Дегенмен бөпелер көбіне танымайтын адамдардың жанында мазасызданып, оған жылау арқылы қарсылық білдіреді. Бұл — бөпеңіз үшін өтпелі кезең. Осы уақытта оны көргенде жылайтын бейтаныс адамдармен араласуға мәжбүрлемеуіңіз керек. Әсіресе бір жерге барған кезде бөпеңіз мазасызданып, біреудің қолына барғысы келмесе, оның бұл қалауына құрметпен қарап, айналадағылардың да құрметтеуін қамтамасыз етіңіз. Сондай-ақ осы кезеңде бөпеңіздің жанында тек Сіз бен әкесінің болғанын қалауы — әбден табиғи жағдай. Ажырасудан қорқуы күшейген бөпеңізді ұзақ уақыт жалғыз қалдырмауға, қажет болса, жанынан алыстамауға кеңес береміз.') WHERE id = '21e5fb9b-957f-4246-8c1d-e631e7b5dd81';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Егер бөпеңіз жиі ауыратын болса, өзіңізді кінәламаңыз және өзіңізді жеткіліксіз сезінбеңіз. Бөпеңіздің иммундық жүйесі әлі толық қалыптаспағандықтан, суық тию мен тұмау жиі кездесуі мүмкін. Бөпелердің көбі алғашқы екі жылда шамамен он рет суық тиіп ауырады. Алғашқы айларда қиын болып көрінетін бұл жағдай бөпеңізге сол сәтте жай ғана жайсыздық туғызады. Бұл кезеңді барынша жеңіл өткізу үшін бөпеңізге мүмкіндігінше жайлы жағдай жасауға тырысыңыз. Мысалы, ауырған кезде бөпеңіздің ағзасына көбірек ұйқы қажет болады. Сондықтан шомылдырғаннан кейін жасайтын босаңсытушы массаж оның ұйықтауын едәуір жеңілдетеді. Егер мұрны бітеліп қалса, ұйықтаған кезде басының астына қоятын жастықты әдеттегіден сәл биігірек етіп таңдауға болады. Суық тиген кезде бөпеңіздің сұйықтыққа қажеттілігі артатынын ұмытпаңыз. Сондықтан оның жеткілікті мөлшерде су ішуін және ана сүтін (немесе сүт қоспасын) қабылдауын қамтамасыз етуіңіз керек.') WHERE id = '0c97a7c0-87cb-4c6d-bccc-18d59ae9a64f';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіздің қимыл-қозғалыс дағдылары, сезімдері мен ақыл-ойы айтарлықтай дамығандықтан, ол өте белсенді болатын кезеңге аяқ басты. Бұл кезеңде бөпеңіз қолы жеткеннің бәрін ұстау сияқты жаңа дағдыларды меңгеруі мүмкін. Ол шамасы жетіп, көтере алатын әрбір затты сілкіп, бір-біріне соғып, жерге тастап немесе лақтыра бастауы ықтимал. Заттарға осылай әсер ете алатынын түсінгенде, ол бір әрекетті жалықпастан қайта-қайта қайталауы мүмкін. Сондықтан бұл кезеңде өте мұқият болуыңыз керектігін ұмытпаңыз. Бас сүйек жарақаттарының көбі дәл осы айларда болады. Сол себепті үйде бөпеңіз үшін белгілі бір шектеулер қоя аласыз. Мысалы, бөпеңіз Сіз отырған бөлмеден шықпауы тиіс. Алдымен бөлмедегі оған зиян келтіруі ықтимал заттарды алып тастауға болады.') WHERE id = 'af4167d5-e075-447d-a653-bf92fb79d76e';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіздің ас қорыту жүйесі айтарлықтай дамыды, сондықтан отбасылық таңғы ас дастарқанынан оған да орын бермеуге еш себеп жоқ. Мысалы, емізгеннен кейін (немесе сүт қоспасымен қоректенсе, бір стақан сүт қоспасымен бірге) бөпеңізге ірімшік, зәйтүн, дәнді дақылдар қосылған нан, тіпті табиғи сары май да бере аласыз. Алайда бөпеңіз әлі барлық тағамды жеуге дайын емес. Сондықтан бұл кезеңде де баялды, жұмыртқаның ағы, бал, сиыр және ешкі сүтін, сондай-ақ аллерген ретінде белгілі жемістерді бермегеніңіз жөн. Бөпеңізде аллергияның пайда болу қаупін барынша азайту үшін генетикалық түрлендірілген, күшті пестицидтер әсеріне ұшыраған, құрамында тәуелділік тудыратын дәм күшейткіштер мен консерванттар бар тағамдардан бас тартуыңыз керек. Өйткені мұндай өңдеуден өткен тағамдар табиғилығын толығымен жоғалтып, бөпенің зат алмасу жүйесі үшін бөгде затқа айналады. Аллергияны жиі тудыратын тағамдардың қатарына өңделген консервілер, генетикалық түрлендірілген кейбір бидай өнімдері, құрамында химиялық заттар бар жемістер мен сүт өнімдері жатады. Сондықтан бөпеңізге консервіленген тағамдарды бермей, табиғи жемістер мен көкөністерді таңдау арқылы аллергия қаупін азайту өте маңызды.') WHERE id = '7dcfd4f4-9aee-4c8d-9828-a2d3f2df221d';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңізбен сапарға шығатын болсаңыз, кейбір шағын қиындықтарға дайын болғаныңыз жөн. Ол қазір өз ортасына, үйіне және күн сайын көретін отбасы мүшелеріне әбден үйреніп, соған сай күн тәртібін қалыптастырды. Жолда жүру және үйреншікті ортасынан алыстап, жаңа жерлерге бару алғашында бөпеңізге аздап қорқынышты көрінуі мүмкін. Сондай-ақ көптеген бейтаныс адамды көруі оның өзін қауіпсіз сезінбеуіне және мазасыздануына себеп болуы ықтимал. Сапар кезінде бөпеңізді тыныштандыру үшін назарын басқа жаққа аударатын бірнеше затты өзіңізбен бірге ала аласыз. Олар суретті кітаптар, дыбыс шығаратын ойыншықтар, саусаққа киілетін қуыршақтар және оның сүйікті тағамдары болуы мүмкін. Осының бәріне қарамастан бөпеңіз мазасызданса, онымен сөйлесіп, сапар ұғымын әлі толық түсінбесе де, жағдайды мүмкіндігінше түсіндіріп көріңіз.') WHERE id = '4ae1b5f1-3350-4a7e-9ecb-70e54028f264';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіздің тамақтануы, денсаулығы мен дене дамуы қаншалықты маңызды болса, оның болашақта сапалы білім алуы да соншалықты маңызды. Білім бөпеңіздің болашағы үшін өте маңызды және Сіздің бұл туралы қазірдің өзінде көп ойланатыныңызды білеміз. Ал осы бағытта не істей алатыныңызды білесіз бе? Егер Монтессори атауын әлі кездестірмеген болсаңыз, Сізге осы білім беру жүйесі туралы айтып бергіміз келеді. Монтессори білім беру жүйесі — бөпенің үйрену қарқынына, қабілеттеріне және қызығушылық танытатын салаларының өзгеруіне қарай қолданылатын әдіс. Егер бұл әдісті қолдануды шешсеңіз, бөпеңіздің айналасына ретімен топтастырылған үйретуші материалдарды дайындауыңыз керек. Оларға түйін байлау және шешу, пішінді блоктарды тиісті орындарға орналастыру, бірінің ішіне бірі салынатын түрлі түсті стақандар жатады. Мұнда ең бастысы — дайындаған материалдарды дұрыс топтастырып, бөпеңіздің қолы жететін жерлерге қою.') WHERE id = 'b4fbd7bc-5bea-4328-9444-1bbb7e0b93ab';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Көзді ашып-жұмғанша бөпеңіз де өсіп қалды. Оның ана сүтіне қосымша тағамдар жей бастаған 9-шы айының аяқталуы тамақтанудағы өтпелі кезеңнің артта қалғанын білдіреді. Осы айдан бастап бөпеңізді ет пен балықты қоса алғанда, бидайдан әзірленген тағамдармен, әртүрлі дәнді дақылдармен және жұмыртқамен таныстыра аласыз. Бұлшықеттері қарқынды дамып жатқан бөпенің тамақтануында ақуыздың маңызы өте зор. Сондықтан күнделікті ас мәзірінде бөпеңізге міндетті түрде күніне бір рет ет немесе ет өнімдерін бере аласыз. Алайда әр бөпе сияқты, Сіздің бөпеңіздің де даму қарқыны өзгеше болатынын ұмытпаңыз. Осы маңызды кезеңде кейбір бөпелер тәбеті жақсы әрі жаңа тағамдарды ынтамен жесе, басқалары құлықсыз болуы мүмкін. Тіпті бұл кезеңде бөпенің өзі үшін жаңа тағамдардан бас тартуы да қалыпты саналады. Сондықтан бөпеңізді мұқият бақылап, оның қажеттіліктеріне сай әрекет етуіңіз керек. Әр жаңа тағамды үш күн ережесі бойынша беруді жалғастырып, ағзасының реакциясын бақылай аласыз. Қосымша тағам мөлшері артқан кезде іш қату, іштің кебуі және рефлюкс сияқты мәселелердің туындауы да қалыпты деп есептеледі. Алайда бұл жайсыздықтар уақыт өте азаяды.') WHERE id = '38f9d9e1-4776-4187-abf9-e1f1ad116098';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Егер бөпеңіз осы кезеңге дейін әлі еңбектеуді үйренбесе, оған бұл дағдыны меңгеруге көмектесе аласыз. Бөпені еңбектеуге ынталандыратын ең танымал тәсіл — оның қолы сәл созғанда жететін жерге қызықты заттарды немесе ең сүйікті ойыншығын қою. Сондай-ақ бөпеңіздің күндіз еденде көбірек уақыт өткізуіне мүмкіндік беріңіз. Ол үшін бөпеңізді тым қатты да, тым жұмсақ та емес жерге жатқызып, алдын ала қауіпсіз етіп белгілеген аумақтың ішінде еркін қимылдауына мүмкіндік бере аласыз. Арқа бұлшықеттерінің дамуы да бөпенің еңбектеуіне айтарлықтай көмектеседі. Осы мақсатта бөпеңізге етпетінен жатып жасайтын жаттығуларды орындата аласыз. Сонымен қатар бөпенің еңбектеуін кешіктіретін жүріс арбасы сияқты құралдарды қолданбауға кеңес береміз.') WHERE id = 'c3473c70-f7b4-432f-afbf-5ede71de258f';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Қарбаласқа толы айларға қош келдіңіз! Бөпеңіз кеше ғана дүниеге келгендей еді... Уақыт неткен жылдам, солай емес пе? Сіз бөпеңіздің жақындап қалған туған күнін қалай атап өтетініңізді ойлай бастағанда, ол осы айда аяғына тік тұрып, Сізді таңғалдыруы мүмкін. Осы айда бөпе аяғына тұрып, бірнеше секунд ешкімнің көмегінсіз тік тұра және бір-екі қадам жасай бастауы мүмкін. Осының арқасында бұрын бөпенің көзіне үлкен болып көрінген заттар кішірейіп, оның өзіне деген сенімі артады. Тіпті кейбір бөпелер осы айда жүріп кетуі мүмкін. Алайда өздігінен жүру үшін әлі ерте, сондықтан бөпеңізді жүруге мәжбүрлемеуіңіз керек. Бірақ бөпеңіз жүруге барынша талпынып жүрсе, бұл дамуды қалай жылдамдатуға болатынын іздеп жүрген шығарсыз. Сондықтан дәрігеріңіздің кеңесімен «алғашқы қадам арбасы» немесе «жүруге арналған серік» деген атаумен сатылатын өнімдерді қарастыра аласыз.') WHERE id = '8ad14916-224e-43df-b050-f067ba32923b';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бұл айда бөпеңіздің даму қарқыны шамамен өткен айдағыдай болады. Алғашқы айлардағыдай тез өспеуі Сізді алаңдатпасын. Бөпеңіз қазір өте қимылшыл болғандықтан, осы айда орта есеппен 300-500 грамм салмақ қосуы мүмкін. ДДСҰ мәліметі бойынша, 10 айлық бөпенің орташа салмағы шамамен 8800 грамм. Алайда бұл көрсеткіш бөпенің жынысына, қимыл белсенділігіне, туған кездегі салмағына және даму ерекшеліктеріне байланысты өзгеруі мүмкін. Яғни бөпеңіздің салмағы 6500 грамм да болуы немесе 12500 грамнан да асуы мүмкін. Сондай-ақ осы айдан бастап бөпеңіздің бойы орта есеппен 1 см-ге ұзаруын жалғастырады. Бас шеңбері де дәл осындай қарқынмен өседі.') WHERE id = '789568fd-44f2-4cb3-9877-cd0130c94687';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіз қазір өте белсенді. Оның күлімсіреуі, аунауы, еңбектеуі және сөйлеуге талпынысы бір сәтке де тоқтамайды! 😊 Дүниеге келген сәтінен бастап меңгерген жаңа дағдылары Сізді әрі таңғалдырып, әрі толқытып, қуантады. Аяғынан тұруға талпынысы мен жүруге дайындық кезеңі де осындай әсерлі өзгерістердің бірі... Әдеттегідей, бұл кезеңде де бөпеңіздің ең үлкен қолдаушылары — Сіз бен жұбайыңыз. Сіздер оның жүруді үйрену кезеңінен көбірек ләззат алуына, өзіне сенімді болып, батыл қадам жасауына көмектесе аласыздар. Осы уақытта болуы ықтимал шағын оқыс жағдайларды ескеріп, бірқатар қауіпсіздік шарасын қабылдау қажет. Мысалы, бөпеңізді кереует, жөргек ауыстыратын үстел немесе диван секілді биік жерлерде тиісті қауіпсіздік шараларын қолданбай жалғыз қалдырмаудан бастай аласыз. 😊') WHERE id = 'b038be51-87de-40aa-81e8-34eb440fed27';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бұл кезеңде бөпеңіз күніне 3-5 рет ана сүтін немесе сүт қоспасын қабылдауды жалғастыруы керек. Оның толықтай қатты тағамға көшуіне әлі уақыт қажет екенін ұмытпаңыз. Осы кезеңде бөпеңізге қосымша тағам ретінде 3 негізгі және 3 тіскебасардан тұратын тамақтану жоспарын құра аласыз. Егер емізіп жүрсеңіз, күн ішінде қалағанынша емізе аласыз. Ал сүт қоспасымен қоректенетін бөпелерге күніне кемінде үш рет 200 ml қоспа жеткілікті болады. Кейбір аналар бөпесі ана сүтін жеткілікті мөлшерде алды деп ойлап, емізуді біртіндеп азайтқысы келуі мүмкін. Алайда бұл дұрыс емес, өйткені бөпеңіз Сіздің сүтіңізден әлі де көп пайда алады. Сүт бездері бөпеңіздің дамуына сай сүттің құрамын өзгертіп отырады. Мысалы, осы айларда сүтіңіздің майлылығы алғашқы айлармен салыстырғанда әлдеқайда жоғары болады.') WHERE id = '40235f48-568d-4e7c-b429-24fa27331c60';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Кейде бөпеңіздің тәбеті кенеттен ашылып немесе мүлде жоғалып кетуі, ұйықтағысы келмеуі немесе сағаттап ұйықтауы, тіпті көңіл күйі де аяқ астынан өзгеруі мүмкін. Егер бұл жағдайлар Сізге таныс болса, оның бір ғана себебі бар: сіздер әлі де даму секірісі (дағдарыс) кезеңіндесіздер! "Дағдарыс", "даму секірісі" немесе "өсу" кезеңі деп аталатын бұл уақыт күн тәртібі бұзылатындықтан, қорқынышты болып көрінуі мүмкін. Бірақ мұның бәрінің себебі бар: әрбір даму секірісі кезінде бөпеңіз жаңа дағдыларды меңгеріп, ақыл-ойы дамиды. Қысқаша айтқанда: "Өсу оңай емес!" деуге болады. Сондықтан осы кезеңдердің жағымды жақтары мен бөпеңіз меңгеретін жаңа дағдыларды ойлап, бұл үдерісті жеңілірек өткізе аласыз. Мысалы, осы даму секірісі кезінде бөпеңіз Сізді қызғана бастайды. Бұл қандай сүйкімді, солай емес пе? Жұбайыңыз жұмыстан келгенде оны сүйгеніңіз бөпеңіздің ашуын келтіруі мүмкін, өйткені ол Сізді өзінен басқа ешкіммен бөліскісі келмейді.') WHERE id = 'b4a75895-ae96-4823-9d66-151563acf366';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Осы айда бөпеңізге күніне кемінде 500 ml ана сүтін беруіңіз керек. Ана сүті болмаса, дәрігеріңізбен кеңесіп, оған ең қолайлы жалғастырушы сүт қоспасын қолдануыңыз қажет. Бөпеңіздің ас қорыту жүйесі сұйық тағамнан қатты тағамға көшуді едәуір дәрежеде қабылдай алатындай дамыды. Дегенмен ішегіне артық салмақ түсірмеу үшін ол күніне ең көбі 3 құты бөпелерге арналған қосымша тағам жеуі керек. Осы мөлшерден артық қосымша тағам беру оның негізгі қорегі саналатын ана сүтін жеткілікті мөлшерде қабылдауына кедергі келтіруі мүмкін. Қатты тағам мен ана сүтінің (немесе ол болмаған жағдайда жалғастырушы сүт қоспасының) тепе-теңдігін қалыптастырғаннан кейін, бөпеңіздің дені сау болып өсуі үшін оған қолайлы тамақтану жоспарын құруыңыз керек. Тағамның мөлшерімен қатар, оны пайдалы тәсілмен дайындау да өте маңызды. Сондықтан бөпеңіздің тамағын әзірлегенде буға пісіру, қайнату немесе пеште пісіру сияқты пайдалы әдістерге басымдық бергеніңіз жөн.') WHERE id = '2fad46fb-e452-4335-9758-a95de808e8f1';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бөпеңіз біраз уақыттан бері еңбектеп жүр, сондықтан үнемі бір ортада болудан жалығуы мүмкін. Әсіресе айналасындағылардың бәрі жүретінін көргенде, өзі де орнынан тұруға талпына бастайды. Ол үшін алдымен бір жерден ұстап, аяғынан тұруға тырысады. Біраз уақыт әрекеттері сәтсіз болуы мүмкін немесе алғашқы талпынысынан-ақ қолынан келуі ықтимал. Бұл әр бөпенің даму ерекшеліктері мен қоршаған ортасына байланысты өзгереді. Алдымен бөпеңіздің жақын маңдағы жиһаздан ұстап, орнынан тұруға тырысатынын байқайсыз. Мұны істей алатынын түсінгенде, тіреусіз тұруға талпынады. Алайда оған қол жеткізу үшін әлі де біраз уақыт қажет. Осы кезеңде бөпеңізді қолдау үшін кресло немесе орындық сияқты ұстай алатын заттардың үстіне оның назарын аударатын ойыншықтарды қоя аласыз.') WHERE id = '02985c47-f203-4125-957b-15eb60906ec2';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бір орында отырмайтын, энергиясы тасып, үнемі қозғалыста жүретін бөпенің киімін ауыстыру басқа аналар сияқты Сізді де әбден шаршатуы мүмкін. Бөпеңіз киінгенді ұнатпайтын шығар, сондықтан әр киім ауыстыру Сіз бен бөпеңіз үшін күреске айналуы мүмкін. 😊 Бұл жағдайды жеңілдетуге көмектесетін бірнеше амал бар. Бөпеңіз қосымша тағам жей бастағандықтан, киімін жиі былғайды. Сол себепті киім сатып алғанда дақ жұқпайтын маталарды таңдасаңыз, жұмысыңыз едәуір жеңілдейді. Киіндіріп жатқанда назарын басқа жаққа аудару үшін қолына сүйікті ойыншығын немесе қызықты бір зат беруге болады. Сондай-ақ сатып алатын футболкасы мен жейдесінің басы өтетін жері кеңейетін әрі созылмалы матадан тігілгеніне назар аударған жөн.') WHERE id = '80933d1b-7705-420b-8df2-38fff58443d1';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Тіс күтімі барлық адам үшін маңызды болғаны сияқты, бөпеңіз үшін де аса қажет. Әсіресе жаңа шыққан тістерінің сау болып өсуі оның болашағы үшін өте маңызды. Бөпеңізде тіс тазалау әдетін қалыптастыру үшін мұны қазірден бастап, күнделікті дағдыға айналдырған жөн. Алғашқы кезде тістеріне қалай күтім жасау керектігі туралы сұрақтарыңыз болуы мүмкін. Бөпеңіздің алғашқы тісі шыққанда, оны дәке немесе саусаққа киілетін тіс щеткасымен тазалауға болады. Ал 1 жастан кейін оған тіс щеткасын беріп, алдына отырып, тісті қалай тазалау керектігін көрсете аласыз. Бөпеңіз бастапқыда жасай алмаса да, Сізге еліктеу арқылы мұны тез үйренеді. Алайда тіс пастасын қолдануға әлі ерте екенін ұмытпаған жөн.') WHERE id = '37f66307-1b67-498c-b0b6-20e87a8898b8';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Өте қимылшыл бөпеңіз жазатайым жағдайға тап болмауы үшін бірқатар қауіпсіздік шарасын қабылдауыңыз керек. Мысалы, еденге түсіп кеткен дәрілерді, жаңғақтар мен дәндерді, үзіліп қалған түймелерді және тиын сияқты заттарды бөпеңіз жұтып қоймауы үшін дереу жинап, мұқият болған жөн. Бір нәрседен ұстап, орнынан тұруға тырысып жүрген бөпеңізге үстел мен журнал үстелі сияқты жиһаздардың үшкір бұрыштары қауіп төндіруі мүмкін. Сондықтан мұндай жиһаздарды бөпе жатқан бөлмеден шығарып қоюға немесе бұрыштарына арнайы қорғаныш орнатуға болады. Барлығын ұстап, зерттеуге қызығатын бөпеңіз үшін электр розеткаларына қорғаныш қақпақтар сатып алуға болады. Бөпе ішіне құлап кетуі мүмкін терең ойыншық себеттерін, басына киіп алуы мүмкін целлофан пакеттерді және тұншығу қаупін тудыратын сымдарды қолы жетпейтін жерге алып қою керек. Сондай-ақ есіктерді жабық ұстау, терезелерге, шкафтар мен тартпаларға қауіпсіздік құлыптарын орнату ықтимал қауіптердің алдын алады.') WHERE id = '6dba7d69-27ca-40ac-b3c1-c74bcff813bb';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бірнеше минут бойы әуреленіп пісірген картобыңызды езу, қолын сорпаға салу, берген сәбізіңізді еденге лақтыру... Мұның бәрі Сізге таныс па? Уайымдамаңыз, мұндай жағдай тек Сізде ғана емес! 😊 Бұл кезеңде тамақтану бөпеңіз үшін тек қарнын тойдыру ғана емес, ойынға да айналуы мүмкін. Ыждағатпен дайындаған асыңыздың асқазанына емес, айналаға шашылғаны Сізді абдыратып жіберуі мүмкін. Алайда бұл үшін бөпеңізге қатты ұрысу оның тамақтан суынуына әкелуі ықтимал. Сондықтан алдындағы тамақты алып қойып, өзіңіз тамақтандырғыңыз келуі мүмкін. Дегенмен мұның бәрі қалыпты үдеріс екенін және бөпеңіз осындай зерттеулер арқылы жаңа нәрселерді үйренетінін ұмытпаңыз.') WHERE id = 'cffb22db-240d-4023-8834-7c4c580e8149';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Бұл кезеңде бөпеңіздің асқазан сыйымдылығы орта есеппен 230 ml шамасында болады. Сондықтан бөпем аз жейді деп уайымдаудың қажеті жоқ. Әлі де аз-аздан, бірақ жиі тамақтануды қажет ететін бөпеңіз дайындаған тағамыңыздың бәрін бірден жеп қоя алмауы мүмкін. Оған мөлшерден көп тамақ беруге тырысқанша, тағамдық құндылығы жоғары өнімдерден теңгерімді тамақтану мәзірін құра аласыз. Мысалы, осы кезеңде бөпеге дене салмағының әр килограмына тәулігіне 1.02 грамм ақуыз (протеин) қажет. Бұл орташа салмағы 9000 грамм болатын бөпеге тәулігіне 9.2 грамм ақуыз қажет дегенді білдіреді. Ана сүтінің 100 грамында шамамен 1 грамм ақуыз болады. Жасанды қоспаларда бұл көрсеткіш өзгеше болуы мүмкін. Бұған қоса, бөпеңіздің тәуліктік ақуыз қажеттілігін бұршақ тұқымдастар мен ет өнімдері арқылы да қамтамасыз ете аласыз.') WHERE id = '338a7b7c-cd77-4384-ba83-6dc7af52489b';
UPDATE public.baby_daily_info SET info_kk = COALESCE(info_kk, 'Егер бөпеңіз әлі аяғынан тік тұра алмайды және жүруге талпынбайды деп ойласаңыз, бұл туралы алаңдауға негіз жоқ екенін біліңіз. Әр баланың жүре бастайтын уақыты әртүрлі, сондықтан бұл үдерісті жеделдету немесе қысқарту мүмкін емес. Бөпеңізді қолынан ұстап, аяғына тұрғызу және қадам бастыру оған қатты ұнауы мүмкін. Мұны ойын ретінде қысқа уақыт жасауға болады, бірақ одан ерте жүріп кетеді немесе аяғына тез тұрады деп үлкен нәтиже күтпеген жөн. Дәрігерлер 1 жасқа дейін бөпелердің аяқтарына ұдайы күш түсіруді, оларды тік тұрғызып, қадам бастыру жаттығуларын жасауды аса ұсынбайды. Өйткені мұндай жаттығулар бөпенің жалпы бұлшықет дамуына ешқандай пайда әкелмейді. Тіпті кейбір анатомиялық ауытқуларға себеп болуы мүмкін екені де айтылады. Сондықтан бұл мәселеде бөпеңізге шамадан тыс күш түсірмеуге кеңес береміз.') WHERE id = '4cd9c678-a1f8-4663-9ede-462dc0cff3d9';